INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (1, N'Hồ Điệp Và Kình Ngư', N'8935212370189', N'Bìa Mềm', CAST(72540.00 AS Decimal(12, 2)), CAST(155000.00 AS Decimal(12, 2)), CAST(111600.00 AS Decimal(12, 2)), N'https://res.cloudinary.com/dabxzdaf8/image/upload/v1748965053/Book_cover/m9fqhd3t5god0rrqugla.webp', N'Tuế Kiến', N'<h2 dir="ltr">T&Oacute;M TẮT NỘI DUNG S&Aacute;CH</h2>
<p dir="ltr">Một c&ocirc; g&aacute;i trẻ đang sống một cuộc đời b&igrave;nh thường nhưng lại v&ocirc; t&igrave;nh bị cuốn v&agrave;o thế giới đen tối đầy b&iacute; ẩn của một người đ&agrave;n &ocirc;ng nguy hiểm nhưng đầy cuốn h&uacute;t. Anh l&agrave; kẻ đứng tr&ecirc;n đỉnh cao quyền lực, l&agrave; người m&agrave; c&ocirc; kh&ocirc;ng n&ecirc;n y&ecirc;u. Nhưng c&agrave;ng muốn trốn chạy, c&agrave;ng kh&ocirc;ng thể tho&aacute;t.</p>
<p dir="ltr">Giữa họ l&agrave; y&ecirc;u hay hận? L&agrave; bảo vệ hay hủy diệt?<br>L&agrave; vận mệnh đ&atilde; an b&agrave;i hay chỉ l&agrave; một tr&ograve; đ&ugrave;a t&agrave;n nhẫn của số phận?</p>
<p dir="ltr">Những b&iacute; mật ch&ocirc;n giấu dần được phơi b&agrave;y, những lựa chọn đau đớn buộc phải đưa ra. Khi đ&atilde; bước v&agrave;o v&aacute;n cờ sinh tử n&agrave;y, liệu t&igrave;nh y&ecirc;u c&oacute; đủ để cứu rỗi cả hai?</p>', 2024, NULL, 272, 11, 9, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (2, N'Búp Sen Xanh, Bông Sen Vàng', N'8935279173631', N'Bìa Mềm', CAST(94900.00 AS Decimal(12, 2)), CAST(159000.00 AS Decimal(12, 2)), CAST(146000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/z/6/z6561017314500_aafd0b9fa2adef2c6de6449617ee4c80.jpg', N'Sơn Tùng', N'<p><strong>B&ocirc;ng Sen V&agrave;ng</strong></p>
<p><strong>"B&uacute;p sen xanh"</strong>&nbsp;n&oacute;i về khởi thủy gia đ&igrave;nh v&agrave; qu&atilde;ng đời thơ ấu của Hồ Ch&iacute; Minh cho đến khi ra đi t&igrave;m đường cứu nước;&nbsp;<strong>"B&ocirc;ng sen v&agrave;ng"</strong>, ở diện hẹp hơn cũng n&oacute;i về thời ấu thơ v&agrave; tuổi trẻ của B&aacute;c với t&ecirc;n gọi Nguyễn Sinh C&ocirc;n sống với cha mẹ ở Huế - một trung t&acirc;m văn h&oacute;a, ch&iacute;nh trị thời bấy giờ...</p>
<p>Sở dĩ nh&agrave; văn d&agrave;nh hẳn 1 cuốn tiểu thuyết để đề cập tới qu&atilde;ng đời n&agrave;y bởi, trong nhiều lần đ&agrave;m đạo tại Chiếu Văn Văn Chương với c&aacute;c bạn văn, t&aacute;c giả Sơn T&ugrave;ng đều nhận định:&nbsp;<strong>&ldquo;Đ&acirc;y l&agrave; qu&atilde;ng thời gian rất quan trọng c&oacute; tầm ảnh hưởng lớn đến nh&acirc;n c&aacute;ch v&agrave; tư tưởng của B&aacute;c sau n&agrave;y&rdquo;</strong>.</p>', 2025, NULL, 424, 13, 14, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (3, N'Trường Ca Achilles', N'8935244843545', N'Bìa Mềm', CAST(82875.00 AS Decimal(12, 2)), CAST(156000.00 AS Decimal(12, 2)), CAST(127500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_195509_1_41170.jpg', N'Madeline Miller', N'<h2 dir="ltr">T&Oacute;M TẮT NỘI DUNG S&Aacute;CH</h2>
<p dir="ltr">"Anh sẽ kh&ocirc;ng bao giờ để họ l&agrave;m tổn thương em."</p>
<p dir="ltr">Lấy cảm hứng từ&nbsp;Iliad,&nbsp;Trường Ca Achilles&nbsp;l&agrave; c&acirc;u chuyện về t&igrave;nh y&ecirc;u, danh vọng v&agrave; bi kịch giữa hai con người bị r&agrave;ng buộc bởi số phận.</p>
<p dir="ltr">Patroclus &ndash; ch&agrave;ng ho&agrave;ng tử bị lưu đ&agrave;y, mang trong m&igrave;nh t&acirc;m hồn dịu d&agrave;ng v&agrave; khao kh&aacute;t y&ecirc;u thương. Achilles &ndash; vị chiến binh huyền thoại, người được ti&ecirc;n tri sẽ trở th&agrave;nh anh h&ugrave;ng vĩ đại nhất Hy Lạp. Họ gặp nhau, gắn b&oacute; b&ecirc;n nhau, v&agrave; t&igrave;nh y&ecirc;u nảy nở giữa những ng&agrave;y tuổi trẻ.</p>
<p dir="ltr">"Patroclus, em l&agrave; &aacute;nh s&aacute;ng của đời anh."</p>
<p dir="ltr">Thế nhưng, định mệnh kh&ocirc;ng bao giờ ưu &aacute;i những kẻ y&ecirc;u nhau. Khi chiến tranh th&agrave;nh Troy nổ ra, Achilles buộc phải lựa chọn giữa danh vọng bất tử v&agrave; t&igrave;nh y&ecirc;u duy nhất đời m&igrave;nh. C&ograve;n Patroclus, d&ugrave; biết r&otilde; c&aacute;i chết đang chờ đợi, vẫn t&igrave;nh nguyện ở b&ecirc;n người m&igrave;nh y&ecirc;u.</p>
<p dir="ltr">Dưới ng&ograve;i b&uacute;t l&atilde;ng mạn v&agrave; đầy m&ecirc; hoặc của Madeline Miller,&nbsp;Trường Ca Achilles&nbsp;kh&ocirc;ng chỉ l&agrave; một c&acirc;u chuyện về chiến tranh v&agrave; vinh quang, m&agrave; c&ograve;n l&agrave; một bản t&igrave;nh ca đầy khắc khoải, nơi t&igrave;nh y&ecirc;u vĩnh cửu tỏa s&aacute;ng ngay cả giữa bi kịch đẫm m&aacute;u.</p>
<p dir="ltr">"Ngay cả khi c&aacute;i chết chia cắt ch&uacute;ng ta, anh vẫn sẽ t&igrave;m em."</p>', 2020, NULL, 444, 3, 13, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (4, N'Nhật Ký Đặng Thùy Trâm (Tái Bản 2022)', N'8935235234338', N'Bìa Mềm', CAST(47775.00 AS Decimal(12, 2)), CAST(90000.00 AS Decimal(12, 2)), CAST(73500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935235234338.jpg', N'Đặng Thùy Trâm', N'<h2 class="block-content-product-detail-title">M&ocirc; tả sản phẩm</h2>
<div id="product_tabs_description_contents">
<div id="desc_content" class="std">
<p>Một cuốn nhật k&iacute; nhặt được b&ecirc;n x&aacute;c của một nữ Việt Cộng đ&atilde; su&yacute;t bị người l&iacute;nh Mỹ n&eacute;m v&agrave;o lửa, nhưng người phi&ecirc;n dịch đ&atilde; khuy&ecirc;n anh ta n&ecirc;n giữ lại v&igrave; "trong đ&oacute; c&oacute; lửa". Nhật k&iacute; Đặng Th&ugrave;y Tr&acirc;m l&agrave; những ghi ch&eacute;p h&agrave;ng ng&agrave;y của một người nữ b&aacute;c sĩ về cuộc sống của chị nơi chiến tuyến. Cuốn nhật k&iacute; l&agrave; thế giới ri&ecirc;ng của người tr&iacute; thức nhạy cảm m&agrave; kh&ocirc;ng yếu đuối, tha thiết với cuộc sống m&agrave; kh&ocirc;ng hề sợ h&atilde;i trước những gian nan. Ở đ&oacute; ta vẫn gặp những băn khoăn trăn trở trước t&igrave;nh y&ecirc;u, trước cuộc sống phức tạp h&agrave;ng ng&agrave;y, những nỗi buồn, nỗi nhớ nhung, sự c&ocirc; đơn của một người con g&aacute;i, nhưng đồng thời ch&uacute;ng ta cũng thấy được một &yacute; ch&iacute; m&atilde;nh liệt, những lời n&oacute;i tự động vi&ecirc;n cảnh tỉnh, một l&ograve;ng can đảm phi thường - những điều đ&atilde; l&agrave;m n&ecirc;n một thế hệ anh h&ugrave;ng.</p>
</div>
</div>', 2022, NULL, 296, 9, 13, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (5, N'Nhà Giả Kim (Tái Bản 2020)', N'8935235226272', N'Bìa Mềm', CAST(41925.00 AS Decimal(12, 2)), CAST(79000.00 AS Decimal(12, 2)), CAST(64500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_195509_1_36793.jpg', N'Paulo Coelho', N'<h2 dir="ltr">T&Oacute;M TẮT NỘI DUNG S&Aacute;CH</h2>
<p dir="ltr">Santiago &ndash; một ch&agrave;ng trai chăn cừu trẻ tuổi, rời qu&ecirc; hương để theo đuổi giấc mơ t&igrave;m kho b&aacute;u ở Kim Tự Th&aacute;p Ai Cập. Tr&ecirc;n h&agrave;nh tr&igrave;nh ấy, anh gặp gỡ nhiều người, từ &ocirc;ng vua th&ocirc;ng th&aacute;i, người bu&ocirc;n pha l&ecirc; đến Nh&agrave; Giả Kim huyền b&iacute;.&nbsp;Tất cả những trải nghiệm trong chuyến phi&ecirc;u du theo đuổi vận mệnh của m&igrave;nh đ&atilde; gi&uacute;p Santiago thấu hiểu được &yacute; nghĩa s&acirc;u xa nhất của hạnh ph&uacute;c, h&ograve;a hợp với vũ trụ v&agrave; con người.</p>
<p dir="ltr">Mỗi cuộc gặp gỡ kh&ocirc;ng chỉ gi&uacute;p anh tiến gần hơn đến kho b&aacute;u m&agrave; c&ograve;n gi&uacute;p anh hiểu được mục đ&iacute;ch thật sự của đời m&igrave;nh:&nbsp;</p>
<p dir="ltr"><em>Tr&iacute;ch Nh&agrave; giả Kim: "Kho b&aacute;u kh&ocirc;ng nằm ở nơi ta đến, m&agrave; nằm trong ch&iacute;nh h&agrave;nh tr&igrave;nh ta đi."</em></p>', 2020, NULL, 227, 18, 12, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (6, N'Doraemon - Tiểu Thuyết - Nobita Và Cuộc Phiêu Lưu Vào Thế Giới Trong Tranh', N'9786042252997', N'Bìa Mềm', CAST(35100.00 AS Decimal(12, 2)), CAST(60000.00 AS Decimal(12, 2)), CAST(54000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/d/o/doraemon-tieu-thuyet_nobita-va-ban-giao-huong-dia-cau_bia_2.jpg', N'Fujiko F Fujio, Satoshi Ito, Yukiyo Teramoto', N'<p><strong>Doraemon - Tiểu Thuyết - Nobita V&agrave; Cuộc Phi&ecirc;u Lưu V&agrave;o Thế Giới Trong Tranh</strong></p>
<p>Khi cả thế giới x&ocirc;n xao về bức tranh cổ trị gi&aacute; h&agrave;ng chục tỉ y&ecirc;n mới được ph&aacute;t hiện th&igrave; Nobita đang cặm cụi vẽ b&agrave;i mĩ thuật được giao trong k&igrave; nghỉ h&egrave;. Bỗng, một mảnh tranh lạ k&igrave; h&igrave;nh miếng chả c&aacute; từ đ&acirc;u rơi tr&uacute;ng đầu cậu. Cậu t&ograve; m&ograve;, d&ugrave;ng bảo bối đ&egrave;n dẫn v&agrave;o tranh để kh&aacute;m ph&aacute;, v&agrave; trong tranh, cậu gặp c&ocirc; b&eacute; Claire b&iacute; ẩn. Cuộc gặp mở ra một chuyến phi&ecirc;u lưu v&ocirc; tiền kho&aacute;ng hậu. Bất ngờ thay, C&ocirc;ng quốc Artoria xinh đẹp m&agrave; nh&oacute;m bạn đặt ch&acirc;n đến ch&iacute;nh l&agrave; thế giới Trung Cổ trong bức tranh qu&yacute; đang g&acirc;y chấn động! Dường như, truyền thuyết h&atilde;i h&ugrave;ng về ng&agrave;y tận thế m&agrave; người d&acirc;n nơi đ&acirc;y truyền tụng đang dần trở th&agrave;nh hiện thực. Liệu nh&oacute;m bạn c&oacute; thể xoay chuyển vận mệnh, ph&aacute; bỏ lời sấm v&agrave; giải cứu thế giới trong tranh?</p>', 2025, NULL, 240, 8, 14, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (7, N'Lén Nhặt Chuyện Đời', N'9786043651591', N'Bìa Mềm', CAST(28730.00 AS Decimal(12, 2)), CAST(85000.00 AS Decimal(12, 2)), CAST(44200.00 AS Decimal(12, 2)), N'https://res.cloudinary.com/dabxzdaf8/image/upload/v1748965387/Book_cover/jlimhqpgskoazyai8pwg.webp', N'Mộc Trầm', N'<p><strong>L&eacute;n Nhặt Chuyện Đời</strong></p>
<p>Tại v&ugrave;ng ngoại &ocirc; xứ Đan Mạch xưa, người thợ kim ho&agrave;n Per Enevoldsen đ&atilde; cho ra mắt một m&oacute;n đồ trang sức lấy &yacute; tưởng từ Pandora - người phụ nữ đầu ti&ecirc;n của nh&acirc;n loại mang vẻ đẹp như một ngọc nữ ph&ugrave; dung, ki&ecirc;u sa v&agrave; b&iacute; ẩn trong Thần thoại Hy Lạp. V&ograve;ng Pandora được kết hợp từ một sợi d&acirc;y bằng v&agrave;ng, bạc hoặc bằng da c&ugrave;ng với những vi&ecirc;n charm được chế t&aacute;c đa dạng, tỉ mỉ. &Yacute; tưởng của &ocirc;ng, mỗi vi&ecirc;n charm như một c&acirc;u chuyện, một kỷ niệm đ&aacute;ng nhớ của người sở hữu chiếc v&ograve;ng. Khi một vi&ecirc;n charm được th&ecirc;m v&agrave;o sợi Pandora l&agrave; cuộc đời lại c&oacute; th&ecirc;m một k&yacute; ức cần lưu lại để nhớ, để thương, để tr&acirc;n trọng. L&eacute;n nhặt chuyện đời ra mắt trong khoảng thời gian ch&ocirc;ng ch&ecirc;nh nhất của bản th&acirc;n, hay n&oacute;i c&aacute;ch kh&aacute;c l&agrave; một cậu b&eacute; mới lớn, vừa bước ra khỏi c&aacute;i vỏ bọc vốn an to&agrave;n của m&igrave;nh. Những c&acirc;u chuyện trong L&eacute;n nhặt chuyện đời l&agrave; những c&acirc;u chuyện t&ocirc;i được nghe kể lại, hoặc v&ocirc; t&igrave;nh bắt gặp, hoặc nhặt nhạnh ở đ&acirc;u đ&oacute; trong miền k&yacute; ức rời rạc của qu&aacute; khứ, kh&ocirc;ng theo một tr&igrave;nh tự hay một thời gian n&agrave;o nhất định.</p>
<p>Mỗi một c&acirc;u chuyện l&agrave; một vi&ecirc;n charm lấp l&aacute;nh, ki&ecirc;u kỳ, c&oacute; sức h&uacute;t mạnh mẽ đối với một người trẻ như t&ocirc;i lu&ocirc;n t&ograve; m&ograve; với những điều dung dị trong cuộc sống. T&ocirc;i &acirc;m thầm nhặt những vi&ecirc;n charm ấy về, kết th&agrave;nh sợi Pandora cho ch&iacute;nh m&igrave;nh. L&eacute;n ở đ&acirc;y kh&ocirc;ng phải l&agrave; một c&aacute;i g&igrave; đ&oacute; vụng trộm, &acirc;m thầm sợ người kh&aacute;c ph&aacute;t hiện. M&agrave; n&oacute; l&agrave; lặng lẽ. T&ocirc;i lặng lẽ nghe, lặng lẽ quan s&aacute;t, lặng lẽ đi t&igrave;m v&agrave; lặng lẽ viết n&ecirc;n quyển s&aacute;ch n&agrave;y. T&ocirc;i vẫn th&iacute;ch d&ugrave;ng từ L&eacute;n hơn, v&igrave; đơn giản, t&ocirc;i thấy bản th&acirc;n m&igrave;nh trong đ&oacute;. L&eacute;n nhặt chuyện đời được chia th&agrave;nh năm chương: chương thứ nhất n&oacute;i về t&igrave;nh y&ecirc;u của cả giới trẻ v&agrave; người tu sĩ; chương thứ hai viết về gia đ&igrave;nh; chương thứ ba d&agrave;nh cho những người trẻ; chương thứ tư l&agrave; những c&acirc;u chuyện b&ecirc;n đời, những b&agrave;i t&acirc;m sự của người tu sĩ; chương năm l&agrave; thơ v&agrave; chương cuối c&ugrave;ng l&agrave; t&acirc;m sự của bản th&acirc;n khi t&ocirc;i đ&atilde; về gi&agrave;. Nếu ai nghĩ L&eacute;n nhặt chuyện đời sẽ giảng thuyết về ch&acirc;n l&yacute;, định hướng cho người trẻ hay chữa l&agrave;nh những vết thương&hellip; th&igrave; đ&atilde; t&igrave;m sai chỗ, bản th&acirc;n chưa bao giờ nghĩ quyển s&aacute;ch n&agrave;y sẽ l&agrave;m được điều đ&oacute;.</p>
<p>Đ&acirc;y chỉ l&agrave; những c&acirc;u chuyện, những suy nghĩ về cuộc đời của một người trẻ đang ch&ocirc;ng ch&ecirc;nh. Đ&ocirc;i khi, t&ocirc;i h&oacute;a th&agrave;nh một &ocirc;ng gi&agrave; của năm chục năm sau kể về những k&yacute; ức thời vụng dại. Chỉ mong sao, đọc L&eacute;n nhặt chuyện đời, người ta c&oacute; thể t&igrave;m được đ&acirc;u đ&oacute; những vi&ecirc;n charm ph&ugrave; hợp với bản th&acirc;n m&igrave;nh. Quyển s&aacute;ch n&agrave;y sẽ l&agrave; dấu ấn lớn nhất đối với cuộc đời của bản th&acirc;n. Mỗi b&agrave;i viết l&agrave; một vi&ecirc;n charm của Pandora L&eacute;n nhặt chuyện đời v&agrave; L&eacute;n nhặt chuyện đời cũng sẽ l&agrave; một vi&ecirc;n charm lấp l&aacute;nh trong sợi Pandora của cuộc đời t&ocirc;i. Quyển s&aacute;ch n&agrave;y, xin được nhớ về những người Thầy của t&ocirc;i, về Từ Quang, về gia đ&igrave;nh, v&agrave; tất cả những ai đ&atilde; hiện diện trong thời thanh xu&acirc;n của t&ocirc;i. Để nhắc rằng, t&ocirc;i đ&atilde; từng c&oacute; mặt trong cuộc đời của họ, v&agrave; họ c&oacute; mặt trong quyển s&aacute;ch n&agrave;y của t&ocirc;i.</p>', 2022, NULL, 213, 12, 1, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (8, N'Cây Cam Ngọt Của Tôi', N'8935235228351', N'Bìa Mềm', CAST(57525.00 AS Decimal(12, 2)), CAST(108000.00 AS Decimal(12, 2)), CAST(88500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_217480.jpg', N'José Mauro de Vasconcelos', N'<h3 dir="ltr"><strong>T&Oacute;M TẮT NỘI DUNG S&Aacute;CH</strong></h3>
<p dir="ltr">Nếu tuổi thơ l&agrave; một m&oacute;n qu&agrave;, th&igrave; với Zez&eacute;, đ&oacute; l&agrave; một m&oacute;n qu&agrave; c&oacute; cả vị ngọt lẫn đắng.</p>
<p dir="ltr">Zez&eacute; - một cậu b&eacute; ngh&egrave;o năm tuổi tại Brazil, th&ocirc;ng minh, l&eacute;m lỉnh nhưng lu&ocirc;n bị gia đ&igrave;nh xem như một đứa trẻ hư. Những tr&ograve; nghịch ngợm của cậu thường bị trừng phạt bằng đ&ograve;n roi, nhưng ai biết rằng đằng sau đ&oacute; l&agrave; một tr&aacute;i tim khao kh&aacute;t y&ecirc;u thương?</p>
<p dir="ltr">Người bạn duy nhất lu&ocirc;n lắng nghe cậu ch&iacute;nh l&agrave; c&acirc;y cam ngọt nhỏ b&eacute; trong vườn, nơi cậu c&oacute; thể gửi gắm những b&iacute; mật v&agrave; nỗi buồn của m&igrave;nh. Rồi một ng&agrave;y, Zez&eacute; gặp &ocirc;ng Portuga - một người đ&agrave;n &ocirc;ng xa lạ nhưng lại l&agrave; &aacute;nh s&aacute;ng dịu d&agrave;ng đầu ti&ecirc;n trong cuộc đời đầy b&atilde;o tố của cậu b&eacute;. &Ocirc;ng dạy cậu về l&ograve;ng nh&acirc;n &aacute;i, về t&igrave;nh y&ecirc;u thương v&ocirc; điều kiện - thứ m&agrave; Zez&eacute; lu&ocirc;n khao kh&aacute;t nhưng chưa từng c&oacute; được.</p>
<p dir="ltr">Nhưng rồi, số phận kh&ocirc;ng cho ph&eacute;p Zez&eacute; giữ m&atilde;i những hạnh ph&uacute;c nhỏ nhoi đ&oacute;&hellip;</p>
<p dir="ltr">C&acirc;y Cam Ngọt Của T&ocirc;i kh&ocirc;ng chỉ l&agrave; c&acirc;u chuyện của một cậu b&eacute; &ndash; đ&oacute; c&ograve;n l&agrave; bức tranh về những nỗi đau v&ocirc; h&igrave;nh của tuổi thơ, về sự khắc nghiệt của cuộc sống nhưng cũng đầy những tia s&aacute;ng hy vọng.</p>', 2020, NULL, 244, 19, 1, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (9, N'Người Đàn Ông Mang Tên OVE (Tái Bản)', N'8934974182375', N'Bìa Mềm', CAST(87100.00 AS Decimal(12, 2)), CAST(160000.00 AS Decimal(12, 2)), CAST(134000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8934974182375.jpg', N'Fredrik Backman', N'<h3 dir="ltr">T&Oacute;M TẮT NỘI DUNG S&Aacute;CH</h3>
<p dir="ltr">Ove l&agrave; một người đ&agrave;n &ocirc;ng 59 tuổi, sống một cuộc đời nghi&ecirc;m t&uacute;c, theo nguy&ecirc;n tắc v&agrave; kh&ocirc;ng th&iacute;ch thay đổi. &Ocirc;ng cộc cằn, kh&oacute; gần, thậm ch&iacute; c&oacute; vẻ đ&aacute;ng gh&eacute;t. Nhưng s&acirc;u b&ecirc;n trong, Ove l&agrave; một người đ&agrave;n &ocirc;ng mang nhiều nỗi đau, đặc biệt l&agrave; sau khi mất đi người vợ y&ecirc;u dấu.</p>
<p dir="ltr">Cuộc sống của Ove đảo lộn khi một gia đ&igrave;nh trẻ chuyển đến b&ecirc;n cạnh nh&agrave; &ocirc;ng v&agrave; sự xuất hiện của con m&egrave;o hoang. Họ v&ocirc; t&igrave;nh &ldquo;x&acirc;m nhập&rdquo; v&agrave;o cuộc sống đơn độc của &ocirc;ng, k&eacute;o theo những t&igrave;nh huống dở kh&oacute;c dở cười. Dần dần,&nbsp;tấm l&ograve;ng nh&acirc;n hậu của Ove được h&eacute; lộ, chứng minh rằng ngay cả những người kh&eacute;p k&iacute;n nhất cũng c&oacute; thể mở l&ograve;ng khi gặp đ&uacute;ng người.</p>
<p dir="ltr">Cuốn s&aacute;ch n&agrave;y cũng đ&atilde; được chuyển thể th&agrave;nh bộ phim đ&igrave;nh đ&aacute;m với sự tham gia của Tom Hanks, đ&atilde; được đề cử ở hạng mục phim n&oacute;i tiếng nước ngo&agrave;i hay nhất tại Oscar 2017.</p>', 2022, NULL, 452, 11, 12, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (10, N'Hà Thanh Hải Yến - Ngang Qua Ngõ Nhỏ Bình An', N'8936213491613', N'Bìa Mềm', CAST(97825.00 AS Decimal(12, 2)), CAST(196000.00 AS Decimal(12, 2)), CAST(150500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/b/_/b_a-_o-h_-thanh-h_i-y_n_b_a-tr_c.jpg', N'Quất Tử Bất Toan', N'<p><strong>H&agrave; Thanh Hải Yến - Ngang Qua Ng&otilde; Nhỏ B&igrave;nh An</strong></p>
<p>Bị bố đ&aacute;nh đập d&atilde; man, bị bạn học bắt nạt, trong l&uacute;c tuyệt vọng c&ugrave;ng quẫn, t&ocirc;i t&igrave;m đến tiệm xăm trong g&oacute;c ng&otilde;.</p>
<p>Nghe n&oacute;i &ocirc;ng chủ l&agrave; một t&ecirc;n c&ocirc;n đồ, rất hung h&atilde;n v&agrave; dữ dằn, người xung quanh đều e sợ anh.</p>
<p>Đẩy cửa, t&ocirc;i moi từ trong t&uacute;i ra một tờ mười tệ nh&agrave;u nhĩ, lấy hết dũng kh&iacute; hỏi:</p>
<p>&ldquo;Nghe n&oacute;i anh thu ph&iacute; bảo k&ecirc;, vậy anh... c&oacute; thể bảo vệ t&ocirc;i kh&ocirc;ng?&rdquo;</p>
<p>Giữa l&agrave;n kh&oacute;i thuốc lượn lờ, người đ&agrave;n &ocirc;ng nhếch m&ocirc;i ph&igrave; cười.</p>
<p>&ldquo;Nh&oacute;c con nh&agrave; ai đ&acirc;y? To gan thật đấy.&rdquo;</p>
<p>Sau n&agrave;y, anh chỉ v&igrave; tờ mười tệ ấy m&agrave; bảo vệ t&ocirc;i suốt mười năm.</p>', 2024, NULL, 324, 6, 11, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (11, N'BộNếu Biết Trăm Năm Là Hữu Hạn - Ấn Bản Kỉ Niệm 10 Năm Xuất Bản (Tái Bản 2024)', N'8932000134749', N'Bìa Mềm', CAST(89700.00 AS Decimal(12, 2)), CAST(159000.00 AS Decimal(12, 2)), CAST(138000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8932000134749_1.jpg', N'Phạm Lữ Ân', N'<h2 dir="ltr">T&Oacute;M TẮT NỘI DUNG S&Aacute;CH</h2>
<p dir="ltr">Nếu Biết Trăm Năm L&agrave; Hữu Hạn&nbsp;l&agrave; tập hợp 40 b&agrave;i viết nhẹ nh&agrave;ng nhưng s&acirc;u sắc, gi&agrave;u cảm x&uacute;c từ chuy&ecirc;n mục&nbsp;Cảm thức&nbsp;của&nbsp;B&aacute;n nguyệt san Sinh Vi&ecirc;n Việt Nam. Cuốn s&aacute;ch dẫn dắt người đọc đi s&acirc;u v&agrave;o những cảm nhận về cuộc đời, t&igrave;nh y&ecirc;u, t&igrave;nh bạn v&agrave; sự th&agrave;nh bại, đặt ra những c&acirc;u hỏi m&agrave; ai cũng từng nghĩ đến nhưng &iacute;t ai d&aacute;m đối diện:</p>
<ul>
<li dir="ltr">
<p dir="ltr">Ch&uacute;ng ta đang sống hay chỉ đang tồn tại?</p>
</li>
<li dir="ltr">
<p dir="ltr">Hạnh ph&uacute;c thực sự nằm ở đ&acirc;u?</p>
</li>
<li dir="ltr">
<p dir="ltr">Điều g&igrave; sẽ khiến ch&uacute;ng ta kh&ocirc;ng hối tiếc khi nh&igrave;n lại?</p>
</li>
</ul>
<p dir="ltr">Với giọng văn dung dị, th&acirc;n mật, t&aacute;c giả dễ d&agrave;ng chạm đến tr&aacute;i tim người đọc, khiến ta như đang lắng nghe một người bạn t&acirc;m sự. Những c&acirc;u chuyện giản dị nhưng chứa nhiều tầng cảm x&uacute;c: ho&agrave;i niệm, s&acirc;u sắc, ch&acirc;n th&agrave;nh - gợi mở những suy ngẫm mới mẻ về gi&aacute; trị của từng khoảnh khắc trong cuộc đời.</p>
<p dir="ltr">Cuốn s&aacute;ch kh&ocirc;ng chỉ l&agrave; một t&aacute;c phẩm văn học m&agrave; c&ograve;n l&agrave; một lời nhắc nhở nhẹ nh&agrave;ng: Thời gian l&agrave; hữu hạn, h&atilde;y sống sao cho xứng đ&aacute;ng!</p>', 2024, NULL, 263, 13, 5, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (12, N'Trốn Lên Mái Nhà Để Khóc - Tặng Kèm Bookmark', N'8935325015984', N'Bìa Mềm', CAST(49400.00 AS Decimal(12, 2)), CAST(95000.00 AS Decimal(12, 2)), CAST(76000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/b/_/b_a-1-tr_n-l_n-m_i-nh_-_-kh_c-2.jpg', N'Lam', N'<h2 dir="ltr">T&oacute;m tắt nội dung s&aacute;ch&nbsp;</h2>
<p dir="ltr">M&aacute;i nh&agrave; &ndash; nơi cao nhất trong căn nh&agrave; nhưng lại l&agrave; nơi s&acirc;u nhất trong t&acirc;m hồn một đứa trẻ. Ở đ&oacute;, Lam đ&atilde; lắng nghe nhịp thở của qu&aacute; khứ, nơi c&oacute; giọng n&oacute;i của mẹ, b&agrave;n tay của b&agrave;, những k&yacute; ức đẹp đẽ xen lẫn những nỗi đau kh&oacute; gọi t&ecirc;n.</p>
<p>&nbsp;</p>
<p dir="ltr">"Lớn l&ecirc;n, t&ocirc;i nhận ra m&aacute;i nh&agrave; kh&ocirc;ng phải nơi tr&uacute; ẩn, m&agrave; l&agrave; nơi để chuẩn bị cho những h&agrave;nh tr&igrave;nh tiếp theo. Nhưng đ&ocirc;i khi, t&ocirc;i vẫn muốn trốn l&ecirc;n đ&oacute;, để được kh&oacute;c m&agrave; kh&ocirc;ng ai nh&igrave;n thấy."</p>
<p dir="ltr">Cuốn s&aacute;ch l&agrave; những d&ograve;ng t&acirc;m sự ch&acirc;n thật, một h&agrave;nh tr&igrave;nh quay về thời thơ ấu để t&igrave;m kiếm ch&iacute;nh m&igrave;nh.</p>', 2023, NULL, 208, 21, 7, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (13, N'Tôi Thích Dáng Vẻ Nỗ Lực Của Chính Mình', N'9786044059761', N'Bìa Mềm', CAST(49400.00 AS Decimal(12, 2)), CAST(99000.00 AS Decimal(12, 2)), CAST(76000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/4/0/40eebd4668f7f312da5486d5804cc24e.jpg', N'Lily Trương', N'<p><strong>GIỚI THIỆU T&Aacute;C PHẨM:</strong></p>
<p>NẾU &Ocirc;NG TRỜI KH&Ocirc;NG BAN CHO BẠN SỰ MAY MẮN, VẬY H&Atilde;Y TỰ BIẾN BẢN TH&Acirc;N M&Igrave;NH TH&Agrave;NH &ldquo;KỲ T&Iacute;CH&rdquo;</p>
<p>- C&oacute; phải bạn lu&ocirc;n thắc mắc tại sao sau rất nhiều nỗ lực, m&igrave;nh vẫn chưa c&oacute; được sự tiến bộ m&agrave; bản th&acirc;n hằng mong đợi?</p>
<p>- C&oacute; phải bạn vẫn nghi ngờ rằng bản th&acirc;n đang &ldquo;giậm ch&acirc;n tại chỗ&rdquo; v&agrave; ng&agrave;y m&igrave;nh chạm v&agrave;o ước mơ c&oacute; thể sẽ chẳng bao giờ đến?</p>
<p>- C&oacute; phải bạn cho rằng m&igrave;nh đ&atilde; cố gắng rất nhiều, nhưng cuối c&ugrave;ng lại kh&ocirc;ng bằng một phần nhỏ sự may mắn của người kh&aacute;c?</p>
<p>Vậy h&atilde;y lắng nghe lời chia sẻ đầy &yacute; nghĩa của t&aacute;c giả Lily Trương trong cuốn s&aacute;ch &ldquo;T&ocirc;i th&iacute;ch d&aacute;ng vẻ nỗ lực của ch&iacute;nh m&igrave;nh&rdquo;.</p>
<p>&ldquo;Kho&aacute;ng vật muốn th&agrave;nh kim cương cũng phải chịu một sức n&oacute;ng đỉnh điểm 1200 độ. S&acirc;u phải lột x&aacute;c để ho&aacute; bướm, phượng ho&agrave;ng phải chịu đau đớn để t&aacute;i sinh. Bất cứ cao thủ n&agrave;o cũng cần phải trải qua khoảng thời gian thử th&aacute;ch kh&oacute; khăn. Kh&ocirc;ng phải ai sinh ra cũng c&oacute; t&agrave;i năng thi&ecirc;n bẩm v&agrave; sẽ chẳng ai c&oacute; thể lu&ocirc;n gặp may mắn. Tiếp tục ki&ecirc;n tr&igrave;, chăm chỉ, bạn sẽ biến m&igrave;nh trở th&agrave;nh kỳ t&iacute;ch.&rdquo;</p>
<p>Được chắp b&uacute;t bởi một trong những t&aacute;c giả trẻ t&agrave;i năng - Lily Trương, &ldquo;T&ocirc;i th&iacute;ch d&aacute;ng vẻ nỗ lực của ch&iacute;nh m&igrave;nh&rdquo; hứa hẹn sẽ trở th&agrave;nh người bạn tri kỷ lu&ocirc;n tiếp th&ecirc;m động lực để bạn nu&ocirc;i dưỡng ước mơ v&agrave; kh&aacute;m ph&aacute; tri thức. H&atilde;y nhớ rằng muốn đứng được ở nơi m&agrave; người kh&aacute;c kh&ocirc;ng đứng được, bạn phải chịu được những &aacute;p lực m&agrave; người thường kh&ocirc;ng thể chịu được.</p>', 2024, NULL, 208, 21, 14, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (14, N'Đám Trẻ Ở Đại Dương Đen', N'8935325011559', N'Bìa Mềm', CAST(49400.00 AS Decimal(12, 2)), CAST(99000.00 AS Decimal(12, 2)), CAST(76000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935325011559.jpg', N'Châu Sa Đáy Mắt', N'<h2 dir="ltr">T&Oacute;M TẮT NỘI DUNG S&Aacute;CH</h2>
<p dir="ltr">Trong một đại dương kh&ocirc;ng c&oacute; s&oacute;ng, chỉ c&oacute; những tầng u &aacute;m của nỗi buồn đang lặng lẽ d&igrave;m chết nội t&acirc;m - những đứa trẻ hiện ra, kh&ocirc;ng t&ecirc;n, kh&ocirc;ng m&agrave;u, kh&ocirc;ng cả quyền được ồn &agrave;o.</p>
<p dir="ltr">Ch&uacute;ng l&agrave; ai? L&agrave; những t&acirc;m hồn non nớt bị bỏ rơi bởi ch&iacute;nh nơi gọi l&agrave; "nh&agrave;". L&agrave; những đứa trẻ kh&ocirc;ng được quyền lựa chọn sự xuất hiện của m&igrave;nh trong cuộc đời n&agrave;y - v&agrave; đang tự bơi giữa d&ograve;ng nước đen của tổn thương, của c&ocirc; độc, của c&acirc;u hỏi kh&ocirc;ng lời giải: "V&igrave; sao m&igrave;nh lại ở đ&acirc;y?"</p>
<p dir="ltr">Kh&ocirc;ng giật g&acirc;n, kh&ocirc;ng g&agrave;o th&eacute;t, cuốn s&aacute;ch l&agrave; một h&agrave;nh tr&igrave;nh của lặng im nhưng kh&aacute;ng cự, của đau nhưng kh&ocirc;ng đầu h&agrave;ng. Những đoạn độc thoại như lời th&igrave; thầm từ vực s&acirc;u, những mảnh k&yacute; ức rời rạc tưởng như sẽ ch&igrave;m m&atilde;i dưới đ&aacute;y&hellip; bỗng trồi l&ecirc;n th&agrave;nh tiếng n&oacute;i - của một thế hệ trẻ đang đi t&igrave;m &aacute;nh s&aacute;ng nhỏ nhất trong biển đ&ecirc;m.</p>', 2023, NULL, 280, 7, 14, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (15, N'Mẹ Làm Gì Có Ước Mơ', N'8935325011047', N'Bìa Mềm', CAST(44525.00 AS Decimal(12, 2)), CAST(89000.00 AS Decimal(12, 2)), CAST(68500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/9/8/98bde27a91ea4bb412fb.jpg', N'Hạ Mer', N'<p>&ldquo;Ước mơ của mẹ l&agrave; g&igrave;?&rdquo;</p>
<p>&ldquo;Th&igrave; cho ch&uacute;ng m&agrave;y ăn học đ&agrave;ng ho&agrave;ng, đầy đủ để mai sau đỡ khổ.&rdquo;</p>
<p>&ldquo;Kh&ocirc;ng, ước mơ kh&aacute;c cơ.&rdquo;</p>
<p>&ldquo;Mai sau ch&uacute;ng m&agrave;y lập gia đ&igrave;nh, chọn được đ&uacute;ng người, vợ chồng y&ecirc;u thương nhau.&rdquo;</p>
<p>&ldquo;Ước mơ d&agrave;nh ri&ecirc;ng cho bản th&acirc;n mẹ cơ m&agrave;.&rdquo;</p>
<p><strong>&ldquo;MẸ TH&Igrave; L&Agrave;M G&Igrave; C&Oacute; ƯỚC MƠ.&rdquo;</strong></p>
<p>Bạn c&oacute; bao giờ hỏi ước mơ của bố mẹ l&agrave; g&igrave;? Hoặc d&ugrave; c&oacute; hỏi bố mẹ cũng chỉ trả lời qua loa như &ldquo;L&agrave;m g&igrave; c&oacute;&hellip;&rdquo;. Nhưng bạn biết kh&ocirc;ng, l&agrave;m g&igrave; c&oacute; ai tr&ecirc;n thế giới n&agrave;y kh&ocirc;ng c&oacute; ước mơ cơ chứ, chỉ l&agrave; ước mơ của bố mẹ ch&uacute;ng ta được cất giấu rất s&acirc;u trong tim v&agrave; đ&aacute;nh đổi bằng nụ cười của những đứa con m&agrave; th&ocirc;i.</p>
<p>Tại sao mẹ lại chẳng c&oacute; nổi một ước mơ cho ri&ecirc;ng m&igrave;nh? Phải chăng g&aacute;nh vai mẹ đ&atilde; qu&aacute; mỏi mệt với cơm &aacute;o gạo tiền, với những bữa ăn v&agrave; học ph&iacute; của con.</p>
<p>&Agrave; kh&ocirc;ng, mẹ c&oacute; ước mơ đấy chứ. Mẹ ước mơ c&oacute; một người bố, rồi mẹ cho n&oacute; cả một gia đ&igrave;nh. Mẹ ước mơ được tới trường, n&ecirc;n mẹ cho n&oacute; học con chữ. Mẹ ước mơ được một bữa no, n&ecirc;n dẫu c&oacute; phải đi l&agrave;m vất vả khổ cực đến đ&acirc;u mẹ cũng cho n&oacute; được bữa cơm ngon. Chỉ kh&aacute;c một điều, ước mơ của mẹ l&agrave; c&aacute;c con mất rồi.</p>
<p>Đ&oacute; l&agrave; h&igrave;nh ảnh của MẸ m&agrave; bạn sẽ bắt gặp trong &ldquo;Mẹ l&agrave;m g&igrave; c&oacute; ước mơ&rdquo;. Tựa một thước phim quay chậm đưa bạn trở lại những ng&agrave;y b&eacute; thơ, dưới v&ograve;ng tay chai sạn nhưng đầy ấm &aacute;p của mẹ. Khi tạm cất ước mơ của m&igrave;nh sang một b&ecirc;n, ước mơ của mẹ &ldquo;h&oacute;a ra con từ bao giờ&rdquo; v&agrave; &ldquo;thế giới của mẹ ch&iacute;nh l&agrave; con&rdquo;. Bố mẹ đ&atilde; dồn hết khả năng của m&igrave;nh, d&agrave;nh cho con những g&igrave; tốt nhất để con được thực hiện ước mơ.</p>
<p>Ch&uacute;ng ta đừng chỉ mải chạy theo ước mơ của m&igrave;nh m&agrave; qu&ecirc;n mất những người đ&atilde; hy sinh cả cuộc đời để m&igrave;nh c&oacute; cơ hội thực hiện ước mơ ấy. C&oacute; thể gọi điện về nh&agrave; thường xuy&ecirc;n hơn, hoặc nếu c&oacute; thể, h&atilde;y trở về nh&agrave; nếu đ&atilde; đi đủ l&acirc;u. Đ&oacute; l&agrave; những điều m&agrave; Hạ Mer muốn gửi gắm đến bạn qua &ldquo;Mẹ l&agrave;m g&igrave; c&oacute; ước mơ&rdquo;.</p>
<p>Hy vọng cuốn s&aacute;ch sẽ gi&uacute;p bạn th&ecirc;m tr&acirc;n qu&yacute; từng khoảnh khắc b&ecirc;n cạnh những người m&agrave; m&igrave;nh y&ecirc;u thương.</p>', 2023, NULL, 208, 20, 9, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (16, N'Tiếng Gọi Chân Trời', N'8934974207917', N'Bìa Mềm', CAST(43550.00 AS Decimal(12, 2)), CAST(95000.00 AS Decimal(12, 2)), CAST(67000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8934974207917.jpg', N'Nguyễn Ngọc Tư', N'https://www.fahasa.com/tieng-goi-chan-troi.html?fhs_campaign=CATEGORY', 2025, NULL, 152, 5, 8, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (17, N'Nơi Nào Có Mẹ - Nơi Ấy Là Nhà - Tặng Kèm Bookmark', N'8935325019395', N'Bìa Mềm', CAST(44850.00 AS Decimal(12, 2)), CAST(90000.00 AS Decimal(12, 2)), CAST(69000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/z/5/z5288994344245_f98249489626ef768c679043558bebee.jpg', N'Hạ Mer', N'<p><strong>Nơi N&agrave;o C&oacute; Mẹ - Nơi Ấy L&agrave; Nh&agrave;</strong></p>
<p>Tr&ecirc;n đời n&agrave;y, sẽ chẳng c&oacute; ai v&igrave; bạn quan t&acirc;m m&agrave; hỏi &ldquo;Dạo n&agrave;y con l&agrave;m g&igrave;, dạo n&agrave;y con c&oacute; đủ tiền kh&ocirc;ng, dạo n&agrave;y con c&oacute; ăn uống đầy đủ kh&ocirc;ng?&rdquo;... ngoại trừ MẸ của bạn.</p>
<p>Tr&ecirc;n đời n&agrave;y, sẽ chẳng c&oacute; ai sẵn s&agrave;ng mua những thứ tốt nhất cho bạn d&ugrave; họ c&oacute; thể cả năm kh&ocirc;ng mua lấy một bộ quần &aacute;o mới&hellip; ngoại trừ MẸ của bạn.</p>
<p>Tr&ecirc;n đời n&agrave;y, sẽ chẳng c&oacute; ai cho bạn những bữa ăn miễn ph&iacute;, y&ecirc;u thương bạn v&ocirc; điều kiện&hellip;ngoại trừ MẸ của bạn.</p>
<p>Đ&uacute;ng thật l&agrave; &ldquo;thế gian rộng lớn, c&oacute; mẹ l&agrave; đủ&rdquo;, nơi ch&uacute;ng ta muốn quay trở về để được chữa l&agrave;nh, được an ủi. D&ugrave; cả thế giới c&oacute; bỏ mặc bạn, vẫn d&aacute;m chắc chắn một điều, trong l&ograve;ng mẹ, bạn ch&iacute;nh l&agrave; cả thế giới.</p>
<p>NƠI N&Agrave;O C&Oacute; MẸ, NƠI ẤY L&Agrave; NH&Agrave; l&agrave; lời nhắn m&agrave; t&aacute;c giả Hạ Mer gửi đến tất cả ch&uacute;ng ta: Khi bạn t&igrave;m ho&agrave;i chẳng thấy hạnh ph&uacute;c, về nh&agrave; đi! Nơi c&oacute; Mẹ, c&oacute; một m&acirc;m cơm ấm, một v&ograve;ng tay &ecirc;m, một g&oacute;c s&acirc;n nhỏ. Nơi c&oacute; mẹ tựa một gốc đại thụ che trời, lu&ocirc;n đ&oacute;ng vai trầm mặc, che gi&oacute;, che mưa cho bạn, sẵn s&agrave;ng hy sinh mọi thứ m&agrave; kh&ocirc;ng cần hồi đ&aacute;p.</p>
<p>Cuốn s&aacute;ch n&agrave;y kh&ocirc;ng c&oacute; triết l&yacute; hay b&agrave;i học cao si&ecirc;u g&igrave; cả, ở đ&acirc;y chỉ c&oacute; những mẩu chuyện</p>
<p>nho nhỏ m&agrave; t&aacute;c giả Hạ Mer g&oacute;p nhặt từ những năm th&aacute;ng tuổi thơ cho tới l&uacute;c trải nghiệm v&agrave; trưởng th&agrave;nh giữa cuộc đời rộng lớn. Mong rằng những con chữ n&agrave;y sẽ gi&uacute;p &iacute;ch g&igrave; đ&oacute; cho bạn hoặc bạn sẽ bắt gặp h&igrave;nh ảnh của bản th&acirc;n m&igrave;nh trong đ&oacute;.</p>
<p>&ldquo;- Mẹ ơi, con sắp l&ecirc;n xe rồi, chắc khoảng hai, ba tiếng nữa l&agrave; về đến nh&agrave;. Mẹ l&agrave;m dưa x&agrave;o, canh chuối đậu với mua mận cho con nh&eacute;.</p>
<p>- Mẹ biết rồi, bao giờ về gần đến nơi th&igrave; gọi mẹ ra đ&oacute;n.&rdquo;</p>
<p>- V&acirc;ng ạ.&rdquo;</p>
<p>Hy vọng rằng khi cầm tr&ecirc;n tay cuốn s&aacute;ch n&agrave;y, đọc từng mẩu chuyện nhỏ c&oacute; thể gi&uacute;p bạn vui vẻ, hạnh ph&uacute;c hơn v&agrave; những vết thương trong t&acirc;m hồn từ thời thơ ấu sẽ được chữa l&agrave;nh.</p>', 2024, NULL, 192, 20, 8, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (18, N'Món Hàng Hiệu Mang Tên “Tôi”', N'8935325026447', N'Bìa Mềm', CAST(57525.00 AS Decimal(12, 2)), CAST(115000.00 AS Decimal(12, 2)), CAST(88500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/b/i/bia_mon-hang-hieu-mang-ten-toi_nguoi-tre-viet.jpg', N'Gari', N'<p><strong>M&oacute;n H&agrave;ng Hiệu Mang T&ecirc;n &ldquo;T&ocirc;i&rdquo;</strong></p>
<p>C&oacute; phải, bạn đang mải chạy theo những ti&ecirc;u chuẩn của x&atilde; hội, so s&aacute;nh bản th&acirc;n với người kh&aacute;c m&agrave; qu&ecirc;n mất gi&aacute; trị thực sự của ch&iacute;nh m&igrave;nh?</p>
<p>C&oacute; phải, bạn đang cố gắng thay đổi bản th&acirc;n để ph&ugrave; hợp với mong đợi của người kh&aacute;c, chạy theo những ti&ecirc;u chuẩn &aacute;p đặt m&agrave; qu&ecirc;n mất điều quan trọng nhất: sống l&agrave; ch&iacute;nh m&igrave;nh.</p>
<p>C&oacute; phải, bạn đang trở th&agrave;nh kiểu người m&agrave; bạn chẳng hề mong muốn "trở th&agrave;nh"?</p>
<p>Nếu bạn cũng đang lạc lối giữa những con đường ch&ecirc;nh v&ecirc;nh của cuộc đời th&igrave; đ&acirc;y l&agrave; cuốn s&aacute;ch gi&uacute;p bạn vững tin v&agrave;o bản th&acirc;n, t&igrave;m ra phi&ecirc;n bản tốt hơn của ch&iacute;nh m&igrave;nh v&agrave; học c&aacute;ch tr&acirc;n trọng ch&iacute;nh m&igrave;nh.</p>
<p>Cuốn s&aacute;ch n&agrave;y kh&ocirc;ng chỉ l&agrave; một chỉ dẫn, m&agrave; c&ograve;n l&agrave; người bạn đồng h&agrave;nh, gi&uacute;p bạn viết n&ecirc;n phương ch&acirc;m sống của ri&ecirc;ng m&igrave;nh: một tuổi trẻ kh&ocirc;ng hối tiếc, một h&agrave;nh tr&igrave;nh đầy ắp hạnh ph&uacute;c, bất chấp những cơn s&oacute;ng gi&oacute; tr&ograve;ng tr&agrave;nh m&agrave; đời mang đến. Cuộc đời, đẹp hay kh&ocirc;ng, ch&iacute;nh l&agrave; ở c&aacute;ch bạn nh&igrave;n nhận. H&atilde;y nhớ: "Th&agrave; l&agrave;m một ng&ocirc;i sao băng để rực s&aacute;ng, c&ograve;n hơn l&agrave;m một h&agrave;nh tinh vĩnh cửu m&agrave; chỉ biết ngủ y&ecirc;n."</p>
<p>"Tr&ecirc;n đời n&agrave;y, bạn kh&ocirc;ng cần phải chạy đua để chứng minh gi&aacute; trị của m&igrave;nh với ai cả. Hoa thơm kh&ocirc;ng năn nỉ ong bướm đến, trời xanh kh&ocirc;ng cần ai c&ocirc;ng nhận n&oacute; cao. Bạn cũng vậy, kh&ocirc;ng cần ai cho ph&eacute;p, vẫn cứ thể sống một cuộc đời đ&aacute;ng gi&aacute;. Ng&agrave;y mai ra sao, kh&ocirc;ng ai biết trước. Điều tưởng chừng l&agrave; m&atilde;i m&atilde;i, c&oacute; thể chỉ c&ograve;n l&agrave; dĩ v&atilde;ng trong một c&aacute;i chớp mắt. Vậy n&ecirc;n, đừng để h&ocirc;m nay tr&ocirc;i qua trong sự đắn đo của &aacute;nh nh&igrave;n người kh&aacute;c. H&atilde;y sống như c&aacute;ch m&igrave;nh muốn, y&ecirc;u những g&igrave; m&igrave;nh y&ecirc;u, l&agrave;m những điều khiến tr&aacute;i tim rung động. Bởi v&igrave; rốt cuộc th&igrave;&hellip; đời vẫn l&agrave; của m&igrave;nh. Kh&ocirc;ng ai c&oacute; thể sống hộ, c&agrave;ng kh&ocirc;ng một ai c&oacute; thể g&aacute;nh v&aacute;c gi&ugrave;m."</p>
<p>Giờ th&igrave; bạn đ&atilde; sẵn s&agrave;ng viết tiếp chương mới của cuộc đời - một phi&ecirc;n bản mạnh mẽ hơn, tự do hơn chưa?</p>', 2025, NULL, 240, 17, 4, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (19, N'The Garden Of Youth - Vườn Thanh Xuân', N'9786044806075', N'Bìa Mềm', CAST(84500.00 AS Decimal(12, 2)), CAST(169000.00 AS Decimal(12, 2)), CAST(130000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786044806075.jpg', N'Đào Hoàng Diệu', N'<p><strong>Vườn Thanh Xu&acirc;n (The Garden Of Youth)</strong></p>
<p>Cuốn s&aacute;ch The Garden Of Youth - Vườn Thanh Xu&acirc;n sẽ l&agrave; những th&ocirc;ng điệp, c&acirc;u chuyện, B&agrave;i học s&acirc;u sắp song ngữ Anh - Việt gi&agrave;u m&agrave;u sắc v&agrave; nhiều cung bậc cảm x&uacute;c, sẽ l&agrave; m&oacute;n qu&agrave; truyền đến bạn cảm hứng r&egrave;n luyện tiếng Anh, kh&ocirc;ng ngừng n&acirc;ng cấp, ho&agrave;n thiện bản th&acirc;n ng&agrave;y c&agrave;ng tốt đẹp hơn. V&agrave; x&acirc;y dựng cho ch&iacute;nh m&igrave;nh một khu vườn thanh xu&acirc;n thật rực rỡ, thật mu&ocirc;n m&agrave;u v&agrave; thật đ&aacute;ng nhớ"<br>Tr&iacute;ch lời n&oacute;i đầu trong cuốn s&aacute;ch.</p>
<p>- C&aacute;c c&acirc;u v&agrave; đoạn tr&iacute;ch dẫn song ngữ xen kẽ về b&agrave;i học cuộc sống, c&acirc;u chuyện t&igrave;nh y&ecirc;u tuổi thanh xu&acirc;n v&agrave; kh&aacute;t vọng ho&agrave;i b&atilde;o tuổi trẻ. Truyền cảm hứng r&egrave;n luyện tiếng anh v&agrave; n&acirc;ng cấp ho&agrave;n thiện bản th&acirc;n mỗi ng&agrave;y trở n&ecirc;n tốt đẹp hơn.<br>- Từ vựng v&agrave; ngữ ph&aacute;p ở mức độ cơ bản, dễ đọc hiểu v&agrave; ghi nhớ, gi&uacute;p bạn tăng vốn từ vựng, ghi nhớ x3 v&agrave; cải thiện tiếng anh dễ d&agrave;ng hơn.<br>- L&agrave; m&oacute;n qu&agrave; đồng h&agrave;nh v&agrave; x&acirc;y dựng tuổi thanh xu&acirc;n của bạn thật rực rỡ v&agrave; thật đ&aacute;ng nhớ!</p>', 2024, NULL, 274, 9, 9, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (20, N'Có Một Ngày, Bố Mẹ Sẽ Già Đi (Tái Bản 2024)', N'8935325025266', N'Bìa Mềm', CAST(45825.00 AS Decimal(12, 2)), CAST(92000.00 AS Decimal(12, 2)), CAST(70500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/c/o/co-mot-ngay-bo-me-se-gia-di_2.jpg', N'Nhiều Tác Giả', N'<p><strong>C&oacute; Một Ng&agrave;y, Bố Mẹ Sẽ Gi&agrave; Đi</strong></p>
<p>Bao l&acirc;u rồi bạn chưa về nh&agrave;?</p>
<p>Bao l&acirc;u rồi bạn chưa ngồi qu&acirc;y quần b&ecirc;n m&acirc;m cơm gia đ&igrave;nh?</p>
<p>&ldquo;Trong thế giới của người trưởng th&agrave;nh, những x&ocirc; bồ chốn đ&ocirc; thị v&agrave; dụ hoặc nơi trần thế ng&agrave;y c&agrave;ng nhiều.&rdquo; Ch&uacute;ng ta bị cuốn v&agrave;o guồng quay cuộc sống v&agrave; v&ocirc; t&igrave;nh bỏ qu&ecirc;n những người th&acirc;n y&ecirc;u rồi đến khi nhận ra, c&oacute; những chuyện đ&atilde; kh&ocirc;ng thể v&atilde;n hồi. Thời gian giống như đường một chiều, kẻ lữ h&agrave;nh ch&uacute;ng ta chỉ c&oacute; thể tiến về ph&iacute;a trước v&agrave; tuổi t&aacute;c của bố mẹ cũng vậy, sẽ ng&agrave;y một gi&agrave; đi theo năm th&aacute;ng.</p>
<p>&ldquo;C&oacute; một ng&agrave;y, bố mẹ sẽ gi&agrave; đi&rdquo; l&agrave; những c&acirc;u chuyện cảm động về t&igrave;nh th&acirc;n, gia đ&igrave;nh v&agrave; người nh&agrave;. Mỗi trang s&aacute;ch đều t&aacute;i hiện k&yacute; ức tuổi thơ với những khoảnh khắc qu&yacute; b&aacute;u b&ecirc;n những người th&acirc;n y&ecirc;u. Căn nh&agrave; thời thơ ấu, m&oacute;n ăn thơm ngon mẹ nấu, những lời dặn d&ograve; của bố, sự &acirc;n cần của &ocirc;ng b&agrave; d&agrave;nh cho con ch&aacute;u&hellip; Những h&igrave;nh ảnh gần gũi m&agrave; b&igrave;nh dị n&agrave;y sẽ &ocirc;m lấy bạn, trở th&agrave;nh nguồn sức mạnh to lớn gi&uacute;p bạn vượt qua gi&ocirc;ng b&atilde;o cuộc đời.</p>
<p>&ldquo;Bạn ơi, mau về nh&agrave; th&ocirc;i&hellip;</p>
<p>c&oacute; &aacute;nh đ&egrave;n v&agrave;ng ấm &aacute;p lu&ocirc;n s&aacute;ng,</p>
<p>c&oacute; bữa cơm n&oacute;ng hổi vương hương thơm,</p>
<p>c&oacute; gia đ&igrave;nh đang ng&oacute;ng tr&ocirc;ng đợi chờ, bất kể bao m&ugrave;a mưa nắng.</p>
<p>Đong đầy thương nhớ v&agrave; t&igrave;nh y&ecirc;u v&ocirc; điều kiện.&rdquo;</p>', 2024, NULL, 216, 6, 5, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (21, N'Người Ếch - Kẻ Giết Người Hàng Loạt', N'8935325023309', N'Bìa Mềm', CAST(78325.00 AS Decimal(12, 2)), CAST(157000.00 AS Decimal(12, 2)), CAST(120500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/b/i/bia1-nguoiech.jpg', N'Shichiri Nakayama', N'<h2 dir="ltr">T&Oacute;M TẮT NỘI DUNG S&Aacute;CH</h2>
<p dir="ltr">Một vụ &aacute;n r&ugrave;ng rợn l&agrave;m chấn động cả th&agrave;nh phố: thi thể một người đ&agrave;n &ocirc;ng được ph&aacute;t hiện với vết rạch kỳ qu&aacute;i tr&ecirc;n bụng, giống như h&igrave;nh một con ếch. Kh&ocirc;ng danh t&iacute;nh, kh&ocirc;ng dấu vết, chỉ c&oacute; một bức thư nặc danh li&ecirc;n kết vụ &aacute;n với một c&aacute;i chết b&iacute; ẩn từng xảy ra nhiều năm trước.</p>
<p dir="ltr">Thanh tra Kirisawa nhận nhiệm vụ điều tra, nhưng c&agrave;ng dấn s&acirc;u, anh c&agrave;ng nhận ra mọi thứ kh&ocirc;ng đơn thuần l&agrave; một vụ giết người. Những đầu mối mơ hồ, những nh&acirc;n chứng biến mất một c&aacute;ch kỳ lạ, v&agrave; một thế lực v&ocirc; h&igrave;nh dường như đang thao t&uacute;ng tất cả. "Người Ếch" &ndash; đ&oacute; l&agrave; g&igrave;? Một b&iacute; danh, một kẻ s&aacute;t nh&acirc;n h&agrave;ng loạt, hay một thực thể vượt xa tr&iacute; tưởng tượng của con người?</p>
<p dir="ltr">Sự thật ẩn giấu trong b&oacute;ng tối, nhưng liệu c&oacute; ai đủ dũng cảm để đối mặt?</p>', 2024, NULL, 336, 13, 6, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (22, N'Ghi Chép Pháp Y', N'8935325009433', N'Bìa Mềm', CAST(75075.00 AS Decimal(12, 2)), CAST(150000.00 AS Decimal(12, 2)), CAST(115500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/b/_/b_a-tr_c---ph_p-y-600.jpg', N'Lưu Hiểu Huy', N'<p><strong>GHI CH&Eacute;P PH&Aacute;</strong><strong>P Y - NHỮNG C&Aacute;I CHẾT B&Iacute; ẨN</strong>&nbsp;&ndash;</p>
<p><strong><em>L&agrave;m c&aacute;ch n&agrave;o để một &ldquo;x&aacute;c chết l&ecirc;n tiếng&rdquo;? -&nbsp;</em>đ&oacute; l&agrave;&nbsp;<em>c&ocirc;ng việc của b&aacute;c sĩ ph&aacute;p y.&nbsp;</em></strong></p>
<p>&ldquo;Ghi ch&eacute;p ph&aacute;p y - Những c&aacute;i chết b&iacute; ẩn&rdquo; l&agrave; cuốn s&aacute;ch nằm trong hệ liệt với &ldquo;Ph&aacute;p y Tần Minh&rdquo; - bộ tiểu thuyết nổi đ&igrave;nh đ&aacute;m của xứ Trung đ&atilde; được chuyển thể th&agrave;nh series phim. Cuốn s&aacute;ch tổng hợp những vụ &aacute;n c&oacute; thật, được viết bởi b&aacute;c sĩ ph&aacute;p y Lưu Hiểu Huy - người c&oacute; 15 năm kinh nghiệm v&agrave; từng mổ xẻ hơn 800 tử thi.&nbsp;</p>
<p>Trải qua 15 c&acirc;u chuyện kinh ho&agrave;ng, cuốn s&aacute;ch sẽ đưa bạn bước v&agrave;o hiện trường của những vụ &aacute;n man rợ như: x&aacute;c chết phi tang dưới c&aacute;nh đồng ng&ocirc;, thi thể thiếu nữ kh&ocirc;ng l&agrave;nh lặn, x&aacute;c chết nhầy nhụa đang bị gi&ograve;i bọ đục kho&eacute;t hay một thi thể co cứng trong m&agrave;ng bọc nilon&hellip;lần theo những dấu vết, gh&eacute;p lại sự thật từ những mảnh vụn thi thể, nguy&ecirc;n nh&acirc;n của c&aacute;i chết sẽ dần được h&eacute; mở.</p>
<p>Mỗi vụ &aacute;n đều l&agrave; một ẩn số, hiện trường vụ &aacute;n bao gồm cả x&aacute;c chết ch&iacute;nh l&agrave; chiếc ch&igrave;a kh&oacute;a để truy t&igrave;m hung thủ ngay cả khi n&oacute; kh&ocirc;ng c&ograve;n nguy&ecirc;n vẹn. Vậy l&agrave;m c&aacute;ch để c&aacute;c b&aacute;c sĩ ph&aacute;p y c&oacute; thể x&aacute;c định thương tật, c&aacute;c dấu hiệu cơ thể bị x&acirc;m hại? Cuốn s&aacute;ch n&agrave;y sẽ tr&igrave;nh b&agrave;y những kiến thức chuy&ecirc;n m&ocirc;n v&agrave; quy tr&igrave;nh xử l&yacute; vụ &aacute;n, từ hiện trường vụ &aacute;n đến đ&agrave;i giải phẫu, x&eacute;t nghiệm nội tạng, ph&acirc;n t&iacute;ch chất độc&hellip; từng bước t&igrave;m ra b&iacute; mật ẩn giấu sau mỗi tử thi, phơi b&agrave;y những manh mối li&ecirc;n quan đến tội &aacute;c con người v&agrave; lỗ hổng của x&atilde; hội.</p>
<p>Kh&ocirc;ng chỉ thuật lại những vụ &aacute;n v&agrave; c&aacute;c phương ph&aacute;p ph&aacute;p y, cuốn s&aacute;ch c&ograve;n chứa đựng cảm x&uacute;c của t&aacute;c giả đối với nghề nghiệp v&agrave; sự m&eacute;o m&oacute; của bản chất con người. Chẳng hạn, một đứa trẻ bệnh nặng phải đau đớn đến thế n&agrave;o khi bị người nh&agrave; đem ra l&agrave;m c&ocirc;ng cụ để đ&ograve;i bồi thường? Cuốn s&aacute;ch sẽ phơi b&agrave;y những g&oacute;c khuất của x&atilde; hội, những h&agrave;nh vi thủ &aacute;c, sự biến chất v&agrave; mất nh&acirc;n t&iacute;nh của một bộ phận con người trong x&atilde; hội.</p>
<p>Nếu bạn t&ograve; m&ograve; muốn biết c&aacute;ch đ&aacute;nh gi&aacute; tuổi của người chết dựa tr&ecirc;n mức độ m&ograve;n răng? Hay c&aacute;ch d&ugrave;ng một con gi&ograve;i từ người chết để suy ra thời điểm ch&iacute;nh x&aacute;c của vụ &aacute;n giết người?&nbsp; Hy vọng cuốn s&aacute;ch n&agrave;y sẽ cho bạn trải nghiệm kh&oacute; qu&ecirc;n về nghề ph&aacute;p y.</p>', 2022, NULL, 344, 8, 7, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (23, N'Ghi Chép Pháp Y', N'8935325015106', N'Bìa Mềm', CAST(62400.00 AS Decimal(12, 2)), CAST(125000.00 AS Decimal(12, 2)), CAST(96000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/b/_/b_a-tr_c-gcpy-2-1.jpg', N'Lưu Hiểu Huy', N'<p><em><strong>GHI CH&Eacute;P PH&Aacute;P Y 2 - KHI TỬ THI BIẾT N&Oacute;I</strong></em></p>
<p>Nếu kẻ thủ &aacute;c d&ugrave;ng c&aacute;i chết để khiến một người im lặng, th&igrave; b&aacute;c sĩ ph&aacute;p y sẽ gi&uacute;p nạn nh&acirc;n &ldquo;mở miệng&rdquo; th&ocirc;ng qua những mật m&atilde; để lại tr&ecirc;n thi thể.</p>
<p>&ldquo;Ghi ch&eacute;p ph&aacute;p y 2 - Khi tử thi biết n&oacute;i&rdquo; được t&aacute;c giả của bộ tiểu thuyết đ&igrave;nh đ&aacute;m &ldquo;Ph&aacute;p y Tần Minh&rdquo; v&agrave; Ph&oacute; gi&aacute;m đốc Hiệp hội ph&aacute;p y Trung Quốc - Ch&acirc;u Diệc Vũ giới thiệu, l&agrave; một trong những cuốn s&aacute;ch về ph&aacute;p y v&agrave; tội phạm đ&aacute;ng đọc nhất. Cuốn s&aacute;ch tổng hợp 8 vụ &aacute;n c&oacute; thật, được viết bởi b&aacute;c sĩ ph&aacute;p y Li&ecirc;u Tiểu Đao với 18 năm kinh nghiệm mổ xẻ tử thi bằng con dao bạc số 24.</p>
<p>Cuốn s&aacute;ch sẽ dẫn bạn bước v&agrave;o hiện trường những vụ &aacute;n gh&ecirc; rợn, dưới g&oacute;c nh&igrave;n chuy&ecirc;n m&ocirc;n của một b&aacute;c sĩ ph&aacute;p y: luộc xương để đo&aacute;n tuổi x&aacute;c chết, x&aacute;c định thời gian tử vong dựa v&agrave;o vỏ nhộng tr&ecirc;n thi thể, d&ugrave;ng găng tay da người để nhận dạng danh t&iacute;nh nạn nh&acirc;n&hellip; từng bước rửa oan cho người đ&atilde; khuất, phơi b&agrave;y những lỗ hổng ph&aacute;p luật v&agrave; sự mất nh&acirc;n t&iacute;nh của một bộ phận con người trong x&atilde; hội.</p>
<p>Kh&ocirc;ng chỉ thuật lại c&aacute;c phương ph&aacute;p nghiệp vụ, cuốn s&aacute;ch c&ograve;n chứa đựng suy tư của t&aacute;c giả về những vụ &aacute;n dai dẳng kh&ocirc;ng lời giải đ&aacute;p, những tử thi v&ocirc; danh kh&ocirc;ng thể l&ecirc;n tiếng v&agrave; những gia đ&igrave;nh c&ograve;n &ocirc;m hy vọng t&igrave;m được x&aacute;c người th&acirc;n&hellip;</p>
<p>&lsquo;Những vụ &aacute;n chưa giải quyết kh&ocirc;ng phải l&agrave; một xấp giấy mỏng, m&agrave; đ&oacute; l&agrave; những &ldquo;nấm mồ&rdquo; của c&aacute;c nạn nh&acirc;n đ&egrave; l&ecirc;n tim t&ocirc;i.&rdquo;</p>', 2023, NULL, 232, 12, 11, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (24, N'Hồ Sơ Máu - Vén Màn 13 Vụ Án Rúng Động Mọi Thời Đại', N'8935325027437', N'Bìa Mềm', CAST(69550.00 AS Decimal(12, 2)), CAST(139000.00 AS Decimal(12, 2)), CAST(107000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/b/i/bia-ho-so-mau---bia-truoc-1_1.jpg', N'Đường', N'<p><strong>Hồ Sơ M&aacute;u - V&eacute;n M&agrave;n 13 Vụ &Aacute;n R&uacute;ng Động Mọi Thời Đại</strong></p>
<p>&ldquo;Hồ sơ m&aacute;u - V&eacute;n m&agrave;n 13 vụ &aacute;n r&uacute;ng động mọi thời đại&rdquo; - Cuốn s&aacute;ch n&agrave;y chứa nhiều t&igrave;nh tiết v&agrave; h&igrave;nh ảnh hiện trường r&ugrave;ng rợn, dễ g&acirc;y &aacute;m ảnh, độc giả cần lưu &yacute; trước khi đọc.</p>
<p>Cuốn s&aacute;ch l&agrave; tuyển tập 13 vụ &aacute;n nổi tiếng c&oacute; thật ở Trung Quốc như: Hello Kitty kh&ocirc;ng đầu; B&aacute;nh bao x&aacute; x&iacute;u nh&acirc;n thị/t người; Cậu b&eacute; v&aacute;y đỏ ở Tr&ugrave;ng Kh&aacute;nh; Những c&ocirc; g&aacute;i dưới cống tho&aacute;t nước;... Được t&aacute;c giả tổng hợp lại dựa tr&ecirc;n c&aacute;c nguồn t&agrave;i liệu ch&iacute;nh thống, k&egrave;m theo c&aacute;c ph&acirc;n t&iacute;ch đ&aacute;nh gi&aacute; của ch&iacute;nh t&aacute;c giả nhằm mang đến cho độc giả g&oacute;c nh&igrave;n to&agrave;n diện về c&aacute;c vụ &aacute;n chấn động trong lịch sử. Tội &aacute;c của những kẻ s/&aacute;t n/h&acirc;n t&acirc;/m th/ần ấy vượt sức tưởng tượng sẽ khiến tất cả những ai đọc cuốn s&aacute;ch n&agrave;y phải thấy ớn lạnh khiếp sợ.</p>
<p>H&atilde;y đảm bảo rằng bạn đủ vững t&acirc;m l&yacute; trước khi bước v&agrave;o thế giới đầy b&oacute;ng tối. Nếu bạn l&agrave; người nhạy cảm với những chủ đề n&agrave;y, h&atilde;y c&acirc;n nhắc kỹ trước khi tiếp tục. Đ&acirc;y kh&ocirc;ng phải l&agrave; một cuốn s&aacute;ch d&agrave;nh cho những ai t&igrave;m kiếm sự nhẹ nh&agrave;ng hay giải tr&iacute; đơn thuần.</p>', 2025, NULL, 304, 11, 14, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (25, N'Ghi Chép Pháp Y', N'8935325023156', N'Bìa Mềm', CAST(52325.00 AS Decimal(12, 2)), CAST(105000.00 AS Decimal(12, 2)), CAST(80500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/b/_/b_a-tr_c-gcpy4_bebooks.jpg', N'Lưu Hiểu Huy', N'<p><strong>Ghi Ch&eacute;p Ph&aacute;p Y - Lật Lại Hồ Sơ Tội &Aacute;c</strong></p>
<p>&ldquo;Ghi ch&eacute;p ph&aacute;p y - Lật lại hồ sơ tội &aacute;c&rdquo; l&agrave; phần cuối c&ugrave;ng, kh&eacute;p lại chuỗi series đ&igrave;nh đ&aacute;m &ldquo;Ghi ch&eacute;p ph&aacute;p y&rdquo; được giới thiệu bởi t&aacute;c giả Ph&aacute;p y Tần Minh v&agrave; Ph&oacute; gi&aacute;m đốc Hiệp hội ph&aacute;p y Trung Quốc, Ch&acirc;u Diệc Vũ.</p>
<p>Cuốn s&aacute;ch bao gồm 5 vụ &aacute;n phức tạp, đ&aacute;nh dấu sự trở lại của Lưu B&aacute;t B&aacute;ch, b&aacute;c sĩ ph&aacute;p y nổi tiếng với con số 8 - 18 năm kinh nghiệm mổ xẻ cho 800 x&aacute;c chết. Bằng lối mi&ecirc;u tả chi tiết v&agrave; gh&ecirc; rợn, t&aacute;c giả sẽ đưa bạn quay trở về qu&aacute; khứ, theo đuổi những hồ sơ tội &aacute;c k&eacute;o d&agrave;i h&agrave;ng chục năm, tưởng như kh&ocirc;ng thể n&agrave;o ph&aacute; giải.</p>
<p>Điểm đặc biệt trong &ldquo;Ghi ch&eacute;p ph&aacute;p y - Lật lại hồ sơ tội &aacute;c&rdquo; ch&iacute;nh l&agrave; tất cả c&aacute;c nạn nh&acirc;n đều l&agrave; nữ giới. Một c&ocirc; b&eacute; 16 tuổi bị lừa b&aacute;n v&agrave; cưỡng bức bởi 5 người đ&agrave;n &ocirc;ng. Một nữ sinh bị bạn th&acirc;n bố mẹ quấy rối, s&aacute;t hại rồi giấu x&aacute;c v&agrave;o khe giường. Một c&ocirc; g&aacute;i bị chồng sắp cưới đ&acirc;m chết chỉ v&igrave; mang thai v&agrave; kh&ocirc;ng chịu chia tay&hellip; Tất cả đều chịu chung số phận bị cắn x&eacute;, ch&agrave; đạp bởi những con &aacute;c quỷ đội lốt &ldquo;người quen&rdquo;.</p>
<p>Một mặt ch&uacute;ng x&acirc;y dựng niềm tin khiến nạn nh&acirc;n bu&ocirc;ng lỏng cảnh gi&aacute;c, mặt kh&aacute;c lại tỉ mỉ l&ecirc;n kế hoạch, t&iacute;nh to&aacute;n từng bước nhằm thỏa m&atilde;n th&uacute; t&iacute;nh c&aacute; nh&acirc;n. Mối quan hệ c&agrave;ng gần gũi, thủ đoạn c&agrave;ng tiến h&oacute;a phức tạp, t&agrave;n nhẫn. Những thi thể trở th&agrave;nh m&oacute;n đồ chơi gi&uacute;p ch&uacute;ng &ldquo;n&acirc;ng cấp&rdquo; khả năng giết người, x&oacute;a dấu vết, l&agrave;m giả bằng chứng để qua mặt cảnh s&aacute;t.</p>
<p>Khao kh&aacute;t theo đuổi ch&iacute;nh nghĩa v&agrave; nghi&ecirc;m t&uacute;c trong từng đường dao, t&aacute;c giả sẽ trực tiếp lột bỏ lớp ngụy trang mẫu mực của kẻ thủ &aacute;c bằng ch&iacute;nh kiến thức nghiệp vụ của m&igrave;nh: s&agrave;ng lọc m&atilde; gen trội khoanh v&ugrave;ng nghi phạm, quan s&aacute;t vết thương x&aacute;c định hung kh&iacute;, phục dựng hiện trường th&ocirc;ng qua qu&aacute; tr&igrave;nh giải phẫu&hellip;</p>
<p>&ldquo;T&ocirc;i l&agrave; một b&aacute;c sĩ ph&aacute;p y. Tuy c&oacute; giấy ph&eacute;p sử dụng s&uacute;ng, nhưng vũ kh&iacute; thật sự của t&ocirc;i lại l&agrave; chiếc hộp kh&aacute;m nghiệm đang x&aacute;ch tr&ecirc;n tay&rdquo; - Lưu B&aacute;t B&aacute;ch</p>', 2024, NULL, 168, 13, 13, 100)
