INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (27, N'Phía Sau Nghi Can X (Tái Bản 2024)', N'8935235240902', N'Bìa Mềm', CAST(67080.00 AS Decimal(12, 2)), CAST(129000.00 AS Decimal(12, 2)), CAST(103200.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_187738_1.jpg', N'Higashino Keigo', N'<h2 dir="ltr">T&Oacute;M TẮT NỘI DUNG S&Aacute;CH</h2>
<p dir="ltr">Một vụ &aacute;n mạng. Một người phụ nữ v&agrave; con g&aacute;i bị đẩy v&agrave;o đường c&ugrave;ng. Một thi&ecirc;n t&agrave;i to&aacute;n học sẵn s&agrave;ng l&agrave;m mọi thứ để bảo vệ họ.</p>
<p dir="ltr">Trong Ph&iacute;a Sau Nghi Can X, Higashino Keigo kh&ocirc;ng chỉ dựng l&ecirc;n một vụ &aacute;n h&oacute;c b&uacute;a m&agrave; c&ograve;n khắc họa một cuộc đấu tr&iacute; đỉnh cao giữa kẻ che giấu tội &aacute;c v&agrave; cảnh s&aacute;t điều tra. Khi th&aacute;m tử Kusanagi bắt đầu nghi ngờ, một m&agrave;n đấu tr&iacute; căng thẳng giữa suy luận sắc b&eacute;n v&agrave; t&igrave;nh cảm s&acirc;u k&iacute;n dần h&eacute; lộ. Động cơ thực sự của kẻ t&igrave;nh nghi l&agrave; g&igrave;? Hắn đ&atilde; giấu điều g&igrave; ph&iacute;a sau lớp vỏ ho&agrave;n hảo?</p>
<p dir="ltr">Đ&acirc;y kh&ocirc;ng chỉ l&agrave; một c&acirc;u chuyện trinh th&aacute;m, m&agrave; c&ograve;n l&agrave; cuộc đấu tr&iacute; nghẹt thở giữa cảm x&uacute;c v&agrave; l&yacute; tr&iacute;, giữa sự thật v&agrave; những b&iacute; mật kh&ocirc;ng bao giờ n&ecirc;n bị phơi b&agrave;y. Liệu c&ocirc;ng l&yacute; c&oacute; thực sự chiến thắng, hay c&oacute; những tội lỗi kh&ocirc;ng thể bị ph&aacute;n x&eacute;t?&nbsp;</p>', 2024, NULL, 396, 7, 9, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (28, N'BộMa Quỷ Dân Gian Ký', N'8936213490357', N'Bìa Mềm', CAST(139100.00 AS Decimal(12, 2)), CAST(268000.00 AS Decimal(12, 2)), CAST(214000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/2/d/2d-mqgdk_1.jpg', N'Duy Văn', N'<p><strong>&ldquo;MA QUỶ D&Acirc;N GIAN K&Yacute;&rdquo; - KHI MA QUỶ VIỆT NAM CH&Iacute;NH THỨC ĐƯỢC ĐƯA V&Agrave;O TRANG S&Aacute;CH</strong></p>
<p>Cuốn s&aacute;ch &ldquo;Ma quỷ d&acirc;n gian k&yacute;&rdquo; l&agrave; một trong số &iacute;t những c&ocirc;ng tr&igrave;nh hiếm hoi đề cập đến những c&acirc;u chuyện về ma quỷ được truyền miệng văn h&oacute;a d&acirc;n gian Việt Nam, kh&ocirc;ng chỉ l&agrave; trong văn h&oacute;a của d&acirc;n tộc Việt m&agrave; c&ograve;n trong văn h&oacute;a của những d&acirc;n tộc thiểu số kh&aacute;c ở nhiều v&ugrave;ng miền.</p>
<p>Kh&aacute;c với văn ho&aacute; Phương T&acirc;y, c&aacute;c giai thoại về ma quỷ ở văn ho&aacute; Phương Đ&ocirc;ng - đặc biệt l&agrave; Việt Nam thường cho thấy ma quỷ gần gũi với con người hơn. Thường ma &ldquo;xuất th&acirc;n&rdquo; từ những linh hồn của người đ&atilde; khuất, hoặc một biến đổi về t&acirc;m linh với những lo&agrave;i vật quen thuộc đang sống. Ch&iacute;nh v&igrave; vậy, trong văn ho&aacute; Việt Nam c&aacute;c v&ugrave;ng miền, ma quỷ xuất hiện nhiều trong những c&acirc;u chuyện, tin đồn d&acirc;n gian, thường để giải tr&iacute;, hoặc doạ nạt, nhưng ph&iacute;a sau l&agrave; gi&aacute;o huấn, răn dạy người kh&aacute;c phải t&ocirc;n trọng những v&ugrave;ng đất, thi&ecirc;n nhi&ecirc;n hoặc mộ phần của người đ&atilde; mất. V&agrave; ph&iacute;a sau ma quỷ, l&agrave; những t&acirc;m t&igrave;nh, những th&oacute;i quen, quan niệm về tự nhi&ecirc;n, về lẽ phải của người Việt trong đời sống sinh hoạt hằng ng&agrave;y. Song, từ trước đến nay, chưa c&oacute; một khảo cứu đầy đủ n&agrave;o về ma quỷ ở Việt Nam, cho đến khi &ldquo;Ma Quỷ D&acirc;n Gian K&yacute;&rdquo; ra đời.</p>
<p>T&aacute;c phẩm l&agrave; một bộ s&aacute;ch du khảo tập hợp c&aacute;c lo&agrave;i ma quỷ v&agrave; hiện tượng t&acirc;m linh trong văn ho&aacute; truyền miệng ở Việt Nam, được chia l&agrave;m c&aacute;c chương nhỏ, đi k&egrave;m với tranh vẽ theo phong c&aacute;ch d&acirc;n gian hiện đại. Mỗi chương sẽ gồm một chủ đề, với minh hoạ sống động v&agrave; những th&ocirc;ng tin đầy đủ về định nghĩa, đặc t&iacute;nh v&agrave; niềm tin d&acirc;n gian về c&aacute;c loại ma quỷ. Cuối s&aacute;ch l&agrave; phần phụ lục c&aacute;c s&aacute;ng t&aacute;c thơ truyện li&ecirc;n quan đến ma quỷ d&acirc;n gian.</p>', 2023, NULL, 260, 12, 9, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (29, N'Sự Im Lặng Của Bầy Cừu (Tái Bản 2019)', N'8935235220508', N'Bìa Mềm', CAST(61100.00 AS Decimal(12, 2)), CAST(115000.00 AS Decimal(12, 2)), CAST(94000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_180812.jpg', N'Thomas Harris', N'<h2 dir="ltr">T&Oacute;M TẮT NỘI DUNG S&Aacute;CH&nbsp;</h2>
<p dir="ltr">B&iacute; ẩn đằng sau sự im lặng</p>
<p dir="ltr">Một t&ecirc;n s&aacute;t nh&acirc;n h&agrave;ng loạt đang lộng h&agrave;nh, bắt c&oacute;c v&agrave; giết hại phụ nữ. Những nạn nh&acirc;n bị lột da một c&aacute;ch kinh ho&agrave;ng, kh&ocirc;ng dấu vết, kh&ocirc;ng manh mối. Chỉ c&oacute; một người c&oacute; thể gi&uacute;p ph&aacute; giải vụ &aacute;n &ndash; Hannibal Lecter.</p>
<p dir="ltr">Hắn kh&ocirc;ng đơn giản l&agrave; một kẻ s&aacute;t nh&acirc;n, m&agrave; l&agrave; một thi&ecirc;n t&agrave;i bệnh hoạn. Hắn nh&igrave;n thấu t&acirc;m tr&iacute; con người, đọc vị từng g&oacute;c tối s&acirc;u thẳm nhất trong linh hồn họ. FBI cần hắn. Nhưng đổi lại, hắn cũng cần một thứ: sự thật đen tối của ch&iacute;nh người đang truy bắt m&igrave;nh.</p>
<p dir="ltr">Clarice Starling &ndash; nữ thực tập sinh FBI trẻ tuổi, liều lĩnh bước v&agrave;o tr&ograve; chơi nguy hiểm nhất đời c&ocirc;. Một kẻ s&aacute;t nh&acirc;n gi&uacute;p truy t&igrave;m một kẻ s&aacute;t nh&acirc;n kh&aacute;c. Nhưng liệu ai mới l&agrave; kẻ thao t&uacute;ng trong v&aacute;n cờ n&agrave;y?</p>
<p dir="ltr">&ldquo;Clarice, lũ cừu c&ograve;n k&ecirc;u la trong đầu c&ocirc; kh&ocirc;ng?&rdquo;<br>&ndash; Hannibal Lecter</p>', 2019, NULL, 359, 4, 7, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (30, N'Thảm Họa Tuyết Trắng', N'8935235243842', N'Bìa Mềm', CAST(98475.00 AS Decimal(12, 2)), CAST(185000.00 AS Decimal(12, 2)), CAST(151500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935235243842.jpg', N'Higashino Keigo', N'<p><strong>Thảm Họa Tuyết Trắng</strong></p>
<p>Một con dốc trượt tuyết đ&atilde; bị c&agrave;i bom.</p>
<p>&ldquo;Ta c&oacute; thể k&iacute;ch nổ quả bom bất cứ l&uacute;c n&agrave;o, từ bất cứ đ&acirc;u.&rdquo; Ngay trước thềm năm mới, một kẻ b&iacute; ẩn đ&atilde; gửi thư đe dọa đến khu trượt tuyết v&agrave; tuy&ecirc;n bố rằng hắn đ&atilde; đặt bom ở đ&acirc;u đ&oacute; b&ecirc;n dưới lớp tuyết d&agrave;y hơn hai m&eacute;t. Để tr&aacute;nh g&acirc;y thiệt hại đến h&igrave;nh ảnh v&agrave; việc kinh doanh vốn dĩ đang gặp nhiều kh&oacute; khăn, khu trượt tuyết đ&atilde; chấp nhận giao tiền chuộc cho t&ecirc;n tội phạm. Tuy nhi&ecirc;n, hết ba mươi triệu rồi lại đến năm mươi triệu, thủ phạm chưa c&oacute; dấu hiệu dừng lại. Liệu đ&acirc;y c&oacute; phải một vụ tống tiền đơn thuần, hay l&agrave; một &acirc;m mưu trả th&ugrave;? Mọi manh mối đều nằm ở b&atilde;i trượt tuyết cắm, nơi xảy ra vụ việc bi thảm để lại những vết thương chưa l&agrave;nh v&agrave; nỗi &aacute;m ảnh day dứt cho người trong cuộc...</p>
<p>Cuộc đua sinh tử với t&ecirc;n tội phạm diễn ra gay cấn đến nghẹt thở trong tiếng t&iacute;ch tắc oan nghiệt của quả bom hẹn giờ. Khi ranh giới giữa &ldquo;hung thủ&rdquo; v&agrave; &ldquo;nạn nh&acirc;n&rdquo; dần trở n&ecirc;n mờ mịt, khi lương t&acirc;m bị đồng tiền b&oacute;p nghẹt, con người c&oacute; thể đ&aacute;nh mất nh&acirc;n t&iacute;nh đến đ&acirc;u, c&oacute; thể ch&agrave; đạp l&ecirc;n những gi&aacute; trị tốt đẹp n&agrave;o?</p>', 2025, NULL, 364, 17, 2, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (31, N'Truyện Trạng Quỳnh - Trạng Lợn (Tái Bản)', N'8935236429825', N'Bìa Mềm', CAST(17225.00 AS Decimal(12, 2)), CAST(35000.00 AS Decimal(12, 2)), CAST(26500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935236429825.jpg', N'Mạnh Linh', N'<p><strong>Truyện Trạng Quỳnh - Trạng Lợn</strong></p>
<p>C&oacute; nhiều c&acirc;u chuyện về một nh&acirc;n vật xuất chủng được nh&acirc;n d&acirc;n truyền tụng suốt từ đời n&agrave;y sang đời kh&aacute;c th&agrave;nh một h&igrave;nh tượng nh&acirc;n vật văn học d&acirc;n gian độc đ&aacute;o. Ấy l&agrave; Trạng Quỳnh, một đại diện ưu t&uacute; của tr&iacute; tuệ nh&acirc;n d&acirc;n, được nh&acirc;n d&acirc;n x&acirc;y dựng, bồi đắp ng&agrave;y th&ecirc;m phong ph&uacute;, ho&agrave;n chỉnh t&agrave;i năng v&agrave; t&iacute;nh c&aacute;ch, h&ograve;a trộn yếu tố hiện thực v&agrave; những giả tưởng huyền thoại pha chất trần gian.</p>
<p>Người ta đồn rằng, Quỳnh hay chữ từ l&uacute;c c&ograve;n l&agrave; b&agrave;o thai trong bung me. Chuy&ecirc;n kể, trong thời gian b&agrave; mẹ Quỳnh mang thai, c&oacute; lần ra cầu ao giặt quần &aacute;o, bỗng nh&igrave;n thấy một con vịt bầu to đang bơi lội thỏa th&iacute;ch tr&ecirc;n mặt ao. B&agrave; cũng vốn l&agrave; người hay chữ, tức cảnh sinh tinh, buột miệng đọc l&ecirc;n một c&acirc;u, xem ra thật hợp t&igrave;nh hợp cảnh, lại chứa chan th&igrave; vi:</p>
<p>L&ecirc;nh đ&ecirc;nh bầu trời mặt nước. Ai ngờ, chợt b&agrave; nghe tiếng trẻ con từ trong bụng m&igrave;nh ph&aacute;t ra: Lẳng lơ quả m&iacute;t tr&ecirc;n c&agrave;nh. Thật l&agrave; đổi thanh, đối &yacute;, đối lời. B&agrave; mẹ sững sờ hồi l&acirc;u về sự kh&aacute;c thường ấy v&agrave; tin rằng đứa con sau n&agrave;y minh sinh chẳng kh&aacute;c người nh&agrave; trời xuất thế. Về sau, qua như lời, Quỳnh sinh v&agrave; lớn l&ecirc;n như một nh&acirc;n vật kh&aacute;c thường. Chuyện lạ đ&oacute; đ&acirc;y c&ograve;n lưu giữ m&atilde;i trong tr&iacute; nhớ người đời. (Tr&iacute;ch Giỏi từ trong bụng mẹ).</p>', 2023, NULL, 162, 17, 7, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (32, N'Những Mẫu Chuyện Hài Hước Trong Kinh Doanh Của Người Do Thái', N'8935074130839', N'Bìa Mềm', CAST(40950.00 AS Decimal(12, 2)), CAST(79000.00 AS Decimal(12, 2)), CAST(63000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935074130839.jpg', N'Hoa Sơn', N'<p>Những Mẫu Chuyện H&agrave;i Hước Trong Kinh Doanh Của Người Do Th&aacute;i</p>
<p>&ldquo;T&iacute;nh h&agrave;i hước l&agrave; &aacute;nh mặt trời của tư duy.&rdquo;</p>
<p>- Edward Bulwer-Lytton</p>
<p>Để trụ vững tr&ecirc;n thương trường cạnh tranh khốc liệt như ng&agrave;y nay, doanh nh&acirc;n Do Th&aacute;i đ&atilde; kh&eacute;o l&eacute;o vận dụng tư duy kinh doanh vượt trội v&agrave; khiếu h&agrave;i hước độc đ&aacute;o v&agrave;o trong quản l&yacute;, tiếp thị, đ&agrave;m ph&aacute;n... Đ&oacute; cũng ch&iacute;nh l&agrave; l&yacute; do họ gặt h&aacute;i được những th&agrave;nh tựu to lớn khiến cả thế giới phải ngả mũ k&iacute;nh phục.</p>
<p>D&acirc;n tộc Do Th&aacute;i kh&ocirc;ng những l&agrave; một d&acirc;n tộc kh&ocirc;n ngoan, c&oacute; đầu &oacute;c kinh doanh nhạy b&eacute;n m&agrave; c&ograve;n c&oacute; khiếu h&agrave;i hước. T&agrave;i năng kinh doanh của họ được thể hiện trong c&aacute;c chuyện cười d&acirc;n gian, được lưu truyền trong giới doanh nh&acirc;n. Nghi&ecirc;n cứu t&iacute;nh h&agrave;i hước của người Do Th&aacute;i cũng ch&iacute;nh l&agrave; kh&aacute;m ph&aacute; sự kh&ocirc;n ngoan thực tiễn của họ.</p>
<p>Những mẩu chuyện h&agrave;i hước trong kinh doanh của người Do Th&aacute;i với hơn 100 mẩu chuyện đặc sắc l&agrave; hơn 100 tiếng cười ở nhiều lĩnh vực kh&aacute;c nhau trong đời sống kinh doanh: quản l&yacute;, tiếp thị, đ&agrave;m ph&aacute;n, tiền bạc&hellip; Những lời b&igrave;nh đi k&egrave;m sẽ gi&uacute;p bạn gợi mở nhiều suy nghĩ v&agrave; nhận ra &yacute; nghĩa s&acirc;u xa m&agrave; từng mẩu chuyện gửi gắm.</p>
<p>Bạn sẽ c&oacute; những gi&acirc;y ph&uacute;t thư gi&atilde;n tuyệt vời v&agrave; nghiệm ra được nhiều b&agrave;i học từ những mẩu chuyện th&uacute; vị được g&oacute;p nhặt trong s&aacute;ch, v&agrave; hơn thế nữa, bạn sẽ c&oacute; c&aacute;i nh&igrave;n lạc quan hơn về con người v&agrave; cuộc sống.</p>', 2023, NULL, 176, 4, 3, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (33, N'Người Nói Đạo Lý Thường Sống Khá Giả', N'8935235240803', N'Bìa Mềm', CAST(87880.00 AS Decimal(12, 2)), CAST(169000.00 AS Decimal(12, 2)), CAST(135200.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935235240803.jpg', N'Lê Bích', N'<p><strong>Người N&oacute;i Đạo L&yacute; Thường Sống Kh&aacute; Giả</strong></p>
<p>L&ecirc; B&iacute;ch - Nh&acirc;n vật ảo với chiếc bụng phệ, rốn lồi, khu&ocirc;n mặt lu&ocirc;n tỏ vẻ tư lự, tr&ecirc;n th&ocirc;ng thi&ecirc;n văn, dưới tường địa l&yacute;, tam gi&aacute;o, cửu lưu, tứ thư, ngũ kinh, tinh thần y&ecirc;u nước trung trinh, đạo đức lung linh, phong tục, luật lệ, bản quyền, Horoscope, vật l&yacute; lượng tử... c&aacute;i g&igrave; L&ecirc; B&iacute;ch cũng tưởng l&agrave; ch&agrave;ng biết.</p>
<p>V&agrave; nay, L&ecirc; B&iacute;ch quyết định sử dụng tất cả hiểu biết của m&igrave;nh để... n&oacute;i đạo l&yacute;, trở th&agrave;nh một vị thiền sư gi&uacute;p đời!</p>
<p>... Hay c&oacute; thật l&agrave; thế kh&ocirc;ng nhỉ?</p>', 2024, NULL, 372, 2, 11, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (34, N'Cười Và Học Tiếng Anh - 45 Truyện Cười Chơi Chữ Giúp Học Giỏi Tiếng Anh', N'8935069923583', N'Bìa Mềm', CAST(16380.00 AS Decimal(12, 2)), CAST(36000.00 AS Decimal(12, 2)), CAST(25200.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/b/i/bia-45-truyen-cuoi--1.jpg', N'Nguyễn Quốc Hùng, M.A', N'<p><strong>Cười V&agrave; Học Tiếng Anh - 45 Truyện Cười Chơi Chữ Gi&uacute;p Học Giỏi Tiếng Anh</strong></p>
<p><strong><em>45 Truyện cười chơi chữ gi&uacute;p học giỏi tiếng Anh</em></strong>&nbsp;l&agrave; ấn phẩm thứ ba thuộc bộ s&aacute;ch&nbsp;<strong><em>Cười v&agrave; Học tiếng Anh</em></strong>&nbsp;rất được y&ecirc;u th&iacute;ch, tập trung v&agrave;o việc tiếp cận ngoại ngữ th&ocirc;ng qua những t&igrave;nh huống sinh động trong thực tế.</p>
<p>C&oacute; niềm vui khi học một điều mới mẻ, v&agrave; cứ học một điều mới mẻ lại th&ecirc;m vui, đ&oacute; l&agrave; ước muốn của kh&ocirc;ng chỉ những bạn trẻ.</p>
<p>Cuốn s&aacute;ch n&agrave;y chứa tới 45 niềm vui để học: nụ cười hứng khởi sẽ gi&uacute;p ch&uacute;ng ta&nbsp;<em>hiểu, nhớ v&agrave; vận dụng được ng&ocirc;n ngữ tiếng Anh</em>&nbsp;trong c&aacute;c ngữ cảnh phong ph&uacute;. Đọc 45 truyện cười, ch&uacute;ng ta tủm tỉm v&igrave; nhiều yếu tố chơi chữ đa dạng: Nh&agrave; du h&agrave;nh vũ trụ th&iacute;ch bộ phận n&agrave;o của m&aacute;y vi t&iacute;nh nhất? Chẳng phải đ&oacute; l&agrave;&nbsp;<strong>space bar</strong>&nbsp;sao! C&ograve;n nữa, đố bạn giữa&nbsp;<em>hot</em>&nbsp;v&agrave;&nbsp;<em>cold</em>&nbsp;th&igrave; trạng th&aacute;i n&agrave;o nhanh hơn? Theo t&ocirc;i,&nbsp;<em>hot</em>&nbsp;nhanh hơn đấy, bởi v&igrave;&nbsp;<strong>everyone catches a cold</strong>&nbsp;(bị cảm lạnh). V&agrave; nếu c&oacute; ai thắc mắc đ&agrave;n b&ograve; sẽ giải tr&iacute; bằng c&aacute;ch n&agrave;o, h&atilde;y lưu &yacute; đến&nbsp;<strong>moooovies</strong>&nbsp;nh&eacute; (tiếng k&ecirc;u của b&ograve; được kh&eacute;o l&eacute;o lồng v&agrave;o từ movie &ndash; phim ảnh).</p>
<p>Quả thực, tiếng cười ch&iacute;nh l&agrave; một yếu tố khiến ng&ocirc;n ngữ lu&ocirc;n trở th&agrave;nh &ldquo;sinh ngữ&rdquo;.</p>
<p>Người bi&ecirc;n soạn s&aacute;ch l&agrave; thầy Nguyễn Quốc H&ugrave;ng M.A, một trong những chuy&ecirc;n gia c&oacute; uy t&iacute;n về giảng dạy tiếng Anh tại Việt Nam, với 34 năm c&ocirc;ng t&aacute;c &ndash; giảng dạy tại trường Đại học Ngoại ngữ H&agrave; Nội, 25 năm x&acirc;y dựng c&aacute;c chương tr&igrave;nh tiếng Anh tr&ecirc;n truyền h&igrave;nh VTV2 v&agrave; 20 năm tr&ecirc;n s&oacute;ng đ&agrave;i Tiếng n&oacute;i Việt Nam. Thầy l&agrave; t&aacute;c giả của những cuốn s&aacute;ch như:</p>
<p><em>Dạy tiếng Anh: Xu hướng mới</em></p>
<p><em>Cười &amp; Học tiếng Anh: 65 Truyện cười đa nghĩa gi&uacute;p học giỏi tiếng Anh</em></p>
<p><em>Cười &amp; Học tiếng Anh: 50 Truyện cười theo t&igrave;nh huống gi&uacute;p học giỏi tiếng Anh</em></p>
<p><em>Cười &amp; Học tiếng Anh: 45 Truyện cười chơi chữ gi&uacute;p học giỏi tiếng Anh</em> v.v.</p>', 2024, NULL, 44, 17, 5, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (35, N'Tam Quốc Lầy Lội Diễn Nghĩa - Tập 1', N'8935235241763', N'Bìa Mềm', CAST(100425.00 AS Decimal(12, 2)), CAST(189000.00 AS Decimal(12, 2)), CAST(154500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935235241763.jpg', N'Trần Lỗi', N'<p><strong>Tam Quốc Lầy Lội Diễn Nghĩa - Tập 1</strong></p>
<p>Th&ocirc;ng thường, để đ&aacute;nh gi&aacute; một chư hầu c&oacute; thực lực hay kh&ocirc;ng, ngo&agrave;i qu&acirc;n số nhiều &iacute;t, c&ograve;n phải xem x&eacute;t ba phương diện: mưu sĩ, v&otilde; tướng, lương thực. M&agrave; tr&ecirc;n ba phương diện n&agrave;y, Vi&ecirc;n Thiệu đều c&oacute; thực lực cấp cao nhất, &ocirc;ng ta c&oacute; một nh&oacute;m mưu sĩ với chỉ số IQ nổ cả m&aacute;y đo, c&oacute; một nh&oacute;m v&otilde; tướng với sức chiến đấu rất mạnh, c&ograve;n c&oacute; lương thực dồi d&agrave;o ăn kh&ocirc;ng hết. Vậy v&igrave; sao một chư hầu với cấu h&igrave;nh đỉnh ch&oacute;p nhường ấy lại thất bại tan t&agrave;nh trước T&agrave;o Th&aacute;o trong trận Quan Độ - trận chung kết tranh đoạt phương Bắc?</p>
<p>Kh&ocirc;ng bằng cấp, l&yacute; lịch, kinh nghiệm l&agrave;m việc, Gia C&aacute;t Lượng l&agrave;m thế n&agrave;o để v&agrave;o thẳng tầng lớp quyết s&aacute;ch trong c&ocirc;ng ty của Lưu Bị?<br>Bằng những bức biếm họa vẽ tay v&agrave; c&aacute;ch kể chuyện kh&ocirc;i h&agrave;i, Trần Lỗi &amp; cộng sự đ&atilde; phục hồi sinh động nhiều c&acirc;u chuyện đặc sắc trong Tam quốc diễn nghĩa, khiến độc giả vừa cười sảng kho&aacute;i vừa &ocirc;n lại những m&agrave;n kinh điển của bộ danh t&aacute;c n&agrave;y, nh&igrave;n chuyện cũ từ g&oacute;c mới đầy th&uacute; vị.</p>', 2024, NULL, 360, 10, 7, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (36, N'Tam Quốc Lầy Lội Diễn Nghĩa - Tập 2', N'8935235242180', N'Bìa Mềm', CAST(99125.00 AS Decimal(12, 2)), CAST(186000.00 AS Decimal(12, 2)), CAST(152500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935235242180.jpg', N'Trần Lỗi', N'<p><strong>Tam Quốc Lầy Lội Diễn Nghĩa - Tập 2</strong></p>
<p>Quan Vũ đ&atilde; từng bước &ldquo;cuốn theo chiều gi&oacute;&rdquo; như thế n&agrave;o, để rồi cuối c&ugrave;ng để mất cả Kinh Ch&acirc;u lẫn t&iacute;nh mạng, cũng khiến cho ch&iacute; nguyện thống nhất thi&ecirc;n hạ của Lưu Bị chỉ l&agrave; hoa trong gương, trăng dưới nước?</p>
<p>Gia C&aacute;t Lượng s&aacute;u lần ra Kỳ Sơn, tiếc rằng &ldquo;xuất qu&acirc;n chưa thắng th&acirc;n đ&agrave; th&aacute;c&rdquo;. C&ocirc;ng cuộc Bắc phạt n&agrave;y nh&igrave;n chung thất bại bởi hai nguy&ecirc;n nh&acirc;n n&agrave;o?</p>
<p>&ldquo;Sảng kho&aacute;i chỉ l&agrave; nhất thời, sống l&acirc;u mới l&agrave; tinh t&uacute;y của b&agrave;i học th&agrave;nh c&ocirc;ng thời Tam Quốc.&rdquo; Tư M&atilde; &Yacute; dựa v&agrave;o kỹ năng trường thọ, ẩn nhẫn nhiều năm, rốt cuộc đ&atilde; đợi được cơ hội lật ngược thế cờ, đưa gia tộc Tư M&atilde; trỗi dậy ra sao?</p>
<p>Bằng những bức biếm họa vẽ tay v&agrave; c&aacute;ch kể chuyện v&ocirc; c&ugrave;ng h&agrave;i hước. Trần Lỗi &amp; cộng sự đ&atilde; phục hồi sinh động nhiều c&acirc;u chuyện đặc sắc trong Tam quốc diễn nghĩa, khiến độc giả vừa cười sảng kho&aacute;i vừa &ocirc;n lại những m&agrave;n kinh điển của bộ danh t&aacute;c n&agrave;y, xem chuyện cũ từ g&oacute;c nh&igrave;n mới đầy th&uacute; vị.</p>', 2024, NULL, 332, 8, 10, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (37, N'Đời Về Cơ Bản Là Buồn Cười (Tái Bản 2022)', N'8935235235427', N'Bìa Mềm', CAST(40950.00 AS Decimal(12, 2)), CAST(90000.00 AS Decimal(12, 2)), CAST(63000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935235235427.jpg', N'Lê Bích', N'<p>Cơ bản m&agrave; n&oacute;i th&igrave; nếu kh&ocirc;ng cẩn thận mọi thứ đều c&oacute; thể g&acirc;y ra hạnh ph&uacute;c !</p>
<p>Tui hiểu mấy người n&oacute;i xấu g&igrave; tui nhưng tui kh&ocirc;ng quan t&acirc;m !</p>
<p>Phụ nữ l&agrave; số 1 !</p>
<p>L&ecirc; B&iacute;ch - Nh&acirc;n vật ảo với chiếc bụng phệ, rốn lồi, khu&ocirc;n mặt lu&ocirc;n tỏ vẻ tư lự, tr&ecirc;n th&ocirc;ng thi&ecirc;n văn, dưới tường địa l&yacute;, tam gi&aacute;o, cửu lưu, tứ thư, ngũ kinh, tinh thần y&ecirc;u nước trung trinh, đạo đức lung linh, phong tục, luật lệ, bản quyền, Horoscope, vật l&yacute; lượng tử... c&aacute;i g&igrave; L&ecirc; B&iacute;ch cũng tưởng l&agrave; ch&agrave;ng biết.</p>
<p>Năm 2015, L&ecirc; B&iacute;ch xuất hiện v&agrave; nhanh ch&oacute;ng thu h&uacute;t được c&aacute;c bạn trẻ nhờ những ph&aacute;t ng&ocirc;n &ldquo;chuẩn kh&ocirc;ng cần chỉnh&rdquo; do ch&iacute;nh nh&oacute;m bạn nghĩ ra, b&ecirc;n cạnh đ&oacute; cũng c&oacute; một số status dịch từ nước ngo&agrave;i, một số kh&aacute;c mượn &yacute; của một v&agrave;i ng&agrave;n người bạn.</p>
<p>Đời Về Cơ Bản L&agrave; Buồn Cười l&agrave; một tập hợp những ph&aacute;t ng&ocirc;n ấy của L&ecirc; B&iacute;ch, dĩ nhi&ecirc;n l&agrave; chưa từng xuất hiện tr&ecirc;n fanpage, b&ecirc;n cạnh những c&acirc;u n&oacute;i quen thuộc l&agrave;m n&ecirc;n t&ecirc;n tuổi của L&ecirc; B&iacute;ch.</p>', 2022, NULL, 162, 2, 4, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (38, N'Ba Gã Cùng Thuyền (Chưa Kể Con Chó)', N'8935235238374', N'Bìa Mềm', CAST(46800.00 AS Decimal(12, 2)), CAST(88000.00 AS Decimal(12, 2)), CAST(72000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935235238374.jpg', N'Jerome K. Jerome', N'<p><strong>Ba G&atilde; C&ugrave;ng Thuyền (Chưa Kể Con Ch&oacute;)</strong></p>
<p><em><strong>Sơ lược về t&aacute;c phẩm:</strong></em></p>
<p>- 1 trong 100 t&aacute;c phẩm xuất sắc nhất mọi thời đại do NXB Penguin tổ chức b&igrave;nh chọn</p>
<p>- 1 trong 10 t&aacute;c phẩm h&agrave;i hước nhất trong lịch sử theo AbeBooks.</p>
<p>Bọn hắn c&oacute; bốn mạng (t&iacute;nh cả con ch&oacute;), v&agrave; bọn hắn tiến h&agrave;nh chuyến du h&agrave;nh s&ocirc;ng Thames để đời n&agrave;y với một l&yacute; do ch&iacute;nh đ&aacute;ng kh&ocirc;ng để đ&acirc;u cho hết: để thư gi&atilde;n. Quả thật, nếu kh&ocirc;ng t&iacute;nh đến sự cứng đầu cứng cổ của mớ h&agrave;nh l&yacute;, sự v&ocirc; ơn của con thuyền, sự quỷ quyệt của c&aacute;i ấm tr&agrave;, sự om s&ograve;m của bầy thi&ecirc;n nga (v.v. v&agrave; v.v.) th&igrave; &aacute;i ch&agrave;, bọn hắn quả đ&atilde; được thư gi&atilde;n thật. Th&ecirc;m v&agrave;o đ&oacute;, bọn hắn c&ograve;n được biết thế n&agrave;o l&agrave; một chuyến du h&agrave;nh đ&iacute;ch thực&hellip;</p>
<p>Nhờ đ&oacute;, độc giả c&oacute; thể ngấu nghiến từng c&acirc;u từng chữ những c&acirc;u chuyện ly kỳ hấp dẫn m&agrave; g&atilde; J. ấy đ&atilde; vui l&ograve;ng kể lại, c&oacute; thể xu&yacute;t xoa trước tầng tầng lớp lớp kiến thức văn h&oacute;a, lịch sử, địa l&yacute; trong t&aacute;c phẩm, c&oacute; thể tấm tắc trước văn phong, c&oacute; thể cười lăn trước những chi tiết kh&ocirc;n lường, c&oacute; thể vỗ đ&ugrave;i đ&aacute;nh đ&eacute;t m&agrave; ngưỡng mộ văn t&agrave;i của t&aacute;c giả. V&agrave;, xin nhắc độc giả rằng, đ&acirc;y kh&ocirc;ng phải một c&acirc;u chuyện, đ&acirc;y l&agrave; bản tường thuật ch&acirc;n thực kh&ocirc;ng thể bỏ lỡ về một chuyến du h&agrave;nh s&ocirc;ng nước &ldquo;độc nhất v&ocirc; nhị&rdquo;&hellip;</p>', 2023, NULL, 262, 11, 15, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (39, N'Kho Tàng Truyện Tiếu Lâm Việt Nam (Tái Bản 2023)', N'8935236433204', N'Bìa Mềm', CAST(39975.00 AS Decimal(12, 2)), CAST(80000.00 AS Decimal(12, 2)), CAST(61500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935236433204.jpg', N'Đức Thành', N'<p><strong>Kho T&agrave;ng Truyện Tiếu L&acirc;m Việt Nam</strong></p>
<p>Trong cuộc sống, tiếng cười c&oacute; &yacute; nghĩa v&ocirc; c&ugrave;ng quan trọng. Bởi vậy, những c&acirc;u chuyện tiếu l&acirc;m g&acirc;y cười cũng rất được ưa chuộng trong đời sống văn h&oacute;a d&acirc;n gian.</p>
<p>Qua năm th&aacute;ng, những c&acirc;u chuyện đ&atilde; được s&aacute;ng tạo n&ecirc;n v&agrave; truyền miệng từ đời n&agrave;y sang đời kh&aacute;c. Tuy nhi&ecirc;n, ng&agrave;y nay, những c&acirc;u chuyện đ&oacute; đ&atilde; được sưu tầm v&agrave; ghi lại bằng chữ viết, nhằm lưu giữ l&acirc;u d&agrave;i v&agrave; truyền b&aacute; rộng r&atilde;i hơn.</p>
<p>Cuốn s&aacute;ch n&agrave;y tập hợp những c&acirc;u chuyện tiếu l&acirc;m đặc sắc, được nhiều người ưa th&iacute;ch nhất.</p>', 2023, NULL, 288, 16, 8, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (40, N'Trạng Cười Hay Nhất (Tái Bản 2023)', N'8935236432252', N'Bìa Mềm', CAST(37375.00 AS Decimal(12, 2)), CAST(75000.00 AS Decimal(12, 2)), CAST(57500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_221256_1.jpg', N'Đức Thành, Hải Yến', N'<p><strong>Trạng Cười Hay Nhất</strong></p>
<p>Cuốn s&aacute;ch tuyển tập những c&acirc;u chuyện trạng cười hay nhất trong kho t&agrave;ng văn học d&acirc;n gian Việt Nam.</p>
<p>Trong lịch sử h&igrave;nh th&agrave;nh v&agrave; ph&aacute;t triển của d&acirc;n tộc xuất hiện kh&ocirc;ng &iacute;t những nh&acirc;n vật xuất ch&uacute;ng với tr&iacute; th&ocirc;ng minh kiệt xuất, t&agrave;i ứng đối nhanh nhạy khiến cho nhiều lần sứ giả Trung Quốc phải c&uacute;i m&igrave;nh k&iacute;nh nể như Trạng Quỳnh, Trạng Lợn, M&acirc;n Nhuỵ, Phủ Tuấn, &Ocirc;ng &Oacute;, &Ocirc;ng Tuyn, Ch&agrave;ng Quậy, Ch&agrave;ng Cu, Y Lo&agrave;...</p>', 2023, NULL, 376, 10, 13, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (41, N'Nhật Ký Trong Tù (Tái Bản)', N'8935095632053', N'Bìa Mềm', CAST(24375.00 AS Decimal(12, 2)), CAST(48000.00 AS Decimal(12, 2)), CAST(37500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_244718_1_5088.jpg', N'Hồ Chí Minh', N'<p>Nhật K&yacute; Trong T&ugrave; (T&aacute;i Bản)</p>
<p>Chủ tịch Hồ Ch&iacute; Minh l&agrave; vị l&atilde;nh tụ thi&ecirc;n t&agrave;i của Đảng v&agrave; nh&acirc;n d&acirc;n Việt Nam, anh h&ugrave;ng giải ph&oacute;ng d&acirc;n tộc, danh nh&acirc;n văn ho&aacute; thế giới. Người kết tinh trong m&igrave;nh những phẩm chất v&agrave; gi&aacute; trị tinh thần cao qu&yacute; nhất của giai cấp c&ocirc;ng nh&acirc;n v&agrave; d&acirc;n tộc việt Nam. Cuộc đời, sự nghiệp của Người l&agrave; một tấm gương s&aacute;ng v&igrave; d&acirc;n, v&igrave; nước. Trong suốt cuộc đời hoạt động c&aacute;ch mạng, Người đ&atilde; trải qua nhiều kh&oacute; khăn, gian khổ, thậm ch&iacute; nguy hiểm đến t&iacute;nh mạng, nhưng d&ugrave; bất kỳ ho&agrave;n cảnh n&agrave;o. Người cũng vẫn lu&ocirc;n lạc quan, tin tưởng v&agrave;o thắng lợi của c&aacute;ch mạng. Tinh thần ấy thể hiện r&otilde; trong nhiều trước t&aacute;c của Người, trong đ&oacute; tập thơ Nhật k&yacute; trong t&ugrave;.</p>
<p>Đ&acirc;y l&agrave; một tập thơ chữ H&aacute;n, gồm hơn một trăm b&agrave;i thơ, phần cuối c&oacute; một số ghi ch&eacute;p về qu&acirc;n sự v&agrave; thời sự, được Chủ tịch Hồ Ch&iacute; Minh s&aacute;ng t&aacute;c trong thời gian hơn một năm (từ 29-8-1942 đến 10-9-1943) Người bị ch&iacute;nh quyền địa phương của Tưởng Giới Thạch bắt giam tr&aacute;i ph&eacute;p tại c&aacute;c nh&agrave; t&ugrave; ở tỉnh Quảng t&acirc;y, Trung Quốc. Nhật k&yacute; trong t&ugrave; l&ecirc;n &aacute;n chế độc nh&agrave; t&ugrave; h&agrave; khắc của ch&iacute;nh quyền Quốc d&acirc;n Đảng, thể hiện tinh thần lạc quan c&aacute;ch mạng v&agrave; t&igrave;nh cảm nh&acirc;n đạo cộng sản chủ nghĩa cao đẹp của Chủ tịch Hồ Ch&iacute; Minh. Tập thơ được đ&aacute;nh gi&aacute; l&agrave; một văn kiện lịch sử quan trọng, một t&aacute;c phẩm văn học xuất sắc, c&oacute; t&aacute;c dụng gi&aacute;o dục s&acirc;u sắc phẩm chất v&agrave; đạo đức c&aacute;ch mạng cho nhiều thế hệ.</p>', 2021, NULL, 175, 11, 14, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (42, N'Nhật Ký Trong Tù (Tái Bản)', N'8936067606294', N'Bìa Mềm', CAST(33800.00 AS Decimal(12, 2)), CAST(80000.00 AS Decimal(12, 2)), CAST(52000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8936067606294.jpg', N'Hồ Chí Minh', N'<p>Gi&aacute;o sư Phương Lựu, nh&agrave; l&yacute; luận ph&ecirc; b&igrave;nh NXB Văn Học đ&atilde; đưa ra bằng chứng, tuy được viết bằng chữ H&aacute;n nhưng "Nhật k&yacute; trong t&ugrave;" của B&aacute;c rất kh&aacute;c với thơ Đường. Trước hết, n&eacute;t ri&ecirc;ng ấy c&oacute; được l&agrave; do từ ngữ được sử dụng theo chiều hướng phổ th&ocirc;ng h&oacute;a, đại ch&uacute;ng h&oacute;a. B&ecirc;n cạnh vốn từ vựng cổ được vận dụng, B&aacute;c c&ograve;n đưa v&agrave;o nhiều từ ngữ bạch thoại - khẩu ngữ.</p>
<p>&ldquo;Ng&ocirc;n từ của B&aacute;c kh&ocirc;ng phải l&agrave; ng&ocirc;n từ cổ điển. Thể loại thơ của B&aacute;c cũng 4 c&acirc;u nhưng n&oacute; l&agrave; tứ tuyệt tự sự - ghi nhật k&iacute;, kể chuyện. Đ&oacute; l&agrave; điều rất kh&aacute;c thơ Đường. Thơ Đường hay so s&aacute;nh, đối thanh, đối &yacute; nhưng thơ của B&aacute;c kh&ocirc;ng chủ về đối. Những việc l&agrave;m của B&aacute;c rất nhỏ nhưng c&oacute; nhiều việc nhỏ của B&aacute;c cũng c&oacute; &yacute; nghĩa lớn. Điều đ&oacute; khẳng định B&aacute;c của ch&uacute;ng ta rất tr&acirc;n trọng, y&ecirc;u qu&yacute; văn h&oacute;a Trung Quốc v&agrave; ra sức học tập n&oacute; nhưng kh&ocirc;ng bao giờ rập khu&ocirc;n.&rdquo; - Gi&aacute;o sư Phương Lựu ph&acirc;n t&iacute;ch.</p>
<p>Gi&aacute;o sư Phương Lựu khẳng định, cống hiến lớn nhất của Chủ tịch Hồ Ch&iacute; Minh về mặt thể loại NXB Văn Học trong &ldquo;Nhật k&iacute; trong t&ugrave;&rdquo; l&agrave; s&aacute;ng tạo ra thể thơ tứ tuyệt tự sự. Hiển nhi&ecirc;n thơ Đường c&oacute; nhiều b&agrave;i mang t&iacute;nh chất tự sự như: &ldquo;Tam tại&rdquo;, &ldquo;Tam biệt&rdquo; của Đỗ Phủ; &ldquo;Trường hận ca&rdquo;, &ldquo;Tỳ b&agrave; h&agrave;nh&rdquo; của Bạch Cư Dị&hellip; nhưng kh&ocirc;ng phải l&agrave; thơ tứ tuyệt.</p>
<p>Thơ Đường luật, nhất l&agrave; tứ tuyệt, th&igrave; tuyệt đại bộ phận l&agrave; thơ trữ t&igrave;nh, tả cảnh hoặc kết hợp cả hai. Ngược lại, thơ tứ tuyệt trong &ldquo;Nhật k&iacute; trong t&ugrave;&rdquo; tuy c&oacute; những b&agrave;i trữ t&igrave;nh nhưng lại c&oacute; t&iacute;nh chất &ldquo;nhật k&iacute;&rdquo; với nhiều chi tiết đời thường, v&iacute; dụ như b&agrave;i: &ldquo;Chia nước&rdquo;, &ldquo; Viết hộ b&aacute;o c&aacute;o cho c&aacute;c bạn t&ugrave;&rdquo;, &ldquo;L&ecirc;n xe lửa đi Lai T&acirc;n&rdquo;, &ldquo;Cuộc sống trong t&ugrave;&rdquo;&hellip;</p>', 2022, NULL, 300, 3, 9, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (43, N'Thơ Tố Hữu (Tái Bản 2024)', N'8935095633753', N'Bìa Mềm', CAST(27950.00 AS Decimal(12, 2)), CAST(55000.00 AS Decimal(12, 2)), CAST(43000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/h/h/hh_bia_tho-to-huu_bia-1.jpg', N'Tố Hữu', N'<p><strong>Thơ Tố Hữu</strong></p>
<p>"Tố Hữu l&agrave; một nh&agrave; thơ lớn. n&oacute;i đ&uacute;ng hơn, &ocirc;ng l&agrave; nh&agrave; thơ l&atilde;ng mạn c&aacute;ch mạng. Cả cuộc đời &ocirc;ng gắn b&oacute; với c&aacute;ch mạng. Thơ với đời l&agrave; một. Trước sau đều nhất qu&aacute;n. Tố Hữu nh&igrave;n c&aacute;ch mạng bằng con mắt l&atilde;ng mạn của một thi sĩ. Thơ &ocirc;ng dường như chỉ c&oacute; một giọng. Đ&oacute; l&agrave; gi&oacute;ng h&aacute;t từng bừng ca ngợi c&aacute;ch mạng. Đọc thơ &ocirc;ng trong bất cứ ho&agrave;n cảnh v&agrave; t&acirc;m trạng n&agrave;o. Ta cũng thấy phấn chấn, n&aacute;o nức như đi trẩy hội. Đến đ&acirc;u cũng nghe vang tiếng trống, tiếng k&egrave;n. M&agrave; thơ &ocirc;ng đ&acirc;u chỉ c&oacute; trống ph&aacute;ch linh đ&igrave;nh như một đ&aacute;m rước, &ocirc;ng c&ograve;n bắn cả 21 ph&aacute;t đại b&aacute;c vang trời. Cho đến nay, chỉ c&oacute; &ocirc;ng l&agrave; nh&agrave; thơ Việt Nam duy nhất đ&atilde; bắn đại b&aacute;c trang trọng như thế."</p>
<p>(Tr&iacute;ch Ch&acirc;n dung v&agrave; đối thoại - Trần Đăng Khoa)</p>', 2024, NULL, 220, 19, 4, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (44, N'Nhật Ký Trong Tù (Tái Bản 2020)', N'8935244843620', N'Bìa Mềm', CAST(34450.00 AS Decimal(12, 2)), CAST(65000.00 AS Decimal(12, 2)), CAST(53000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935244843620.jpg', N'Hồ Chí Minh', N'<p>&ldquo;Tập thơ Nhật k&yacute; trong t&ugrave;của Hồ Ch&iacute; Minh l&agrave; một kho t&agrave;ng về biết bao kh&iacute;a cạnh của cuộc đời, con người v&agrave; nghệ thuật m&agrave; sự phong ph&uacute; c&ograve;n cần được tiếp tục nghi&ecirc;n cứu.&rdquo; - THỦ TƯỚNG PHẠM VĂN ĐỒNG</p>
<p>&ldquo;Thế rồi, giữa kh&ocirc;ng kh&iacute; h&eacute;o hon t&agrave;n lụi của bộ phận văn chương kh&ocirc;ng c&ograve;n mấy ai biết đến l&agrave; văn học chữ H&aacute;n do người Việt Nam s&aacute;ng t&aacute;c, bước v&agrave;o thập ni&ecirc;n cuối c&ugrave;ng của nửa đầu thế kỷ XX bỗng đ&acirc;u lại c&oacute; một tiếng n&oacute;i đột xuất kh&aacute;c thường, cất l&ecirc;n từ một ch&acirc;n trời mới lạ! Tập Ngục trung nhật k&yacute; của Hồ Ch&iacute; Minh - Nguyễn &Aacute;i Quốc ch&iacute;nh l&agrave; ch&acirc;n trời chưa biết đến ấy v&agrave; l&agrave; nguồn sinh lực mới l&agrave;m tươi tắn trở lại d&ograve;ng thơ Việt - H&aacute;n, đ&atilde; tạo n&ecirc;n một kết cục vi&ecirc;n m&atilde;n &iacute;t ai ngờ cho tiến tr&igrave;nh một ngh&igrave;n năm thơ ca chữ H&aacute;n Việt Nam.&rdquo; - GI&Aacute;O SƯ ĐẶNG THAI MAI</p>
<p>&ldquo;N&eacute;t đặc sắc trong thơ của Người l&agrave;&nbsp; niềm&nbsp; tin&nbsp; tưởng&nbsp; v&agrave;&nbsp; sự&nbsp; ung&nbsp; dung ngay&nbsp; cả&nbsp; trong&nbsp; nỗi&nbsp; bất&nbsp; hạnh&nbsp; kh&ocirc;ng thể&nbsp; tin&nbsp; nổi.&nbsp; Trong&nbsp; một&nbsp; ho&agrave;n&nbsp; cảnh như&nbsp; vậy,&nbsp; Hồ&nbsp; Ch&iacute;&nbsp; Minh&nbsp; vẫn&nbsp; rung cảm nồng nhiệt khi tho&aacute;ng nh&igrave;n một khoảng&nbsp; trời&nbsp; xanh,&nbsp; tho&aacute;ng&nbsp; nh&igrave;n&nbsp; một c&aacute;nh chim chiều hoặc chợt nhận thấy hương&nbsp; thơm&nbsp; của&nbsp; hoa&nbsp; rừng&nbsp; sẩm&nbsp; tối. Hoặc khi người thấy một cảnh n&uacute;i xa mờ, những cảnh sống b&igrave;nh thường nơi th&ocirc;n x&oacute;m - c&ocirc; g&aacute;i qu&ecirc; đang xay ng&ocirc;, tiếng&nbsp; s&aacute;o&nbsp; trẻ &nbsp;chăn&nbsp; tr&acirc;u,&nbsp; ngọn&nbsp; kh&oacute;i lam chiều.&rdquo; - NH&Agrave; B&Aacute;O MỸHARRISON S. SALISBURY</p>
<p>&hellip; &ldquo;Sự hiểu biết của Người chẳng những&nbsp; kh&ocirc;ng&nbsp; ngh&egrave;o&nbsp; đi&nbsp; m&agrave;&nbsp; c&ograve;n&nbsp; được l&agrave;m gi&agrave;u th&ecirc;m l&ecirc;n nhờ con mắt ch&uacute; &yacute; quan s&aacute;t v&agrave; c&aacute;i tai rất th&iacute;nh, nhờ tấm l&ograve;ng cởi mở của Người.&hellip;&nbsp; Tất&nbsp; cả&nbsp; những&nbsp; điều&nbsp; đ&oacute;&nbsp; thấm đượm trong những b&agrave;i thơ ngắn của tập nhật k&yacute;, tạo th&agrave;nh bầu kh&ocirc;ng kh&iacute;, th&agrave;nh hệ thống tuần ho&agrave;n, th&agrave;nh điệu nhạc nội tại của ch&uacute;ng.&rdquo; - NH&Agrave; THƠ NGA PAVEL ANTOKOLSKY</p>', 2020, NULL, 292, 6, 2, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (45, N'Truyện Kiều (Tái Bản 2022)', N'8936067604634', N'Bìa Mềm', CAST(30940.00 AS Decimal(12, 2)), CAST(68000.00 AS Decimal(12, 2)), CAST(47600.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8936067604634.jpg', N'Nguyễn Du', N'<p><strong>Truyện Kiều (T&aacute;i Bản 2022)</strong></p>
<p>Quyển Truyện Th&uacute;y Kiều n&agrave;y l&agrave; một quyển s&aacute;ch kiệt t&aacute;c l&agrave;m bằng quốc &acirc;m ta. Người trong nước từ kẻ ngu phu ngu phụ cho ch&iacute; người c&oacute; văn học, ai cũng biết, ai cũng đọc, m&agrave; ai cũng chịu l&agrave; hay. Một quyển s&aacute;ch c&oacute; gi&aacute; trị như thế, m&agrave; chỉ hiềm v&igrave; c&aacute;c bản in ra, c&oacute; nhiều bản kh&ocirc;ng giống nhau, rồi c&oacute; người lại tự &yacute; m&igrave;nh đem chữa đi, chữa lại, th&agrave;nh ra c&agrave;ng ng&agrave;y c&agrave;ng sai lầm th&ecirc;m ra. Mới đ&acirc;y những bản in bằng quốc ngữ, tuy c&oacute; dễ đọc v&agrave; dễ xem hơn trước, nhưng chưa thấy c&oacute; bản in n&agrave;o thật ch&iacute;nh đ&aacute;ng, những điều sai lầm vẫn c&ograve;n như c&aacute;c bản chữ N&ocirc;m cũ, m&agrave; chữ quốc ngữ viết lại kh&ocirc;ng được đ&uacute;ng, v&agrave; những lời giải th&iacute;ch cũng kh&ocirc;ng kỹ c&agrave;ng lắm. Ch&uacute;ng t&ocirc;i thấy vậy, mới nhặt nhạnh c&aacute;c bản cũ, rồi so s&aacute;nh với c&aacute;c bản mới để hiệu chỉnh lại cho gần được như nguy&ecirc;n văn. Ch&uacute;ng t&ocirc;i lại hết sức t&igrave;m t&ograve;i đủ c&aacute;c điển t&iacute;ch m&agrave; giải th&iacute;ch cho r&otilde; r&agrave;ng, để ai xem cũng hiểu, kh&ocirc;ng phải ngờ điều g&igrave; nữa.Hiện nay tập nguy&ecirc;n văn của t&aacute;c giả l&agrave;m ra th&igrave; kh&ocirc;ng t&igrave;m thấy nữa, chỉ c&oacute; hai bản kh&aacute;c nhau &iacute;t nhiều l&agrave;: bản Phường in ở phố H&agrave;ng Gai, H&agrave; Nội; v&agrave; bản Kinh của vua Dực T&ocirc;ng bản triều đ&atilde; chữa lại.Bản Phường l&agrave; bản của &ocirc;ng Phạm Qu&yacute; Th&iacute;ch đem khắc, in ra trước hết cả.</p>
<p>&Ocirc;ng hiệu l&agrave; Lập Trai, người l&agrave;ng Hu&ecirc; Đường (nay đổi l&agrave; l&agrave;ng Lương Đường) phủ B&igrave;nh Giang, tỉnh Hải Dương, đỗ tiến sĩ về cuối đời L&ecirc;, c&ugrave;ng với t&aacute;c giả l&agrave; bạn đồng thanh đồng kh&iacute;, cho n&ecirc;n khi quyển truyện n&agrave;y l&agrave;m xong, th&igrave; t&aacute;c giả đưa cho &ocirc;ng xem. Chắc cũng c&oacute; sửa đổi lại một v&agrave;i c&acirc;u, nhưng xem lời văn th&igrave; chỗ n&agrave;o cũng một giọng cả. Vậy n&ecirc;n ch&uacute;ng t&ocirc;i thiết tưởng rằng lấy bản Phường l&agrave;m cốt, th&igrave; c&oacute; lẽ kh&ocirc;ng sai lầm l&agrave; mấy. C&ograve;n những chỗ m&agrave; bản Kinh đổi kh&aacute;c đi, hoặc những c&acirc;u về sau người ta sửa lại, th&igrave; ch&uacute;ng t&ocirc;i phụ lục cả ở dưới, để độc giả c&oacute; thể xem m&agrave; c&acirc;n nhắc hơn k&eacute;m. Lại c&oacute; một v&agrave;i chữ người ta muốn đổi đi, nhưng kh&ocirc;ng đ&uacute;ng với c&aacute;c bản N&ocirc;m cũ, th&igrave; ch&uacute;ng t&ocirc;i cũng ch&uacute; th&iacute;ch xuống dưới, chứ kh&ocirc;ng tự tiện m&agrave; đổi nguy&ecirc;n văn. Chủ &yacute; của ch&uacute;ng t&ocirc;i l&agrave; muốn giữ cho đ&uacute;ng c&aacute;c bản cũ, chứ kh&ocirc;ng phải muốn l&agrave;m cho hay hơn.Truyện Th&uacute;y Kiều n&agrave;y nguy&ecirc;n l&uacute;c đầu t&aacute;c giả nhan l&agrave; Đoạn trường t&acirc;n thanh.</p>', 2022, NULL, 248, 9, 6, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (46, N'Tục Ngữ, Ca Dao, Dân Ca Việt Nam - Bìa Cứng (Tái Bản 2023)', N'8935236431767', N'Bìa Cứng', CAST(69875.00 AS Decimal(12, 2)), CAST(140000.00 AS Decimal(12, 2)), CAST(107500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935236431767.jpg', N'Vũ Ngọc Phan', N'<p><strong>Tục Ngữ, Ca Dao, D&acirc;n Ca Việt Nam - B&igrave;a Cứng (T&aacute;i Bản 2023)</strong></p>
<p>T&aacute;c phẩm của nh&agrave; nghi&ecirc;n cứu văn học Vũ Ngọc Phan được trao tặng Giải thưởng Hồ Ch&iacute; Minh đợt đầu ti&ecirc;n (năm1996, lĩnh vực văn nghệ d&acirc;n gian).</p>
<p>Cuốn s&aacute;ch được t&aacute;c giả d&agrave;y c&ocirc;ng sưu tầm, khảo cứu trong suốt những năm tham gia kh&aacute;ng chiến chống Ph&aacute;p, đặc biệt từ khi chuyển sang l&agrave;m c&ocirc;ng t&aacute;c nghi&ecirc;n cứu văn - sử - địa v&agrave; ho&agrave;n th&agrave;nh v&agrave;o năm 1956. Vũ Ngọc Phan đ&atilde; c&oacute; phần nghi&ecirc;n cứu t&acirc;m huyết về đặc điểm, gi&aacute; trị đặc sắc của tục ngữ, ca dao, d&acirc;n ca v&ocirc; c&ugrave;ng đa dạng v&agrave; phong ph&uacute; của d&acirc;n tộc Việt Nam ta (trong đ&oacute; c&oacute; cả của một số d&acirc;n tộc thiểu số) b&ecirc;n cạnh phần tuyển chọn c&ocirc;ng phu.</p>
<p>Đặc biệt, cuốn s&aacute;ch c&ograve;n c&oacute; phần bi&ecirc;n khảo rất sớm (với tầm nh&igrave;n xa tr&ocirc;ng rộng) v&agrave; rất gi&aacute; trị về d&acirc;n ca, bao gồm c&aacute;c loại h&igrave;nh như: h&aacute;t trống qu&acirc;n, h&aacute;t xẩm, h&aacute;t quan họ Bắc Ninh, h&aacute;t ghẹo Ph&uacute; Thọ, h&aacute;t v&iacute;, h&aacute;t giặm Nghệ Tĩnh, h&ograve; Huế, d&acirc;n ca miền Nam Trung Bộ, d&acirc;n ca Nam Bộ&hellip;</p>', 2023, NULL, 664, 10, 4, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (47, N'Tục Ngữ Lược Giải (Tái Bản 2024)', N'8935236433631', N'Bìa Mềm', CAST(46475.00 AS Decimal(12, 2)), CAST(110000.00 AS Decimal(12, 2)), CAST(71500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935236433631.jpg', N'Lê Văn Hòe', N'<p><strong>Tục Ngữ Lược Giải (T&aacute;i Bản 2024)</strong></p>
<p>Tục ngữ ta, nhiều c&acirc;u rất kh&oacute; hiểu. Kh&oacute; hiểu hoặc v&igrave; lời qu&aacute; vắn tắt, hoặc v&igrave; &yacute; tưởng bỏ lửng giữa chừng, hoặc v&igrave; chữ d&ugrave;ng qu&aacute; cổ.</p>
<p>Kh&ocirc;ng những anh em thanh ni&ecirc;n học sinh, ngay người lớn ch&uacute;ng ta, nhiều khi cũng kh&ocirc;ng khỏi l&uacute;ng t&uacute;ng trước &yacute; nghĩa một v&agrave;i c&acirc;u tục ngữ, vốn y&ecirc;u chuộng quốc văn, quốc học, ch&uacute;ng t&ocirc;i ch&uacute; trọng đến tục ngữ v&agrave; văn học Việt Nam đ&atilde; từ l&acirc;u.</p>
<p>Rồi sau, trải qua nhiều địa phương, tiếp x&uacute;c với nhiều nghề nghiệp, những điều tai nghe mắt thấy c&ugrave;ng những kinh nghiệm bản th&acirc;n đ&atilde; gi&uacute;p ch&uacute;ng t&ocirc;i hiểu th&ecirc;m một số tục ngữ cần phải giải th&iacute;ch.</p>
<p>Dĩ nhi&ecirc;n, s&aacute;ch&nbsp;<strong>Tục Ngữ Lược Giải</strong>&nbsp;n&agrave;y chỉ giải th&iacute;ch sơ lược đại &yacute; m&agrave; th&ocirc;i, kh&ocirc;ng đi s&acirc;u v&agrave;o lai lịch hay l&agrave; điển cố c&aacute;c tục ngữ. V&agrave; cũng kh&ocirc;ng thể giải th&iacute;ch hết tất cả c&aacute;c tục ngữ Việt Nam, m&agrave; chỉ giải nghĩa những c&acirc;u cần phải giải nghĩa, v&agrave; đ&atilde; t&igrave;m thấy nghĩa.</p>
<p>Những điều tai nghe mắt thấy, những kinh nghiệm hiểu biết của một người, d&ugrave; sao cũng chưa thể đầy đủ được. Những khuyết điểm sai lầm trong s&aacute;ch, nếu c&oacute;, ch&uacute;ng t&ocirc;i mong được c&aacute;c bậc cao minh sẵn l&ograve;ng chỉ gi&aacute;o cho.</p>', 2024, NULL, 332, 4, 13, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (48, N'Tặng Bé Bốn Mùa', N'8935244891157', N'Bìa Mềm', CAST(22425.00 AS Decimal(12, 2)), CAST(46000.00 AS Decimal(12, 2)), CAST(34500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/t/a/tang-be-bon-mua.jpg', N'Lê Thị Thiên Hương', N'<p><strong>Tặng B&eacute; Bốn M&ugrave;a</strong></p>
<p>Cuốn thơ đầu tay của một b&agrave; mẹ trẻ gửi tặng bạn đọc nhỏ tuổi bốn m&ugrave;a xu&acirc;n, hạ, thu, đ&ocirc;ng.</p>
<p>Mời b&eacute; vui c&ugrave;ng những nh&acirc;n vật b&eacute; nhỏ v&agrave; nghịch ngợm như c&aacute;nh cam, ốc s&ecirc;n, c&agrave;o c&agrave;o, m&egrave;o nhỏ&hellip; trong một thế giới mang d&aacute;ng dấp một khu vườn đầy hoa tr&aacute;i, mở ra c&aacute;nh đồng xanh tươi.</p>
<p>Ch&iacute;nh giữa thế giới đ&oacute; l&agrave; gia đ&igrave;nh ấm c&uacute;ng, nơi b&eacute; lớn l&ecirc;n b&igrave;nh an&hellip;</p>', 2023, NULL, 52, 13, 7, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (49, N'Thơ Xuân Quỳnh (Tái Bản 2024)', N'8935095633937', N'Bìa Mềm', CAST(19110.00 AS Decimal(12, 2)), CAST(42000.00 AS Decimal(12, 2)), CAST(29400.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/t/h/tho-xuan-quynh---b1.jpg', N'Xuân Quỳnh', N'<p><strong>Thơ Xu&acirc;n Quỳnh</strong></p>
<p>Xu&acirc;n Quỳnh đ&atilde; để lại dấu ấn đậm n&eacute;t trong d&ograve;ng thơ t&igrave;nh Việt Nam. Thơ của c&ocirc; l&agrave; tiếng l&ograve;ng của một t&acirc;m hồn phụ nữ thấm đẫm t&igrave;nh cảm. C&ocirc; d&agrave;nh nhiều t&acirc;m huyết cho đề t&agrave;i t&igrave;nh y&ecirc;u v&agrave; l&agrave; một trong những người viết thơ t&igrave;nh hay nhất ở thời đại ch&uacute;ng ta.</p>
<p>Tuyển tập&nbsp;<strong>Thơ Xu&acirc;n Quỳnh</strong>&nbsp;giới thiệu tới bạn đọc những b&agrave;i thơ t&igrave;nh gi&agrave;u cảm x&uacute;c, nồng n&agrave;n v&agrave; dữ dội như&nbsp;<em>Thơ viết cho m&igrave;nh v&agrave; những người con g&aacute;i kh&aacute;c</em>,&nbsp;<em>S&oacute;ng</em>&nbsp;hay những b&agrave;i thơ dung dị viết tặng c&aacute;c con trai y&ecirc;u qu&yacute; của c&ocirc; như&nbsp;<em>Ch&ugrave;m thơ xu&acirc;n cho ba con nhỏ</em> (tặng Tuấn Anh, tặng Minh Vũ, tặng Quỳnh Thơ). Tất cả nhờ t&igrave;nh y&ecirc;u thương, thấm đẫm nữ t&iacute;nh ấy m&agrave; bất chấp mọi khổ đau, buồn phiền của một duy&ecirc;n phận nhiều lận đận, Xu&acirc;n Quỳnh để lại trong thơ niềm tin vững chắc về sự hiện diện của hạnh ph&uacute;c c&oacute; thật giữa trần gian n&agrave;y.</p>', 2024, NULL, 140, 9, 2, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (50, N'Nhật Ký Trong Tù', N'8935279149704', N'Bìa Mềm', CAST(56225.00 AS Decimal(12, 2)), CAST(110000.00 AS Decimal(12, 2)), CAST(86500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935279149704.jpg', N'Hồ Chí Minh', N'<p><strong>Nhật K&yacute; Trong T&ugrave;</strong></p>
<p>T&aacute;c phẩm &ldquo;Nhật k&yacute; trong t&ugrave;&rdquo; l&agrave; tập thơ gồm 133 b&agrave;i, viết bằng chữ H&aacute;n, ra đời trong một ho&agrave;n cảnh đặc biệt. Th&aacute;ng 8/1942, Nguyễn &Aacute;i Quốc bị ch&iacute;nh quyền Tưởng Giới Thạch bắt giam v&ocirc; cớ tại T&uacute;c Vinh, Quảng T&acirc;y, khi Người sang Trung Quốc c&ocirc;ng t&aacute;c với danh nghĩa l&agrave; đại biểu của Việt Nam độc lập đồng minh v&agrave; Ph&acirc;n bộ quốc tế phản x&acirc;m lược của Việt Nam. V&agrave; từ đ&acirc;y bắt đầu h&agrave;nh tr&igrave;nh 13 th&aacute;ng đầy gian nan, cực khổ trải qua 18 nh&agrave; lao của 13 huyện thuộc tỉnh Quảng T&acirc;y. Trong những th&aacute;ng ng&agrave;y đ&oacute; (th&aacute;ng 8/1942 &ndash; th&aacute;ng 9/1943), Người đ&atilde; s&aacute;ng t&aacute;c tập thơ &ldquo;Ngục trung nhật k&yacute;&rdquo; (Nhật k&yacute; trong t&ugrave;).</p>
<p>Tập thơ phản &aacute;nh một c&aacute;ch ch&acirc;n thực về chế độ nh&agrave; t&ugrave; v&agrave; một phần x&atilde; hội Trung Quốc dưới thời Tưởng Giới Thạch. Nh&agrave; t&ugrave; l&agrave; nơi diễn ra nhiều tệ nạn (đ&aacute;nh bạc, bu&ocirc;n b&aacute;n, hối lộ&hellip;), với bao bất c&ocirc;ng, ngang tr&aacute;i, đ&agrave;y ải, &aacute;p bức người d&acirc;n trong cảnh khốn c&ugrave;ng. Mỗi b&agrave;i thơ trong tập nhật k&yacute; l&agrave; tiếng l&ograve;ng của t&aacute;c giả, khắc họa s&acirc;u sắc t&acirc;m hồn, những suy nghĩ, t&igrave;nh cảm của B&aacute;c trong thời gian bị giam cầm nơi đất kh&aacute;ch. Đ&oacute; l&agrave; l&ograve;ng y&ecirc;u nước thiết tha, lu&ocirc;n đau đ&aacute;u hướng về Tổ quốc, mong được trở về h&ograve;a m&igrave;nh v&agrave;o cuộc chiến đấu của đồng ch&iacute;, đồng b&agrave;o. T&igrave;nh y&ecirc;u thương bao la, v&ocirc; bờ bến của Người kh&ocirc;ng chỉ d&agrave;nh cho mọi kiếp người, kh&ocirc;ng ph&acirc;n biệt giai cấp, d&acirc;n tộc m&agrave; c&ograve;n l&agrave; t&igrave;nh y&ecirc;u thi&ecirc;n nhi&ecirc;n, h&ograve;a m&igrave;nh v&agrave;o mu&ocirc;n cảnh vật. To&aacute;t l&ecirc;n từ to&agrave;n bộ tập nhật k&yacute; l&agrave; một tinh thần lạc quan c&aacute;ch mạng, niềm tin v&agrave;o ng&agrave;y mai tươi s&aacute;ng, &yacute; ch&iacute; ki&ecirc;n cường, bền bỉ, l&ograve;ng quyết t&acirc;m sắt đ&aacute; của Người. Bản lĩnh của người chiến sĩ cộng sản, sức mạnh tinh thần lớn lao đ&atilde; đưa Người vượt qua đ&agrave;y ải, ngục t&ugrave;, đến với ng&agrave;y tự do, trở về Tổ quốc th&acirc;n y&ecirc;u, l&atilde;nh đạo to&agrave;n d&acirc;n gi&agrave;nh độc lập, tự do cho d&acirc;n tộc. T&aacute;c phẩm đ&atilde; trở th&agrave;nh bảo vật quốc gia của Việt Nam, được bạn b&egrave; quốc tế ngợi ca v&agrave; được dịch ra nhiều ng&ocirc;n ngữ tr&ecirc;n thế giới.</p>', 2023, NULL, 260, 2, 11, 98)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (51, N'Hồi Ký Nguyễn Thị Bình - Gia Đình, Bạn Bè Và Đất Nước', N'8935279173471', N'Bìa Mềm', CAST(98182.50 AS Decimal(12, 2)), CAST(159000.00 AS Decimal(12, 2)), CAST(151050.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/b/_/b_a-gia-_nh_-b_n-b_-v_-_t-n_c_1.jpg', N'Nguyễn Thị Bình', N'<p><strong>Hồi K&yacute; Nguyễn Thị B&igrave;nh - Gia Đ&igrave;nh, Bạn B&egrave; V&agrave; Đất Nước</strong></p>
<p><strong>NỘI DUNG CH&Iacute;NH</strong></p>
<p>Đ&acirc;y l&agrave; cuốn hồi k&yacute; của b&agrave; Nguyễn Thị B&igrave;nh, nguy&ecirc;n Ph&oacute; Chủ tịch nước, nữ Bộ trưởng Ngoại giao đầu ti&ecirc;n, Trưởng đo&agrave;n đ&agrave;m ph&aacute;n của Ch&iacute;nh phủ C&aacute;ch mạng L&acirc;m thời Cộng h&ograve;a miền Nam Việt Nam tại H&ograve;a đ&agrave;m Paris.</p>
<p>Cuốn s&aacute;ch t&aacute;i hiện cuộc đời của b&agrave;, một nh&acirc;n chứng sống đ&atilde; tham gia, chứng kiến những chuyển biến thăng trầm của lịch sử, từ thời thơ ấu cho đến khi tham gia hoạt động c&aacute;ch mạng, những dấu mốc quan trọng trong cuộc đấu tranh gi&agrave;nh độc lập d&acirc;n tộc v&agrave; cả khi đ&atilde; nghỉ hưu, như b&agrave; đ&atilde; chọn một đầu đề thật giản dị: &ldquo;Gia đ&igrave;nh, bạn b&egrave; v&agrave; đất nước&rdquo; - những nguồn gốc đ&atilde; tạo n&ecirc;n sức mạnh đặc biệt trong b&agrave;.</p>
<p>&ldquo;C&oacute; lẽ b&agrave; l&agrave; người Việt Nam c&oacute; nhiều bạn b&egrave; nhất tr&ecirc;n thế giới, từ những người d&acirc;n thường cho đến c&aacute;c nguy&ecirc;n thủ quốc gia nổi tiếng v&agrave; thuộc nhiều chế độ ch&iacute;nh trị kh&aacute;c nhau. Những năm th&aacute;ng ấy, b&agrave; c&oacute; mặt ở hầu khắp h&agrave;nh tinh, v&agrave; thật lạ, thật đẹp, h&igrave;nh ảnh của một Việt Nam đang chiến đấu khốc liệt lại được đại diện kh&ocirc;ng phải bằng một chiến binh đằng đằng s&aacute;t kh&iacute; m&agrave; l&agrave; một phụ nữ nhỏ nhắn, khi&ecirc;m nhường m&agrave; uy&ecirc;n b&aacute;c, gần gũi m&agrave; sang trọng, sự ki&ecirc;n định kh&ocirc;ng g&igrave; lay chuyển nổi lại được thể hiện ch&iacute;nh bằng một vẻ thong dong đầy tự tin... B&agrave; đem bạn b&egrave; về cho d&acirc;n tộc. V&agrave; đấy l&agrave; một trong những nh&acirc;n tố quan trọng nhất quyết định thắng lợi kỳ lạ của Việt Nam trong thế kỷ qua." (Nh&agrave; văn Nguy&ecirc;n Ngọc)</p>
<p>Trong lịch sử ngoại giao thế giới, Hội nghị Paris về Việt Nam l&agrave; cuộc hội đ&agrave;m k&eacute;o d&agrave;i ng&agrave;y nhất, r&ograve;ng r&atilde; 4 năm, từ năm 1968 đến năm 1973. Hội nghị c&oacute; 4 trưởng đo&agrave;n, trong đ&oacute; c&oacute; duy nhất một nữ trưởng đo&agrave;n - b&agrave; Nguyễn Thị B&igrave;nh - Bộ trưởng Bộ Ngoại giao &ndash; Trưởng đo&agrave;n đ&agrave;m ph&aacute;n của Ch&iacute;nh phủ C&aacute;ch mạng l&acirc;m thời Cộng h&ograve;a miền Nam Việt Nam tại Hội nghị Paris về Việt Nam. . Để c&oacute; được chiến thắng ngoại giao mang t&iacute;nh lịch sử n&agrave;y, c&oacute; sự đ&oacute;ng g&oacute;p hi sinh của cả d&acirc;n tộc Việt Nam, trong đ&oacute; kh&ocirc;ng thể kh&ocirc;ng nhắc đến b&agrave; Nguyễn Thị B&igrave;nh &ndash; một trong những người đại diện c&aacute;c b&ecirc;n k&yacute; hiệp định Paris năm 1973 v&agrave; l&agrave; người phụ nữ duy nhất đặt b&uacute;t k&yacute; v&agrave;o Hiệp định n&agrave;y.</p>
<p>Cuốn s&aacute;ch được b&agrave; Nguyễn Thị B&igrave;nh bắt tay viết từ năm 2007, ho&agrave;n th&agrave;nh v&agrave;o cuối năm 2009 v&agrave; được bổ sung, chỉnh sửa qua c&aacute;c năm 2013, 2014, 2023. Từng trang hồi k&yacute; được thể hiện bằng ng&ocirc;n từ giản dị, kh&ocirc;ng triết l&yacute; cao si&ecirc;u m&agrave; gần gũi, s&acirc;u lắng, nhưng đ&atilde; to&aacute;t l&ecirc;n được tinh thần y&ecirc;u nước, &yacute; thức tr&aacute;ch nhiệm, tấm l&ograve;ng v&igrave; nước v&igrave; d&acirc;n, tạo n&ecirc;n sức nặng trong từng c&acirc;u, từng chữ của cuốn hồi k&yacute;.</p>', 2025, NULL, 268, 20, 7, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (52, N'Sách Điệp Viên Hoàn Hảo X6 - Phạm Xuân Ẩn (Trọn bộ)', N'8935086855737', N'Bìa Mềm', CAST(92300.00 AS Decimal(12, 2)), CAST(178000.00 AS Decimal(12, 2)), CAST(142000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935086855737.jpg', N'Larry Berman', N'<p><strong>Điệp Vi&ecirc;n Ho&agrave;n Hảo X6 - Phạm Xu&acirc;n Ẩn</strong></p>
<p>Ấn bản mới n&agrave;y c&oacute; bổ sung Lời giới thiệu của t&aacute;c giả cho lần t&aacute;i bản 2013 &ldquo;S&aacute;u năm sau: hồi tưởng về s&aacute;ch Điệp Vi&ecirc;n Ho&agrave;n Hảo&rdquo;. Larry Berman viết: &ldquo;&hellip;cuộc đời của Ẩn kh&ocirc;ng chỉ l&agrave; một c&acirc;u chuyện chiến tranh m&agrave; c&ograve;n l&agrave; c&acirc;u chuyện về h&agrave;n gắn, về l&ograve;ng trung th&agrave;nh với đất nước v&agrave; bạn b&egrave;.</p>
<p>Trong ấn bản mới, t&ocirc;i đ&atilde; th&ecirc;m v&agrave;o những c&acirc;u chuyện v&agrave; t&igrave;nh tiết mới m&agrave; hồi năm 2007 chưa thể kể ra. T&ocirc;i cũng phản &aacute;nh lại việc một số độc giả d&acirc;n sự v&agrave; qu&acirc;n sự Mỹ đ&atilde; phản ứng về cuốn s&aacute;ch của t&ocirc;i cũng như về nh&acirc;n vật/con người Phạm Xu&acirc;n Ẩn như thế n&agrave;o. Tuy nhi&ecirc;n, điều l&agrave;m cho ấn bản mới n&agrave;y trở n&ecirc;n rất quan trọng đ&oacute; l&agrave; bản dịch mới. Độc giả Việt Nam sẽ lần đầu ti&ecirc;n được đọc c&acirc;u chuyện về cuộc đời phi thường của Phạm Xu&acirc;n Ẩn như ch&iacute;nh những g&igrave; m&agrave; &ocirc;ng đ&atilde; kể với t&ocirc;i, một người Mỹ viết hồi k&yacute; cho &ocirc;ng. Điều n&agrave;y l&agrave;m cho ấn bản của First News - Tr&iacute; Việt vừa rất đặc biệt, vừa l&agrave; một cuốn s&aacute;ch mới chứa đựng rất nhiều th&ocirc;ng tin lần đầu ti&ecirc;n c&ocirc;ng bố&hellip;&rdquo;.</p>
<p>Đặc biệt trong lần in mới n&agrave;y c&ocirc;ng bố bức thư x&uacute;c động của b&agrave; Thu Nh&agrave;n, vợ thiếu tướng Phạm Xu&acirc;n Ẩn, gửi t&aacute;c giả Larry Berman: &ldquo;Do mắt k&eacute;m, t&ocirc;i phải đọc cuốn s&aacute;ch của &ocirc;ng ba lần trong suốt ba ng&agrave;y, d&ugrave; t&ocirc;i muốn đọc xong ngay lập tức: ba ng&agrave;y đầy cảm x&uacute;c, ba ng&agrave;y đầy nước mắt nhớ thương, đầy t&igrave;nh y&ecirc;u v&agrave; sự tiếc nuối&hellip; V&agrave; giờ đ&acirc;y, mỗi lần đọc lại l&agrave; t&ocirc;i kh&ocirc;ng cầm được nước mắt! Một &iacute;t người bạn của t&ocirc;i cũng c&oacute; cảm x&uacute;c như vậy&hellip; Nhưng t&ocirc;i muốn đọc lại nhiều lần để nhớ về chồng t&ocirc;i.</p>', 2022, NULL, 392, 3, 12, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (53, N'Hồi Ký Nguyễn Thị Bình - Gia Đình, Bạn Bè Và Đất Nước', N'8935279173488', N'Bìa Cứng', CAST(138125.00 AS Decimal(12, 2)), CAST(224000.00 AS Decimal(12, 2)), CAST(212500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/b/_/b_a-gia-_nh_-b_n-b_-v_-_t-n_c_1_1.jpg', N'Nguyễn Thị Bình', N'<p><strong>Hồi K&yacute; Nguyễn Thị B&igrave;nh - Gia Đ&igrave;nh, Bạn B&egrave; V&agrave; Đất Nước</strong></p>
<p><strong>NỘI DUNG CH&Iacute;NH</strong></p>
<p>Đ&acirc;y l&agrave; cuốn hồi k&yacute; của b&agrave; Nguyễn Thị B&igrave;nh, nguy&ecirc;n Ph&oacute; Chủ tịch nước, nữ Bộ trưởng Ngoại giao đầu ti&ecirc;n, Trưởng đo&agrave;n đ&agrave;m ph&aacute;n của Ch&iacute;nh phủ C&aacute;ch mạng L&acirc;m thời Cộng h&ograve;a miền Nam Việt Nam tại H&ograve;a đ&agrave;m Paris.</p>
<p>Cuốn s&aacute;ch t&aacute;i hiện cuộc đời của b&agrave;, một nh&acirc;n chứng sống đ&atilde; tham gia, chứng kiến những chuyển biến thăng trầm của lịch sử, từ thời thơ ấu cho đến khi tham gia hoạt động c&aacute;ch mạng, những dấu mốc quan trọng trong cuộc đấu tranh gi&agrave;nh độc lập d&acirc;n tộc v&agrave; cả khi đ&atilde; nghỉ hưu, như b&agrave; đ&atilde; chọn một đầu đề thật giản dị: &ldquo;Gia đ&igrave;nh, bạn b&egrave; v&agrave; đất nước&rdquo; - những nguồn gốc đ&atilde; tạo n&ecirc;n sức mạnh đặc biệt trong b&agrave;.</p>
<p>&ldquo;C&oacute; lẽ b&agrave; l&agrave; người Việt Nam c&oacute; nhiều bạn b&egrave; nhất tr&ecirc;n thế giới, từ những người d&acirc;n thường cho đến c&aacute;c nguy&ecirc;n thủ quốc gia nổi tiếng v&agrave; thuộc nhiều chế độ ch&iacute;nh trị kh&aacute;c nhau. Những năm th&aacute;ng ấy, b&agrave; c&oacute; mặt ở hầu khắp h&agrave;nh tinh, v&agrave; thật lạ, thật đẹp, h&igrave;nh ảnh của một Việt Nam đang chiến đấu khốc liệt lại được đại diện kh&ocirc;ng phải bằng một chiến binh đằng đằng s&aacute;t kh&iacute; m&agrave; l&agrave; một phụ nữ nhỏ nhắn, khi&ecirc;m nhường m&agrave; uy&ecirc;n b&aacute;c, gần gũi m&agrave; sang trọng, sự ki&ecirc;n định kh&ocirc;ng g&igrave; lay chuyển nổi lại được thể hiện ch&iacute;nh bằng một vẻ thong dong đầy tự tin... B&agrave; đem bạn b&egrave; về cho d&acirc;n tộc. V&agrave; đấy l&agrave; một trong những nh&acirc;n tố quan trọng nhất quyết định thắng lợi kỳ lạ của Việt Nam trong thế kỷ qua." (Nh&agrave; văn Nguy&ecirc;n Ngọc)</p>
<p>Trong lịch sử ngoại giao thế giới, Hội nghị Paris về Việt Nam l&agrave; cuộc hội đ&agrave;m k&eacute;o d&agrave;i ng&agrave;y nhất, r&ograve;ng r&atilde; 4 năm, từ năm 1968 đến năm 1973. Hội nghị c&oacute; 4 trưởng đo&agrave;n, trong đ&oacute; c&oacute; duy nhất một nữ trưởng đo&agrave;n - b&agrave; Nguyễn Thị B&igrave;nh - Bộ trưởng Bộ Ngoại giao &ndash; Trưởng đo&agrave;n đ&agrave;m ph&aacute;n của Ch&iacute;nh phủ C&aacute;ch mạng l&acirc;m thời Cộng h&ograve;a miền Nam Việt Nam tại Hội nghị Paris về Việt Nam. . Để c&oacute; được chiến thắng ngoại giao mang t&iacute;nh lịch sử n&agrave;y, c&oacute; sự đ&oacute;ng g&oacute;p hi sinh của cả d&acirc;n tộc Việt Nam, trong đ&oacute; kh&ocirc;ng thể kh&ocirc;ng nhắc đến b&agrave; Nguyễn Thị B&igrave;nh &ndash; một trong những người đại diện c&aacute;c b&ecirc;n k&yacute; hiệp định Paris năm 1973 v&agrave; l&agrave; người phụ nữ duy nhất đặt b&uacute;t k&yacute; v&agrave;o Hiệp định n&agrave;y.</p>
<p>Cuốn s&aacute;ch được b&agrave; Nguyễn Thị B&igrave;nh bắt tay viết từ năm 2007, ho&agrave;n th&agrave;nh v&agrave;o cuối năm 2009 v&agrave; được bổ sung, chỉnh sửa qua c&aacute;c năm 2013, 2014, 2023. Từng trang hồi k&yacute; được thể hiện bằng ng&ocirc;n từ giản dị, kh&ocirc;ng triết l&yacute; cao si&ecirc;u m&agrave; gần gũi, s&acirc;u lắng, nhưng đ&atilde; to&aacute;t l&ecirc;n được tinh thần y&ecirc;u nước, &yacute; thức tr&aacute;ch nhiệm, tấm l&ograve;ng v&igrave; nước v&igrave; d&acirc;n, tạo n&ecirc;n sức nặng trong từng c&acirc;u, từng chữ của cuốn hồi k&yacute;.</p>', 2025, NULL, 268, 2, 12, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (54, N'Người Thầy (Tái Bản 2023)', N'9786045193327', N'Bìa Mềm', CAST(133575.00 AS Decimal(12, 2)), CAST(267000.00 AS Decimal(12, 2)), CAST(205500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786045193327.jpg', N'Nguyễn Chí Vịnh', N'<p><strong>Người Thầy</strong></p>
<p>Nh&acirc;n vật trung t&acirc;m trong cuốn s&aacute;ch l&agrave; &ocirc;ng Ba Quốc, tức Thiếu tướng, Anh h&ugrave;ng Lực lượng vũ trang (LLVT) nh&acirc;n d&acirc;n Đặng Trần Đức, một nh&agrave; t&igrave;nh b&aacute;o xuất sắc của t&igrave;nh b&aacute;o quốc ph&ograve;ng Việt Nam, một c&aacute;n bộ t&igrave;nh b&aacute;o t&agrave;i năng, hội tụ đầy đủ những phẩm chất của một điệp vi&ecirc;n "chui s&acirc;u, leo cao" ho&agrave;n hảo, một nh&agrave; chỉ huy c&oacute; tầm nh&igrave;n chiến lược, sắc sảo, quyết liệt v&agrave; l&agrave; một người thầy c&oacute; c&aacute; t&iacute;nh đặc biệt, nghi&ecirc;m khắc nhưng v&ocirc; c&ugrave;ng nh&acirc;n văn, s&acirc;u sắc.</p>
<p>Với 500 trang khổ lớn, được bố cục th&agrave;nh 7 chương theo phong c&aacute;ch hiện đại, cuốn s&aacute;ch "Người thầy" kh&ocirc;ng chỉ kể về những đ&oacute;ng g&oacute;p quan trọng của &ocirc;ng Ba Quốc đối với ng&agrave;nh T&igrave;nh b&aacute;o quốc ph&ograve;ng m&agrave; c&ograve;n n&oacute;i về sự mất m&aacute;t, hy sinh thầm lặng của c&aacute; nh&acirc;n &ocirc;ng v&agrave; gia đ&igrave;nh, người th&acirc;n. Cuốn s&aacute;ch đồng thời cũng đem đến cho bạn đọc những c&acirc;u chuyện cuộc đời, những điệp vụ, chiến c&ocirc;ng của một số nh&acirc;n vật nổi tiếng, những nh&agrave; t&igrave;nh b&aacute;o lỗi lạc cũng như những người chỉ huy trực tiếp v&agrave; những đồng đội &ldquo;v&agrave;o sinh ra tử&rdquo; của t&aacute;c giả.</p>
<p>Dưới g&oacute;c nh&igrave;n của t&aacute;c giả, Thiếu tướng Đặng Trần Đức l&agrave; một người sẵn s&agrave;ng hy sinh v&igrave; đất nước dưới sự l&atilde;nh đạo của Đảng, hết m&igrave;nh v&igrave; nhiệm vụ, nghi&ecirc;m khắc về c&ocirc;ng việc nhưng cũng rất đời thường, quan t&acirc;m v&agrave; s&acirc;u s&aacute;t đối với thế hệ trẻ. Với tấm l&ograve;ng k&iacute;nh trọng, cảm phục về người thầy của m&igrave;nh, Thượng tướng Nguyễn Ch&iacute; Vịnh đ&atilde; truyền lửa cho đo&agrave;n vi&ecirc;n, thanh ni&ecirc;n, thế hệ trẻ về t&igrave;nh y&ecirc;u, l&yacute; tưởng c&aacute;ch mạng của Thiếu tướng Đặng Trần Đức, về niềm tin đối với thế hệ trẻ của lớp người đi trước.</p>
<p>Thượng tướng Nguyễn Ch&iacute; Vịnh t&acirc;m sự đ&acirc;y l&agrave; cuốn s&aacute;ch &ocirc;ng viết d&agrave;nh cho c&aacute;c bạn trẻ. C&acirc;u chuyện về Thiếu tướng Đặng Trần Đức cũng như những người đồng đội của &ocirc;ng, kh&ocirc;ng chỉ l&agrave; c&acirc;u chuyện về ri&ecirc;ng &ocirc;ng, về ng&agrave;nh t&igrave;nh b&aacute;o quốc ph&ograve;ng, m&agrave; c&ograve;n l&agrave; những c&acirc;u chuyện về thế hệ Hồ Ch&iacute; Minh, kh&ocirc;ng chỉ l&agrave; lịch sử m&agrave; c&ograve;n l&agrave; gi&aacute; trị của d&acirc;n tộc, của đất nước phải giữ g&igrave;n. Đ&oacute; cũng ch&iacute;nh l&agrave; l&yacute; do để cuốn s&aacute;ch ra mắt bạn đọc.</p>
<p>T&aacute;c giả cũng mong muốn cuốn s&aacute;ch &ldquo;Người thầy&rdquo; đến với bạn đọc n&oacute;i chung, thế hệ trẻ n&oacute;i ri&ecirc;ng như một mảnh gh&eacute;p rất nhỏ về qu&aacute; khứ, qua đ&oacute; để bạn đọc hiểu r&otilde; hơn về gi&aacute; trị của h&ograve;a b&igrave;nh.</p>', 2023, NULL, 498, 2, 1, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (55, N'Sách Điệp Viên Hoàn Hảo X6 - Phạm Xuân Ẩn (Trọn bộ)', N'8935086855720', N'Bìa Cứng', CAST(102700.00 AS Decimal(12, 2)), CAST(198000.00 AS Decimal(12, 2)), CAST(158000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935086855720.jpg', N'Larry Berman', N'<p>Phạm Xu&acirc;n Ẩn, một c&aacute;i t&ecirc;n chứa biết bao điều b&iacute; ẩn, kh&ocirc;ng chỉ với người Việt Nam, m&agrave; đối với cả rất nhiều ch&iacute;nh kh&aacute;ch v&agrave; b&aacute;o ch&iacute; thế giới, đặc biệt l&agrave; b&aacute;o ch&iacute; Mỹ. Người ta đ&atilde; b&igrave;nh luận, tranh c&atilde;i, phỏng đo&aacute;n v&agrave; viết rất nhiều về &ocirc;ng, thậm ch&iacute; c&ograve;n l&agrave;m phim t&agrave;i liệu nhiều tập về &ocirc;ng, nhưng dường như c&ograve;n c&oacute; qu&aacute; nhiều điều vẫn chưa được l&agrave;m s&aacute;ng tỏ. Cho đến khi một người Mỹ bắt tay v&agrave;o cuộc&hellip; Đ&oacute; ch&iacute;nh l&agrave; Larry Berman, nh&agrave; sử học, gi&aacute;o sư ch&iacute;nh trị học thuộc đại học California, một chuy&ecirc;n gia xuất sắc chuy&ecirc;n nghi&ecirc;n cứu về cuộc chiến tranh x&acirc;m lược Việt Nam của Mỹ.</p>
<p>Năm 2007, quyển s&aacute;ch Perfect Spy - The Incredible Double Life of PHAM XUAN AN Time Magazine Reporter &amp; Vietnamese Communist Agent (Điệp vi&ecirc;n ho&agrave;n hảo &ndash; Hai cuộc đời kh&oacute; tin (hay cuộc đời hai mặt theo c&aacute;ch gọi của Phương T&acirc;y về&nbsp;&nbsp; Phạm Xu&acirc;n Ẩn, ph&oacute;ng vi&ecirc;n tạp ch&iacute; Reuters, Time v&agrave; tướng t&igrave;nh b&aacute;o Cộng sản Việt Nam)) của Larry Berman được xuất bản lần đầu ti&ecirc;n tại Mỹ đ&atilde; g&acirc;y chấn động dư luận Mỹ, kiều b&agrave;o Việt Nam ở Mỹ v&agrave; cả ở Việt Nam. V&igrave; trước khi quyển s&aacute;ch n&agrave;y ra đời, rất &iacute;t người biết v&agrave; hiểu về tướng t&igrave;nh b&aacute;o Phạm Xu&acirc;n Ẩn, mặc d&ugrave; &ocirc;ng l&agrave; một nh&acirc;n vật huyền thoại của chiến tranh Việt Nam. C&oacute; lẽ bởi v&igrave; cuộc đời của Phạm Xu&acirc;n Ẩn, cũng giống như t&ecirc;n của &ocirc;ng, chứa đựng nhiều b&iacute; ẩn về con người v&agrave; sự nghiệp của một nh&agrave; t&igrave;nh b&aacute;o vĩ đại, t&agrave;i năng v&agrave; bản lĩnh nhưng lại v&ocirc; c&ugrave;ng khi&ecirc;m nhường, b&igrave;nh dị.</p>
<p>Phạm Xu&acirc;n Ẩn (sinh ng&agrave;y 12/9/1927, mất ng&agrave;y 20/9/2006) tham gia hoạt động c&aacute;ch mạng từ đầu thập ni&ecirc;n 1950, năm 1953 được kết nạp Đảng v&agrave; được giao nhiệm vụ hoạt động điệp b&aacute;o. Nhằm tạo vỏ bọc tốt hơn để c&oacute; thể th&acirc;m nhập s&acirc;u hơn v&agrave;o giới chức ch&iacute;nh quyền v&agrave; qu&acirc;n đội S&agrave;i G&ograve;n, năm 1957 &ocirc;ng được cấp tr&ecirc;n bố tr&iacute; cho sang Mỹ học ng&agrave;nh b&aacute;o ch&iacute;. Năm 1959, Phạm Xu&acirc;n Ẩn về nước, l&agrave;m việc cho H&atilde;ng tin Reuters v&agrave; sau đ&oacute; l&agrave; tạp ch&iacute; h&agrave;ng đầu Time, New York Herald Tribune của Mỹ. Với kiến thức uy&ecirc;n b&aacute;c, hiểu biết rộng, cương trực v&agrave; t&agrave;i năng giao tiếp, ngoại giao kh&aacute;c biệt, độc đ&aacute;o theo kiểu l&atilde;ng tử, h&agrave;o hoa, ngang t&agrave;ng, &ldquo;chửi thề như bắp rang&rdquo;, xuất hiện với phong c&aacute;ch thượng lưu, thừa hưởng văn h&oacute;a được đ&agrave;o tạo ch&iacute;nh qui từ Mỹ, &ocirc;ng đ&atilde; th&acirc;m nhập v&agrave; l&agrave; bạn tri kỷ với c&aacute;c tướng lĩnh, tr&ugrave;m an ninh mật vụ cả Mỹ v&agrave; S&agrave;i G&ograve;n, giới b&aacute;o ch&iacute; Việt Nam Cộng H&ograve;a v&agrave; Mỹ cũng như c&aacute;c ch&iacute;nh kh&aacute;ch ch&oacute;p bu của ch&iacute;nh quyền S&agrave;i G&ograve;n để khai th&aacute;c những th&ocirc;ng tin tuyệt mật mang tầm chiến lược cho cuộc đối đầu của Bắc Việt Nam với Mỹ v&agrave; ch&iacute;nh quyền S&agrave;i G&ograve;n.</p>', 2022, NULL, 391, 2, 13, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (59, N'Thư Cho Em', N'8935235241015', N'Bìa Mềm', CAST(72800.00 AS Decimal(12, 2)), CAST(140000.00 AS Decimal(12, 2)), CAST(112000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935235241015.jpg', N'Hoàng Nam Tiến', N'<p><strong>Thư Cho Em</strong></p>
<p>Cuốn s&aacute;ch n&agrave;y kể về mối t&igrave;nh vượt qua hai thế kỷ của thiếu tướng Ho&agrave;ng Đan v&agrave; vợ l&agrave; đại biểu Quốc hội Nguyễn Thị An Vinh. Thương nhau từ thuở đ&ocirc;i mươi, n&ecirc;n duy&ecirc;n vợ chồng, họ c&ugrave;ng nhau đi qua những mốc lịch sử lớn lao của d&acirc;n tộc: chiến thắng Điện Bi&ecirc;n Phủ 1954, Khe Sanh 1968, Quảng Trị 1972, S&agrave;i G&ograve;n 1975, bi&ecirc;n giới ph&iacute;a Bắc 1979 v&agrave; 1984.</p>
<p>Vị tướng trận đi khắp c&aacute;c chiến trường &aacute;c liệt, người vợ ở nh&agrave; nu&ocirc;i con v&agrave; phấn đấu sự nghiệp, thời gian họ ở b&ecirc;n nhau &iacute;t ỏi v&ocirc; c&ugrave;ng. V&igrave; thế họ gửi gắm t&acirc;m t&igrave;nh qua những l&aacute; thư băng qua bom đạn, vượt c&aacute;c bi&ecirc;n giới. Những l&aacute; thư trở th&agrave;nh sợi d&acirc;y buộc chặt t&igrave;nh y&ecirc;u của hai con người.</p>
<p>Ho&agrave;ng Nam Tiến đ&atilde; viết thật x&uacute;c động về c&acirc;u chuyện t&igrave;nh y&ecirc;u tr&agrave;n đầy tr&igrave;u mến của ba mẹ, th&ocirc;ng qua những l&aacute; thư ấy, kh&ocirc;ng chỉ để lưu giữ k&yacute; ức ri&ecirc;ng của gia đ&igrave;nh, m&agrave; c&ograve;n kể lại cho người đọc h&ocirc;m nay về một thời đại v&ocirc; c&ugrave;ng anh h&ugrave;ng v&agrave; tuyệt vời l&atilde;ng mạn.</p>', 2024, NULL, 312, 9, 10, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (60, N'Cát Bụi Chân Ai - Tặng Kèm Bookmark Bồi Cứng', N'8938536458953', N'Bìa Mềm', CAST(89375.00 AS Decimal(12, 2)), CAST(179000.00 AS Decimal(12, 2)), CAST(137500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/z/6/z6604030037630_d9e236fa3aa83bd7bbcc38178e38933a.jpg', N'Tô Hoài', N'<p><strong>C&aacute;t Bụi Ch&acirc;n Ai</strong></p>
<p>Cuốn hồi k&yacute; được xuất bản lần đầu v&agrave;o năm 1992 đ&atilde; khắc hoạ th&agrave;nh c&ocirc;ng v&agrave; sống động về ch&acirc;n dung c&aacute;c nh&agrave; văn nổi tiếng Nguyễn Tu&acirc;n, Nguy&ecirc;n Hồng, Nguyễn B&iacute;nh, Xu&acirc;n Diệu,.. đồng thời gi&uacute;p ch&uacute;ng ta hiểu r&otilde; hơn về một thời đại văn học.</p>
<p>&ldquo;Đem c&aacute;i duy&ecirc;n đẹp đẽ mọi bề qu&agrave;ng cho Nguyễn Tu&acirc;n c&oacute; thể chưa k&iacute;n nghĩa, m&agrave; cũng kh&ocirc;ng hẳn đ&uacute;ng. Về văn v&agrave; cả về đời. C&oacute; người m&ecirc; Nguyễn Tu&acirc;n như điếu đổ, từng chữ. C&oacute; người chỉ lướt một đoạn đ&atilde; kh&ocirc;ng chịu được c&aacute;i giọng khụng khiệng, khệnh khạng. Triết l&yacute; v&agrave; c&acirc;u văn Nguyễn Tu&acirc;n kh&ocirc;ng giống vị ho&agrave;i sơn trong thang thuốc bắc, ghẻ bổ một t&yacute;, lại v&ocirc; thưởng v&ocirc; phạt. C&aacute;i chơi của Nguyễn Tu&acirc;n cũng thế. Với người n&agrave;y, kh&ocirc;ng thể thiếu Nguyễn Tu&acirc;n. Người kia th&igrave; kh&ocirc;ng chịu đựng được. &Ocirc; hay, người ta ra người ta th&igrave; người ta phải l&agrave; người ta đ&atilde; chứ.&rdquo;</p>', 2025, NULL, 376, 10, 1, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (61, N'MBA Bằng Hình - The Visual MBA', N'8935235238978', N'Bìa Mềm', CAST(100425.00 AS Decimal(12, 2)), CAST(189000.00 AS Decimal(12, 2)), CAST(154500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935235238978.jpg', N'Jason Barron , MBA', N'<p><strong>MBA Bằng H&igrave;nh - The Visual MBA</strong></p>
<p>Jason Barron, MBA, l&agrave; một nh&agrave; l&atilde;nh đạo đầy s&aacute;ng tạo tập trung v&agrave;o chiến lược sản phẩm số v&agrave; trải nghiệm người d&ugrave;ng. &Ocirc;ng cũng l&agrave; đồng sự s&aacute;ng lập n&ecirc;n c&ocirc;ng ty khởi nghiệp LowestMed, vốn được RetailMeNot th&acirc;u t&oacute;m v&agrave;o năm 2018, v&agrave; hiện nay đang l&agrave;m quản l&yacute; cấp cao cho một tổ chức phi lợi nhuận lớn chuy&ecirc;n về c&aacute;c sản phẩm số cung cấp cho h&agrave;ng triệu người d&ugrave;ng tr&ecirc;n khắp thế giới.</p>
<p>&Ocirc;ng nhận bằng cử nh&acirc;n từ Đại học Southern Virginia năm 2007 v&agrave; bằng Thạc sĩ Quản trị Kinh doanh từ Đại học Brigham Young v&agrave;o năm 2017.</p>
<p>Hiện tại Jason đang sống gần Salt Lake City, Utah, với vợ v&agrave; năm người con. T&igrave;m hiểu th&ecirc;m về Jason tại địa chỉ jasonbarron.com.</p>
<p>Jason Barron mang lại c&aacute;i nh&igrave;n cận cảnh về cấu tr&uacute;c của kh&oacute;a học MBA trong trường kinh doanh th&ocirc;ng qua những ghi ch&eacute;p trực quan trong một cuốn s&aacute;ch đầy những minh họa l&ocirc;i cuốn v&agrave; dễ tiếp thu. Nhờ đ&oacute; bạn đọc c&oacute; thể dễ d&agrave;ng hiểu được những kh&aacute;i niệm quan trọng như:</p>
<p>Kế to&aacute;n quản trị l&agrave; g&igrave;?</p>
<p>L&agrave;m sao để hoạch định t&agrave;i ch&iacute;nh khởi nghiệp?</p>
<p>N&ecirc;n lập chiến lược kinh doanh v&agrave; quản trị doanh nghiệp khởi nghiệp như thế n&agrave;o?</p>
<p>T&agrave;i ch&iacute;nh doanh nghiệp l&agrave; g&igrave; v&agrave; l&agrave;m sao để ph&acirc;n bổ n&oacute; hiệu quả?</p>', 2023, NULL, 207, 14, 4, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (62, N'Bí Mật Tư Duy Triệu Phú (Tái Bản 2021)', N'8935086854624', N'Bìa Mềm', CAST(55900.00 AS Decimal(12, 2)), CAST(108000.00 AS Decimal(12, 2)), CAST(86000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_188995_1_1.jpg', N'T Harv Eker', N'<p>Trong cuốn s&aacute;ch n&agrave;y&nbsp;<strong>T. Harv Eker&nbsp;</strong>sẽ tiết lộ những b&iacute; mật tại sao một số người lại đạt được những th&agrave;nh c&ocirc;ng vượt bậc, được số phận ban cho cuộc sống sung t&uacute;c, gi&agrave;u c&oacute;, trong khi một số người kh&aacute;c phải chật vật, vất vả mới c&oacute; một cuộc sống qua ng&agrave;y. Bạn sẽ hiểu được nguồn gốc sự thật v&agrave; những yếu tố quyết định th&agrave;nh c&ocirc;ng, thất bại để rồi &aacute;p dụng, thay đổi c&aacute;ch suy nghĩ, l&ecirc;n kế hoạch rồi t&igrave;m ra c&aacute;ch l&agrave;m việc, đầu tư, sử dụng nguồn t&agrave;i ch&iacute;nh của bạn theo hướng hiệu quả nhất.</p>
<p>Cuốn s&aacute;ch d&agrave;nh cho những ai c&ograve;n loay hoay muốn t&igrave;m đường đến sự gi&agrave;u c&oacute; v&agrave; th&agrave;nh c&ocirc;ng. &ldquo;B&iacute; mật tự duy triệu ph&uacute;&rdquo; mang đến nhiều tư duy mới cho người đọc về c&aacute;ch suy nghĩ của người gi&agrave;u hay c&aacute;ch suy nghĩ để trở n&ecirc;n gi&agrave;u c&oacute;.</p>
<p>Trong cuốn s&aacute;ch, Eker liệt k&ecirc; 17 c&aacute;ch thức m&agrave; c&aacute;c kế hoạch chi tiết t&agrave;i ch&iacute;nh của những người gi&agrave;u kh&aacute;c với người ngh&egrave;o v&agrave; tầng lớp trung lưu. Một chủ đề được x&aacute;c định trong s&aacute;ch n&agrave;y l&agrave; loại bỏ c&aacute;c suy nghĩ đổ lỗi cho sự thất bại. Eker lập luận rằng: Người gi&agrave;u tin "T&ocirc;i tạo ra cuộc sống của t&ocirc;i", c&ograve;n những người ngh&egrave;o cho rằng "Cuộc sống sẽ tự nhi&ecirc;n đến với t&ocirc;i"; người gi&agrave;u tập trung v&agrave;o c&aacute;c cơ hội trong khi người ngh&egrave;o tập trung v&agrave;o những trở ngại; v&agrave; những người gi&agrave;u ngưỡng mộ những người gi&agrave;u c&oacute; v&agrave; th&agrave;nh c&ocirc;ng kh&aacute;c trong khi người d&acirc;n ngh&egrave;o ghen tị, bực tức trước những người th&agrave;nh c&ocirc;ng v&agrave; gi&agrave;u c&oacute;.</p>
<p><strong>B&iacute; mật tư duy triệu ph&uacute; l&agrave; t&aacute;c phẩm nổi tiếng thế giới được thời b&aacute;o New York Times, Wall Street Journal v&agrave; USB Today b&igrave;nh chọn l&agrave; cuốn s&aacute;ch hay nhất, b&aacute;n chạy nhất trong nhiều năm</strong><strong>.</strong></p>', 2021, NULL, 287, 13, 2, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (63, N'D. Trump - Nghệ Thuật Đàm Phán (Tái Bản 2020)', N'8934974165705', N'Bìa Mềm', CAST(59475.00 AS Decimal(12, 2)), CAST(109000.00 AS Decimal(12, 2)), CAST(91500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_195509_1_49918.jpg', N'Donald J Trump, Tony Schartz', N'<p>Quyển s&aacute;ch cho ch&uacute;ng ta thấy c&aacute;ch Trump l&agrave;m việc mỗi ng&agrave;y - c&aacute;ch &ocirc;ng điều h&agrave;nh c&ocirc;ng việc kinh doanh v&agrave; cuộc sống - cũng như c&aacute;ch &ocirc;ng tr&ograve; chuyện với bạn b&egrave; v&agrave; gia đ&igrave;nh, l&agrave;m ăn với đối thủ, mua th&agrave;nh c&ocirc;ng những s&ograve;ng bạc h&agrave;ng đầu ở th&agrave;nh phố Atlantic, thay đổi bộ mặt của những cao ốc ở th&agrave;nh phố New York&hellip; v&agrave; x&acirc;y dựng những t&ograve;a nh&agrave; chọc trời tr&ecirc;n thế giới.</p>
<p>Quyển s&aacute;ch đi s&acirc;u v&agrave;o đầu &oacute;c của một doanh nh&acirc;n xuất sắc v&agrave; kh&aacute;m ph&aacute; một c&aacute;ch khoa học chưa từng thấy về c&aacute;ch đ&agrave;m ph&aacute;n một thương vụ th&agrave;nh c&ocirc;ng. Đ&acirc;y l&agrave; một cuốn s&aacute;ch th&uacute; vị về đ&agrave;m ph&aacute;n v&agrave; kinh doanh &ndash; v&agrave; l&agrave; một cuốn s&aacute;ch n&ecirc;n đọc cho bất kỳ ai quan t&acirc;m đến đầu tư, bất động sản v&agrave; th&agrave;nh c&ocirc;ng.</p>', 2020, NULL, 328, 15, 4, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (64, N'Quản Trị Bằng Văn Hóa - Cách Thức Kiến Tạo Và Tái Tạo Văn Hóa Tổ Chức', N'8935280401068', N'Bìa Mềm', CAST(125125.00 AS Decimal(12, 2)), CAST(250000.00 AS Decimal(12, 2)), CAST(192500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935280401068.jpg', N'Giản Tư Trung', N'<p><strong>Quản Trị Bằng Văn H&oacute;a - C&aacute;ch Thức Kiến Tạo V&agrave; T&aacute;i Tạo Văn H&oacute;a Tổ Chức</strong></p>
<p>Th&ocirc;ng qua cuốn s&aacute;ch, TS Giản Tư Trung cũng mong muốn g&oacute;p phần cổ vũ v&agrave; th&uacute;c đẩy cho sự ph&aacute;t triển của một phương c&aacute;ch quản trị mới, vừa nh&acirc;n văn, vừa hiệu quả, đ&oacute; l&agrave; &ldquo;Quản trị bằng Văn h&oacute;a / Quản trị bằng Tự trị&rdquo; (Management by Culture /</p>
<p>Management by Self-Mangement). Bởi lẽ t&aacute;c giả tin rằng, b&ecirc;n cạnh c&aacute;c phương c&aacute;ch quản trị truyền thống như Quản trị bằng Luật lệ (Mangement by Polices) hay Quản trị bằng Mục ti&ecirc;u (Management by Objectives) th&igrave; Quản trị bằng Văn h&oacute;a (Management by Culture) ch&iacute;nh l&agrave; tương lai của quản trị v&agrave; tương lai của l&atilde;nh đạo trong một thế giới đầy biến động v&agrave; trong một thời đại m&agrave; con người ng&agrave;y c&agrave;ng trở n&ecirc;n độc lập v&agrave; tự do hơn. Cuốn s&aacute;ch n&agrave;y c&oacute; sự t&iacute;ch hợp xuy&ecirc;n suốt từ tinh thần, tư tưởng v&agrave; triết l&yacute; cho đến phương ph&aacute;p v&agrave; giải ph&aacute;p, cũng như c&oacute; sự kết nối 5 chủ thể văn h&oacute;a l&agrave; c&aacute; nh&acirc;n, bộ phận, tổ chức, kinh thương, v&agrave; quốc gia. Đặc biệt, những tư duy v&agrave; phương ph&aacute;p cốt l&otilde;i về x&acirc;y dựng v&agrave; chuyển đổi văn h&oacute;a được chia sẻ trong cuốn s&aacute;ch n&agrave;y c&oacute; t&iacute;nh nguy&ecirc;n l&yacute;, n&ecirc;n kh&ocirc;ng chỉ &aacute;p dụng cho c&aacute;c doanh nghiệp, m&agrave; c&ograve;n c&oacute; thể &aacute;p dụng cho mọi loại h&igrave;nh tổ chức kh&aacute;c, bao gồm cả trường học, bệnh viện, b&aacute;o ch&iacute;, c&aacute;c tổ chức x&atilde; hội, cơ quan nh&agrave; nước, hay c&aacute;c tổ chức phi ch&iacute;nh phủ.</p>', 2023, NULL, 396, 5, 15, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (65, N'Một Đời Quản Trị (Tái Bản 2019)', N'8934974164623', N'Bìa Mềm', CAST(109200.00 AS Decimal(12, 2)), CAST(200000.00 AS Decimal(12, 2)), CAST(168000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8934974164623.jpg', N'Phan Văn Trường', N'<p>C&oacute; rất nhiều doanh nh&acirc;n vĩ đại, những người s&aacute;ng lập, x&acirc;y dựng, điều h&agrave;nh những c&ocirc;ng ty h&agrave;ng đầu thế giới với doanh thu cả trăm tỷ đ&ocirc;-la Mỹ, những c&ocirc;ng ty s&aacute;ng tạo c&ocirc;ng nghệ v&agrave; sản phẩm l&agrave;m thay đổi thế giới, nhưng họ kh&ocirc;ng viết s&aacute;ch d&ugrave; rằng c&oacute; nhiều s&aacute;ch viết về họ.<br>GS. Phan Văn Trường kh&aacute;c họ. &Ocirc;ng đ&atilde; từng đứng đầu c&aacute;c tập đo&agrave;n khổng lồ với doanh thu 60-70 tỷ đ&ocirc;-la Mỹ, hoạt động tr&ecirc;n cả trăm quốc gia, với h&agrave;ng chục ngh&igrave;n nh&acirc;n vi&ecirc;n đủ c&aacute;c quốc tịch. V&agrave; &ocirc;ng viết s&aacute;ch. Ch&iacute;nh x&aacute;c hơn l&agrave; &ocirc;ng ghi lại những g&igrave; tinh t&uacute;y nhất v&agrave; lại giản dị nhất của một doanh nh&acirc;n người Việt tầm cỡ Global.</p>
<p>Cuốn s&aacute;ch l&agrave; nhật k&yacute;, l&agrave; t&acirc;m sức cả đời của &ocirc;ng n&ecirc;n thật kh&oacute; giới thiệu trong v&agrave;i trang. Nhưng t&ocirc;i muốn ghi lại những điều t&acirc;m đắc.<br>-&nbsp;&nbsp; &nbsp;Phần lớn Doanh nh&acirc;n nhầm lẫn giữa quản l&yacute; v&agrave; quản trị. Vậy nh&agrave; l&atilde;nh đạo quản trị Doanh nghiệp như thế n&agrave;o, họ phải l&agrave;m g&igrave;&hellip;<br>-&nbsp;&nbsp; &nbsp;L&agrave;m thế n&agrave;o để x&acirc;y dựng doanh nghiệp trường tồn<br>-&nbsp;&nbsp; &nbsp;Quản trị doanh nghiệp ch&iacute;nh l&agrave; quản trị con người</p>
<p>C&oacute; lẽ những điều tr&ecirc;n bạn đ&atilde; gặp ở rất nhiều cuốn s&aacute;ch nhưng ở đ&acirc;y c&oacute; 2 điều kh&aacute;c biệt:<br>-&nbsp;&nbsp; &nbsp;L&agrave; b&agrave;i học thực tế, l&agrave; tinh t&uacute;y của một doanh nh&acirc;n tầm cỡ Global<br>-&nbsp;&nbsp; &nbsp;H&agrave;nh xử chuy&ecirc;n nghiệp, quyết định s&aacute;ng suốt, th&agrave;nh c&ocirc;ng lớn&hellip;ở tầm Global&nbsp; nhưng vẫn mang đậm chất Việt, đậm chất nh&acirc;n văn.</p>
<p>V&agrave; đặc biệt những c&acirc;u chuyện của &ocirc;ng, những b&agrave;i học của &ocirc;ng lại được kể bằng những con người thực &Ocirc;ng đ&atilde; c&ugrave;ng l&agrave;m việc, bằng những c&acirc;u chuyện thực của đời m&igrave;nh</p>', 2022, NULL, 495, 4, 6, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (66, N'Vị Tu Sĩ Bán Chiếc Ferrari (Tái Bản Từ Cuốn Tìm Về Sức Mạnh Vô Biên) - Tái Bản 2020', N'8935086852996', N'Bìa Mềm', CAST(50700.00 AS Decimal(12, 2)), CAST(98000.00 AS Decimal(12, 2)), CAST(78000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_195509_1_55840.jpg', N'Robin Sharma', N'<p><strong>Vị tu sĩ b&aacute;n chiếc Ferrari</strong></p>
<p><strong>C</strong><strong>uốn s&aacute;ch cho những người kh&aacute;t khao theo đuổi đam m&ecirc;</strong></p>
<p><strong>Vị Tu Sĩ B&aacute;n Chiếc F</strong><strong>erarri</strong>&nbsp;kh&ocirc;ng phải l&agrave; một cuốn s&aacute;ch xa lạ, cuốn s&aacute;ch n&agrave;y l&agrave; một trong những ấn phẩm kinh điển của thế giới về đề t&agrave;i truyền cảm hứng, theo đuổi l&yacute; tưởng sống, v&agrave; hướng về một cuộc sống hạnh ph&uacute;c. Đ&acirc;y cũng l&agrave; cuốn s&aacute;ch đầu ti&ecirc;n m&agrave; t&aacute;c giả, nh&agrave; diễn thuyết nổi tiếng thế giới Robin Sharma chấp b&uacute;t.</p>
<p>Cuốn s&aacute;ch g&acirc;y được tiếng vang khi xuất bản năm 1997 v&agrave; b&aacute;n được hơn 3 triệu bản v&agrave;o năm 2013.</p>
<p>Từng được xuất bản v&agrave; b&aacute;n chạy ở Việt Nam với c&aacute;i t&ecirc;n T&igrave;m về sức mạnh v&ocirc; bi&ecirc;n, trong lần t&aacute;i bản n&agrave;y,&nbsp;<strong>Vị</strong><strong>&nbsp;tu sĩ b&aacute;n chiếc Ferrari</strong>&nbsp;l&agrave; phi&ecirc;n bản bổ sung, ho&agrave;n thiện v&agrave; tiếp tục l&agrave; cuốn s&aacute;ch kinh điển về đề t&agrave;i truyền cảm hứng, theo đuổi l&yacute; tưởng sống, hướng tới cuộc sống hạnh ph&uacute;c của t&aacute;c giả Robin Sharma.</p>
<p>Ngay từ năm 1997, Vị tu sĩ b&aacute;n chiếc Ferrari đ&atilde; nhanh ch&oacute;ng trở th&agrave;nh hiện tượng v&agrave; nằm trong danh s&aacute;ch best-seller, b&aacute;n ra hơn 4 triệu bản tại 50 quốc gia tr&ecirc;n khắp thế giới. Điều đặc biệt, khi đ&oacute; Robin Sharma chỉ l&agrave; một t&aacute;c giả trẻ chưa c&oacute; t&ecirc;n tuổi.</p>
<p>Vậy, tại sao cuốn s&aacute;ch n&agrave;y lại c&oacute; sức hấp dẫn với bạn đọc tr&ecirc;n to&agrave;n thế giới?</p>
<p><strong>Vị tu sĩ b&aacute;n chiếc Ferrari</strong>&nbsp;kể về Julian Manter, một luật sư dưới con mắt x&atilde; hội l&agrave; một người đứng tr&ecirc;n đỉnh cao danh vọng: l&agrave; &ldquo;ng&ocirc;i sao&rdquo; trong ng&agrave;nh luật, thu nhập l&ecirc;n tới bảy con số, sở hữu một căn biệt thự tr&aacute;ng lệ, một chiếc m&aacute;y bay ri&ecirc;ng v&agrave; một chiếc Ferrari m&agrave;u đỏ b&oacute;ng lo&aacute;ng đ&aacute;ng ngưỡng mộ.</p>
<p>Nhưng &iacute;t ai biết, trong nội t&acirc;m s&acirc;u thẳm Julian lại l&agrave; một con người đầy đau khổ, căng thẳng. Bởi đằng sau cuộc sống &ldquo;lung linh&rdquo; của anh những dấu hiệu của sự sụp đổ trong niềm vui v&agrave; &yacute; nghĩa sống: li&ecirc;n tục bị cuốn v&agrave;o c&ocirc;ng việc, v&agrave;o một v&ograve;ng xo&aacute;y kh&ocirc;ng thể dừng lại; như anh n&oacute;i &ldquo;l&uacute;c n&agrave;o cũng c&oacute; một vụ kiện &ldquo;khủng&rdquo; đang chờ sẵn, quy m&ocirc; vụ sau, lớn hơn vụ trước&rdquo;.</p>
<p>V&agrave; cuối c&ugrave;ng, trong một vụ kiện, Julian đột quỵ v&agrave; nhập viện. Để rồi ngay khi xuất viện, Julian đ&atilde; c&oacute; một quyết định l&agrave; bước ngoặt thay đổi cuộc đời. Anh b&aacute;n tất cả t&agrave;i sản của m&igrave;nh, trong đ&oacute; c&oacute; chiếc xe Ferrari - niềm tự h&agrave;o của m&igrave;nh, v&agrave; bắt đầu h&agrave;nh tr&igrave;nh đến Ấn Độ để gặp gỡ c&aacute;c nh&agrave; hiền triết Sivana. Qua đ&oacute;, anh dần &ldquo;lột x&aacute;c&rdquo; v&agrave; t&igrave;m lại ch&iacute;nh m&igrave;nh, trở th&agrave;nh một con người th&agrave;nh c&ocirc;ng, sống một cuộc đời &yacute; nghĩa v&agrave; để lại di sản trong đời sống.</p>', 2020, NULL, 264, 1, 8, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (67, N'Dẫn Dắt Một Bầy Sói Hay Chăn Một Đàn Cừu', N'8936066699594', N'Bìa Mềm', CAST(97500.00 AS Decimal(12, 2)), CAST(195000.00 AS Decimal(12, 2)), CAST(150000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8936066699594.jpg', N'Tiffani Bova', N'<p><strong>Dẫn Dắt Một Bầy S&oacute;i Hay Chăn Một Đ&agrave;n Cừu</strong></p>
<p><strong><em>Ph&aacute;t triển đội ngũ nh&acirc;n sự - N&acirc;ng cao trải nghiệm kh&aacute;ch h&agrave;ng &ndash; Gia tăng hiệu suất c&ocirc;ng việc</em></strong></p>
<p>Trong cuộc chiến thu h&uacute;t kh&aacute;ch h&agrave;ng, c&aacute;c doanh nghiệp đầu tư h&agrave;ng triệu đ&ocirc; la để cải thiện trải nghiệm của kh&aacute;ch h&agrave;ng. Họ giao h&agrave;ng nhanh hơn, tung ra c&aacute;c sản phẩm mới v&agrave; kh&ocirc;ng ngừng cải tiến giao diện người d&ugrave;ng, v&agrave; họ thường g&acirc;y &aacute;p lực lớn hơn cho nh&acirc;n vi&ecirc;n v&igrave; lợi nhuận giảm dần. Theo t&aacute;c giả Tiffani Bova, việc tập trung duy nhất v&agrave;o trải nghiệm của kh&aacute;ch h&agrave;ng &ndash; m&agrave; kh&ocirc;ng xem x&eacute;t t&aacute;c động đến nh&acirc;n vi&ecirc;n của bạn &ndash; thực sự cản trở sự ph&aacute;t triển về l&acirc;u d&agrave;i. C&aacute;c c&ocirc;ng ty th&agrave;nh c&ocirc;ng nhất &aacute;p dụng Tư duy trải nghiệm để củng cố cả trải nghiệm của nh&acirc;n vi&ecirc;n (EX) v&agrave; trải nghiệm của kh&aacute;ch h&agrave;ng (CX) c&ugrave;ng một l&uacute;c.</p>
<p>Dựa tr&ecirc;n nghi&ecirc;n cứu độc quyền từ hai nghi&ecirc;n cứu do Salesforce t&agrave;i trợ với h&agrave;ng ngh&igrave;n nh&acirc;n vi&ecirc;n v&agrave; gi&aacute;m đốc điều h&agrave;nh cấp cao, cuốn s&aacute;ch &ldquo;Dẫn dắt một bầy s&oacute;i hay chăn một đ&agrave;n cừu&rdquo; tr&igrave;nh b&agrave;y chi tiết ch&iacute;nh x&aacute;c c&aacute;ch c&ocirc;ng ty của bạn c&oacute; thể &aacute;p dụng tư duy trải nghiệm tr&ecirc;n quy m&ocirc; lớn. D&ugrave; bạn đang l&agrave;m quản l&yacute;, khởi nghiệp, hay quản l&yacute; cấp cao, cuốn s&aacute;ch sẽ gi&uacute;p bạn sử dụng v&agrave; giữ ch&acirc;n những nh&acirc;n vi&ecirc;n t&agrave;i năng nhất, khiến họ to&agrave;n t&acirc;m, to&agrave;n &yacute; với sứ mệnh của bạn, thu h&uacute;t kh&aacute;ch h&agrave;ng nhiều hơn trước. Nh&acirc;n vi&ecirc;n l&agrave; tr&aacute;i tim của doanh nghiệp bạn. Nếu bạn muốn duy tr&igrave; khả năng cạnh tranh tr&ecirc;n thị trường ng&agrave;y nay, đầu tư v&agrave;o con người kh&ocirc;ng c&ograve;n l&agrave; điều n&ecirc;n c&oacute; nữa m&agrave; l&agrave; điều bắt buộc phải c&oacute;. Sau khi đọc cuốn s&aacute;ch n&agrave;y, bạn sẽ trang bị cho m&igrave;nh một c&acirc;u trả lời thỏa đ&aacute;ng cho c&acirc;u hỏi &ldquo;N&ecirc;n đặt-nh&acirc;n-vi&ecirc;n hay kh&aacute;ch-h&agrave;ng l&ecirc;n trước&rdquo;?</p>', 2024, NULL, 358, 14, 14, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (68, N'Cơn Lốc Quản Trị - Ba Trụ Cột Của Văn Hóa Doanh Nghiệp', N'8934974189220', N'Bìa Mềm', CAST(76375.00 AS Decimal(12, 2)), CAST(140000.00 AS Decimal(12, 2)), CAST(117500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8934974189220.jpg', N'Phan Văn Trường', N'<p><strong>Cơn Lốc Quản Trị - Ba Trụ Cột Của Văn H&oacute;a Doanh Nghiệp</strong></p>
<p>Doanh nghiệp n&agrave;o cũng c&oacute; l&uacute;c gặp phải những vấn đề kh&ocirc;ng nhất thiết mang t&iacute;nh kỹ thuật, như sự thiếu vắng động lực, hoặc tinh thần tương t&aacute;c v&agrave; l&agrave;m việc nh&oacute;m thấp, thậm ch&iacute; l&agrave; m&acirc;u thuẫn giữa c&aacute;c th&agrave;nh vi&ecirc;n, trong đ&oacute; c&oacute; cả c&aacute;c l&atilde;nh đạo cấp trung v&agrave; cấp cao. Chẳng c&ocirc;ng cụ quản l&yacute; n&agrave;o cho ph&eacute;p giải quyết được những vấn đề bắt nguồn từ sự ganh tị, đố kị, thi&ecirc;n vị, hoặc tệ hơn nữa l&agrave; nạn b&egrave; đảng hay tham nhũng nội bộ.</p>
<p>C&aacute;c m&ocirc; h&igrave;nh quản l&yacute; chỉ mang l&yacute; luận kỹ thuật cục bộ hạn hẹp v&agrave; những giải ph&aacute;p cấu tr&uacute;c c&oacute; sẵn cho doanh nghiệp. Chỉ văn h&oacute;a mới c&oacute; khả năng v&agrave;o s&acirc;u một c&aacute;ch uyển chuyển c&aacute;c vấn đề trong mối quan hệ giữa người với người. V&agrave; đ&acirc;y ch&iacute;nh l&agrave; những vấn đề m&agrave; c&aacute;c doanh nghiệp Việt Nam thường gặp phải.</p>
<p>Trong t&aacute;c phẩm mới nhất về văn h&oacute;a doanh nghiệp, t&aacute;c giả Phan Văn Trường ph&aacute;t triển v&agrave; đi s&acirc;u hơn nữa về chủ đề kh&aacute; trừu tượng n&agrave;y. Vẫn giữ nguy&ecirc;n phong c&aacute;ch tiếp cận dựa tr&ecirc;n những c&acirc;u chuyện từ thực tế trải nghiệm của m&igrave;nh, &ocirc;ng dẫn dắt độc giả tr&ecirc;n con đường t&igrave;m hiểu vai tr&ograve; của văn h&oacute;a doanh nghiệp, đồng thời đi s&acirc;u giải th&iacute;ch ba phong c&aacute;ch văn h&oacute;a m&agrave; ch&iacute;nh &ocirc;ng đ&atilde; ti&ecirc;n phong &aacute;p dụng cho những doanh nghiệp m&igrave;nh từng tham gia quản trị.</p>', 2023, NULL, 248, 4, 1, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (69, N'Nhỏ Là Đẹp', N'8935280912311', N'Bìa Mềm', CAST(87750.00 AS Decimal(12, 2)), CAST(169000.00 AS Decimal(12, 2)), CAST(135000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935280912311.jpg', N'E F Schumacher', N'<p>NHỎ L&Agrave; ĐẸP l&agrave; lời k&ecirc;u gọi kinh điển của nh&agrave; kinh tế học E. F. Schumacher tốt nghiệp Oxford, để chấm dứt chủ nghĩa ti&ecirc;u d&ugrave;ng qu&aacute; độ. Schumacher đ&atilde; tạo cảm hứng cho những phong tr&agrave;o như &ldquo;Mua h&agrave;ng địa phương&rdquo; v&agrave; &ldquo;Thương mại c&ocirc;ng bằng&rdquo;, trong khi vẫn mạnh mẽ k&ecirc;u gọi phản đối &ldquo;chủ nghĩa tư bản casino&rdquo; (phong tr&agrave;o chống to&agrave;n cầu h&oacute;a) v&agrave; những tập đo&agrave;n khổng lồ g&acirc;y l&atilde;ng ph&iacute;.</p>
<p>Được vinh danh v&agrave;o danh s&aacute;ch 100 cuốn s&aacute;ch g&acirc;y ảnh hưởng nhất kể từ Chiến tranh thế giới lần thứ hai của Tạp ch&iacute; Văn học Thời đại, &ldquo;Nhỏ l&agrave; đẹp&rdquo; đưa ra những luận điểm logic một c&aacute;ch mạch lạc để x&acirc;y dựng những nền kinh tế phục vụ nhu cầu của những cộng đồng chứ kh&ocirc;ng phải c&aacute;c tập đo&agrave;n.</p>', 2022, NULL, 392, 13, 9, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (70, N'Nhà Lãnh Đạo Không Chức Danh (Tái Bản 2022)', N'8934974179184', N'Bìa Mềm', CAST(57200.00 AS Decimal(12, 2)), CAST(105000.00 AS Decimal(12, 2)), CAST(88000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8934974179184.jpg', N'Robin Sharma', N'<p><strong>Nh&agrave; L&atilde;nh Đạo Kh&ocirc;ng Chức Danh</strong></p>
<p>Suốt hơn 15 năm, Robin Sharma đ&atilde; thầm lặng chia sẻ với những c&ocirc;ng ty trong danh s&aacute;ch Fortune 500 v&agrave; nhiều người si&ecirc;u gi&agrave;u kh&aacute;c một c&ocirc;ng thức th&agrave;nh c&ocirc;ng đ&atilde; gi&uacute;p &ocirc;ng trở th&agrave;nh một trong những nh&agrave; cố vấn l&atilde;nh đạo được theo đuổi nhiều nhất thế giới. Đ&acirc;y l&agrave; lần đầu ti&ecirc;n Sharma c&ocirc;ng bố c&ocirc;ng thức độc quyền n&agrave;y với bạn, để bạn c&oacute; thể đạt được những g&igrave; tốt nhất, đồng thời gi&uacute;p tổ chức của bạn c&oacute; thể c&oacute; những bước đột ph&aacute; đến một cấp độ th&agrave;nh c&ocirc;ng mới trong thời đại thi&ecirc;n biến vạn h&oacute;a như hiện nay.</p>
<p>Trong cuốn s&aacute;ch Nh&agrave; L&atilde;nh Đạo Kh&ocirc;ng Chức Danh, bạn sẽ học được:</p>
<p>L&agrave;m thế n&agrave;o để l&agrave;m việc v&agrave; tạo ảnh hưởng với mọi người như một si&ecirc;u sao, bất chấp bạn đang ở vị tr&iacute; n&agrave;o</p>
<p>Một phương ph&aacute;p để nhận biết v&agrave; nắm bắt cơ hội v&agrave;o những thời điểm thay đổi</p>
<p>Những b&iacute; mật thật sự của sự đổi mới</p>
<p>Một chiến lược tức thời để x&acirc;y dựng đội nh&oacute;m tuyệt vời v&agrave; trở th&agrave;nh một nh&agrave; cung cấp ngoạn mục của kh&aacute;ch h&agrave;ng</p>
<p>Những thủ thuật cứng rắn gi&uacute;p trở n&ecirc;n mạnh mẽ cả về thể chất lẫn tinh thần để c&oacute; thể đi đầu trong lĩnh vực của bạn</p>
<p>Những phương thức thực tế để đ&aacute;nh bại sự căng thẳng, x&acirc;y dựng một &yacute; ch&iacute; bất bại, giải ph&oacute;ng năng lượng, v&agrave; c&acirc;n bằng cuộc sống c&aacute; nh&acirc;n</p>
<p>Bất kể bạn l&agrave;m g&igrave; trong tổ chức v&agrave; cuộc sống hiện tại của bạn như thế n&agrave;o, một thực tế quan trọng duy nhất l&agrave; bạn c&oacute; khả năng thể hiện năng lực l&atilde;nh đạo. Cho d&ugrave; sự nghiệp hiện tại của bạn đang ở đ&acirc;u, bạn vẫn lu&ocirc;n cần phải thể hiện những khả năng tột đỉnh của m&igrave;nh. Cuốn s&aacute;ch n&agrave;y sẽ hướng dẫn bạn l&agrave;m thế n&agrave;o để khai th&aacute;c tối đa khả năng đ&oacute;, cũng như thay đổi cuộc sống v&agrave; thế giới xung quanh bạn.</p>', 2022, NULL, 272, 7, 15, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (71, N'Từ Tốt Đến Vĩ Đại - Jim Collins (Tái Bản 2021)', N'8934974171485', N'Bìa Mềm', CAST(70850.00 AS Decimal(12, 2)), CAST(130000.00 AS Decimal(12, 2)), CAST(109000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/n/x/nxbtre_full_09462021_024609.jpg', N'Jim Collins', N'<p>Jim Collins c&ugrave;ng nh&oacute;m nghi&ecirc;n cứu đ&atilde; miệt m&agrave;i nghi&ecirc;n cứu những c&ocirc;ng ty c&oacute; bước nhảy vọt v&agrave; bền vững để r&uacute;t ra những kết luận s&aacute;t sườn, những yếu tố cần k&iacute;p để đưa c&ocirc;ng ty từ tốt đến vĩ đại. Đ&oacute; l&agrave; những yếu tố khả năng l&atilde;nh đạo, con người, văn h&oacute;a, kỷ luật, c&ocirc;ng nghệ&hellip; Những yếu tố n&agrave;y được nh&oacute;m nghi&ecirc;n cứu xem x&eacute;t tỉ mỉ v&agrave; kiểm chứng cụ thể qua 11 c&ocirc;ng ty nhảy vọt l&ecirc;n vĩ đại. Mỗi kết luận của nh&oacute;m nghi&ecirc;n cứu đều hữu &iacute;ch, vượt thời gian, &yacute; nghĩa v&ocirc; c&ugrave;ng to lớn đối với mọi l&atilde;nh đạo v&agrave; quản l&yacute; ở mọi loại h&igrave;nh c&ocirc;ng ty (từ c&ocirc;ng ty c&oacute; nền tảng v&agrave; xuất ph&aacute;t tốt đến những c&ocirc;ng ty mới khởi nghiệp), v&agrave; mọi lĩnh vực ng&agrave;nh nghề. Đ&acirc;y l&agrave; cuốn s&aacute;ch n&ecirc;n đọc đối với bất kỳ l&atilde;nh đạo hay quản l&yacute; n&agrave;o!</p>', 2021, NULL, 484, 13, 10, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (72, N'Người Giàu Có Nhất Thành Babylon', N'9786043941807', N'Bìa Mềm', CAST(33124.00 AS Decimal(12, 2)), CAST(98000.00 AS Decimal(12, 2)), CAST(50960.00 AS Decimal(12, 2)), N'https://res.cloudinary.com/dabxzdaf8/image/upload/v1748968447/Book_cover/pngctukea2nqz8sa0vfo.webp', N'George Samuel Clason', N'<div id="product_tabs_description_contents">
<div id="desc_content" class="std">
<p><strong>Người Gi&agrave;u C&oacute; Nhất Th&agrave;nh Babylon</strong></p>
<p>Th&agrave;nh cổ Babylon được biết đến l&agrave; nơi khởi minh rực rỡ nhất thời cổ đại, nơi c&oacute; những th&agrave;nh qu&aacute;ch đồ sộ, d&acirc;n cư đ&ocirc;ng đ&uacute;c v&agrave; c&aacute;c hoạt động giao thương diễn ra nhộn nhịp. Vậy, những người ở Babylon đ&atilde; l&agrave;m thế n&agrave;o để trở th&agrave;nh thương gia, l&agrave;m thế n&agrave;o để trở th&agrave;nh người gi&agrave;u nhất? Điều g&igrave; đ&atilde; khiến họ c&oacute; thể l&agrave;m chủ vận mệnh v&agrave; l&agrave;m chủ t&agrave;i ch&iacute;nh khi chỉ l&agrave; những n&ocirc; lệ thấp k&eacute;m?</p>
<p>Cuốn s&aacute;ch Người gi&agrave;u c&oacute; nhất th&agrave;nh Babylon sẽ mang đến cho độc giả những c&acirc;u chuyện về b&iacute; mật của sự gi&agrave;u c&oacute;, được kể qua lời của những n&ocirc; lệ, thương gia, thợ thuyền đến từ 4.000 năm trước.</p>
<p>Họ sẽ tiết lộ cho bạn những nguy&ecirc;n tắc quan trọng để sở hữu tiền - v&agrave;ng v&agrave; tăng sinh lợi nhuận từ số vốn ban đầu. Nếu bạn đang t&igrave;m kiếm sự gi&agrave;u c&oacute;, h&atilde;y nhớ rằng, tiền kh&ocirc;ng được ph&eacute;p đứng y&ecirc;n, n&oacute; phải tham gia v&agrave;o d&ograve;ng chảy thị trường, tạo ra lợi &iacute;ch cho chủ sở hữu. Những phương ph&aacute;p n&agrave;y sẽ khiến bạn phải bất ngờ v&igrave; n&oacute; kh&ocirc;ng kh&oacute; khăn, v&ocirc; c&ugrave;ng đơn giản nhưng lại dễ d&agrave;ng bị bỏ qua hoặc v&ocirc; t&igrave;nh l&atilde;ng qu&ecirc;n đi mất t&iacute;nh căn bản của việc l&agrave;m gi&agrave;u.</p>
<p>Cuốn s&aacute;ch Người gi&agrave;u c&oacute; nhất th&agrave;nh Babylon được viết bởi George Samuel Clason - doanh nh&acirc;n th&agrave;nh c&ocirc;ng với Clason Map v&agrave; Clason Publishing. Clason Map l&agrave; nơi cho ra đời bản đồ giao th&ocirc;ng đầu ti&ecirc;n của Hoa Kỳ v&agrave; Canada, sau đ&oacute; ph&aacute; sản trong cuộc Đại khủng hoảng. Năm 1926, George Samuel Clason bắt đầu xuất bản những c&acirc;u chuyện của m&igrave;nh, ch&uacute;ng được c&aacute;c chủ doanh nghiệp v&agrave; những ai muốn th&agrave;nh c&ocirc;ng trong việc l&agrave;m gi&agrave;u h&agrave;o hứng đ&oacute;n nhận.</p>
</div>
</div>', 2023, NULL, 208, 2, 12, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (73, N'48 Nguyên Tắc Chủ Chốt Của Quyền Lực (Tái Bản 2020)', N'8934974165569', N'Bìa Mềm', CAST(109200.00 AS Decimal(12, 2)), CAST(200000.00 AS Decimal(12, 2)), CAST(168000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_195509_1_32101.jpg', N'Robert Greene', N'<p>Quyền lực c&oacute; sức hấp dẫn v&ocirc; c&ugrave;ng mạnh mẽ đối với con người trong mọi thời, ở mọi nơi, với mọi giai tầng. Lịch sử x&eacute;t cho c&ugrave;ng l&agrave; cuộc đấu tranh triền mi&ecirc;n để gi&agrave;nh cho bằng được quyền lực cai trị của c&aacute;c tập đo&agrave;n thống trị, từ cổ ch&iacute; kim, từ đ&ocirc;ng sang t&acirc;y.</p>
<p>Quyền lực l&agrave; thứ m&agrave; rất nhiều người mong muốn nhưng kh&ocirc;ng phải ai cũng dễ d&agrave;ng đạt được. Vươn l&ecirc;n những vị tr&iacute; cao hơn trong thang bậc x&atilde; hội thường được xem l&agrave; một kh&aacute;t khao rất con người. Nhưng, liệu c&oacute; phải chỉ những t&agrave;i năng xuất ch&uacute;ng mới c&oacute; thể đạt được điều đ&oacute;? Kh&ocirc;ng hẳn vậy. Bởi &iacute;t ai biết rằng, để gi&agrave;nh được một vị tr&iacute; quyền lực thực tế vẫn mang t&iacute;nh c&ocirc;ng thức.</p>
<p>Qua nghi&ecirc;n cứu lịch sử nh&acirc;n loại, với những nh&acirc;n vật c&oacute; quyền lực nhất tự cổ ch&iacute; kim, Robert Greene đ&atilde; kh&aacute;i qu&aacute;t n&ecirc;n 48 nguy&ecirc;n tắc tạo n&ecirc;n quyền lực một c&aacute;ch c&oacute; cơ sở khoa học. Mỗi nguy&ecirc;n tắc đều được t&aacute;c giả ph&acirc;n t&iacute;ch, giải th&iacute;ch r&otilde; r&agrave;ng, mang t&iacute;nh thuyết phục cao v&agrave; cực kỳ hấp dẫn. Một số quy luật đ&ograve;i hỏi sự kh&ocirc;n ngoan sắc sảo, một số cần sự l&eacute;n l&uacute;t v&agrave; một số kh&aacute;c ho&agrave;n to&agrave;n vắng mặt l&ograve;ng thương x&oacute;t&hellip; Nhưng d&ugrave; bạn th&iacute;ch hay kh&ocirc;ng th&iacute;ch, tất cả những quy luật n&agrave;y đều c&oacute; nhiều ứng dụng trong c&aacute;c t&igrave;nh huống thực tế của cuộc đời.</p>
<p>Phi lu&acirc;n l&yacute;, xảo quyệt, nhẫn t&acirc;m v&agrave; dồi d&agrave;o tư liệu, &ldquo;48 nguy&ecirc;n tắc chủ chốt của quyền lực&rdquo; của Robert Greene ho&agrave;n to&agrave;n c&oacute; thể gi&uacute;p bạn vươn tới những đỉnh cao quyền lực v&agrave; cũng c&oacute; thể gi&uacute;p bạn đạt được tột đỉnh vinh quang.</p>', 2020, NULL, 504, 15, 1, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (74, N'Người Giàu Có Nhất Thành Babylon', N'8935086851944', N'Bìa Mềm', CAST(50700.00 AS Decimal(12, 2)), CAST(98000.00 AS Decimal(12, 2)), CAST(78000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_195509_1_41914.jpg', N'George S Clason', N'<p><strong>Người gi&agrave;u c&oacute; nhất th&agrave;nh Babylon</strong></p>
<p>Trước mắt bạn, tương lai đang trải rộng con đường dẫn tới những miền đất xa x&ocirc;i đầy hứa hẹn. Tr&ecirc;n con đường đ&oacute;, bạn h&aacute;o hức, mong muốn thực hiện nhiều ước mơ, dự định, kh&aacute;t khao&hellip; của ri&ecirc;ng m&igrave;nh.</p>
<p>Để những nguyện vọng của m&igrave;nh được thực hiện, &iacute;t nhất bạn phải th&agrave;nh c&ocirc;ng về mặt tiền bạc. Quyển s&aacute;ch n&agrave;y sẽ gi&uacute;p bạn biết c&aacute;ch vận dụng những nguy&ecirc;n l&yacute; quan trọng để ph&aacute;t triển t&agrave;i ch&iacute;nh. H&atilde;y để cuốn s&aacute;ch dẫn dắt bạn đi từ một ho&agrave;n cảnh kh&oacute; khăn, ti&ecirc;u biểu l&agrave; một c&aacute;i t&uacute;i l&eacute;p xẹp, đến một cuộc sống đầy đủ v&agrave; hạnh ph&uacute;c, ti&ecirc;u biểu l&agrave; một t&uacute;i tiền căng phồng, sung t&uacute;c.</p>
<p>Khi n&oacute;i đến tiền bạc, ch&uacute;ng ta thường đề cập đến quy luật trọng trường v&agrave; n&oacute; lu&ocirc;n phổ qu&aacute;t v&agrave; bất biến trong mọi trường hợp. Trải qua thời gian d&agrave;i v&agrave; ph&aacute;t triển, quy luật n&agrave;y đ&atilde; được trải nghiệm v&agrave; đ&uacute;c r&uacute;t th&agrave;nh những b&iacute; quyết kh&ocirc;ng chỉ đảm bảo cho bạn một t&uacute;i tiền đầy, m&agrave; c&ograve;n gi&uacute;p cho bạn c&oacute; một cuộc sống c&acirc;n bằng để c&oacute; thể ph&aacute;t triển mỹ m&atilde;n hơn những tiềm năng của bản th&acirc;n trong c&aacute;c lĩnh vực kh&aacute;c của cuộc sống. Bởi tr&ecirc;n thực tế, kh&ocirc;ng ai c&oacute; thể phủ nhận rằng sự dồi d&agrave;o về vật chất c&oacute; thể l&agrave;m cho đời sống con người trở n&ecirc;n tốt đẹp hơn. Ri&ecirc;ng trong lĩnh vực kinh doanh, sức mạnh t&agrave;i ch&iacute;nh l&agrave; phương tiện chủ yếu để đo lường mức độ th&agrave;nh đạt của c&aacute;c doanh nh&acirc;n.</p>
<p>Ng&agrave;y nay, tiền bạc vẫn c&oacute; những ảnh hưởng lớn đối với cuộc sống con người, cũng giống như c&aacute;ch đ&acirc;y năm ng&agrave;n năm n&oacute; đ&atilde; chi phối mạnh mẽ cuộc sống của cư d&acirc;n vương quốc Babylon, th&uacute;c đẩy họ t&igrave;m hiểu v&agrave; nắm bắt c&aacute;c quy luật tạo ra tiền, nhằm c&oacute; được một cuộc sống sung t&uacute;c v&agrave; sang trọng bậc nhất.</p>
<p>Những trang s&aacute;ch n&agrave;y sẽ đưa ch&uacute;ng ta trở lại vương quốc Babylon cổ đại, c&aacute;i n&ocirc;i nu&ocirc;i dưỡng những nguy&ecirc;n l&yacute; cơ bản về t&agrave;i ch&iacute;nh m&agrave; giờ đ&acirc;y con người hiện đại đ&atilde; kế thừa v&agrave; vận dụng tr&ecirc;n to&agrave;n thế giới.</p>', 2020, NULL, 214, 2, 10, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (75, N'Nghĩ Giàu & Làm Giàu (Tái Bản 2020)', N'8935086844342', N'Bìa Mềm', CAST(57200.00 AS Decimal(12, 2)), CAST(110000.00 AS Decimal(12, 2)), CAST(88000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/n/g/nghigiaulamgiau_110k-01_bia-1.jpg', N'Napoleon Hill', N'<p align="center"><strong>NGHĨ GI&Agrave;U V&Agrave; L&Agrave;M GI&Agrave;U</strong></p>
<p><strong>Think and Grow Rich - Nghĩ gi&agrave;u v&agrave; l&agrave;m gi&agrave;u</strong>&nbsp;l&agrave; một trong những cuốn s&aacute;ch b&aacute;n chạy nhất mọi thời đại. Đ&atilde; hơn 60 triệu bản được ph&aacute;t h&agrave;nh với gần trăm ng&ocirc;n ngữ tr&ecirc;n to&agrave;n thế giới v&agrave; được c&ocirc;ng nhận l&agrave; cuốn s&aacute;ch tạo ra nhiều triệu ph&uacute;, một cuốn s&aacute;ch truyền cảm hứng th&agrave;nh c&ocirc;ng nhiều hơn bất cứ cuốn s&aacute;ch kinh doanh n&agrave;o trong lịch sử.</p>
<p>T&aacute;c phẩm n&agrave;y đ&atilde; gi&uacute;p t&aacute;c giả của n&oacute;, Napoleon Hill, được t&ocirc;n vinh bằng danh hiệu &ldquo;người tạo ra những nh&agrave; triệu ph&uacute;&rdquo;. Đ&acirc;y cũng l&agrave; cuốn s&aacute;ch hiếm hoi được đứng trong top của rất nhiều b&igrave;nh chọn theo nhiều ti&ecirc;u ch&iacute; kh&aacute;c nhau - b&igrave;nh chọn của độc giả, của giới chuy&ecirc;n m&ocirc;n, của b&aacute;o ch&iacute;. L&yacute; do để&nbsp;<strong>Think and Grow Rich - Nghĩ gi&agrave;u v&agrave; l&agrave;m gi&agrave;u</strong>&nbsp;c&oacute; được vinh quang n&agrave;y thật hiển nhi&ecirc;n v&agrave; dễ hiểu: Bằng việc đọc v&agrave; &aacute;p dụng những phương ph&aacute;p đơn giản, c&ocirc; đọng n&agrave;y v&agrave;o đời sống của mỗi c&aacute; nh&acirc;n m&agrave; đ&atilde; c&oacute; h&agrave;ng ng&agrave;n người tr&ecirc;n thế giới trở th&agrave;nh triệu ph&uacute; v&agrave; th&agrave;nh c&ocirc;ng bền vững.</p>
<p>Điều th&uacute; vị nhất l&agrave; c&aacute;c b&iacute; quyết n&agrave;y c&oacute; thể được hiểu v&agrave; &aacute;p dụng bởi bất kỳ một người b&igrave;nh thường n&agrave;o, hoạt động trong bất cứ lĩnh vực n&agrave;o. Qua hơn 70 năm tồn tại, những đ&uacute;c kết về th&agrave;nh c&ocirc;ng của Napoleon Hill đến nay vẫn kh&ocirc;ng hề bị lỗi thời, ngược lại, thời gian ch&iacute;nh l&agrave; minh chứng sống động cho t&iacute;nh đ&uacute;ng đắn của những b&iacute; quyết m&agrave; &ocirc;ng chia sẻ.</p>
<p>Sinh ra trong một gia đ&igrave;nh ngh&egrave;o v&ugrave;ng T&acirc;y Virginia, con đường th&agrave;nh c&ocirc;ng của Napoleon Hill cũng trải qua nhiều thăng trầm. Khởi đầu bằng ch&acirc;n cộng t&aacute;c vi&ecirc;n cho một tờ b&aacute;o địa phương l&uacute;c 15 tuổi, đến năm 19 tuổi Hill trở th&agrave;nh nh&agrave; quản l&yacute; mỏ than trẻ tuổi nhất, sau đ&oacute; bỏ ngang để theo đuổi ng&agrave;nh luật. Napoleon Hill c&ograve;n kinh qua nhiều nghề như kinh doanh gỗ, xe hơi, viết b&aacute;o về kinh doanh&hellip;</p>
<p>Đ&oacute; l&agrave; những c&ocirc;ng việc &ocirc;ng từng nếm trải trước khi 25 tuổi! Song kh&aacute;c với những người th&agrave;nh đạt kh&aacute;c, &ocirc;ng cẩn thận ph&acirc;n t&iacute;ch từng sự kiện trọng đại trong đời m&igrave;nh, r&uacute;t ra những b&agrave;i học, rồi tiếp tục r&uacute;t gọn ch&uacute;ng th&agrave;nh c&aacute;c nguy&ecirc;n tắc căn bản, tổ chức c&aacute;c nguy&ecirc;n tắc ấy th&agrave;nh triết l&yacute; sống v&agrave; r&egrave;n luyện...</p>', 2020, NULL, 400, 1, 2, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (76, N'Lời Thú Tội Của Một Sát Thủ Kinh Tế - Bìa Cứng (Tái Bản 2023)', N'8935210307910', N'Bìa Cứng', CAST(111475.00 AS Decimal(12, 2)), CAST(245000.00 AS Decimal(12, 2)), CAST(171500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935210307910.jpg', N'John Perkins', N'<p><strong>Lời Th&uacute; Tội Của Một S&aacute;t Thủ Kinh Tế - B&igrave;a Cứng</strong></p>
<p>Sau th&agrave;nh c&ocirc;ng của hai ấn bản đầu ti&ecirc;n:&nbsp;<em>Lời th&uacute; tội của một s&aacute;t thủ kinh tế&nbsp;</em>(2004) v&agrave;&nbsp;<em>Lời th&uacute; tội mới của một s&aacute;t thủ kinh tế&nbsp;</em>(2016), t&aacute;c giả John Perkins đ&atilde; bắt tay bổ sung v&agrave; cập nhật những sự kiện mới nhất về t&igrave;nh h&igrave;nh kinh tế thế giới dưới sự ảnh hưởng của c&aacute;c s&aacute;t thủ kinh tế (EHM), đặc biệt l&agrave; l&agrave;n s&oacute;ng EHM thứ ba của Trung Quốc ng&agrave;y nay. Ngay khi cuốn s&aacute;ch được ph&aacute;t h&agrave;nh ở Mỹ v&agrave;o ng&agrave;y 28/2/2023,&nbsp;<strong>T&acirc;n Việt Books</strong>&nbsp;đ&atilde; nhanh ch&oacute;ng c&oacute; bản quyền cập nhật, tiến h&agrave;nh chuyển ngữ v&agrave; bi&ecirc;n tập để ra mắt v&agrave;o th&aacute;ng 7/2023 n&agrave;y.</p>
<p>Trong hai ấn phẩm trước, John Perkins đ&atilde; tiết lộ những vụ tham nhũng v&agrave; mưu đồ quốc tế đ&atilde; v&agrave; đang biến nền cộng h&ograve;a Hoa Kỳ th&agrave;nh một đế chế to&agrave;n cầu. Trong ấn bản thứ 3 n&agrave;y, cựu EHM John Perkins sẽ tiếp tục qu&aacute; tr&igrave;nh đ&oacute; bằng c&aacute;ch m&ocirc; tả những sửa đổi nguy hiểm c&oacute; t&iacute;nh hiệu quả cao của Trung Quốc đối với chiến lược EHM v&agrave; đưa ra một kế hoạch để chuyển đổi một nền kinh tế chết, suy tho&aacute;i th&agrave;nh một nền kinh tế sống, t&aacute;i sinh th&agrave;nh c&ocirc;ng. &Ocirc;ng đ&atilde; cập nhật v&agrave; bổ sung th&ecirc;m 12 chương mới b&ugrave;ng nổ tr&igrave;nh b&agrave;y chi tiết về sức hấp dẫn, sự b&oacute;c lột v&agrave; sự t&agrave;n ph&aacute; của chiến lược EHM của Trung Quốc ở Mỹ Latinh, ch&acirc;u &Aacute;, ch&acirc;u Phi, Trung Đ&ocirc;ng, thậm ch&iacute; l&agrave; cả ch&acirc;u &Acirc;u.</p>
<p>Như được m&ocirc; tả trong ba ấn bản, EHM l&agrave; những chuy&ecirc;n gia được trả lương cao để đi thuyết phục c&aacute;c nước c&oacute; thu nhập thấp chấp nhận c&aacute;c khoản vay khổng lồ để x&acirc;y dựng c&aacute;c dự &aacute;n cơ sở hạ tầng mang lại lợi nhuận cho c&aacute;c doanh nghiệp Mỹ. C&aacute;c c&ocirc;ng cụ m&agrave; EHM sử dụng bao gồm c&aacute;c b&aacute;o c&aacute;o t&agrave;i ch&iacute;nh gian dối, c&aacute;c cuộc bầu cử bị sắp đặt, hối lộ, tống tiền, t&igrave;nh dục v&agrave; cả &aacute;m s&aacute;t. Một khi c&aacute;c quốc gia đi vay ngập trong nợ nần, c&aacute;c tập đo&agrave;n Mỹ v&agrave; Trung Quốc sẽ nhảy v&agrave;o khai th&aacute;c dầu mỏ v&agrave; c&aacute;c nguồn t&agrave;i nguy&ecirc;n kh&aacute;c của đất nước họ.</p>
<p>Ấn bản mới nhất của&nbsp;<em>Lời th&uacute; tội của một s&aacute;t thủ kinh tế&nbsp;</em>sẽ tập trung chủ yếu v&agrave;o chiến lược của Trung Quốc, một chiến lược m&agrave; Trung Quốc đ&atilde; học được từ những lỗi sai của c&aacute;c EHM Mỹ v&agrave; từ những th&agrave;nh c&ocirc;ng của đất nước Mỹ, để dần dần vươn l&ecirc;n trở th&agrave;nh đối t&aacute;c kinh tế quan trọng của nhiều quốc gia tr&ecirc;n thế giới. Trung Quốc thể hiện m&igrave;nh l&agrave; h&igrave;nh mẫu cho sự th&agrave;nh c&ocirc;ng kinh tế vượt bậc ở trong nước v&agrave; thực hiện những sửa đổi to lớn trong chiến lược EHM ở nước ngo&agrave;i. Nổi bật nhất trong những thay đổi đ&oacute;, Trung Quốc đ&atilde; thay thế c&aacute;c điều kiện trong ch&iacute;nh s&aacute;ch&nbsp;<em>t&acirc;n tự do&nbsp;</em>của Mỹ bằng lời hứa kh&ocirc;ng can thiệp v&agrave;o ch&iacute;nh phủ của c&aacute;c nước đi vay nếu họ d&ugrave;ng khoản vay của Trung Quốc thu&ecirc; c&aacute;c c&ocirc;ng ty Trung Quốc x&acirc;y dựng cơ sở hạ tầng.</p>', 2023, NULL, 516, 12, 12, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (77, N'Sóng Thần Công Nghệ - The Coming Wave', N'8936219420303', N'Bìa Mềm', CAST(149500.00 AS Decimal(12, 2)), CAST(299000.00 AS Decimal(12, 2)), CAST(230000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8936219420303.jpg', N'Mustafa Suleyman', N'<p><strong>S&oacute;ng Thần C&ocirc;ng Nghệ - The Coming Wave</strong></p>
<p>Cuốn s&aacute;ch như lời cảnh b&aacute;o khẩn cấp từ người đồng s&aacute;ng lập c&ocirc;ng ty tr&iacute; tuệ nh&acirc;n tạo ti&ecirc;n phong DeepMind, một phần của Google, Mustafa Suleyman, về những rủi ro chưa từng c&oacute; m&agrave; AI v&agrave; c&aacute;c c&ocirc;ng nghệ ph&aacute;t triển nhanh kh&aacute;c g&acirc;y ra cho trật tự to&agrave;n cầu v&agrave; cơ hội ch&uacute;ng ta c&oacute; thể ngăn chặn ch&uacute;ng.</p>
<p>Ch&uacute;ng ta đang tiến tới một ngưỡng quan trọng trong lịch sử lo&agrave;i người. Chẳng bao l&acirc;u nữa bạn sẽ sống được bao quanh bởi AI, m&aacute;y in DNA v&agrave; m&aacute;y t&iacute;nh lượng tử, mầm bệnh được thiết kế v&agrave; vũ kh&iacute; tự động, trợ l&yacute; robot, Ch&uacute;ng sẽ tổ chức cuộc sống của bạn, điều h&agrave;nh doanh nghiệp của bạn v&agrave; điều h&agrave;nh c&aacute;c dịch vụ cốt l&otilde;i của Ch&iacute;nh phủ.</p>
<p>Kh&ocirc;ng ai trong ch&uacute;ng ta được chuẩn bị cho điều n&agrave;y cả.</p>
<p>Trong S&oacute;ng thần c&ocirc;ng nghệ, Suleyman cho thấy l&agrave;n s&oacute;ng c&ocirc;ng nghệ mới mạnh mẽ v&agrave; t&acirc;n tiến n&agrave;y sẽ tạo ra sự thịnh vượng to lớn nhưng cũng đe dọa tới nền tảng của trật tự to&agrave;n cầu; x&aacute;c định th&aacute;ch thức tất yếu của thời đại ch&uacute;ng ta đang sống, ch&iacute;nh l&agrave;: &ldquo;vấn đề ngăn chặn&rdquo; - nhiệm vụ duy tr&igrave; quyền kiểm so&aacute;t c&aacute;c c&ocirc;ng nghệ mạnh mẽ.</p>', 2024, NULL, 486, 5, 8, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (78, N'Dốc Hết Trái Tim (Tái Bản 2018)', N'8934974152361', N'Bìa Mềm', CAST(81900.00 AS Decimal(12, 2)), CAST(150000.00 AS Decimal(12, 2)), CAST(126000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8934974152361_11.jpg', N'Howard Schultz , Dori Jones Yang', N'<p>Dốc Hết Tr&aacute;i Tim (T&aacute;i Bản 2018)</p>
<p><em><strong>Dốc hết tr&aacute;i tim</strong></em>&nbsp;l&agrave; một quyển s&aacute;ch hay d&agrave;nh cho doanh nh&acirc;n v&agrave; mọi gi&aacute;m đốc hay l&atilde;nh đạo c&ocirc;ng ty. T&aacute;c giả đồng thời l&agrave; người s&aacute;ng lập của thương hiệu Starbucks, chia sẻ c&acirc;u chuyện đầy cảm hứng về cuộc đời của &ocirc;ng từ khi c&ograve;n đi học đến khi trở th&agrave;nh CEO của một thương hiệu nổi tiếng tr&ecirc;n to&agrave;n thế giới. Độc giả sẽ t&igrave;m thấy nơi đ&acirc;y b&agrave;i học về quản trị rất tuyệt vời, m&agrave; gi&aacute; trị của n&oacute; vẫn c&ograve;n vững v&agrave;ng trong hiện tại. Những kinh nghiệm của t&aacute;c giả về x&acirc;y dựng một c&ocirc;ng ty c&oacute; tr&aacute;ch nhiệm x&atilde; hội đối với nh&acirc;n vi&ecirc;n, với cộng đồng v&agrave; đối với m&ocirc;i trường sẽ cuốn h&uacute;t lan truyền cảm hứng đến độc giả để họ &aacute;p dụng n&oacute; v&agrave;o cuộc sống v&agrave; c&ocirc;ng việc kinh doanh của m&igrave;nh.</p>
<p>Th&agrave;nh c&ocirc;ng của C&ocirc;ng ty C&agrave; ph&ecirc; Starbucks l&agrave; một trong những c&acirc;u chuyện kỳ diệu nhất về kinh doanh trong suốt nhiều thập kỷ. Một cửa h&agrave;ng nhỏ ven s&ocirc;ng ở Seattle rốt cuộc lại lớn mạnh v&agrave; ph&aacute;t triển n&ecirc;n hơn một ng&agrave;n s&aacute;u trăm cửa h&agrave;ng tr&ecirc;n khắp thế giới v&agrave; mỗi ng&agrave;y lại c&oacute; th&ecirc;m một cửa h&agrave;ng mới mọc l&ecirc;n. Tuyệt vời hơn cả, Starbucks đ&atilde; th&agrave;nh c&ocirc;ng trong việc giữ vững cam kết về chất lượng sản phẩm ưu việt v&agrave; mang lại những g&igrave; tốt đẹp nhất cho nh&acirc;n vi&ecirc;n của m&igrave;nh.</p>
<p>Trong&nbsp;<em><strong>Dốc hết tr&aacute;i tim</strong></em>, CEO Howard Schultz chỉ ra c&aacute;c nguy&ecirc;n tắc định h&igrave;nh n&ecirc;n hiện tượng Starbucks, chia sẻ những tri thức m&agrave; &ocirc;ng đ&uacute;c kết được từ cuộc h&agrave;nh tr&igrave;nh biến c&agrave; ph&ecirc; ngon th&agrave;nh một phần tất yếu của trải nghiệm Mỹ. C&aacute;c nh&agrave; tiếp thị, c&aacute;c nh&agrave; quản l&yacute;, v&agrave; c&aacute;c doanh nh&acirc;n sẽ kh&aacute;m ph&aacute; ra c&aacute;ch biến l&ograve;ng đam m&ecirc; th&agrave;nh lợi nhuận trong cuốn bi&ecirc;n ni&ecirc;n k&yacute; của một c&ocirc;ng ty "đ&atilde; l&agrave;m thay đổi mọi thứ... từ khẩu vị của ch&uacute;ng ta, ng&ocirc;n ngữ của ch&uacute;ng ta cho đến bộ mặt của to&agrave;n khu Main Street".</p>', 2018, NULL, 488, 20, 9, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (80, N'Tính Trước 5 Bước', N'8935278606123', N'Bìa Mềm', CAST(109850.00 AS Decimal(12, 2)), CAST(220000.00 AS Decimal(12, 2)), CAST(169000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935278606123_1.jpg', N'Greg Dinkin, Patrick Bet-David', N'<p><strong>T&iacute;nh Trước 5 Bước</strong></p>
<p>Mặc d&ugrave; việc kinh doanh cũng y&ecirc;u cầu ch&uacute;ng ta suy t&iacute;nh trước nhiều nước đi giống như khi chơi cờ v&aacute;n, cuốn s&aacute;ch n&agrave;y sẽ kh&ocirc;ng đi s&acirc;u ph&acirc;n t&iacute;ch m&ocirc;n cờ vua m&agrave; chỉ b&agrave;n về việc &aacute;p dụng tầm nh&igrave;n v&agrave; tầm nh&igrave;n. c&aacute;ch tư duy của một tướng cờ vua v&agrave;o kinh doanh.</p>
<p>Những người kh&ocirc;ng biết t&iacute;nh trước nhiều hơn nước đi thường l&agrave; c&aacute;i t&ocirc;i, cảm x&uacute;c v&agrave; sợ h&atilde;i sợ h&atilde;i sợ h&atilde;i chi phối. H&atilde;y thử đặt m&igrave;nh v&agrave;o vấn đề giải quyết của nh&acirc;n vi&ecirc;n b&aacute;n h&agrave;ng giỏi nhất của bạn để từ bỏ c&ocirc;ng việc nếu kh&ocirc;ng được tăng lương. Một kẻ nghiệp dư dễ x&uacute;c động sẽ trả lời: &ldquo;Kh&ocirc;ng ai được ph&eacute;p tấn c&ocirc;ng t&ocirc;i!&rdquo; hoặc &ldquo;Ch&uacute;ng ta kh&ocirc;ng cần đến anh ta!&rdquo;. Ngược lại, một chiến lược gia c&oacute; đầu &oacute;c thực tế sẽ ngay lập tức lập tức lập tức t&iacute;nh to&aacute;n c&aacute;c nước đi tiếp theo.</p>
<p>Việc dạy dỗ con c&aacute;i cũng tương tự như vậy. Bạn cảm thấy thật dễ chịu khi cho con m&igrave;nh tất cả những g&igrave; ch&uacute;ng muốn, cho d&ugrave; đ&oacute; l&agrave; b&aacute;nh kẹo, iPad hay quyền được nghỉ tập đ&agrave;n piano. Họ sẽ cười v&agrave; n&oacute;i y&ecirc;u bạn.Bạn biết rằng nếu từ chối ngậm ng&ugrave;i th&igrave; hậu quả sẽ khủng khiếp thế n&agrave;o: con bạn sẽ kinh tởm l&ecirc;n v&agrave; n&oacute;i ra những lời hờn dỗi, cũng hỗn h&agrave;o. Giống như trong kinh doanh, bạn thường c&oacute; một lựa chọn dễ d&agrave;ng hơn v&agrave; một lựa chọn hiệu quả hơn. Để lựa chọn hiệu quả, bạn cần t&iacute;nh to&aacute;n trước 5 nước đi.</p>', 2023, NULL, 372, 13, 15, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (81, N'Giải Trí Đến Chết', N'8936066695107', N'Bìa Mềm', CAST(89375.00 AS Decimal(12, 2)), CAST(179000.00 AS Decimal(12, 2)), CAST(137500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8936066695107.jpg', N'Neil Postman', N'<p><em>&ldquo;T&aacute;c phẩm kinh điển b&aacute;n chạy nhất của bậc thầy&nbsp;</em><em>Neil Postman, một bậc thầy về nghi&ecirc;n cứu văn h&oacute;a truyền th&ocirc;ng.&rsquo;&rsquo;</em></p>
<p>Tại sao b&acirc;y giờ những c&ocirc;ng việc li&ecirc;n quan đến giải tr&iacute; lại kiếm được kh&aacute; nhiều ?&nbsp;</p>
<p>Tại sao content mang t&iacute;nh giải tr&iacute; lại thu h&uacute;t nhiều lượt xem hơn những content kh&aacute;c ?</p>
<p>H&igrave;nh thức truyền th&ocirc;ng c&oacute; ảnh hưởng đến tư duy v&agrave; văn h&oacute;a như thế n&agrave;o ?&nbsp;</p>
<p>Việc x&atilde; hội lo&agrave;i người ph&aacute;t triển từ h&igrave;nh thức ng&ocirc;n ngữ văn n&oacute;i cho đến văn viết, in ấn, rồi đến tivi c&oacute; thể gợi mở nhiều suy nghĩ về h&igrave;nh thức truyền th&ocirc;ng chủ yếu ch&uacute;ng ta d&ugrave;ng hiện tại: Internet.&nbsp;<strong>&ldquo;</strong><strong><em>Giải tr&iacute; đến chết</em></strong><em>&rsquo;&rsquo;&nbsp;</em>một cuốn s&aacute;ch ph&acirc;n t&iacute;ch s&acirc;u về t&igrave;nh h&igrave;nh một đất nước Hoa Kỳ đ&atilde; đầu độc tư duy của ch&iacute;nh n&oacute; bằng tivi v&agrave; giải tr&iacute; từ những năm 80, nhưng vẫn c&ograve;n nhiều gi&aacute; trị cho đến b&acirc;y giờ.</p>
<p>Đồng thời cuốn s&aacute;ch c&ograve;n g&acirc;y chấn động về t&aacute;c động ăn m&ograve;n của truyền h&igrave;nh v&agrave; phương tiện truyền th&ocirc;ng điện tử đối với văn h&oacute;a con người. Đ&oacute; l&agrave; c&aacute;i nh&igrave;n ti&ecirc;n tri về những g&igrave; sẽ xảy ra khi ch&iacute;nh trị, b&aacute;o ch&iacute;, gi&aacute;o dục v&agrave; thậm ch&iacute; cả t&ocirc;n gi&aacute;o trở th&agrave;nh đối tượng của nhu cầu giải tr&iacute; v&agrave; mạng x&atilde; hội trở th&agrave;nh một thế lực c&oacute; thể thao t&uacute;ng v&agrave; khống chế tư tưởng con người.</p>
<p>Giờ đ&acirc;y, với sự b&ugrave;ng nổ của Internet, smartphone, mạng x&atilde; hội v&agrave; thực tế ảo v&agrave; c&aacute;c thuật to&aacute;n gợi &yacute; nội dung tinh vi, c&aacute;c nội dung n&agrave;y ng&agrave;y c&agrave;ng lan rộng đến mọi ng&oacute;c ng&aacute;ch tr&ecirc;n thế giới, khuếch đại sự truy cầu c&aacute;c k&iacute;ch th&iacute;ch t&acirc;m l&yacute; v&agrave; dục vọng của con người &ndash; th&igrave; &yacute; nghĩa của cuốn s&aacute;ch c&agrave;ng to lớn hơn.</p>
<p>Sự b&ugrave;ng nổ của Internet, c&aacute;c ứng dụng di động, mạng x&atilde; hội v&agrave; tr&ograve; chơi điện tử ng&agrave;y nay đang g&acirc;y ra một l&agrave;n s&oacute;ng nghiện ngập mới. Ch&uacute;ng giống như một loại ma t&uacute;y tinh thần, được ti&ecirc;m bằng một ống ti&ecirc;m dưới da ch&iacute;nh l&agrave; chiếc điện thoại di động l&uacute;c n&agrave;o cũng c&oacute; trong t&uacute;i của mỗi người. Thực tế, mạng x&atilde; hội dễ d&agrave;ng g&acirc;y nghiện hơn cả rượu bia v&agrave; ma t&uacute;y bởi v&igrave; ch&uacute;ng phổ biến hơn, được cộng đồng chấp nhận rộng r&atilde;i v&agrave; gần như l&agrave; ho&agrave;n to&agrave;n miễn ph&iacute;.</p>
<p>Những điều n&agrave;y cho thấy Neil Postman đ&atilde; đ&uacute;ng khi nhận định đ&uacute;ng, vào thời đại giải tr&iacute;, ti&ecirc;u khiển v&ocirc; độ như hiện nay, kẻ hủy diệt nh&acirc;n loại kh&ocirc;ng phải l&agrave; &ldquo;kẻ th&ugrave;&rdquo; hay những điều ch&uacute;ng ta th&ugrave; gh&eacute;t, sợ h&atilde;i, m&agrave; rất c&oacute; thể l&agrave; những th&uacute; vui ti&ecirc;u khiển, những điều ch&uacute;ng ta đang y&ecirc;u th&iacute;ch v&agrave; m&ecirc; đắm kia.</p>
<p><em>Những thứ ch&uacute;ng ta</em><em>&nbsp;y&ecirc;u th&iacute;ch sẽ hủy hoại ch&uacute;ng ta.</em></p>', 2023, NULL, 336, 11, 14, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (82, N'Logistics Và Quản Trị Chuỗi Cung Ứng', N'8935278607557', N'Bìa Mềm', CAST(247650.00 AS Decimal(12, 2)), CAST(495000.00 AS Decimal(12, 2)), CAST(381000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/l/o/logistic-v_-qu_n-tr_-chu_i-cung-_ng---b_a-1.jpg', N'Paul R. Murphy, Jr., A. Michael Knemeyer', N'<p><strong>Logistics V&agrave; Quản Trị Chuỗi Cung Ứng</strong></p>
<p>Logistics v&agrave; Quản trị chuỗi cung ứng - &ldquo;B&aacute;ch khoa to&agrave;n thư&rdquo; về Logistics thời đại mới</p>
<p>Chỉ cần một c&uacute; click chuột, ta sẽ nhận về h&agrave;ng ngh&igrave;n kết quả với cụm từ &ldquo;Logistics v&agrave; Quản trị chuỗi cung ứng&rdquo;. Điều n&agrave;y l&agrave;m ta như ch&igrave;m trong đại dương th&ocirc;ng tin v&agrave; mơ hồ với những đ&uacute;ng - sai, thật - giả. Những kiến thức v&agrave; kh&aacute;i niệm sai lệch kh&ocirc;ng chỉ g&acirc;y n&ecirc;n những lỗ hổng kiến thức m&agrave; c&ograve;n cản trở qu&aacute; tr&igrave;nh tiếp thu v&agrave; nghi&ecirc;n cứu. V&agrave; quyển s&aacute;ch textbook Logistics v&agrave; Quản trị chuỗi cung ứng sẽ l&agrave; ngọn hải đăng soi s&aacute;ng, mang đến những th&ocirc;ng tin, kiến thức ch&iacute;nh x&aacute;c v&agrave; đưa bạn tho&aacute;t khỏi những băn khoăn về ng&agrave;nh nghề th&uacute; vị n&agrave;y.</p>
<p>Quyển s&aacute;ch được &ocirc;ng Trần Thanh Hải - Ph&oacute; Cục trưởng Cục Xuất nhập khẩu (Bộ C&ocirc;ng Thương) v&agrave; Chủ tịch danh dự Hiệp hội Ph&aacute;t triển nh&acirc;n lực Logistics Việt Nam (VALOMA); c&ugrave;ng &ocirc;ng Đ&agrave;o Trọng Khoa - Ph&oacute; Chủ tịch Thường trực Hiệp hội Doanh nghiệp Dịch vụ Logistics Việt Nam viết lời giới thiệu v&agrave; đề xuất với bạn đọc.</p>
<p>Logistics v&agrave; Quản trị chuỗi cung ứng l&agrave; một cuốn &ldquo;b&aacute;ch khoa to&agrave;n thư&rdquo; mang đến những kiến thức, hướng dẫn đầy đủ nhất về Logistics v&agrave; quản trị chuỗi cung ứng đương đại. Điều đ&oacute; sẽ mang đến cho độc giả những th&ocirc;ng tin v&agrave; kiến thức ch&iacute;nh x&aacute;c, bổ &iacute;ch nhưng vẫn v&ocirc; c&ugrave;ng dễ d&agrave;ng tiếp thu, gi&uacute;p độc giả dễ d&agrave;ng hơn trong việc t&igrave;m hiểu v&agrave; nghi&ecirc;n cứu về ng&agrave;nh nghề &ldquo;mắt x&iacute;ch ph&aacute;t triển kinh tế&rdquo; n&agrave;y. Quyển textbook n&agrave;y sẽ gi&uacute;p bạn nắm r&otilde; từ kho vận đến giao nhận một c&aacute;ch dễ d&agrave;ng với 3 phần ch&iacute;nh: Tổng quan về Logistics, Quản trị chuỗi cung ứng v&agrave; C&aacute;c th&agrave;nh tố của hệ thống Logistics. Mỗi phần sẽ tiếp tục chia ra th&agrave;nh c&aacute;c mục nhỏ, bảo đảm sẽ gi&uacute;p bạn hiểu tường tận từng ng&otilde; ng&aacute;ch của Logistics v&agrave; quản trị chuỗi cung ứng.</p>', 2024, NULL, 436, 9, 12, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (83, N'Tiếp Thị 6.0 - Tương Lai Là Toàn Nhập - Marketing 6.0 - The Future Is Immersive', N'8934974205432', N'Bìa Mềm', CAST(76375.00 AS Decimal(12, 2)), CAST(140000.00 AS Decimal(12, 2)), CAST(117500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8934974205432.jpg', N'Philip Kotler, Hermawan Kartajaya, Iwan Setiawan', N'<p><strong>Tiếp Thị 6.0 - Tương Lai L&agrave; To&agrave;n Nhập - Marketing 6.0 - The Future Is Immersive</strong></p>
<p>Trong "Tiếp thị 6.0", Philip Kotler, nh&agrave; tiếp thị nổi tiếng đ&atilde; phổ biến kh&aacute;i niệm "4P trong tiếp thị", giải th&iacute;ch c&aacute;ch c&aacute;c nh&agrave; tiếp thị c&oacute; thể sử dụng c&ocirc;ng nghệ để đ&aacute;p ứng nhu cầu của kh&aacute;ch h&agrave;ng v&agrave; tạo ra sự kh&aacute;c biệt. Trong thời đại mới tiếp thị si&ecirc;u k&ecirc;nh (metamarketing) ng&agrave;y nay, cuốn s&aacute;ch n&agrave;y sẽ cung cấp cho c&aacute;c nh&agrave; tiếp thị c&aacute;ch t&iacute;ch hợp sự ph&aacute;t triển c&ocirc;ng nghệ v&agrave; m&ocirc; h&igrave;nh kinh doanh với những thay đổi đ&aacute;ng kể trong h&agrave;nh vi của người ti&ecirc;u d&ugrave;ng đ&atilde; xảy ra trong thập kỷ qua.</p>
<p>Độc giả sẽ được t&igrave;m hiểu về:</p>
<p>- C&aacute;c nền tảng của tiếp thị si&ecirc;u k&ecirc;nh</p>
<p>- Thế hệ Z v&agrave; Thế hệ Alpha c&ugrave;ng c&aacute;c c&ocirc;ng nghệ m&agrave; họ sử dụng hằng ng&agrave;y</p>
<p>- C&aacute;ch khai th&aacute;c metaverse v&agrave; thực tế mở rộng</p>
<p>- Những trở ngại tiềm ẩn v&agrave; c&aacute;c giải ph&aacute;p để tạo ra trải nghiệm tương t&aacute;c v&agrave; to&agrave;n nhập</p>
<p>Tiếp thị đ&atilde; ph&aacute;t triển để giải quyết những th&aacute;ch thức to&agrave;n cầu v&agrave; thay đổi kỳ vọng của kh&aacute;ch h&agrave;ng. &Aacute;p dụng c&aacute;c chủ đề về sự bền vững v&agrave; c&ocirc;ng nghệ mới để thu h&uacute;t với kh&aacute;ch h&agrave;ng l&agrave; điều cần thiết để c&aacute;c doanh nghiệp duy tr&igrave; sự ph&ugrave; hợp của m&igrave;nh. Quả thực tiếp thị đ&atilde; chuyển từ truyền thống sang kỹ thuật số, nhưng hầu hết kh&aacute;ch h&agrave;ng vẫn đ&aacute;nh gi&aacute; cao một số h&igrave;nh thức tương t&aacute;c con người. Do đ&oacute;, tiếp thị đa k&ecirc;nh v&agrave; hợp k&ecirc;nh đ&atilde; trở n&ecirc;n phổ biến trong giới tiếp thị nhằm tận dụng cả sự tương t&aacute;c truyền thống v&agrave; kỹ thuật số. Tiếp thị si&ecirc;u k&ecirc;nh vượt xa điều đ&oacute; v&agrave; mang lại sự hội tụ thực sự giữa vật l&yacute; v&agrave; kỹ thuật số bằng c&aacute;ch cung cấp một trải nghiệm kh&aacute;ch h&agrave;ng tương t&aacute;c v&agrave; to&agrave;n nhập hơn trong cả kh&ocirc;ng gian vật l&yacute; lẫn kỹ thuật số.</p>', 2024, NULL, 296, 15, 13, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (84, N'90 - 20 - 30 - 90 Bài Học Vỡ Lòng Về Ý Tưởng Và Câu Chữ (Tái Bản 2021) (Bản Đen Trắng)', N'8936170870384', N'Bìa Mềm', CAST(101400.00 AS Decimal(12, 2)), CAST(195000.00 AS Decimal(12, 2)), CAST(156000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_188907_2.jpg', N'Huỳnh Vĩnh Sơn', N'<p><strong>90 - 20 - 30 - 90 B&agrave;i Học Vỡ L&ograve;ng Về &Yacute; Tưởng V&agrave; C&acirc;u Chữ</strong></p>
<p>NG&Agrave;NH QUẢNG C&Aacute;O QU&Aacute; MAY MẮN. L&uacute;c n&agrave;o cũng lung linh trong mắt c&aacute;c bạn trẻ y&ecirc;u s&aacute;ng tạo. Ai cũng muốn ra trường sẽ hiến bộ n&atilde;o đầy ắp &yacute; tưởng cho một c&ocirc;ng ty quảng c&aacute;o chất chơi n&agrave;o đ&oacute;.</p>
<p>Nhưng dẫu c&oacute; được chuẩn bị kĩ c&agrave;ng, gi&aacute;o tr&igrave;nh quốc tế 5 sao đi nữa th&igrave; n&agrave;ng (Quảng) C&aacute;o l&uacute;c n&agrave;o cũng ki&ecirc;u k&igrave;. Ở trường th&igrave; học h&agrave;nh, v&agrave;o c&ocirc;ng ty th&igrave; vừa h&agrave;nh vừa học. Để c&oacute; &yacute; tưởng v&agrave; c&acirc;u chữ x&agrave;i được, c&aacute;c &ldquo;mầm non s&aacute;ng tạo&rdquo; phải va chạm li&ecirc;n tục v&agrave; tự m&igrave;nh vỡ lấy những b&agrave;i học, c&agrave;ng nhanh c&agrave;ng tốt, kh&ocirc;ng được để deadline qua mặt.</p>
<p>V&agrave; người trực tiếp chăn dắt &ldquo;bọn trẻ&rdquo; đi qua những ng&agrave;y ban sơ ấy l&agrave; &ldquo;sinh vật&rdquo; mang t&ecirc;n &ldquo;mentor/ supervisor/ senior creative &ndash; &ldquo;Sếp&rdquo; trực tiếp, nh&acirc;n vi&ecirc;n s&aacute;ng tạo l&agrave;m kha kh&aacute; năm.</p>
<p>Mời bạn đến với h&agrave;nh tr&igrave;nh 90 ng&agrave;y &ndash; tương đương 3 th&aacute;ng thực tập của c&ocirc; n&agrave;ng Copywriter vừa tr&ograve;n 20, dưới trướng một l&atilde;o Senior Copywriter vừa chấm 30.</p>
<p>20 vừa bước ch&acirc;n ra khỏi giảng đường đại học, bắt đầu đối mặt với những thử th&aacute;ch thực sự.<br>30 vừa bước sang năm h&agrave;nh nghề thứ 9, bắt đầu đối mặt với &aacute;p lực dẫn dắt đ&agrave;n em.<br>Hai con người xa ơi l&agrave; xa nhưng gặp nhau nơi niềm vui s&aacute;ng tạo, chiến đấu c&ugrave;ng nhau tại một Agency quảng c&aacute;o.<br>Mỗi ng&agrave;y 20 v&agrave; 30 lại &ldquo;quần nhau&rdquo; v&agrave; mang về những b&agrave;i học của ri&ecirc;ng m&igrave;nh.</p>
<p>20 th&igrave; cặm cụi g&otilde; l&ecirc;n tr&ecirc;n blog, 30 th&igrave; h&iacute; ho&aacute;y viết từng trang.</p>
<p>C&ograve;n bạn th&igrave; ung dung cầm trọn những d&ograve;ng t&acirc;m tư ấy tr&ecirc;n tay.</p>', 2021, NULL, 398, 12, 3, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (85, N'Toàn Thư Về Ý Tưởng Quảng Cáo', N'9786047774449', N'Bìa Cứng', CAST(263575.00 AS Decimal(12, 2)), CAST(495000.00 AS Decimal(12, 2)), CAST(405500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786047774449.jpg', N'Pete Barry', N'<p><strong>To&agrave;n Thư Về &Yacute; Tưởng Quảng C&aacute;o</strong></p>
<p>Tựa s&aacute;ch To&agrave;n Thư Về &Yacute; Tưởng Quảng C&aacute;o đề cập đến bước đầu ti&ecirc;n v&agrave; quan trọng nhất để l&agrave;m n&ecirc;n quảng c&aacute;o đặc sắc, vượt thời gian: &yacute; tưởng gốc.</p>
<p>Nếu kh&ocirc;ng c&oacute; &yacute; tưởng gốc đặc sắc, ta sẽ chẳng c&oacute; g&igrave; ngo&agrave;i hoa ho&egrave; hoa s&oacute;i. C&aacute;c kiểu chữ, bảng m&agrave;u, ảnh chụp hoặc h&igrave;nh minh họa đẹp nhất cũng kh&ocirc;ng thể cứu nổi &yacute; tưởng tồi. (Hoặc c&oacute; thể n&oacute;i một c&aacute;ch thẳng thừng: &ldquo;Ph&iacute; c&ocirc;ng v&ocirc; &iacute;ch.&rdquo;) &Yacute; tưởng gốc trong quảng c&aacute;o cũng như chiếc v&aacute;y đen nhỏ nhắn trong ng&agrave;nh thời trang: ta lu&ocirc;n lu&ocirc;n cần đến n&oacute;.</p>', 2023, NULL, 356, 11, 9, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (86, N'BộNgười Bán Hàng Vĩ Đại Nhất Thế Giới', N'8935086851524', N'Bìa Mềm', CAST(76700.00 AS Decimal(12, 2)), CAST(148000.00 AS Decimal(12, 2)), CAST(118000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_195509_1_47973.jpg', N'Og Mandino', N'<p>"Người B&aacute;n H&agrave;ng Vĩ Đại Nhất Thế Giới" kể về c&acirc;u chuyện của Hafid, một cậu b&eacute; chăn lạc đ&agrave; ngh&egrave;o, ở Jerusalem thời cổ đại.&nbsp; Xuất th&acirc;n l&agrave; một cậu nh&oacute;c tr&ocirc;ng lạc đ&agrave; cho đo&agrave;n bu&ocirc;n của Pathros, nhưng với quyết t&acirc;m đổi đời, muốn cải thiện vị tr&iacute; của m&igrave;nh trong cuộc sống, Hafid lu&ocirc;n nu&ocirc;i ước mơ được trở th&agrave;nh người b&aacute;n h&agrave;ng. Cậu tin chỉ như thế m&igrave;nh mới c&oacute; cơ hội trở n&ecirc;n gi&agrave;u c&oacute; v&agrave; th&agrave;nh c&ocirc;ng.</p>
<p>Giống như nhiều người theo đuổi đam m&ecirc; kh&aacute;c, trong suốt h&agrave;nh tr&igrave;nh ấy đ&ocirc;i l&uacute;c Hafid đ&atilde; nghĩ đến việc quay trở về với c&ocirc;ng việc chăn lạc đ&agrave;, kiếm những đồng xu lẻ sống qua ng&agrave;y. Biết bao nhi&ecirc;u mối suy tư nghi ngờ, thương tiếc bản th&acirc;n đ&atilde; nảy ra trong t&acirc;m tr&iacute; v&agrave; bủa v&acirc;y lấy cậu, nhưng với &yacute; ch&iacute; v&agrave; quyết t&acirc;m, cuối c&ugrave;ng Hafid cũng trở th&agrave;nh người b&aacute;n h&agrave;ng t&agrave;i năng nhất l&uacute;c bấy giờ.</p>
<p>B&iacute; mật n&agrave;o đ&atilde; l&agrave;m n&ecirc;n th&agrave;nh c&ocirc;ng? Đ&oacute; ch&iacute;nh l&agrave; những nguy&ecirc;n tắc được một thương nh&acirc;n gi&agrave;u c&oacute; v&agrave; th&agrave;nh c&ocirc;ng truyền lại v&agrave; Hafid đ&atilde; giữ kỹ trong 10 cuộn giấy da trong suốt hơn ba thập kỉ qua. Với Hafid, những thứ giản dị n&agrave;y c&ograve;n qu&yacute; hơn cả kim cương. Nhờ &aacute;p dụng những nguy&ecirc;n tắc trong cuộn giấy da đ&oacute; m&agrave; Hafid được mệnh danh l&agrave; &ldquo;Người b&aacute;n h&agrave;ng vĩ đại nhất thế giới&rdquo;. Tuy nhi&ecirc;n, s&aacute;ch kh&ocirc;ng chỉ dạy bạn c&aacute;ch&nbsp;&ldquo;b&aacute;n h&agrave;ng&rdquo;, m&agrave; n&oacute; c&ograve;n l&agrave; một cuốn s&aacute;ch dạy bạn l&agrave;m người, gi&uacute;p bạn trở th&agrave;nh người&nbsp;&ldquo;vĩ đại nhất&rdquo;&nbsp;trong lĩnh vực m&agrave; bạn chọn.</p>
<p>Vậy những nguy&ecirc;n tắc ấy l&agrave; g&igrave; v&agrave; l&agrave;m c&aacute;ch n&agrave;o để đưa ch&uacute;ng v&agrave;o thực tiễn? Những b&iacute; mật n&agrave;y chỉ được tiết lộ khi bạn cầm tr&ecirc;n tay cuốn s&aacute;ch&nbsp;<strong><em>Người b&aacute;n h&agrave;ng vĩ đại nhất thế giới</em></strong>, đọc thật cẩn thận, tiếp thu v&agrave; lưu từng chi tiết.</p>', 2020, NULL, 296, 21, 6, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (87, N'Content Bạc Tỷ (Tái Bản)', N'8936066695114', N'Bìa Mềm', CAST(89375.00 AS Decimal(12, 2)), CAST(179000.00 AS Decimal(12, 2)), CAST(137500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8936066695114.jpg', N'Diệp Tiểu Ngư', N'<p>Kinh doanh muốn ph&aacute;t triển l&acirc;u d&agrave;i th&igrave; content phải c&oacute; hiệu quả. Content hiệu quả l&agrave; content c&oacute; thể h&aacute;i ra tiền. Rất nhiều content được ch&uacute; trọng từng c&acirc;u chữ với những c&acirc;u văn bay bổng nhưng lại kh&ocirc;ng thể mang lại hấp dẫn đối với người đọc. Viết content cũng giống việc m&oacute;c nối c&aacute;c th&ocirc;ng tin lại với nhau,&nbsp;<strong>&ldquo;Content bạc tỷ<em>&rdquo;</em></strong>&nbsp;sẽ chỉ ra cho bạn 4 bước cụ thể để x&acirc;y dựng chiến dịch viết một b&agrave;i quảng c&aacute;o chuy&ecirc;n nghiệp: &ldquo;N&oacute;i những g&igrave; &ndash; N&oacute;i với ai &ndash; N&oacute;i ở đ&acirc;u &ndash; N&oacute;i thế n&agrave;o&rdquo;. N&oacute;i một c&aacute;ch dễ hiểu hơn th&igrave; ch&iacute;nh l&agrave; xem kh&aacute;ch h&agrave;ng l&agrave; đối tượng để t&aacute;n gẫu, ch&uacute;ng ta &aacute;p dụng đ&uacute;ng bốn điều tr&ecirc;n sẽ khiến cuộc tr&ograve; chuyện đạt được hiệu quả cao hơn.</p>
<p>Trước hết, ch&uacute;ng ta cần phải hiểu r&otilde; rằng: Mục đ&iacute;ch m&agrave; content phải đạt được l&agrave; g&igrave;? L&agrave; để kh&aacute;ch h&agrave;ng biết đến ch&uacute;ng ta v&agrave; thậm ch&iacute; l&agrave; y&ecirc;u th&iacute;ch ch&uacute;ng ta? Hay l&agrave; khiến kh&aacute;ch h&agrave;ng ngay lập tức chốt đơn mua ngay sau khi đọc xong content? Muốn đạt được những mục đ&iacute;ch như thế th&igrave; ch&uacute;ng ta cần để kh&aacute;ch h&agrave;ng biết được những th&ocirc;ng tin g&igrave;? Cảm nhận được điều g&igrave;? Cuốn s&aacute;ch n&agrave;y sẽ giới thiệu những b&iacute; quyết cụ thể, gi&uacute;p bạn ph&acirc;n t&iacute;ch &ldquo;đối tượng t&aacute;n gẫu&rdquo; cũng ch&iacute;nh l&agrave; nh&oacute;m người m&agrave; ch&uacute;ng ta gọi l&agrave; &ldquo;đối tượng content hướng đến&rdquo;. N&oacute; như chiếc cầu nối đưa bạn đến gần với đối tượng t&aacute;n gẫu, gi&uacute;p bạn c&agrave;ng hiểu r&otilde; hơn về sản phẩm v&agrave; c&aacute;c &ldquo;thượng đế&rdquo; của thị trường.</p>
<p>Content n&ecirc;n truyền đạt c&aacute;c th&ocirc;ng tin về sản phẩm đến &ldquo;đối tượng t&aacute;n gẫu&rdquo; như thế n&agrave;o th&igrave; sẽ mang lại hiệu quả cao hơn v&agrave; linh hoạt hơn? Để gi&uacute;p bạn nắm vững phương ph&aacute;p triển khai nội dung v&agrave; d&agrave;n b&agrave;i của một b&agrave;i content tốt hơn, t&aacute;c giả Diệp Tiểu Ngư đ&atilde; liệt k&ecirc; c&aacute;c v&iacute; dụ trong từng phần, gi&uacute;p bạn mở rộng tư duy cũng như x&acirc;u chuỗi, hệ thống lại c&aacute;c phương ph&aacute;p viết xuy&ecirc;n suốt từ đầu đến cuối của một b&agrave;i content.</p>
<p><strong>&ldquo;Content bạc tỷ&rdquo;</strong> với nội dung thiết thực, giải th&iacute;ch cặn kẽ, diễn đạt kh&eacute;o l&eacute;o, kh&ocirc;ng chỉ d&agrave;nh ri&ecirc;ng cho những Copywriter m&agrave; c&ograve;n cho tất cả những ai c&oacute; hứng th&uacute; với việc viết content.&nbsp; Nếu bạn l&agrave; một t&acirc;n binh trong lĩnh vực Copywriting, cuốn s&aacute;ch n&agrave;y sẽ gi&uacute;p bạn đi đ&uacute;ng đường ngay từ khi mới bắt đầu, c&ograve;n nếu bạn đ&atilde; kinh nghiệm, n&oacute; sẽ gi&uacute;p bạn c&oacute; một tư duy nhạy b&eacute;n hơn trong việc viết content.</p>', 2022, NULL, 384, 19, 14, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (88, N'Kế Hoạch Cho Sự Nghiệp Tự Chủ Và Bền Vững - Kinh Doanh Chuyên Môn Của Chính Mình', N'8936170870698', N'Bìa Mềm', CAST(127400.00 AS Decimal(12, 2)), CAST(245000.00 AS Decimal(12, 2)), CAST(196000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8936170870698.jpg', N'Linh Phan', N'<p><strong>Kế Hoạch Cho Sự Nghiệp Tự Chủ V&agrave; Bền Vững - Kinh Doanh Chuy&ecirc;n M&ocirc;n Của Ch&iacute;nh M&igrave;nh</strong></p>
<p>Kh&aacute;i niệm &ldquo;Nền kinh tế chuy&ecirc;n gia&rdquo; (Expert Economy) đang trỗi dậy mạnh mẽ hơn bao giờ hết trong ba năm gần đ&acirc;y, được dẫn dắt bởi c&aacute;c doanh nh&acirc;n &ldquo;kinh doanh chuy&ecirc;n m&ocirc;n&rdquo; - những người kiếm tiền từ ch&iacute;nh tri thức, tr&iacute; tuệ v&agrave; kinh nghiệm m&agrave; họ từng học hỏi.</p>
<p>Cuốn s&aacute;ch<strong>&nbsp;&ldquo;KINH DOANH CHUY&Ecirc;N M&Ocirc;N CỦA CH&Iacute;NH M&Igrave;NH - Kế hoạch cho sự nghiệp tự chủ v&agrave; bền vững&rdquo;</strong>&nbsp;lần lượt mở ra những hiểu biết về nền kinh tế chuy&ecirc;n gia, về một chuy&ecirc;n gia kinh doanh, về c&aacute;ch để thương mại ho&aacute; v&agrave; b&aacute;n chuy&ecirc;n m&ocirc;n trong bối cảnh nền kinh tế hiện tại. Định nghĩa &ldquo;chuy&ecirc;n gia&rdquo; được t&aacute;i thiết lập, những bản chất, y&ecirc;u cầu v&agrave; tương lai của chuy&ecirc;n gia l&agrave;m kinh doanh cũng sẽ được kh&aacute;m ph&aacute; trong ấn phẩm n&agrave;y.</p>
<p>Linh Phan - t&aacute;c giả của cuốn s&aacute;ch được biết đến như một nh&agrave; kinh doanh chuy&ecirc;n m&ocirc;n với c&aacute;c c&ocirc;ng việc như viết s&aacute;ch, tư vấn chiến lược truyền th&ocirc;ng v&agrave; khai vấn t&acirc;m l&yacute;. Từ vị tr&iacute; quản l&yacute; thương hiệu tại một branding agency, t&aacute;c giả đ&atilde; tự mở cho m&igrave;nh chặng đường sự nghiệp mới tr&ecirc;n cương vị solopreneur, đạt mức thu nhập l&ecirc;n tới 3.500.000.000vnđ/năm.</p>', 2023, NULL, 204, 6, 15, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (89, N'BộChiến Tranh Tiền Tệ', N'9786043437881', N'Bìa Mềm', CAST(77220.00 AS Decimal(12, 2)), CAST(165000.00 AS Decimal(12, 2)), CAST(118800.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/b/i/bia-truoc-chien-tranh-tien-te-phan-1-1.jpg', N'Song Hong Bing', N'<p><strong>Chiến Tranh Tiền Tệ - Phần 1 - Ai Thực Sự L&agrave; Người Gi&agrave;u Nhất Thế Giới?</strong></p>
<p>Một khi đọc &ldquo;Chiến tranh tiền tệ - Ai thật sự l&agrave; người gi&agrave;u nhất thế giới&rdquo; bạn sẽ phải giật m&igrave;nh nhận ra một điều kinh khủng rằng, đằng sau những tờ giấy bạc ch&uacute;ng ta chi ti&ecirc;u h&agrave;ng ng&agrave;y l&agrave; cả một thế lực ngầm đ&aacute;ng sợ - một thế lực b&iacute; ẩn với quyền lực si&ecirc;u nhi&ecirc;n c&oacute; thể điều khiển cả thế giới rộng lớn n&agrave;y.</p>
<p>&ldquo;Chiến tranh tiền tệ - Ai thật sự l&agrave; người gi&agrave;u nhất thế giới&rdquo; đề cập đến một cuộc chiến khốc liệt, kh&ocirc;ng khoan nhượng v&agrave; dai dẳng giữa một nh&oacute;m nhỏ c&aacute;c &ocirc;ng tr&ugrave;m t&agrave;i ch&iacute;nh &ndash; đứng đầu l&agrave; gia tộc Rothschild &ndash; với c&aacute;c thể chế t&agrave;i ch&iacute;nh của nhiều quốc gia. Đ&oacute; l&agrave; một cuộc chiến m&agrave; đồng tiền l&agrave; s&uacute;ng đạn v&agrave; mức s&aacute;t thương thật sự gh&ecirc; gớm.</p>
<p>Đồng thời, &ldquo;Chiến tranh tiền tệ - Ai thật sự l&agrave; người gi&agrave;u nhất thế giới&rdquo; c&ograve;n gi&uacute;p bạn hiểu th&ecirc;m nhiều điều, rằng Bill Gates chưa phải l&agrave; người gi&agrave;u nhất h&agrave;nh tinh, rằng tỉ lệ tử vong của c&aacute;c tổng thống Mỹ lại cao hơn tỉ lệ tử trận của binh l&iacute;nh Mỹ ngo&agrave;i chiến trường, hay v&igrave; sao phố Wall lại mạo hiểm đổ hết vốn liếng của m&igrave;nh cho việc &ldquo;đầu tư&rdquo; v&agrave;o Hitler.</p>
<p>L&agrave; một cuốn s&aacute;ch l&agrave;m sửng sốt những ai muốn t&igrave;m hiểu về bản chất của tiền tệ, để từ đ&oacute; nhận ra những hiểm họa t&agrave;i ch&iacute;nh tiềm ẩn nhằm chuẩn bị t&acirc;m l&yacute; cho một cuộc chiến tiền tệ &ldquo;kh&ocirc;ng đổ m&aacute;u&rdquo;, &ldquo;Chiến tranh tiền tệ - Ai thật sự l&agrave; người gi&agrave;u nhất thế giới&rdquo; c&ograve;n phơi b&agrave;y những &acirc;m mưu của c&aacute;c nh&agrave; t&agrave;i phiệt thế giới trong việc tạo ra những cơn &ldquo;hạn h&aacute;n&rdquo;, &ldquo;b&atilde;o lũ&rdquo; về tiền tệ để thu lợi nhuận. Cuốn s&aacute;ch cũng đề cập đến sự ph&aacute;t triển của c&aacute;c định chế t&agrave;i ch&iacute;nh &ndash; những cơ cấu được x&acirc;y dựng nhằm đ&aacute;p ứng nhu cầu ph&aacute;t triển vũ b&atilde;o của nền kinh tế to&agrave;n cầu.</p>', 2022, NULL, 532, 13, 1, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (90, N'BộChiến Tranh Tiền Tệ', N'9786043437898', N'Bìa Mềm', CAST(79560.00 AS Decimal(12, 2)), CAST(170000.00 AS Decimal(12, 2)), CAST(122400.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/b/i/bia-truoc-chientrangtiente-2-tb-jpg.jpg', N'Song Hong Bing', N'<p><strong>Chiến Tranh Tiền Tệ - Phần 2 - Sự Thống Trị Của Quyền Lực T&agrave;i Ch&iacute;nh (T&aacute;i Bản 2022)</strong></p>
<p>Trong ấn bản lần thứ nhất của cuốn s&aacute;ch n&agrave;y, t&aacute;c giả đưa ra ba dự đo&aacute;n quan trọng.</p>
<p>Thứ nhất, kinh tế &Acirc;u Mỹ sẽ rơi v&agrave;o t&igrave;nh cảnh ti&ecirc;u điều trường kỳ (ch&iacute; &iacute;t l&agrave; 10 năm), cho d&ugrave; c&oacute; nới lỏng ch&iacute;nh s&aacute;ch về tiền tệ, hay k&iacute;ch th&iacute;ch ch&iacute;nh s&aacute;ch t&agrave;i ch&iacute;nh &ndash; về cơ bản đều v&ocirc; hiệu;</p>
<p>Thứ hai, khi đ&oacute; &ldquo;lượng kh&iacute; thải carbon&rdquo; vẫn l&agrave; một kh&aacute;i niệm tương đối xa lạ với x&atilde; hội Trung Quốc, sẽ ph&aacute;t huy t&aacute;c dụng ng&agrave;y c&agrave;ng quan trọng đối với kinh tế v&agrave; x&atilde; hội, v&agrave; sẽ bị &ldquo;t&agrave;i ch&iacute;nh h&oacute;a&rdquo; v&agrave; &ldquo;tiền tệ h&oacute;a&rdquo;;</p>
<p>Thứ ba, loại tiền tệ chủ quyền sẽ từng bước bị loại tiền tệ khu vực thay thế, v&agrave; cuốn c&ugrave;ng sẽ tiến h&oacute;a hướng đến sự đơn nhất về tiền tệ tr&ecirc;n thế giới.</p>
<p>V&agrave; đến nay, ba dự đo&aacute;n đ&oacute; đều đ&atilde; trở th&agrave;nh sự thực.</p>
<p>Mục đ&iacute;ch của cuốn s&aacute;ch n&agrave;y kh&ocirc;ng phải l&agrave; để dạy bạn c&aacute;ch đầu tư, c&aacute;ch ph&acirc;n bổ t&agrave;i sản hay dạy một bộ phương ph&aacute;p đối ph&oacute; tiền tệ điển h&igrave;nh. Cuốn s&aacute;ch n&agrave;y nhằm trả lời những c&acirc;u hỏi từ l&acirc;u đ&atilde; khiến ch&uacute;ng ta bối rối v&agrave; chưa được giải đ&aacute;p: Tại sao tiền tệ lại c&oacute; xung đột?</p>
<p><em>Th&ocirc;ng tin t&aacute;c giả:</em></p>
<p>Song Hong Binh (Tống Hồng Binh) sinh năm 1968 tại Tứ Xuy&ecirc;n, Trung Quốc. &Ocirc;ng l&agrave; t&aacute;c giả của rất nhiều cuốn s&aacute;ch b&aacute;n chạy, l&agrave; học giả nghi&ecirc;n cứu t&agrave;i ch&iacute;nh thế giới v&agrave; cũng l&agrave; Viện trưởng của Viện nghi&ecirc;n cứu Kinh tế T&agrave;i ch&iacute;nh Ho&agrave;n Cầu (Bắc Kinh). Năm 1990, &ocirc;ng tốt nghiệp Đại học Đ&ocirc;ng Bắc khoa Kiểm so&aacute;t tự động. Đến năm 1994, &ocirc;ng sang Mỹ du học. Trong một thời gian rất d&agrave;i, &ocirc;ng đ&atilde; tập trung nghi&ecirc;n cứu về lịch sử nước Mỹ cũng như lịch sử t&agrave;i ch&iacute;nh thế giới.</p>', 2022, NULL, 632, 16, 13, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (91, N'AI Toàn Năng: Chinh Phục Thời Đại Số', N'8936066696050', N'Bìa Mềm', CAST(104325.00 AS Decimal(12, 2)), CAST(209000.00 AS Decimal(12, 2)), CAST(160500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/a/i/ai-5.0-bia-1.jpg', N'Ajay Agrawal, Joshua Gans, Avi Goldfarb', N'<p><strong>AI 5.0 - Nhanh Hơn, Dễ Hơn, Rẻ Hơn, Ch&iacute;nh X&aacute;c Hơn</strong></p>
<p>Tr&iacute; tuệ nh&acirc;n tạo (AI) đ&atilde; t&aacute;c động đến nhiều ng&agrave;nh c&ocirc;ng nghiệp tr&ecirc;n to&agrave;n thế giới như: t&agrave;i ch&iacute;nh ng&acirc;n h&agrave;ng, dược phẩm, &ocirc; t&ocirc;, c&ocirc;ng nghệ y tế, sản xuất v&agrave; b&aacute;n lẻ. Nhưng n&oacute; chỉ mới bắt đầu cuộc phi&ecirc;u lưu hướng tới những dự đo&aacute;n rẻ hơn, tốt hơn v&agrave; nhanh hơn nhằm th&uacute;c đẩy c&aacute;c quyết định kinh doanh chiến lược.</p>
<p>Trong cuốn s&aacute;ch&nbsp;<em>AI 5.0 &ndash; Nhanh hơn, dễ hơn, rẻ hơn, ch&iacute;nh x&aacute;c hơn</em>, c&aacute;c t&aacute;c giả đi s&acirc;u v&agrave;o việc xem x&eacute;t đơn vị ph&acirc;n t&iacute;ch cơ bản nhất: Quyết định. C&aacute;c t&aacute;c giả giải th&iacute;ch rằng hai th&agrave;nh phần quan trọng trong việc đưa ra quyết định l&agrave;: Dự đo&aacute;n v&agrave; Ph&aacute;n đo&aacute;n, v&agrave; ch&uacute;ng ta thực hiện cả hai yếu tố đ&oacute; c&ugrave;ng nhau trong t&acirc;m tr&iacute; m&agrave; thường kh&ocirc;ng nhận ra.</p>
<p>Sự ph&aacute;t triển của AI đang chuyển dự đo&aacute;n từ con người sang m&aacute;y m&oacute;c, gi&uacute;p con người giảm bớt g&aacute;nh nặng nhận thức n&agrave;y đồng thời tăng tốc độ v&agrave; độ ch&iacute;nh x&aacute;c của c&aacute;c quyết định. Điều n&agrave;y c&oacute; &yacute; nghĩa s&acirc;u sắc đối với sự đổi mới ở cấp độ hệ thống.</p>
<p>Việc thiết kế lại c&aacute;c hệ thống đưa ra c&aacute;c quyết định phụ thuộc lẫn nhau cần c&oacute; thời gian, nhiều ng&agrave;nh đang trong t&igrave;nh trạng y&ecirc;n tĩnh trước cơn b&atilde;o, nhưng khi những hệ thống mới n&agrave;y xuất hiện, ch&uacute;ng c&oacute; thể g&acirc;y rối loạn tr&ecirc;n quy m&ocirc; to&agrave;n cầu.</p>
<p>Chứa đầy những hiểu biết s&acirc;u sắc, v&iacute; dụ phong ph&uacute; v&agrave; lời khuy&ecirc;n thực tế,&nbsp;<em>AI 5.0 &ndash; Nhanh hơn, dễ hơn, rẻ hơn, ch&iacute;nh x&aacute;c hơn</em> &agrave; hướng dẫn phải đọc cho bất kỳ nh&agrave; l&atilde;nh đạo doanh nghiệp hoặc nh&agrave; hoạch định ch&iacute;nh s&aacute;ch n&agrave;o về c&aacute;ch khiến những gi&aacute;n đoạn AI sắp tới c&oacute; lợi cho bạn thay v&igrave; cản trở bạn. Đồng thời, c&aacute;c t&aacute;c giả chỉ ra c&aacute;ch doanh nghiệp c&oacute; thể tận dụng cơ hội cũng như bảo vệ vị thế của m&igrave;nh.</p>', 2024, NULL, 432, 2, 15, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (92, N'How Money Works - Hiểu Hết Về Tiền - Bìa Cứng', N'8935235243682', N'Bìa Cứng', CAST(175825.00 AS Decimal(12, 2)), CAST(330000.00 AS Decimal(12, 2)), CAST(270500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935235243682.jpg', N'DK', N'<p><strong>How Money Works - Hiểu Hết Về Tiền</strong></p>
<p>Cẩm nang giới đơn giản, dễ h&igrave;nh dung nhất từ trước đến nay về tiền tệ v&agrave; hệ thống t&agrave;i ch&iacute;nh thế giới.</p>
<p>Tiền đến từ đ&acirc;u? Sự kh&aacute;c biệt giữa gi&agrave;u c&oacute; v&agrave; thu nhập l&agrave; g&igrave;? C&aacute;c ch&iacute;nh phủ kiểm so&aacute;t tiền tệ như thế n&agrave;o? Tại sao một khoản nợ lại l&agrave; tốt?</p>
<p>How money works &ndash; Hiểu hết về tiền t&igrave;m hiểu c&aacute;ch thức c&aacute;c ch&iacute;nh phủ kiểm so&aacute;t tiền tệ, c&aacute;ch c&aacute;c c&ocirc;ng ty kiếm ra tiền, c&aacute;ch c&aacute;c thị trường t&agrave;i ch&iacute;nh vận h&agrave;nh, c&aacute;ch c&aacute;c c&aacute; nh&acirc;n tối đa h&oacute;a thu nhập th&ocirc;ng qua đầu tư&hellip;</p>
<p>Đưa ra định nghĩa cho h&agrave;ng trăm kh&aacute;i niệm, c&ugrave;ng với những kiến thức nền tảng nhất về c&aacute;c hệ thống t&agrave;i ch&iacute;nh, như tr&aacute;i phiếu, cổ phiếu, tiền m&atilde; h&oacute;a, bitcoin, quản l&yacute; nợ, tr&aacute;nh vỡ nợ trực tuyến v&agrave; gọi vốn cộng đồng, cũng như c&aacute;ch tiền vận h&agrave;nh thế giới.</p>', 2024, NULL, 258, 16, 4, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (93, N'Chip War - Cuộc Chiến Vi Mạch - Bìa Cứng', N'8935235241374', N'Bìa Cứng', CAST(156000.00 AS Decimal(12, 2)), CAST(300000.00 AS Decimal(12, 2)), CAST(240000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935235241374.jpg', N'Chris Miller', N'<p><strong>Chip War - Cuộc Chiến Vi Mạch - B&igrave;a Cứng</strong></p>
<p>Ng&agrave;y nay, sức mạnh qu&acirc;n sự, kinh tế v&agrave; ch&iacute;nh trị được x&acirc;y dựng tr&ecirc;n nền tảng chip m&aacute;y t&iacute;nh. Hầu như mọi thứ đều chạy tr&ecirc;n c&aacute;c con chip, từ t&ecirc;n lửa đến l&ograve; vi s&oacute;ng, đến cả &ocirc; t&ocirc;, điện thoại th&ocirc;ng minh, thị trường chứng kho&aacute;n, thậm ch&iacute; cả lưới điện.</p>
<p>Gần đ&acirc;y, nước Mỹ đ&atilde; thiết kế những con chip nhanh nhất v&agrave; duy tr&igrave; vị thế số một thế giới, nhưng lợi thế đ&oacute; đang c&oacute; nguy cơ suy yếu khi c&aacute;c đối thủ ở Đ&agrave;i Loan, H&agrave;n Quốc v&agrave; ch&acirc;u &Acirc;u nổi l&ecirc;n nắm quyền kiểm so&aacute;t. Mỹ đ&atilde; để c&aacute;c th&agrave;nh phần quan trọng của qu&aacute; tr&igrave;nh sản xuất chip vuột khỏi tầm kiểm so&aacute;t, dẫn đến t&igrave;nh trạng thiếu chip tr&ecirc;n to&agrave;n thế giới v&agrave; cuộc chiến vi mạch nổ ra với đối thủ l&agrave; Trung Quốc đang mong muốn thu hẹp khoảng c&aacute;ch.</p>
<p>Trung Quốc đang chi nhiều tiền cho chip hơn bất kỳ sản phẩm n&agrave;o kh&aacute;c, r&oacute;t h&agrave;ng tỷ đ&ocirc; la v&agrave;o việc x&acirc;y dựng chip, đe dọa tới ưu thế qu&acirc;n sự v&agrave; sự thịnh vượng của nền kinh tế Mỹ.</p>
<p>Con chip của thế kỷ 21 giống như dầu mỏ của thế kỷ 20, v&agrave; v&igrave; thế, lịch sử của chất b&aacute;n dẫn ch&iacute;nh l&agrave; lịch sử của thế kỷ 21. Cuộc chiến vi mạch được xem l&agrave; bi&ecirc;n ni&ecirc;n sử về cuộc chiến k&eacute;o d&agrave;i h&agrave;ng thập ni&ecirc;n để kiểm so&aacute;t thứ đang nổi l&ecirc;n l&agrave; t&agrave;i nguy&ecirc;n quan trọng nhất nhưng lại khan hiếm: c&ocirc;ng nghệ vi mạch.</p>', 2024, CAST(5.0 AS Decimal(3, 1)), 480, 8, 2, 99)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (94, N'BộChiến Tranh Tiền Tệ', N'9786043606492', N'Bìa Mềm', CAST(91260.00 AS Decimal(12, 2)), CAST(195000.00 AS Decimal(12, 2)), CAST(140400.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786043606492.jpg', N'Song Hong Bing', N'<p>Chiến tranh tiền tệ tập 5 &ndash;&nbsp;<em>&ldquo;Tương lai của tiền tệ thế giới &ndash; B&igrave;nh y&ecirc;u trước gi&ocirc;ng b&atilde;o&rdquo;</em>&nbsp;l&agrave; phần cuối c&ugrave;ng trong series đ&igrave;nh đ&aacute;m &ldquo;Chiến tranh tiền tệ&rdquo; được rất nhiều độc giả y&ecirc;u th&iacute;ch v&agrave; đ&aacute;nh gi&aacute; cao.</p>
<p>Năm năm sau khi cuộc khủng hoảng t&agrave;i ch&iacute;nh năm 2008 kết th&uacute;c, c&aacute;c &yacute; kiến về định hướng tương lai của nền kinh tế thế giới vẫn bị chia rẽ rất nhiều. Ch&iacute;nh s&aacute;ch QE &ndash; nơi lỏng định lượng ở Mỹ c&oacute; hiệu quả kh&ocirc;ng? Tiền tệ to&agrave;n cầu ph&aacute;t h&agrave;nh qu&aacute; mức rốt cuộc l&agrave; ph&uacute;c hay họa? Thị trường t&agrave;i ch&iacute;nh đang dần trở n&ecirc;n an to&agrave;n hay ng&agrave;y c&agrave;ng nguy hiểm? Đ&agrave; phục hồi kinh tế đang diễn ra ổn định hay chỉ l&agrave; &aacute;nh chớp l&oacute;e l&ecirc;n rồi vụt tắt?</p>
<p>Trọng của cuốn Chiến tranh tiền tệ 5 biến c&aacute;c kh&aacute;i niệm &ldquo;ph&acirc;n phối của cải&rdquo; th&agrave;nh một con dao giải phẫu để mổ xẻ c&aacute;c hoạt động kinh tế, tiến h&agrave;nh so s&aacute;nh xuy&ecirc;n thời gian v&agrave; kh&ocirc;ng gian giữa &ldquo;giấc mơ Mỹ&rdquo; ng&agrave;y nay với &ldquo;giấc mơ La M&atilde;&rdquo; v&agrave; &ldquo;giấc mơ triều Tống&rdquo; trong lịch sử, đồng thời cung cấp một hệ quy chiếu lịch sử cho &ldquo;giấc mơ Trung Hoa&rdquo; trong tương lai.</p>
<p>Cuốn s&aacute;ch tập trung v&agrave;o ph&acirc;n t&iacute;ch hiện trạng của nền kinh tế Mỹ v&agrave; đồng đ&ocirc; la th&ocirc;ng qua thị trường v&agrave;ng, thị trường chứng kho&aacute;n, cũng như t&igrave;m hiểu d&ograve;ng vốn th&ocirc;ng qua thị trường tr&aacute;i phiếu, kh&aacute;m ph&aacute; lĩnh vực t&agrave;i ch&iacute;nh th&ocirc;ng qua thị trường mua lại, t&igrave;m hiểu căn nguy&ecirc;n c&aacute;c cuộc khủng hoảng th&ocirc;ng qua l&atilde;i suất, bất dộng sản, thị trường việc l&agrave;m&hellip;</p>
<p>Ngo&agrave;i ra, cuốn s&aacute;ch c&ograve;n mở rộng tầm quan s&aacute;t của độc giả đến giai đoạn những năm 2000, từ quan s&aacute;t cận cảnh nền kinh tế Mỹ cho đến giai đoạn đ&aacute;nh gi&aacute; v&agrave; nắm bắt ngọn nguồn trong lịch sử, từ đ&oacute; phục dựng lại một c&aacute;ch ch&acirc;n thực nhất m&ocirc; h&igrave;nh của qu&aacute; tr&igrave;nh suy vong, từ đ&oacute; hiểu được bản chất của tiền tệ c&ugrave;ng những định hướng, hướng đi trong tương lai.</p>', 2022, NULL, 684, 1, 15, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (95, N'Cách Nhìn Mới Về Vàng - The New Case For Gold', N'8934974174868', N'Bìa Mềm', CAST(51675.00 AS Decimal(12, 2)), CAST(95000.00 AS Decimal(12, 2)), CAST(79500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/n/x/nxbtre_full_06222021_032231.jpg', N'James Rickards', N'<p><strong>C&aacute;ch Nh&igrave;n Mới Về V&agrave;ng - The New Case For Gold</strong></p>
<p>** S&aacute;ch b&aacute;n chạy nhất tr&ecirc;n USA Today v&agrave; s&aacute;ch kinh doanh b&aacute;n chạy nhất tr&ecirc;n Wall Street Journal **</p>
<p>Họ n&oacute;i rằng John Maynard Keynes đ&atilde; gọi v&agrave;ng l&agrave; một "th&aacute;nh t&iacute;ch man rợ".</p>
<p>Họ n&oacute;i rằng kh&ocirc;ng c&oacute; đủ v&agrave;ng để chống đỡ cho nền t&agrave;i ch&iacute;nh v&agrave; thương mại.</p>
<p>Họ n&oacute;i rằng nguồn cung v&agrave;ng kh&ocirc;ng thể tăng đủ nhanh để chống đỡ cho tăng trưởng thế giới.</p>
<p>Họ đ&atilde; sai.</p>
<p>Trong bản tuy&ecirc;n ng&ocirc;n đầy t&aacute;o bạo n&agrave;y, t&aacute;c giả s&aacute;ch b&aacute;n chạy nhất v&agrave; nh&agrave; b&igrave;nh luận kinh tế James Rickards đ&atilde; l&ecirc;n tiếng b&ecirc;nh vực v&agrave;ng &mdash; vừa với tư c&aacute;ch một vật lưu trữ t&agrave;i sản kh&ocirc;ng thể thay thế, vừa với tư c&aacute;ch một ti&ecirc;u chuẩn cho tiền tệ.<br>Mức độ bất ổn ch&iacute;nh trị to&agrave;n cầu v&agrave; biến động thị trường ng&agrave;y c&agrave;ng tăng cao. V&agrave;ng, thứ t&agrave;i sản kh&ocirc;n ngoan m&agrave; ai cũng n&ecirc;n sở hữu, đ&atilde; trở th&agrave;nh c&ocirc;ng cụ bảo to&agrave;n t&agrave;i sản quan trọng nhất đối với c&aacute;c ng&acirc;n h&agrave;ng cũng như c&aacute; nh&acirc;n. Dựa tr&ecirc;n c&aacute;c nghi&ecirc;n cứu điển h&igrave;nh trong lịch sử, l&yacute; thuyết tiền tệ v&agrave; kinh nghiệm c&aacute; nh&acirc;n với tư c&aacute;ch một nh&agrave; đầu tư của m&igrave;nh, Rickards kết luận rằng:</p>
<p>&bull; Vụ sụp đổ t&agrave;i ch&iacute;nh tiếp theo sẽ lớn gấp nhiều lần cuộc khủng hoảng năm 2008.</p>
<p>&bull; T&igrave;nh trạng mua v&agrave;o trong hoảng loạn v&agrave; chỉ c&oacute; c&aacute;c ng&acirc;n h&agrave;ng trung ương, quỹ ph&ograve;ng hộ v&agrave; những người chơi lớn kh&aacute;c mới c&oacute; thể mua được v&agrave;ng sẽ xảy ra sớm hơn ch&uacute;ng ta tưởng.</p>
<p>&bull; Việc chủ động chuẩn bị để đương đầu với những g&igrave; sắp xảy ra với tư c&aacute;ch một quốc gia kh&ocirc;ng bao giờ l&agrave; qu&aacute; muộn: lu&ocirc;n c&oacute; đủ v&agrave;ng cho một chế độ bản vị v&agrave;ng nếu ch&uacute;ng ta ấn định một mức gi&aacute; ổn định, kh&ocirc;ng g&acirc;y giảm ph&aacute;t.</p>
<p>Cung cấp hướng dẫn r&otilde; r&agrave;ng về số lượng v&agrave;ng cần mua v&agrave; nơi cất giữ n&oacute;, lập luận ngắn gọn, đầy t&iacute;nh k&iacute;ch th&iacute;ch trong cuốn s&aacute;ch n&agrave;y sẽ thay đổi c&aacute;ch nh&igrave;n của bạn về &ldquo;th&aacute;nh t&iacute;ch man rợ&rdquo; n&agrave;y m&atilde;i m&atilde;i.</p>', 2021, NULL, 224, 15, 7, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (96, N'BộChiến Tranh Tiền Tệ', N'9786043603590', N'Bìa Mềm', CAST(86580.00 AS Decimal(12, 2)), CAST(185000.00 AS Decimal(12, 2)), CAST(133200.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786043603590.jpg', N'Song Hong Bing', N'<p>&Oacute;M TẮT NỘI DUNG:</p>
<p>Cuốn s&aacute;ch tiếp nối d&ograve;ng c&acirc;u chuyện về trận chiến tranh gi&agrave;nh b&aacute; quyền t&agrave;i ch&iacute;nh thế giới, bắt đầu bằng nỗ lực lật đổ b&aacute; quyền đồng bảng Anh của đồng đ&ocirc; la Mỹ v&agrave; cuộc phản c&ocirc;ng của đồng bảng Anh. Cuộc đấu tranh gay gắt giữa đồng đ&ocirc; la v&agrave; đồng bảng Anh đ&atilde; tạo ra một khoảng trống quyền lực t&agrave;i ch&iacute;nh thế giới trong những năm 1930, l&agrave;m trầm trọng th&ecirc;m cuộc Đại suy tho&aacute;i tr&ecirc;n to&agrave;n thế giới. Thế lực &ldquo;Hợp ch&uacute;ng quốc ch&acirc;u &Acirc;u&rdquo; cũng dần được thống nhất v&agrave; trỗi dậy như một si&ecirc;u cường t&agrave;i ch&iacute;nh.</p>
<p>Chiến tranh Thế giới Thứ hai đ&atilde; tạo cơ hội lịch sử cho đồng đ&ocirc; la để ti&ecirc;u diệt đồng bảng Anh.&nbsp;<em>Hiến chương Đại T&acirc;y Dương</em>&nbsp;v&agrave;&nbsp;<em>Đạo luật cho thu&ecirc;</em>&nbsp;l&agrave; những con dao sắc b&eacute;n trong tay Roosevelt nhằm thực hiện mục đ&iacute;ch n&agrave;y. Cuối c&ugrave;ng, bằng c&aacute;ch&ldquo;giữ v&agrave;ng lệnh chư hầu&rdquo;, Hoa Kỳ đ&atilde; th&agrave;nh lập một "Vương triều Bretton Woods &rdquo; với chế độ đ&ocirc; la l&agrave;m nhiếp ch&iacute;nh.</p>
<p>C&ugrave;ng l&uacute;c đ&oacute;, cơ sở của mối quan t&acirc;m trong cuộc h&ocirc;n nh&acirc;n kinh tế "Trung - Mỹ" đang dần rạn nứt v&agrave; tan r&atilde;. Mối quan hệ giữa thế lực si&ecirc;u cường của Mỹ v&agrave; kinh tế đang b&ugrave;ng nổ của Trung Quốc vốn chỉ tồn tại dựa tr&ecirc;n m&ocirc; h&igrave;nh Trung Quốc sản xuất, Mỹ hưởng thụ; Trung Quốc tiết kiệm, Mỹ ti&ecirc;u d&ugrave;ng. Sự chuyển đổi kinh tế trong tương lai của Trung Quốc sẽ tất yếu đ&ograve;i hỏi phải c&oacute; sự chuyển dịch c&aacute;c nguồn lực ch&iacute;nh của nền kinh tế quốc gia từ nghi&ecirc;ng về thị trường nước ngo&agrave;i sang nghi&ecirc;ng về thị trường trong nước, do đ&oacute; l&agrave;m giảm xuất khẩu tiết kiệm sang Hoa Kỳ.</p>
<p>Trung Quốc c&oacute; thể h&oacute;a giải thế bao v&acirc;y của Mỹ hay kh&ocirc;ng, tất cả đều phụ thuộc v&agrave;o việc liệu nước n&agrave;y c&oacute; thể k&ecirc;u gọi c&aacute;c nước ch&acirc;u &Aacute; đo&agrave;n kết lại th&agrave;nh một cộng đồng mạnh c&oacute; chung lợi &iacute;ch. Chỉ khi x&aacute;c lập được vị thế ở ch&acirc;u &Aacute;, Trung Quốc mới c&oacute; thể vươn ra thế giới; chỉ bằng c&aacute;ch khiến cả ch&acirc;u &Aacute; đo&agrave;n kết lại th&agrave;nh một khối thống nhất th&igrave; nền kinh tế Trung Quốc mới c&oacute; thể chuyển đổi th&agrave;nh c&ocirc;ng; chỉ c&oacute; một đồng tiền ch&acirc;u &Aacute; thống nhất th&igrave; mới c&oacute; thể cạnh tranh với đồng đ&ocirc;-la v&agrave; đồng euro tr&ecirc;n trường quốc tế, để rồi cuối c&ugrave;ng h&igrave;nh th&agrave;nh n&ecirc;n thế ch&acirc;n vạc của thời đại &ldquo;chiến quốc tiền tệ&rdquo;.</p>', 2022, NULL, 608, 1, 3, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (97, N'Economix - Các Nền Kinh Tế Vận Hành (Và Không Vận Hành) Thế Nào Và Tại Sao?', N'8935235224537', N'Bìa Mềm', CAST(80925.00 AS Decimal(12, 2)), CAST(152000.00 AS Decimal(12, 2)), CAST(124500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/e/c/economix-01.jpg', N'Michael Goodwin', N'<p>Nếu c&aacute;c bạn từng t&igrave;m c&aacute;ch hiểu những kh&aacute;i niệm kinh tế qua việc đọc v&ocirc; số gi&aacute;o tr&igrave;nh kinh tế học, nhưng vẫn thấy thật kh&oacute; h&igrave;nh dung được bức tranh to&agrave;n cảnh về bộ m&ocirc;n n&agrave;y, th&igrave; cuốn s&aacute;ch sẽ cung cấp cho c&aacute;c bạn một mảnh gh&eacute;p ho&agrave;n chỉnh cho những mảnh nho nhỏ m&agrave; c&aacute;c bạn đ&atilde; đọc qua.</p>
<p>Ch&uacute;ng ta sẽ hiểu r&otilde; hơn về những kh&aacute;i niệm kinh tế cơ bản c&ugrave;ng những học thuyết kinh tế lớn c&ograve;n ảnh hưởng tới ng&agrave;y nay, qua tư tưởng của c&aacute;c nh&agrave; kinh tế học lớn như: Adam Smith, John Keynes...</p>
<p>C&oacute; thể coi đ&acirc;y l&agrave; một cuốn sử về lịch sử kinh tế thế giới kể từ khi nền kinh tế h&agrave;ng h&oacute;a ra đời. Ch&uacute;ng ta sẽ lướt qua v&agrave;i thế kỷ với v&ocirc; số học thuyết về kinh tế học c&ugrave;ng những vụ khủng hoảng kinh tế lớn như thể đang đọc một cuốn truyện tranh, cả bi lẫn h&agrave;i, căng thẳng m&agrave; kh&ocirc;ng k&eacute;m phần sảng kho&aacute;i.</p>
<p>&ldquo;Cuốn s&aacute;ch h&oacute;m hỉnh v&agrave; th&uacute; vị n&agrave;y động chạm đến v&ocirc; số vấn đề phức tạp &ndash; kinh tế học, lịch sử v&agrave; t&agrave;i ch&iacute;nh &ndash; v&agrave; khiến những vấn đề ấy trở n&ecirc;n dễ hiểu với cả những người dốt nhất.&rdquo;</p>
<p>&ndash;<em>Miami Herald</em></p>
<p>&ldquo;<em>Economix</em>đem lại một cảm gi&aacute;c sống động về chủ đề v&ocirc; c&ugrave;ng kh&oacute; hiểu n&agrave;y m&agrave; kh&ocirc;ng phải đơn giản h&oacute;a n&oacute; hoặc khiến độc giả khiếp h&atilde;i.&rdquo;</p>
<p>&ndash; MotherJones.com</p>', 2019, NULL, 310, 19, 7, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (98, N'Tiền Đẻ Ra Tiền - Đầu Tư Tài Chính Thông Minh (Tái Bản 2025)', N'8935246945384', N'Bìa Mềm', CAST(85150.00 AS Decimal(12, 2)), CAST(160000.00 AS Decimal(12, 2)), CAST(131000.00 AS Decimal(12, 2)), N'https://res.cloudinary.com/dabxzdaf8/image/upload/v1748969415/Book_cover/j2sev3glpkxr096pxrmk.webp', N'Duncan Bannatyne', N'<p><strong>Tiền Đẻ Ra Tiền - Đầu Tư T&agrave;i Ch&iacute;nh Th&ocirc;ng Minh</strong></p>
<p>Sau sự th&agrave;nh c&ocirc;ng của hai cuốn s&aacute;ch&nbsp;<strong><em>&ldquo;Thức tỉnh v&agrave; thay đổi cuộc đời bạn: B&iacute; quyết th&agrave;nh c&ocirc;ng của triệu ph&uacute; Anh&rdquo;</em></strong>&nbsp;v&agrave;&nbsp;<strong><em>&ldquo;Quản l&yacute; thời gian th&ocirc;ng minh của người th&agrave;nh đạt: B&iacute; quyết th&agrave;nh c&ocirc;ng của triệu ph&uacute; Anh&rdquo;</em></strong>&nbsp;l&agrave; những c&acirc;u chuyện, những lời khuy&ecirc;n dựa tr&ecirc;n những kinh nghiệm phong ph&uacute; của cuộc đời m&igrave;nh v&agrave; nhằm mục đ&iacute;ch truyền cảm hứng động lực l&agrave;m gi&agrave;u cho mọi c&ocirc;ng d&acirc;n đều c&oacute; thể trở th&agrave;nh triệu ph&uacute;, th&igrave; triệu ph&uacute; người Anh v&agrave; t&aacute;c giả của nhiều đầu s&aacute;ch nổi tiếng&nbsp;<em>Duncan Bannatyne</em>&nbsp;đ&atilde; cho ra mắt cuốn s&aacute;ch &ldquo;&nbsp;<strong><em>Tiền Đẻ Ra Tiền &ndash; Đầu Tư T&agrave;i Ch&iacute;nh Th&ocirc;ng Minh</em></strong>&rdquo;.</p>
<p><em><strong>C&oacute; điều g&igrave; đặc biệt ở cuốn s&aacute;ch &ldquo; Tiền Đẻ Ra Tiền&rdquo; ?</strong></em></p>
<p>Điều đặc biệt so với những cuốn s&aacute;ch kh&aacute;c &ocirc;ng từng viết trước đ&acirc;y, đ&oacute; l&agrave; cuốn s&aacute;ch n&agrave;y kh&ocirc;ng n&oacute;i về chuyện l&agrave;m gi&agrave;u, cũng l&agrave; một phần trong chuỗi c&acirc;u chuyện&nbsp;<strong><em>&ldquo;B&iacute; quyết th&agrave;nh c&ocirc;ng của triệu ph&uacute; Anh&rdquo;</em></strong>&nbsp;nhưng n&oacute; b&agrave;n đến việc kiểm so&aacute;t tiền bạc. Đến với cuối cuốn s&aacute;ch, bạn sẽ c&oacute; sự tự tin để đưa ra những quyết định đ&uacute;ng đắn cho bản th&acirc;n m&igrave;nh v&agrave; những kỹ năng để khiến đồng tiền của m&igrave;nh đi xa hơn, c&oacute; hiệu quả d&ugrave; nền kinh tế c&oacute; ra sao đi chăng nữa.</p>
<p>N&oacute; sẽ b&agrave;n tới những kh&iacute;a cạnh, những th&agrave;nh tố cốt yếu của t&agrave;i ch&iacute;nh v&agrave; mối quan hệ cốt l&otilde;i của bạn với đồng tiền. Nếu bạn kh&ocirc;ng suy nghĩ theo một c&aacute;ch c&oacute; chiến lược về tiền bạc, bạn sẽ kh&ocirc;ng thể l&agrave;m bất cứ thứ g&igrave; c&oacute; t&iacute;nh chiến lược với tiền bạc &ndash; thứ cứ thế tr&ocirc;i tuột ra khỏi t&agrave;i khoản ng&acirc;n h&agrave;ng v&agrave; v&iacute; của bạn. Nội dung của cuốn s&aacute;ch sẽ l&agrave; những lời khuy&ecirc;n theo một kế hoạch cụ thể của Duncan m&agrave; bạn c&oacute; thể &aacute;p dụng ngay được để c&oacute; thể gi&uacute;p bạn quản l&yacute; chi ti&ecirc;u một c&aacute;ch tối ưu nhất, khiến&nbsp;<em>&ldquo;</em><strong><em>Tiền đẻ ra tiền&rdquo;&nbsp;</em></strong>v&agrave; gi&uacute;p bạn đầu tư t&agrave;i ch&iacute;nh một c&aacute;ch th&ocirc;ng minh<strong><em>.&nbsp;</em></strong>Cụ thể, cuốn s&aacute;ch được chia th&agrave;nh 6 phần:</p>
<p>Phần 01: L&yacute; thuyết tiền tệ</p>
<p>Phần 02: Kiếm tiền nhiều hơn</p>
<p>Phần 03: Chi ti&ecirc;u</p>
<p>Phần 04: Vay mượn</p>
<p>Phần 05: Tiết kiệm v&agrave; đầu tư</p>
<p>Ph&agrave;n 06: Kế hoạch</p>', 2025, NULL, 240, 18, 2, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (99, N'BộDạy Con Làm Giàu 01: Để Không Có Tiền Vẫn Tạo Ra Tiền (Tái Bản 2022)', N'8934974180975', N'Bìa Mềm', CAST(43550.00 AS Decimal(12, 2)), CAST(80000.00 AS Decimal(12, 2)), CAST(67000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8934974180975.jpg', N'Robert T Kiyosaki', N'<p><strong>Dạy Con L&agrave;m Gi&agrave;u 01: Cha Gi&agrave;u Cha Ngh&egrave;o -&nbsp;Để Kh&ocirc;ng C&oacute; Tiền Vẫn Tạo Ra Tiền (T&aacute;i Bản 2022)&nbsp;</strong></p>
<p>Người gi&agrave;u kh&ocirc;ng l&agrave;m việc v&igrave; tiền. Họ bắt tiền l&agrave;m việc cho họ. Chấp nhận thất bại l&agrave; bước đầu của th&agrave;nh c&ocirc;ng? Quyền lực của sự lựa chọn! Những b&agrave;i học kh&ocirc;ng c&oacute; trong nh&agrave; trường. H&atilde;y bắt đầu từ h&ocirc;m nay &ldquo;để kh&ocirc;ng c&oacute; tiền vẫn tạo ra tiền&rdquo;&hellip;.</p>
<p>Bạn sẽ l&agrave;m g&igrave; khi được cả hai người cha truyền dạy cho m&igrave;nh về chủ đề tiền bạc v&agrave; sự lựa chọn c&aacute;ch sống trong đời.</p>
<p>Một người l&agrave; bố ruột, c&ograve;n người kia l&agrave; bố người bạn th&acirc;n nhất. Một người c&oacute; nền học vấn rất cao trong khi người kia chỉ học tới trung học, nhưng cả hai đều th&agrave;nh c&ocirc;ng trong sự nghiệp v&agrave; c&oacute; ảnh hưởng đến người kh&aacute;c. T&aacute;c giả của cuốn s&aacute;ch đ&atilde; phải suy nghĩ nhiều v&agrave; cũng học hỏi được rất nhiều điều từ những lời chỉ dạy của hai người cha n&agrave;y. C&ograve;n bạn, bạn sẽ nghĩ g&igrave; khi được nghe những lời khuy&ecirc;n tr&aacute;i ngược của hai &ocirc;ng bố: Một người n&oacute;i: Ham m&ecirc; tiền bạc l&agrave; nguồn gốc của mọi điều xấu.</p>
<p>Một người n&oacute;i: Thiếu thốn tiền bạc l&agrave; nguồn gốc của mọi điều xấu.</p>
<p>Một người tin rằng: T&ocirc;i kh&ocirc;ng mua nổi vật đ&oacute;.</p>
<p>Người kia lại nghĩ: L&agrave;m thế n&agrave;o để mua được vật đ&oacute;.</p>
<p>Một người dạy: Phải học cho giỏi th&igrave; mới được l&agrave;m việc ở những c&ocirc;ng ty tốt.</p>
<p>Người kia bảo: Học cho giỏi th&igrave; mới mua được những c&ocirc;ng ty tốt.</p>
<p>Một người chắc rằng: Ng&ocirc;i nh&agrave; l&agrave; số đầu tư nhiều nhất v&agrave; l&agrave; t&agrave;i sản lớn nhất của ch&uacute;ng ta. Người kia lại nghĩ rằng: Ng&ocirc;i nh&agrave; cũng l&agrave; một khoản tiền trả...</p>', 2022, NULL, 196, 9, 8, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (100, N'Ai Thực Chiến Phải Kiếm Ra Tiền', N'9786044802671', N'Bìa Mềm', CAST(179725.00 AS Decimal(12, 2)), CAST(389000.00 AS Decimal(12, 2)), CAST(276500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786044802671.jpg', N'Nguyễn Tiến Quốc, Luân Đức Đại', N'<p><strong>Ai Thực Chiến Phải Kiếm Ra Tiền</strong></p>
<p>&ldquo;AI Thực Chiến &ndash; Phải Kiếm Ra Tiền&rdquo; ch&iacute;nh l&agrave; tấm bản đồ gi&uacute;p bạn khai ph&aacute; sức mạnh của AI v&agrave; biến n&oacute; th&agrave;nh người bạn đồng h&agrave;nh đắc lực trong h&agrave;nh tr&igrave;nh hiện thực h&oacute;a ước mơ.</p>
<p>Nếu bạn đang mơ ước về một cuộc sống tự do t&agrave;i ch&iacute;nh, l&agrave;m chủ thời gian v&agrave; kh&ocirc;ng bị r&agrave;ng buộc bởi những giới hạn của c&ocirc;ng việc truyền thống, th&igrave; cuốn s&aacute;ch n&agrave;y ch&iacute;nh l&agrave; tấm bản đồ dẫn lối bạn đến th&agrave;nh c&ocirc;ng trong thời đại tr&iacute; tuệ nh&acirc;n tạo.</p>', 2025, NULL, 516, 14, 15, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (101, N'BộDạy Con Làm Giàu 11 - Trường Dạy Kinh Doanh Cho Những Người Thích Giúp Đỡ Người Khác (2022)', N'8934974179931', N'Bìa Mềm', CAST(43550.00 AS Decimal(12, 2)), CAST(80000.00 AS Decimal(12, 2)), CAST(67000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8934974179931.jpg', N'Robert T Kiyosaki', N'<p><strong>Dạy Con L&agrave;m Gi&agrave;u 11: Cha Gi&agrave;u Cha Ngh&egrave;o - Trường Dạy Kinh Doanh Cho Những Người Th&iacute;ch Gi&uacute;p Đỡ Người Kh&aacute;c (2022)</strong></p>
<p>Trong cuốn s&aacute;ch n&agrave;y, t&aacute;c giả tập trung giải th&iacute;ch v&agrave; mở rộng những gi&aacute; trị b&iacute; ẩn của h&igrave;nh thức kinh doanh tiếp thị qua mạng v&agrave; kinh doanh h&agrave;ng đa cấp.</p>
<p>Theo t&aacute;c giả, đ&acirc;y l&agrave; h&igrave;nh thức kinh doanh s&aacute;ng tạo, ph&ugrave; hợp với tất cả những ai mong muốn trở th&agrave;nh người gi&agrave;u c&oacute;.</p>', 2022, NULL, 225, 16, 12, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (102, N'BộBiến Mọi Thứ Thành Tiền - Make Money', N'9786043654370', N'Bìa Mềm', CAST(54600.00 AS Decimal(12, 2)), CAST(168000.00 AS Decimal(12, 2)), CAST(84000.00 AS Decimal(12, 2)), N'https://res.cloudinary.com/dabxzdaf8/image/upload/v1748969293/Book_cover/jqohsuf2zhovaljuhihj.webp', N'Nguyễn Anh Dũng', N'<p>B&iacute; quyết gi&uacute;p bạn tho&aacute;t ngh&egrave;o để đạt được th&agrave;nh c&ocirc;ng v&agrave; gi&agrave;u c&oacute; thực sự &ldquo;Biến mọi thứ th&agrave;nh tiền&rdquo; l&agrave; cuốn s&aacute;ch xoay quanh chủ đề t&agrave;i ch&iacute;nh c&aacute; nh&acirc;n. Đ&acirc;y l&agrave; vấn đề đang được nhiều người, trong đ&oacute; c&oacute; c&aacute;c bạn trẻ đặc biệt quan t&acirc;m. Cuốn s&aacute;ch định hướng người đọc về c&aacute;ch kiếm tiền, tư duy l&agrave;m gi&agrave;u, c&aacute;ch &aacute;p dụng những phương ph&aacute;p l&agrave;m gi&agrave;u v&agrave;o cuộc sống v&agrave; ph&aacute;t triển bản th&acirc;n. B&iacute; quyết gi&uacute;p bạn tho&aacute;t ngh&egrave;o để đạt được th&agrave;nh c&ocirc;ng v&agrave; gi&agrave;u c&oacute; thực sự ở đ&acirc;y kh&ocirc;ng phải l&agrave; c&ocirc;ng thức cho tất cả mọi người.</p>
<p>Cuốn s&aacute;ch chỉ ra cho bạn phương thức, c&ocirc;ng cụ ph&ugrave; hợp đạt được cơ hội chiến thắng l&agrave; hiểu ch&iacute;nh bản th&acirc;n m&igrave;nh.</p>
<p>&ldquo;Biến mọi thứ th&agrave;nh tiền&rdquo; gồm 3 phần lớn:</p>
<p>Phần 1: Kh&aacute;t vọng biến mọi thứ th&agrave;nh tiền</p>
<p>Phần 2: Biến mọi thứ th&agrave;nh tiền</p>
<p>Phần 3: S&aacute;ng tạo d&ograve;ng tiền</p>
<p>Dường như danh từ &ldquo;tiền&rdquo; được nhắc đến xuy&ecirc;n suốt cả cuốn s&aacute;ch. Vậy thế n&agrave;o l&agrave; tiền? Trong quan niệm của mỗi người, vai tr&ograve; của tiền l&agrave; g&igrave;? Ngay trong phần một của cuốn s&aacute;ch đ&atilde; chỉ ra cho người đọc, việc kiếm tiền g&acirc;y ra nhiều kh&oacute; khăn. Mỗi một người sẽ đi t&igrave;m ra kh&oacute; khăn của ri&ecirc;ng m&igrave;nh, bắt đầu t&igrave;m kiếm gi&aacute; trị của tiền, c&aacute;ch thức ph&aacute;t triển đồng tiền. Đồng tiền sống l&agrave; đồng tiền c&oacute; thể tự động h&oacute;a, t&aacute;i tạo v&agrave; tạo ra gi&aacute; trị th&agrave;nh c&ocirc;ng. Cuốn s&aacute;ch được doanh nh&acirc;n trẻ th&agrave;nh đạt Nguyễn Anh Dũng, người biến những trang s&aacute;ch tri thức mang lại gi&aacute; trị tốt đẹp cho con người. Mong muốn của anh sẽ gợi mở nguồn cảm hứng khởi nghiệp, mở rộng g&oacute;c nh&igrave;n v&agrave; c&oacute; quyết định s&aacute;ng suốt hơn cho c&aacute;c doanh nh&acirc;n, bạn trẻ.</p>', 2023, NULL, 285, 17, 9, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (103, N'How Business Works - Hiểu Hết Về Kinh Doanh', N'8935235225053', N'Bìa Mềm', CAST(202475.00 AS Decimal(12, 2)), CAST(380000.00 AS Decimal(12, 2)), CAST(311500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_195509_1_19337.jpg', N'Nhiều Tác Giả', N'<p>Một trong những cuốn cẩm nang về Kinh doanh dễ h&igrave;nh dung nhất từ trước tới nay!</p>
<p>&nbsp;Tại sao d&ograve;ng tiền lại quan trọng? Sản xuất tinh gọn l&agrave; g&igrave;? Marketing kỹ thuật số hoạt động ra sao? Th&agrave;nh vi&ecirc;n hội đồng quản trị gồm những ai? Mua b&aacute;n doanh nghiệp l&agrave; g&igrave;? Cấu tr&uacute;c doanh nghiệp ra sao? Khấu hao l&agrave; g&igrave;? Tr&aacute;ch nhiệm x&atilde; hội của doanh nghiệp ra sao? L&agrave;m thế n&agrave;o để c&oacute; thể th&agrave;nh c&ocirc;ng trong thị trường to&agrave;n cầu của thế kỷ 21?</p>
<p>&nbsp;Với những h&igrave;nh ảnh bắt mắt, đơn giản, kh&ocirc;ng sử dụng thuật ngữ, How business works</p>
<p>&nbsp;Hiểu hết về kinh doanh giải th&iacute;ch mọi kh&aacute;i niệm li&ecirc;n quan đến lĩnh vực kinh doanh, biến những kh&aacute;i niệm kh&oacute; hiểu nhất trở n&ecirc;n dễ hiểu. Mọi kh&iacute;a cạnh của hoạt động kinh doanh sẽ được xem x&eacute;t, ph&acirc;n t&iacute;ch gi&uacute;p độc giả hiểu r&otilde; hơn về kinh doanh, v&agrave; c&aacute;ch c&aacute;c h&igrave;nh th&aacute;i kinh doanh định h&igrave;nh x&atilde; hội hiện đại.</p>
<p>&nbsp;D&ugrave; bạn đang muốn thăng tiến trong c&ocirc;ng việc, khởi sự doanh nghiệp của ri&ecirc;ng m&igrave;nh hay chỉ đơn giản l&agrave; muốn hiểu r&otilde; hơn thế giới kinh doanh v&agrave; t&agrave;i ch&iacute;nh, How business works</p>
<p>&nbsp;Hiểu hết về kinh doanh ch&iacute;nh l&agrave; cuốn cẩm nang kh&ocirc;ng thể bỏ qua!</p>', 2020, NULL, 351, 20, 15, 100)
GO
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (104, N'Coach - Khởi Nghiệp Độc Lập Bằng Kỹ Năng Khai Vấn', N'8936170870643', N'Bìa Mềm', CAST(148200.00 AS Decimal(12, 2)), CAST(285000.00 AS Decimal(12, 2)), CAST(228000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8936170870643.jpg', N'Trần Tiến Công', N'<p><strong>Coach - Khởi Nghiệp Độc Lập Bằng Kỹ Năng Khai Vấn</strong></p>
<p>Với mức thu nhập cao c&ugrave;ng những gi&aacute; trị t&iacute;ch cực mang lại cho cộng đồng, Coaching đang dần trở th&agrave;nh một ng&agrave;nh dịch vụ đầy triển vọng, len lỏi v&agrave;o rất nhiều lĩnh vực kh&aacute;c nhau như sức khoẻ, kỹ năng, sự nghiệp, kinh doanh,... Tại c&aacute;c thị trường đang ph&aacute;t triển, trong đ&oacute; c&oacute; Việt Nam, nguồn nh&acirc;n lực chuy&ecirc;n m&ocirc;n được ghi nhận c&ograve;n rất hạn chế trước nhu cầu ng&agrave;y một tăng cao của x&atilde; hội. Giữa thời điểm khởi đầu của xu hướng Solopreneur - Khởi nghiệp độc lập, Coaching mở ra cơ hội v&ocirc; c&ugrave;ng tiềm năng cho những người muốn x&acirc;y dựng một sự nghiệp độc lập v&agrave; ph&aacute;t triển một cuộc sống c&oacute; &yacute; nghĩa.</p>
<p>Được viết bởi t&aacute;c giả Trần Tiến C&ocirc;ng - nh&agrave; s&aacute;ng lập Vietnam Coaching Institute (học vi&ecirc;n Coach đầu ti&ecirc;n được chứng nhận bởi ICF ở Việt Nam v&agrave;o 2012), cuốn s&aacute;ch &ldquo;COACH - Khởi nghiệp độc lập bằng kỹ năng khai vấn&rdquo; ch&iacute;nh l&agrave; t&agrave;i liệu đầu ti&ecirc;n bạn n&ecirc;n đọc khi đang nung nấu &yacute; định dấn th&acirc;n v&agrave;o lĩnh vực n&agrave;y!</p>', 2023, NULL, 311, 19, 11, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (105, N'Hiểu Hết Về Khởi Nghiệp - How To Start Your Own Business - Bìa Cứng', N'8935235237810', N'Bìa Cứng', CAST(175825.00 AS Decimal(12, 2)), CAST(330000.00 AS Decimal(12, 2)), CAST(270500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935235237810.jpg', N'DK', N'<p><strong>Hiểu Hết Về Khởi Nghiệp - How To Start Your Own Business - B&igrave;a Cứng</strong></p>
<p>HƯỚNG DẪN ĐƠN GIẢN NHẤT, TRỰC QUAN NHẤT TỪNG C&Oacute; ĐỂ TRỜ TH&Agrave;NH MỘT DOANH NH&Acirc;N KHỞI NGHIỆP.</p>
<p>L&agrave;m thế n&agrave;o để t&igrave;m ra được một khoảng trống thị trường? C&aacute;ch huy động vốn tốt nhất l&agrave; g&igrave;? L&agrave;m thế n&agrave;o để quảng b&aacute; sản phẩm hoặc dịch vụ tr&ecirc;n mạng? V&agrave; l&agrave;m thế n&agrave;o để doanh nghiệp hoạt động bền vững?</p>
<p>Từ c&acirc;n bằng sổ s&aacute;ch cho tới x&acirc;y dựng thương hiệu, từ tự t&igrave;m ra những thị trường mới tới vượt qua một cuộc khủng hoảng, cuốn cẩm nang tuyệt vời n&agrave;y sẽ cho ch&uacute;ng ta biết mọi điều cần thiết để doanh nghiệp của m&igrave;nh trở n&ecirc;n nổi bật... v&agrave; duy tr&igrave; sự c&aacute;ch biệt.</p>
<p>Sử dụng h&igrave;nh ảnh đồ họa dễ hiểu v&agrave; nhưng lời khuy&ecirc;n thấu đ&aacute;o, HIỂU HẾT VỀ KHỞI NGHIỆP &ndash; HOW TO START YOUR OWN BUSINESS sẽ giải ph&oacute;ng tinh thần doanh nh&acirc;n khởi nghiệp trong bạn v&agrave; gi&uacute;p bạn biến &yacute; tưởng tuyệt vời của m&igrave;nh th&agrave;nh một dự &aacute;n kinh doanh th&agrave;nh c&ocirc;ng.</p>', 2023, NULL, 223, 4, 15, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (106, N'Người Giàu Có Nhất Thành Babylon', N'8936065773936', N'Bìa Mềm', CAST(32175.00 AS Decimal(12, 2)), CAST(69000.00 AS Decimal(12, 2)), CAST(49500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8936065773936.jpg', N'Jackie Nguyễn', N'<p><strong>Người Gi&agrave;u C&oacute; Nhất Th&agrave;nh Babylon</strong></p>
<p>Người gi&agrave;u c&oacute; nhất th&agrave;nh Babylon l&agrave; cuốn s&aacute;ch kinh điển về quản l&yacute; t&agrave;i ch&iacute;nh, đầu tư v&agrave; l&agrave;m gi&agrave;u dựa tr&ecirc;n những nguy&ecirc;n tắc vượt thời gian. Lấy bối cảnh vương quốc Babylon cổ đại &ndash; nơi được coi l&agrave; c&aacute;i n&ocirc;i của c&aacute;c nguy&ecirc;n tắc t&agrave;i ch&iacute;nh vững chắc &ndash; cuốn s&aacute;ch mang đến những b&agrave;i học qu&yacute; gi&aacute; gi&uacute;p bạn l&agrave;m chủ tiền bạc v&agrave; hướng tới một cuộc sống thịnh vượng.</p>
<p>Th&ocirc;ng qua những c&acirc;u chuyện ngắn gọn nhưng s&acirc;u sắc, cuốn s&aacute;ch chia sẻ c&aacute;c b&iacute; quyết quản l&yacute; t&agrave;i ch&iacute;nh đ&atilde; được kiểm chứng qua nhiều thế hệ. Độc giả sẽ học được c&aacute;ch tho&aacute;t khỏi t&igrave;nh trạng "t&uacute;i tiền l&eacute;p kẹp" v&agrave; x&acirc;y dựng một tương lai sung t&uacute;c, bền vững. Từ nguy&ecirc;n tắc tiết kiệm, đầu tư th&ocirc;ng minh cho đến c&aacute;ch ph&ograve;ng tr&aacute;nh rủi ro t&agrave;i ch&iacute;nh, c&aacute;c b&agrave;i học trong cuốn s&aacute;ch đều mang t&iacute;nh ứng dụng cao v&agrave; ph&ugrave; hợp với mọi đối tượng, đặc biệt l&agrave; những người đang t&igrave;m kiếm sự ổn định về t&agrave;i ch&iacute;nh.</p>
<p>D&ugrave; được viết từ gần một thế kỷ trước, những triết l&yacute; trong Người gi&agrave;u c&oacute; nhất th&agrave;nh Babylon vẫn giữ nguy&ecirc;n gi&aacute; trị v&agrave; tiếp tục truyền cảm hứng cho h&agrave;ng triệu người tr&ecirc;n thế giới trong h&agrave;nh tr&igrave;nh chinh phục sự gi&agrave;u c&oacute;. Đ&acirc;y ch&iacute;nh l&agrave; cuốn s&aacute;ch kh&ocirc;ng thể thiếu đối với bất kỳ ai mong muốn x&acirc;y dựng nền tảng t&agrave;i ch&iacute;nh vững chắc v&agrave; ph&aacute;t triển bản th&acirc;n một c&aacute;ch to&agrave;n diện.</p>', 2024, NULL, 120, 12, 2, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (107, N'Cẩm Nang Mở Nhà Hàng', N'8935251411171', N'Bìa Mềm', CAST(109850.00 AS Decimal(12, 2)), CAST(199000.00 AS Decimal(12, 2)), CAST(169000.00 AS Decimal(12, 2)), N'https://res.cloudinary.com/dabxzdaf8/image/upload/v1748969691/Book_cover/hn0vl4h3xgr2h8kmg2sc.webp', N'Roger Fields', N'<p><strong>Cẩm nang mở nh&agrave; h&agrave;ng</strong>&nbsp;như một cuốn hướng dẫn khởi nghiệp cung cấp cho những chủ nh&agrave; h&agrave;ng tương lai c&aacute;ch l&ecirc;n kế hoạch để mở một nh&agrave; h&agrave;ng của ri&ecirc;ng m&igrave;nh, từ kinh ph&iacute;, địa điểm, thiết kế kh&ocirc;ng gian, x&acirc;y dựng thực đơn, marketing quảng b&aacute;, quản l&yacute; t&agrave;i ch&iacute;nh... &nbsp;Kh&ocirc;ng chỉ vậy, cuốn s&aacute;ch c&ograve;n chia sẻ những b&iacute; quyết th&agrave;nh c&ocirc;ng gi&uacute;p bạn ch&egrave;o l&aacute;i nh&agrave; h&agrave;ng vượt qua năm đầu ti&ecirc;n đầy s&oacute;ng gi&oacute; v&agrave; l&agrave;m ăn ph&aacute;t đạt trong nhiều năm với một lượng kh&aacute;ch h&agrave;ng trung th&agrave;nh.</p>
<p>Mở nh&agrave; h&agrave;ng kh&ocirc;ng phải việc dễ d&agrave;ng, nhưng những hướng dẫn của t&aacute;c giả - một anh ch&agrave;ng kế to&aacute;n, chủ nh&agrave; h&agrave;ng v&agrave; nh&agrave; tư vấn nh&agrave; h&agrave;ng đầy mơ mộng &ndash; sẽ gi&uacute;p biến giấc mơ mở nh&agrave; h&agrave;ng của bạn th&agrave;nh hiện thực.</p>
<p>&ldquo;Sau nhiều năm l&agrave;m việc, t&ocirc;i nghĩ rằng m&igrave;nh đ&atilde; biết tất cả mọi thứ, nhưng khi l&agrave;m việc với Roger, t&ocirc;i nhận ra c&ograve;n qu&aacute; nhiều điều m&igrave;nh cần học hỏi. Cẩm nang mở nh&agrave; h&agrave;ng chứa đựng b&iacute; quyết gi&uacute;p bạn mở v&agrave; điều h&agrave;nh một nh&agrave; h&agrave;ng l&agrave;m ăn ph&aacute;t đạt. Nếu bạn muốn th&agrave;nh c&ocirc;ng trong kinh doanh nh&agrave; h&agrave;ng, h&atilde;y đọc n&oacute;!&rdquo;<br>- GR&Eacute;GOIRE JACQUET, bếp trưởng ki&ecirc;m chủ nh&agrave; h&agrave;ng Gr&eacute;goire</p>', 2020, NULL, 420, 3, 2, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (108, N'Nhà Đầu Tư Thông Minh (Tái Bản 2020)', N'8935235226470', N'Bìa Mềm', CAST(105950.00 AS Decimal(12, 2)), CAST(199000.00 AS Decimal(12, 2)), CAST(163000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_195509_1_44030.jpg', N'Benjamin Graham', N'<p><strong>T&aacute;c Phẩm Kinh Điển Về Tư Vấn Đầu Tư</strong></p>
<p>L&agrave; nh&agrave; tư vấn&nbsp;đầu tư&nbsp;vĩ đại nhất của thế kỷ 20, Benjamin Graham đ&atilde; giảng dạy v&agrave; truyền cảm hứng cho nhiều người tr&ecirc;n khắp thế giới.&nbsp;Triết l&yacute; &ldquo;đầu tư theo gi&aacute; trị&ldquo; của Graham, bảo vệ nh&agrave; đầu tư khỏi những sai lầm lớn&nbsp;v&agrave; dạy anh ta ph&aacute;t triển c&aacute;c chiến lược d&agrave;i hạn, đ&atilde; khiến&nbsp;<em>Nh&agrave; đầu tư th&ocirc;ng minh</em><em>&nbsp;</em>trở th&agrave;nh cẩm nang của thị trường chứng kho&aacute;n kể từ lần xuất bản đầu ti&ecirc;n v&agrave;o năm 1949.</p>
<p>Trải qua năm th&aacute;ng, diễn biến thị trường đ&atilde; chứng minh t&iacute;nh s&aacute;ng suốt trong c&aacute;c chiến lược của Graham. Trong khi vẫn giữ lại to&agrave;n vẹn văn bản ban đầu của Graham, ấn phẩm t&aacute;i bản n&agrave;y bổ sung th&ecirc;m b&igrave;nh luận cập nhật của k&yacute; giả chuy&ecirc;n về t&agrave;i ch&iacute;nh nổi tiếng Jason Zweig. C&aacute;i nh&igrave;n của Zweig bao qu&aacute;t hiện thực của thị trường ng&agrave;y nay, vạch ra sự tương tự giữa những v&iacute; dụ của Graham v&agrave; c&aacute;c t&iacute;t b&aacute;o về t&agrave;i ch&iacute;nh hiện nay, gi&uacute;p bạn đọc c&oacute; sự hiểu biết kỹ lưỡng hơn về c&aacute;ch thức &aacute;p dụng c&aacute;c nguy&ecirc;n tắc của Graham.</p>
<p>Sống động v&agrave; cần thiết,&nbsp;<em>Nh&agrave; đầu tư th&ocirc;ng minh&nbsp;</em>l&agrave; cuốn s&aacute;ch quan trọng nhất m&agrave; bạn c&oacute; dịp đọc về c&aacute;ch thức đạt được c&aacute;c mục ti&ecirc;u t&agrave;i ch&iacute;nh của m&igrave;nh.</p>', 2020, NULL, 644, 9, 14, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (110, N'Chén Thánh Trong Đầu Tư', N'8936230471667', N'Bìa Mềm', CAST(114400.00 AS Decimal(12, 2)), CAST(229000.00 AS Decimal(12, 2)), CAST(176000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/c/h/chen-thanh-trong-dau-tu---converted_1.jpg', N'Tony Robbins, Christopher Zook', N'<p><strong>Ch&eacute;n Th&aacute;nh Trong Đầu Tư</strong></p>
<p>&ldquo;Ch&eacute;n Th&aacute;nh Trong Đầu Tư&rdquo; l&agrave; một t&aacute;c phẩm độc đ&aacute;o, kết tinh từ hơn 50 cuộc phỏng vấn chuy&ecirc;n s&acirc;u với những bộ &oacute;c t&agrave;i ch&iacute;nh vĩ đại nhất thế giới, được thực hiện bởi Tony Robbins &ndash; t&aacute;c giả bestseller của New York Times &ndash; v&agrave; Christopher Zook, một nh&agrave; đầu tư d&agrave;y dạn kinh nghiệm. Kh&ocirc;ng chỉ đơn thuần l&agrave; cuốn s&aacute;ch về c&aacute;c c&ocirc;ng cụ t&agrave;i ch&iacute;nh, t&aacute;c phẩm n&agrave;y cung cấp một hệ thống tư duy, chiến lược to&agrave;n diện để tiếp cận đầu tư một c&aacute;ch bền vững v&agrave; hiệu quả trong bối cảnh thị trường biến động kh&ocirc;ng ngừng.</p>
<p>Kh&aacute;c biệt lớn nhất của &ldquo;Ch&eacute;n Th&aacute;nh Trong Đầu Tư&rdquo; nằm ở g&oacute;c nh&igrave;n tổng hợp từ những nh&agrave; đầu tư h&agrave;ng đầu, trải d&agrave;i nhiều lĩnh vực: cổ phiếu, tr&aacute;i phiếu, bất động sản, vốn mạo hiểm, c&ocirc;ng nghệ đột ph&aacute;, năng lượng, c&aacute;c t&agrave;i sản thay thế&hellip; Mỗi chương s&aacute;ch kh&ocirc;ng chỉ dừng lại ở việc m&ocirc; tả một loại h&igrave;nh đầu tư, m&agrave; c&ograve;n ph&acirc;n t&iacute;ch s&acirc;u c&aacute;ch thức c&aacute;c nh&agrave; đầu tư huyền thoại ứng dụng kiến thức, quản trị rủi ro v&agrave; tối ưu h&oacute;a lợi nhuận trong thực tế.</p>
<p>Một trong những gi&aacute; trị nổi bật của cuốn s&aacute;ch l&agrave; khả năng lật mở những nguy&ecirc;n tắc &iacute;t được tiết lộ &ndash; những c&ocirc;ng thức th&agrave;nh c&ocirc;ng được chia sẻ trực tiếp từ những người đ&atilde; từng đứng vững qua khủng hoảng t&agrave;i ch&iacute;nh to&agrave;n cầu, chứng kiến sự thay đổi li&ecirc;n tục của nền kinh tế, nhưng vẫn duy tr&igrave; được th&agrave;nh quả vượt trội. Những chiến lược n&agrave;y kh&ocirc;ng chỉ mang t&iacute;nh học thuật m&agrave; đ&atilde; được kiểm chứng qua thời gian, qua c&aacute;c biến động lớn của thị trường.</p>
<p>Kh&ocirc;ng chỉ cung cấp chiến lược đầu tư, &ldquo;Ch&eacute;n Th&aacute;nh Trong Đầu Tư&rdquo; c&ograve;n gi&uacute;p người đọc hiểu được tư duy của người th&agrave;nh c&ocirc;ng trong lĩnh vực t&agrave;i ch&iacute;nh: c&aacute;ch nh&igrave;n nhận rủi ro, c&aacute;ch quản trị cảm x&uacute;c, c&aacute;ch đưa ra quyết định trong những thời điểm then chốt. Đ&acirc;y ch&iacute;nh l&agrave; nền tảng gi&uacute;p người đọc x&acirc;y dựng một danh mục đầu tư đa dạng, c&acirc;n bằng giữa tăng trưởng v&agrave; an to&agrave;n, giữa mạo hiểm v&agrave; kiểm so&aacute;t.</p>
<p>T&aacute;c phẩm cũng mang t&iacute;nh ứng dụng cao nhờ hệ thống h&oacute;a kiến thức một c&aacute;ch dễ hiểu, logic, ph&ugrave; hợp cả với nh&agrave; đầu tư mới lẫn nh&agrave; đầu tư đ&atilde; c&oacute; kinh nghiệm. Kh&ocirc;ng hứa hẹn những giải ph&aacute;p l&agrave;m gi&agrave;u nhanh ch&oacute;ng, cuốn s&aacute;ch đặt trọng t&acirc;m v&agrave;o chiến lược d&agrave;i hạn, bền vững, gi&uacute;p người đọc tự tin hơn trong việc quản l&yacute; t&agrave;i ch&iacute;nh, x&acirc;y dựng t&agrave;i sản v&agrave; hướng đến tự do t&agrave;i ch&iacute;nh.</p>', 2025, NULL, 437, 7, 8, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (111, N'Tâm Lý Hành Vi Trong Đầu Tư Chứng Khoán', N'8936066691062', N'Bìa Mềm', CAST(67177.50 AS Decimal(12, 2)), CAST(159000.00 AS Decimal(12, 2)), CAST(103350.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_234386.jpg', N'James Montier', N'<p>Ben Graham, được coi l&agrave; người khai sinh ra trường ph&aacute;i đầu tư gi&aacute; trị đ&atilde; từng n&oacute;i: Vấn đề ch&iacute;nh &ndash; thậm ch&iacute; l&agrave; kẻ th&ugrave; lớn nhất &ndash; m&agrave; c&aacute;c nh&agrave; đầu tư phải đối mặt c&oacute; lẽ ch&iacute;nh l&agrave; bản th&acirc;n mỗi người. Đ&aacute;ng buồn thay, nhận định của Graham vẫn đ&uacute;ng trong bối cảnh ng&agrave;y nay. Thi&ecirc;n kiến, cảm x&uacute;c, tự tin th&aacute;i qu&aacute; v&agrave; lạc quan qu&aacute; mức chỉ l&agrave; một số trong rất nhiều xu hướng h&agrave;nh vi c&oacute; thể khiến c&aacute;c nh&agrave; đầu tư mất tiền. Điều may mắn l&agrave; t&agrave;i ch&iacute;nh h&agrave;nh vi ra đời v&agrave; thừa nhận thực tế tồn tại yếu tố t&acirc;m l&yacute; trong qu&aacute; tr&igrave;nh ra quyết định của tất cả c&aacute;c nh&agrave; đầu tư. &Aacute;p dụng c&aacute;c quy tắc h&agrave;nh vi v&agrave;o đầu tư v&agrave; giao dịch gi&uacute;p nh&agrave; đầu tư tr&aacute;nh được một số bẫy t&acirc;m l&yacute; nghi&ecirc;m trọng c&oacute; thể khiến họ phải trả c&aacute;i gi&aacute; rất đắt.</p>
<p>Trong cuốn s&aacute;ch n&agrave;y, chuy&ecirc;n gia về t&agrave;i ch&iacute;nh h&agrave;nh vi James Montier nhấn mạnh những xu hướng h&agrave;nh vi nguy hiểm v&agrave; những sai lầm t&acirc;m l&yacute; phổ biến m&agrave; c&aacute;c nh&agrave; đầu tư chuy&ecirc;n nghiệp gặp phải. T&aacute;c giả cũng chỉ cho ch&uacute;ng ta c&aacute;ch để nhận ra c&aacute;c bẫy t&acirc;m tr&iacute; n&agrave;y đồng thời t&igrave;m ra những nguy&ecirc;n l&yacute; của t&acirc;m l&yacute; học ẩn s&acirc;u trong c&aacute;c sai lầm đ&oacute;. B&ecirc;n cạnh đ&oacute;, Montier cũng chỉ cho bạn những g&igrave; bạn c&oacute; thể l&agrave;m để bảo vệ danh mục đầu tư v&agrave; đảm bảo lợi nhuận. Trong cuốn s&aacute;ch n&agrave;y, ch&uacute;ng ta cũng sẽ c&ugrave;ng nhau quan s&aacute;t c&aacute;ch một số nh&agrave; đầu tư bậc nhất tr&ecirc;n thế giới &aacute;p dụng để ph&aacute;t triển c&aacute;c quy tr&igrave;nh đầu tư c&oacute; thể giảm thiểu tối đa sai lầm trong h&agrave;nh vi của họ.</p>
<p>Theo từng trang s&aacute;ch, Montier giải th&iacute;ch về tầm quan trọng của việc học c&aacute;ch chuẩn bị, lập kế hoạch, v&agrave; tiếp theo l&agrave; cam kết với một chiến lược. Cụ thể, bạn sẽ thực hiện c&aacute;c ph&acirc;n t&iacute;ch đầu tư trong trạng th&aacute;i l&yacute; t&iacute;nh v&agrave; tỉnh t&aacute;o khi m&agrave; thị trường kh&ocirc;ng c&oacute; qu&aacute; nhiều biến động, v&agrave; tiếp đ&oacute; cam kết trước để tu&acirc;n theo những ph&acirc;n t&iacute;ch v&agrave; c&aacute;c bước h&agrave;nh động đ&atilde; vạch ra. &Ocirc;ng cũng nhấn mạnh sự đi&ecirc;n rồ khi cố gắng dự b&aacute;o diễn biến của thị trường trong tương lai v&agrave; chỉ ra sự kh&aacute;c biệt khi tiếp cận đầu tư m&agrave; kh&ocirc;ng cần giả định ch&uacute;ng ta biết những g&igrave; sẽ xảy ra trong tương lai. Xuy&ecirc;n suốt cuốn s&aacute;ch, Montier nhấn mạnh l&yacute; do tại sao việc cần phải tập trung v&agrave;o qu&aacute; tr&igrave;nh hơn kết quả l&agrave; điều quan trọng trong đầu tư. Tập trung v&agrave;o qu&aacute; tr&igrave;nh, Montier cho thấy sự giải ph&oacute;ng khỏi lo lắng đối với những kh&iacute;a cạnh đầu tư m&agrave; ch&uacute;ng ta thực tế kh&ocirc;ng thể kiểm so&aacute;t, như lợi tức. Bắng c&aacute;ch tập trung v&agrave;o qu&aacute; tr&igrave;nh, ch&uacute;ng ta c&oacute; thể tối đa h&oacute;a tiềm năng tạo lợi nhuận d&agrave;i hạn tốt nhất.</p>', 2021, NULL, 300, 8, 6, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (112, N'Đầu Tư Chứng Khoán: Chơi Trò May Rủi Hay Tích Lũy Tài Chính - Tặng Kèm Code Giảm 50% Khóa Học Online', N'9786043900583', N'Bìa Mềm', CAST(140400.00 AS Decimal(12, 2)), CAST(300000.00 AS Decimal(12, 2)), CAST(216000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786043900583.jpg', N'Lâm Minh Chánh', N'<p>Cuốn s&aacute;ch &ldquo;Đầu tư chứng kho&aacute;n: Chơi tr&ograve; may rủi hay t&iacute;ch lũy t&agrave;i ch&iacute;nh?&rdquo; gi&uacute;p cho độc giả hiểu r&otilde; những kiến thức cơ bản về đầu tư: c&aacute;ch t&iacute;nh tỷ suất lợi nhuận, những rủi ro trong đầu tư chứng kho&aacute;n, c&aacute;c c&ocirc;ng cụ đầu tư, sự kh&aacute;c nhau giữa gi&aacute; v&agrave; gi&aacute; trị, c&aacute;c chiến lược đầu tư, v&agrave; đặc biệt l&agrave; sự kh&aacute;c biệt giữa đầu tư may rủi v&agrave; đầu tư c&oacute; phương ph&aacute;p để t&iacute;ch lũy t&agrave;i ch&iacute;nh.</p>
<p dir="">T&aacute;c giả L&acirc;m Minh Ch&aacute;nh l&agrave; chuy&ecirc;n gia h&agrave;ng đầu về t&agrave;i ch&iacute;nh c&aacute; nh&acirc;n v&agrave; đầu tư. Anh cũng l&agrave; t&aacute;c giả cuốn s&aacute;ch được nhiều người t&igrave;m đọc, tựa đề &ldquo;T&agrave;i ch&iacute;nh c&aacute; nh&acirc;n d&agrave;nh cho người Việt Nam&rdquo; với 50,000 bản đ&atilde; ph&aacute;t h&agrave;nh.</p>
<p dir="">Với phong c&aacute;ch diễn đạt đơn giản, mộc mạc, những v&iacute; dụ thực tế, những minh họa dễ hiểu, t&aacute;c giả L&acirc;m Minh Ch&aacute;nh &ndash; với biệt danh Ch&uacute; Ba T&agrave;i ch&iacute;nh LMC, sẽ gi&uacute;p bất kỳ ai đọc s&aacute;ch cũng hiểu được những vấn đề tưởng như rất kh&oacute; hiểu như:</p>
<p dir="">- Những nguy&ecirc;n tắc quan trọng trong đầu tư.</p>
<p dir="">- Chứng kho&aacute;n, thị trường chứng kho&aacute;n, đầu tư chứng kho&aacute;n.</p>
<p dir="">- Doanh nghiệp v&agrave; Cổ phiếu.</p>
<p dir="">- Những yếu tố quyết định đến Gi&aacute; trị nội tại v&agrave; Gi&aacute; cổ phiếu.</p>
<p dir="">- Sự kh&aacute;c nhau giữa đầu tư may rủi v&agrave; đầu tư c&oacute; phương ph&aacute;p</p>
<p dir="">- 10 phương ph&aacute;p đầu tư cổ phiếu tr&ecirc;n s&agrave;n</p>
<p dir="">- Phương ph&aacute;p đầu tư nhằm t&iacute;ch lũy t&agrave;i ch&iacute;nh v&agrave; đạt độc lập hay tự do t&agrave;i ch&iacute;nh trong tương lai.</p>', 2022, NULL, 406, 8, 9, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (113, N'Để Không Mất Tiền Tỷ Trong Lần Đầu Mua Nhà, Xây Nhà', N'9786048480226', N'Bìa Mềm', CAST(182325.00 AS Decimal(12, 2)), CAST(390000.00 AS Decimal(12, 2)), CAST(280500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786048480226.jpg', N'Lê Quốc Kiên', N'<p><strong>Để Kh&ocirc;ng Mất Tiền Tỷ Trong Lần Đầu Mua Nh&agrave;, X&acirc;y Nh&agrave;</strong></p>
<p>&ldquo;Để kh&ocirc;ng mất tiền tỷ trong lần đầu Mua nh&agrave;, X&acirc;y nh&agrave;, Đầu tư Bất động sản&rdquo; l&agrave; bộ s&aacute;ch đầu ti&ecirc;n hướng đến việc gi&uacute;p độc giả tr&aacute;nh mất tiền trong việc Mua nh&agrave;, X&acirc;y nh&agrave;, đầu tư bất động sản, thay v&igrave; chỉ tập trung n&oacute;i về c&aacute;ch kiếm tiền v&agrave; lờ đi c&aacute;c rủi ro. B&ecirc;n cạnh đ&oacute;, bộ s&aacute;ch cũng như người cố vấn đ&aacute;ng tin cậy, gi&uacute;p độc giả c&oacute; kế hoạch chuẩn bị tốt hơn từ sớm để Mua nh&agrave;, c&oacute; thể tự kiểm so&aacute;t việc X&acirc;y nh&agrave;, biết cần phải l&agrave;m những g&igrave; để c&oacute; một quyết định Đầu Tư hiệu quả nhất. Qua đ&oacute;, độc giả sẽ gần hơn với con đường Sở hữu Nh&agrave; để an cư, X&acirc;y Nh&agrave; để cải thiện m&ocirc;i trường sống tốt hơn, cũng như tăng cơ hội Kiếm Tiền khi đầu tư.</p>
<p>Bộ s&aacute;ch gồm 2 cuốn:</p>
<p>Cuốn 1 : &ldquo;Để kh&ocirc;ng mất tiền tỷ trong lần đầu mua nh&agrave;, x&acirc;y nh&agrave;&rdquo;.</p>
<p>Cuốn s&aacute;ch d&agrave;nh cho người lần đầu mua nh&agrave;, x&acirc;y nh&agrave;. Gi&uacute;p qu&yacute; độc giả biết: Khi MUA căn nh&agrave; đầu ti&ecirc;n cần c&oacute; kế hoạch chuẩn bị t&agrave;i ch&iacute;nh thế n&agrave;o, định gi&aacute; nh&agrave; ra sao, cần lưu &yacute; những g&igrave; để tr&aacute;nh &ldquo;tiền mất tật mang&rdquo;; Khi X&Acirc;Y căn nh&agrave; mơ ước cần phải chuẩn bị những g&igrave;, lựa chọn thầu ra sao, n&ecirc;n bố tr&iacute; nh&agrave; như thế n&agrave;o, cần bao nhi&ecirc;u tiền, l&agrave;m qua c&aacute;c bước n&agrave;o, c&oacute; những sai lầm mất tiền n&agrave;o đang chờ đ&oacute;n m&igrave;nh kh&ocirc;ng.</p>
<p>Cuốn 2 : &ldquo;Để kh&ocirc;ng mất bạc tỷ trong lần đầu kiếm tiền từ bất động sản&rdquo;.</p>
<p>Cuốn s&aacute;ch d&agrave;nh cho người lần đầu đầu tư bất động sản, muốn khai th&aacute;c d&ograve;ng tiền tr&ecirc;n ch&iacute;nh bất động sản. Gi&uacute;p qu&yacute; độc giả biết n&ecirc;n bắt đầu từ đ&acirc;u, t&iacute;nh b&agrave;i to&aacute;n t&agrave;i ch&iacute;nh thế n&agrave;o, triển khai ra sao để đạt hiệu quả tốt nhất, cần tr&aacute;nh những cạm bẫy rủi ro n&agrave;o đang chờ đ&oacute;n m&igrave;nh.</p>', 2025, NULL, 372, 18, 3, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (114, N'Tâm Lý Thị Trường Chứng Khoán - Hành Vi Đám Đông Và Sự Thật Đằng Sau Những Con Sóng (Tái Bản 2023)', N'9786043461435', N'Bìa Mềm', CAST(26650.00 AS Decimal(12, 2)), CAST(50000.00 AS Decimal(12, 2)), CAST(41000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786043461435.jpg', N'George Charles Selden', N'<p>Isaac Newton từng n&oacute;i: &ldquo;T&ocirc;i c&oacute; thể t&iacute;nh to&aacute;n được sự chuyển động của c&aacute;c h&agrave;nh tinh tr&ecirc;n trời, nhưng kh&ocirc;ng thể t&iacute;nh to&aacute;n được sự đi&ecirc;n rồ của con người.&rdquo; Tuy l&agrave; một thi&ecirc;n t&agrave;i về to&aacute;n học v&agrave; vật l&yacute;, Newton vẫn thất bại khi tham gia đầu tư cổ phiếu South Sea, bị con s&oacute;ng t&acirc;m l&yacute; d&igrave;m xuống đ&aacute;y s&acirc;u thua lỗ.<br><br>Sự thật l&agrave;, thị trường chứng kho&aacute;n lu&ocirc;n chịu ảnh hưởng bởi c&aacute;c nh&acirc;n tố t&acirc;m l&yacute;, đặc biệt l&agrave; trong những dao động ngắn hạn. Bằng c&aacute;ch ph&acirc;n t&iacute;ch dựa tr&ecirc;n nền tảng t&acirc;m l&yacute; đ&aacute;m đ&ocirc;ng trong c&aacute;c con s&oacute;ng đầu cơ, George Charles Selden đ&atilde; đặt nền m&oacute;ng cho nhiều c&ocirc;ng cụ ph&acirc;n t&iacute;ch kỹ thuật về sau.<br><br>Qua quyển s&aacute;ch n&agrave;y, bạn sẽ nắm r&otilde; sự h&igrave;nh th&agrave;nh v&agrave; ph&aacute;t triển của c&aacute;c chu kỳ đầu cơ, về những vụ hoảng loạn v&agrave; b&ugrave;ng nổ, cũng như về động cơ đẩy gi&aacute; hay đạp gi&aacute; của những con c&aacute; mập trong từng đợt s&oacute;ng.<br><br>Để c&oacute; thể tham lam khi đ&aacute;m đ&ocirc;ng sợ h&atilde;i v&agrave; sợ h&atilde;i khi đ&aacute;m đ&ocirc;ng tham lam, kh&ocirc;ng c&ograve;n c&aacute;ch n&agrave;o kh&aacute;c, ta buộc phải thấu hiểu cấu tr&uacute;c từng con s&oacute;ng v&agrave; t&acirc;m l&yacute; đ&aacute;m đ&ocirc;ng ẩn b&ecirc;n dưới con s&oacute;ng ấy.</p>', 2023, NULL, 104, 6, 10, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (115, N'Chiến Lược Đầu Tư Vàng Sinh Lời', N'8935325027673', N'Bìa Mềm', CAST(54275.00 AS Decimal(12, 2)), CAST(109000.00 AS Decimal(12, 2)), CAST(83500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/b/i/bia_11.jpg', N'Lưu Đường Hâm', N'<p><strong>Chiến Lược Đầu Tư V&agrave;ng Sinh Lời</strong></p>
<p><em>Chiến Lược Đầu Tư V&agrave;ng Sinh Lời &ndash; Cuốn s&aacute;ch đ&aacute;ng đọc nhất trong thời kỳ kinh tế bất ổn</em></p>
<p>2024 - 2025: V&agrave;ng tăng gi&aacute; kỷ lục, nh&agrave; nh&agrave; đổ x&ocirc; t&iacute;ch trữ. Ai cũng mong muốn &ldquo;mua đ&aacute;y &ndash; b&aacute;n đỉnh&rdquo;, nhưng kh&ocirc;ng &iacute;t người lại rơi v&agrave;o cảnh &ldquo;đu đỉnh &ndash; b&aacute;n th&aacute;o&rdquo;.</p>
<p>Giữa bối cảnh bất ổn kinh tế v&agrave; địa ch&iacute;nh trị to&agrave;n cầu, thị trường v&agrave;ng đang bước v&agrave;o giai đoạn biến động mạnh chưa từng thấy. Gi&aacute; c&oacute; thể tăng đột biến, nhưng cũng c&oacute; thể đảo chiều chỉ trong v&agrave;i phi&ecirc;n. Nếu kh&ocirc;ng c&oacute; chiến lược r&otilde; r&agrave;ng, bạn kh&ocirc;ng chỉ kh&ocirc;ng lời, m&agrave; c&ograve;n hao hụt t&agrave;i ch&iacute;nh c&aacute; nh&acirc;n một c&aacute;ch nguy hiểm.</p>
<p>Vậy, l&agrave;m sao để đầu tư v&agrave;ng th&ocirc;ng minh &ndash; sinh lời &ndash; an to&agrave;n? Cuốn s&aacute;ch &ldquo;Chiến lược đầu tư v&agrave;ng sinh lời&rdquo; của Lưu Đường H&acirc;m &ndash; chuy&ecirc;n gia đầu tư kim loại qu&yacute; h&agrave;ng đầu Trung Quốc &ndash; ch&iacute;nh l&agrave; kim chỉ nam thực chiến bạn cần!</p>', 2025, NULL, 208, 1, 12, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (116, N'Hành Trình Gọi Vốn - 7 Bước Chinh Phục Nhà Đầu Tư', N'8935278607106', N'Bìa Mềm', CAST(90025.00 AS Decimal(12, 2)), CAST(180000.00 AS Decimal(12, 2)), CAST(138500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935278607106.jpg', N'Carlye Adler, Suneel Gupta', N'<p><strong>H&agrave;nh Tr&igrave;nh Gọi Vốn - 7 Bước Chinh Phục Nh&agrave; Đầu Tư</strong></p>
<p><em><strong>Thuyết phục c&aacute;c nh&agrave; đầu tư, dễ hay kh&oacute;?</strong></em></p>
<p>C&acirc;u chuyện khởi nghiệp v&agrave; gọi vốn đang dần trở n&ecirc;n quen thuộc trong nền kinh tế hiện đại. Nhưng c&aacute;c nh&agrave; khởi nghiệp cần phải l&agrave;m g&igrave; để c&oacute; thể thuyết phục được c&aacute;c nh&agrave; đầu tư vẫn l&agrave; một c&acirc;u hỏi kh&oacute;.</p>
<p>Họ thường phải chuẩn bị tất cả mọi thứ, từ t&igrave;m kiếm một &yacute; tưởng đột ph&aacute;, đ&aacute;nh gi&aacute; tiềm năng thị trường đến đưa ra dự đo&aacute;n về lợi nhuận, nhưng c&oacute; khi lời đề nghị nhận đầu tư của họ bị từ chối chỉ v&igrave; phần tr&igrave;nh b&agrave;y thiếu thuyết phục.</p>
<p>Thật sự m&agrave; n&oacute;i th&igrave; tất cả ch&uacute;ng ta đều c&oacute; những khoảnh khắc m&agrave; t&ocirc;i gọi l&agrave; khoảnh khắc khi &yacute; tưởng trong đầu bạn c&oacute; vẻ rất hấp dẫn nhưng đến l&uacute;c n&oacute;i ra th&igrave; n&oacute; nghe thật nhạt nhẽo. Cảm gi&aacute;c n&agrave;y giống như bạn cố gắng nh&eacute;t tờ một đ&ocirc; la nh&agrave;u nhĩ v&agrave;o m&aacute;y b&aacute;n h&agrave;ng tự động nhưng n&oacute; kh&ocirc;ng nhận vậy.</p>
<p>X&eacute;t về mặt gi&aacute; trị, tờ một đ&ocirc; la nhăn nh&uacute;m của bạn cũng tương đương với tờ một đ&ocirc; la mới tinh. Ch&uacute;ng ta cũng kh&ocirc;ng thiếu những tố chất để trở th&agrave;nh người khả t&iacute;n. Ch&uacute;ng ta chỉ cần điều chỉnh phong c&aacute;ch của m&igrave;nh một ch&uacute;t, đủ để kh&ocirc;ng mất đi thế mạnh ri&ecirc;ng cũng như bản sắc c&aacute; nh&acirc;n của mỗi ch&uacute;ng ta.</p>', 2023, NULL, 300, 18, 6, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (117, N'Cổ Phiếu Thường Lợi Nhuận Phi Thường (Tái Bản)', N'8935251408171', N'Bìa Mềm', CAST(109850.00 AS Decimal(12, 2)), CAST(199000.00 AS Decimal(12, 2)), CAST(169000.00 AS Decimal(12, 2)), N'https://res.cloudinary.com/dabxzdaf8/image/upload/v1748969983/Book_cover/lvwqa1i2pgq4ymgujrpz.jpg', N'Philip A. Fisher', N'<p><strong>Cổ Phiếu Thường Lợi Nhuận Phi Thường (T&aacute;i Bản)</strong></p>
<p>Philip Fisher l&agrave; một trong số c&aacute;c nh&agrave; đầu tư c&oacute; ảnh hưởng lớn nhất mọi thời đại. Triết l&yacute; đầu tư của &ocirc;ng kh&ocirc;ng chỉ được nhiều chuy&ecirc;n gia hiện đại nghi&ecirc;n cứu v&agrave; &aacute;p dụng m&agrave; c&ograve;n được rất nhiều nh&agrave; đầu tư coi đ&oacute; l&agrave; cẩm nang dẫn đường cho bản th&acirc;n. Những triết l&yacute; n&agrave;y đ&atilde; được tập hợp trong cuốn s&aacute;ch nổi tiếng của &ocirc;ng - Cổ phiếu thường, Lợi nhuận phi thường (Common Stocks and Uncommon Profits), một trong những gi&aacute;o tr&igrave;nh đầu tư kinh điển d&agrave;nh cho c&aacute;c nh&agrave; đầu tư hiện đại.</p>
<p>Cuốn s&aacute;ch sẽ mang lại cho bạn một c&aacute;i nh&igrave;n to&agrave;n diện, từ những vấn đề hết sức cụ thể như sức mạnh của &ldquo;lời đồn đại&rdquo;, n&ecirc;n mua g&igrave;, khi n&agrave;o, những điều nh&agrave; đầu tư cần tr&aacute;nh, c&aacute;ch t&igrave;m ra một cổ phiếu tiềm năng&hellip; cho đến phương ph&aacute;p h&igrave;nh th&agrave;nh một triết l&yacute; đầu tư đem lại hiệu quả cao.</p>
<p>Fisher đ&atilde; chỉ ra rằng c&oacute; hai c&aacute;ch để thu được lợi nhuận đầu tư lớn nhất: thứ nhất l&agrave; mua cổ phiếu khi thị trường đi xuống v&agrave; đợi l&uacute;c thị trường hồi phục; hoặc &aacute;p dụng c&aacute;ch thứ hai &iacute;t rủi ro hơn v&agrave; lợi nhuận tiềm năng lớn hơn, đ&oacute; l&agrave; đầu tư v&agrave;o một số c&ocirc;ng ty đang tăng trưởng li&ecirc;n tục v&agrave; thu lợi nhuận h&agrave;ng năm. Để t&igrave;m được ch&iacute;nh x&aacute;c những c&ocirc;ng ty như vậy, &ocirc;ng cũng đưa ra 15 luận điểm lựa chọn cổ phiếu v&agrave; những th&agrave;nh tố cần c&oacute; cho một khoản đầu tư hiệu quả.</p>
<p>C&oacute; thể n&oacute;i Cổ phiếu thường, Lợi nhuận phi thường sẽ l&agrave;m thay đổi c&aacute;ch nh&igrave;n nhận của bạn về thị trường t&agrave;i ch&iacute;nh, một cuốn s&aacute;ch xứng đ&aacute;ng c&oacute; một vị tr&iacute; trang trọng tr&ecirc;n gi&aacute; s&aacute;ch của c&aacute;c nh&agrave; đầu tư v&agrave; bất cứ ai quan t&acirc;m đến lĩnh vực n&agrave;y.</p>', 2018, NULL, 477, 10, 7, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (118, N'Yêu Những Điều Không Hoàn Hảo', N'8935235243958', N'Bìa Cứng', CAST(131950.00 AS Decimal(12, 2)), CAST(239000.00 AS Decimal(12, 2)), CAST(203000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/z/6/z6462915542820_903ba3eb4055491da26e9c8ed663901b_1.jpg', N'Hae Min', N'<p><strong>Y&ecirc;u Những Điều Kh&ocirc;ng Ho&agrave;n Hảo</strong></p>
<p>&ldquo;Ngẫm lại cuộc sống của ch&iacute;nh m&igrave;nh, ta sẽ nhận thấy rất nhiều điều kh&ocirc;ng ho&agrave;n hảo. Trước hết, chỉ nh&igrave;n v&agrave;o bản th&acirc;n m&igrave;nh th&ocirc;i ta đ&atilde; cảm nhận được nhiều thiếu s&oacute;t rồi: lời n&oacute;i v&agrave; h&agrave;nh động m&acirc;u thuẫn với nhau, vụng về trong những mối quan hệ x&atilde; hội, chuyện học h&agrave;nh, c&ocirc;ng việc kh&ocirc;ng su&ocirc;n sẻ như &yacute; muốn. Chưa kể đ&ocirc;i khi ta c&ograve;n khiến người kh&aacute;c tổn thương, thậm ch&iacute; c&ograve;n l&agrave;m những việc khiến bản th&acirc;n cảm thấy tội lỗi v&agrave; hối hận. V&agrave; khi nh&igrave;n v&agrave;o những người th&acirc;n trong gia đ&igrave;nh, bạn b&egrave;, đồng nghiệp, ta cũng nhận thấy những điều kh&ocirc;ng-ho&agrave;n-hảo tương tự như vậy.</p>
<p>Nhưng d&ugrave; đang sống giữa thế gian đầy rẫy những điều kh&ocirc;ng ho&agrave;n hảo, ta vẫn kh&ocirc;ng thể ngừng y&ecirc;u thương ch&iacute;nh những điều kh&ocirc;ng ho&agrave;n hảo ấy. Cuộc sống rất đ&aacute;ng để tr&acirc;n trọng, ta kh&ocirc;ng thể ph&iacute; ho&agrave;i cuộc sống v&agrave;o việc mỉa mai hay căm gh&eacute;t thứ g&igrave; đ&oacute; chỉ v&igrave; kh&ocirc;ng thể hiểu được n&oacute; hoặc n&oacute; kh&ocirc;ng vừa &yacute; ta.</p>', 2025, NULL, 300, 13, 12, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (119, N'Con Đường Chẳng Mấy Ai Đi - The Road Less Traveled', N'9786044009674', N'Bìa Mềm', CAST(75075.00 AS Decimal(12, 2)), CAST(165000.00 AS Decimal(12, 2)), CAST(115500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786044009674.jpg', N'M. Scott Peck', N'<p><strong>Con Đường Chẳng Mấy Ai Đi</strong></p>
<p>C&oacute; lẽ kh&ocirc;ng quyển s&aacute;ch n&agrave;o trong thế kỷ n&agrave;y c&oacute; t&aacute;c động s&acirc;u sắc đến đời sống tr&iacute; tuệ v&agrave; tinh thần của ch&uacute;ng ta hơn Con Đường Chẳng Mấy Ai Đi. Với doanh số tr&ecirc;n 10 triệu bản in tr&ecirc;n to&agrave;n thế giới v&agrave; được dịch sang hơn 25 ng&ocirc;n ngữ, đ&acirc;y l&agrave; một hiện tượng trong ng&agrave;nh xuất bản, với hơn mười năm nằm trong danh s&aacute;ch Best-sellers của New York Times.</p>
<p>Với c&aacute;ch h&agrave;nh văn kinh điển v&agrave; th&ocirc;ng điệp đầy thấu hiểu, quyển s&aacute;ch Con Đường Chẳng Mấy Ai Đi gi&uacute;p ch&uacute;ng ta kh&aacute;m ph&aacute; bản chất của c&aacute;c mối quan hệ v&agrave; của một tinh thần trưởng th&agrave;nh. Quyển s&aacute;ch gi&uacute;p ch&uacute;ng ta học c&aacute;ch ph&acirc;n biệt sự lệ thuộc với t&igrave;nh y&ecirc;u; l&agrave;m thế n&agrave;o để trở th&agrave;nh những bậc phụ huynh tinh tế v&agrave; nhạy cảm; v&agrave; cuối c&ugrave;ng l&agrave; l&agrave;m thế n&agrave;o để sống ch&acirc;n thật với ch&iacute;nh m&igrave;nh.</p>
<p>Với d&ograve;ng mở đầu bất hủ của quyển s&aacute;ch, "Cuộc đời n&agrave;y rất kh&oacute; sống", thể hiện quan điểm h&agrave;nh tr&igrave;nh ph&aacute;t triển tinh thần l&agrave; một chặng đường d&agrave;i v&agrave; gian nan, Tiến sĩ Peck thể hiện sự đồng cảm, nhẹ nh&agrave;ng dẫn dắt độc giả vượt qua qu&aacute; tr&igrave;nh kh&oacute; khăn đ&oacute;, để thay đổi hướng tới tầm mức thấu hiểu bản th&acirc;n s&acirc;u sắc hơn.</p>', 2024, NULL, 344, 19, 10, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (120, N'38 Bức Thư Rockefeller Viết Cho Con Trai', N'9786044777481', N'Bìa Mềm', CAST(42159.00 AS Decimal(12, 2)), CAST(138000.00 AS Decimal(12, 2)), CAST(64860.00 AS Decimal(12, 2)), N'https://res.cloudinary.com/dabxzdaf8/image/upload/v1748969894/Book_cover/tourtxloh7zurddb94qe.webp', N'Thanh Hương', N'<p><strong>38 Bức Thư Rockefeller Viết Cho Con Trai</strong></p>
<p>38 BỨC THƯ ROCKEFELLER VIẾT CHO CON TRAI - NHỮNG LỜI T&Acirc;M SỰ ĐẶC BIỆT VỚI NHỮNG NGƯỜI TRẺ ĐANG MƠ HỒ TR&Ecirc;N ĐƯỜNG ĐỜI V&Agrave; NHỮNG NGƯỜI ĐANG HƯỚNG ĐẾN MỘT CUỘC ĐỜI HẠNH PH&Uacute;C, THỊNH VƯỢNG.</p>
<p class="text-justify">Giống như cơ thể c&oacute; những nhu cầu về đồ ăn, tinh thần của ch&uacute;ng ta cũng c&oacute; những ham muốn đối với &ldquo;m&oacute;n ăn tinh thần&rdquo;. Thế nhưng c&oacute; rất nhiều người lấy l&yacute; do kh&ocirc;ng c&oacute; thời gian l&agrave;m c&aacute;i cớ để t&acirc;m hồn m&igrave;nh chịu đựng nỗi đau của cơn đ&oacute;i.</p>
<p class="text-justify">C&oacute; lẽ quan điểm của cha hơi bi quan. Ch&uacute;ng ta đang sống trong thời đại m&agrave; mọi người đều thỏa m&atilde;n nhu cầu từ cổ trở xuống m&agrave; kh&ocirc;ng c&oacute; bất kỳ giới hạn n&agrave;o v&agrave; bỏ b&ecirc; những nhu cầu từ cổ trở l&ecirc;n. Tr&ecirc;n thực tế, con thường nghe người ta n&oacute;i bỏ bữa l&agrave; chuyện lớn, nhưng con sẽ kh&ocirc;ng nghe thấy người ta n&oacute;i: Lần cuối c&ugrave;ng cơn đ&oacute;i của t&acirc;m hồn được thỏa m&atilde;n l&agrave; khi n&agrave;o? Lẽ n&agrave;o tất cả ch&uacute;ng ta đều gi&agrave;u c&oacute; về mặt tinh thần? Tất nhi&ecirc;n l&agrave; kh&ocirc;ng.</p>
<p class="text-justify">Trong thế giới ch&uacute;ng ta, đ&acirc;u đ&acirc;u cũng thấy những người thiếu thốn về mặt tinh thần, những người sống trong trầm cảm, ti&ecirc;u cực, thất bại, u sầu đều rất cần sự nu&ocirc;i dưỡng tinh thần v&agrave; tiếng gọi soi dẫn, nhưng hầu như họ đều từ chối những cơ hội l&agrave;m phong ph&uacute; t&acirc;m hồn m&igrave;nh, để mặc cho t&acirc;m hồn trở n&ecirc;n mờ mịt v&agrave; buồn tẻ. Sẽ thật tuyệt nếu một t&acirc;m tr&iacute; trống rỗng c&oacute; thể giống như một c&aacute;i bụng trống rỗng, chỉ cần được lấp đầy bằng thứ g&igrave; đ&oacute; th&igrave; sẽ thỏa m&atilde;n được chủ nh&acirc;n của n&oacute;. Tiếc thay, mọi chuyện kh&ocirc;ng đơn giản như vậy, thay v&agrave;o đ&oacute; con người phải chấp nhận h&igrave;nh phạt cho sự trống rỗng tinh thần.</p>
<p class="text-justify">T&acirc;m hồn l&agrave; ng&ocirc;i nh&agrave; thực sự của mỗi ch&uacute;ng ta, v&agrave; ch&uacute;ng ta sống c&oacute; tốt hay kh&ocirc;ng đều được quyết định bởi sự nu&ocirc;i dưỡng t&acirc;m hồn. Bởi v&igrave; mọi thứ bước v&agrave;o ng&ocirc;i nh&agrave; n&agrave;y đều c&oacute; mục đ&iacute;ch, n&oacute; sẽ tạo ra thứ g&igrave; đ&oacute; để chuẩn bị cho tương lai của con, hoặc n&oacute; sẽ ph&aacute; hủy thứ g&igrave; đ&oacute; v&agrave; l&agrave;m giảm đi những th&agrave;nh tựu c&oacute; thể đạt được trong cuộc sống trong tương lai của con. Mỗi người nằm trong top đầu đạt đến đỉnh cao hoặc sắp đạt đến đỉnh cao đều t&iacute;ch cực, v&agrave; họ t&iacute;ch cực v&igrave; họ thường xuy&ecirc;n lấp đầy t&acirc;m hồn m&igrave;nh bằng những suy nghĩ tinh thần tốt đẹp, trong sạch, mạnh mẽ, t&iacute;ch cực.</p>', 2023, NULL, 268, 15, 12, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (121, N'Được Học (Tái Bản 2022)', N'8935069922043', N'Bìa Mềm', CAST(96850.00 AS Decimal(12, 2)), CAST(182000.00 AS Decimal(12, 2)), CAST(149000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786043295245_1_2.jpg', N'Tara Westover', N'<p><strong>Được Học</strong></p>
<p>Bạn đọc sẽ biết ngay từ đầu rằng Tara Westover đang kể một c&acirc;u chuyện c&oacute; thực, hơn hết lại l&agrave; c&acirc;u chuyện cuộc đời c&ocirc;, nhưng d&ugrave; &iacute;t hay nhiều ch&uacute;ng ta vẫn cảm thấy sao m&agrave; n&oacute; &ldquo;như tiểu thuyết&rdquo;!</p>
<p>C&ocirc; b&eacute; Tara sống tr&ecirc;n n&uacute;i, đ&atilde; vậy c&ograve;n chưa bao giờ được đi học bởi v&igrave; bố của Tara &ndash; một người quyết liệt b&agrave;i b&aacute;c trường c&ocirc;ng cũng như bất cứ kh&iacute;a cạnh văn minh n&agrave;o &ldquo;phản tự nhi&ecirc;n&rdquo;, phản lại &yacute; Ch&uacute;a &ndash; muốn như thế. Thậm ch&iacute; c&ocirc; b&eacute; n&agrave;y kh&ocirc;ng c&oacute; cả giấy khai sinh, nghĩa l&agrave; trong hệ thống x&atilde; hội c&ocirc; kh&ocirc;ng tồn tại. Tara tồn tại theo &ldquo;luật&rdquo; của bố: c&ocirc; được định nghĩa qua những c&ocirc;ng việc nhằm sửa soạn cho ng&agrave;y Tận thế, những lao động khổ ải ở b&atilde;i phế liệu, v&agrave; tr&ecirc;n hết l&agrave; nề nếp khắc kỷ tuyệt đối thể hiện l&ograve;ng s&ugrave;ng k&iacute;nh Ch&uacute;a.</p>
<p>C&ocirc; g&aacute;i ấy lớn l&ecirc;n hầu như chỉ trong cảm gi&aacute;c vi phạm v&agrave; tội lỗi &ndash; đi học l&agrave; tội lỗi, rung động với bạn kh&aacute;c giới l&agrave; tội lỗi, mặc v&aacute;y v&agrave; &aacute;o thun &ocirc;m s&aacute;t l&agrave; tay sai của quỷ Sa-tăng. Bố Tara đ&atilde; nu&ocirc;i dạy c&ocirc; (cũng như c&aacute;c anh chị em kh&aacute;c) ở một &ldquo;th&agrave;nh tr&igrave;&rdquo; ki&ecirc;n cố đến mức c&ocirc; hầu như kh&ocirc;ng thể quen với những lời khen, với t&igrave;nh cảm &acirc;n cần, ưu &aacute;i. Tara Westover kh&ocirc;ng hề hư cấu chuỗi kịch t&iacute;nh trong đời m&igrave;nh (đọc tự truyện, ch&uacute;ng ta sẽ thấy t&aacute;c giả lu&ocirc;n lo ngại việc kể sai, kể s&oacute;t): từ chuỗi vận nạn của ch&iacute;nh c&ocirc; đến những tai nạn lần lượt xảy ra với c&aacute;c th&agrave;nh vi&ecirc;n gia đ&igrave;nh, m&agrave; hầu như tất cả đều bắt nguồn nơi t&iacute;nh c&aacute;ch, lối sống k&igrave; dị của &ocirc;ng bố. Song c&agrave;ng lật mở những trang s&aacute;ch th&igrave; tim ch&uacute;ng ta c&agrave;ng thắt lại với c&acirc;u hỏi: Sao kia, chuyện n&agrave;y l&agrave;<em>c&oacute; thật</em>?</p>
<p>Tara Westover đ&atilde; vượt qua c&aacute;i c&oacute; thật ấy, dĩ nhi&ecirc;n chẳng hề theo c&aacute;ch thẳng băng, dễ d&agrave;ng, để được đi học; v&agrave; m&atilde;i về sau, khi trở th&agrave;nh Tiến sỹ tại Đại học Cambridge lừng danh, c&ocirc; đ&atilde; buộc phải chấp nhận t&igrave;nh cảnh đứt l&igrave;a mối quan hệ với hầu hết người ruột thịt.</p>
<p>Được học, được gi&aacute;o dục l&agrave; niềm vui, niềm hạnh ph&uacute;c, với một số người đ&oacute; c&ograve;n l&agrave; cứu rỗi. Như Tara. Dẫu gi&aacute; phải trả cực kỳ đắt đỏ, dai dẳng, thấu xương. Nhưng c&ocirc; đ&atilde; chọn để được tự do, để trở n&ecirc;n tốt đẹp hơn, d&ugrave; bao đơn độc.</p>', 2022, NULL, 320, 13, 1, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (122, N'Sức Mạnh Của EQ - Đánh Thức Trí Tuệ Cảm Xúc - Làm Chủ Ngôn Ngữ - Thu Phục Lòng Người', N'8935325020704', N'Bìa Mềm', CAST(49400.00 AS Decimal(12, 2)), CAST(99000.00 AS Decimal(12, 2)), CAST(76000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/b/i/bia_1_suc-manh-cua-eq.jpg', N'Patrick King', N'<p><strong>Sức Mạnh Của EQ - Đ&aacute;nh Thức Tr&iacute; Tuệ Cảm X&uacute;c - L&agrave;m Chủ Ng&ocirc;n Ngữ - Thu Phục L&ograve;ng Người</strong></p>
<p><strong>Th&agrave;nh c&ocirc;ng trong đời bạn sẽ phụ thuộc v&agrave;o c&aacute;ch bạn đối xử với mọi người. Xin lỗi, sự thật th&igrave; lu&ocirc;n phũ ph&agrave;ng.</strong></p>
<p>Nhưng c&oacute; tin tốt cho bạn:&nbsp;<em>Đ&acirc;y l&agrave; kỹ năng c&oacute; thể r&egrave;n luyện được</em>&nbsp;&ndash; v&agrave; cuốn s&aacute;ch n&agrave;y l&agrave; một khởi đầu kh&ocirc;ng thể tuyệt vời hơn.</p>
<p><strong>Sức mạnh của EQ</strong>&nbsp;l&agrave; một cuốn s&aacute;ch đề cao t&iacute;nh thực tiễn, với những kỹ thuật &aacute;p dụng được ngay lập tức:</p>
<p>- Tr&iacute; tuệ đối thoại v&agrave; c&aacute;ch đạt tới thấu cảm CHỈ TRONG 4 BƯỚC</p>
<p>- C&aacute;ch tho&aacute;t ly quan điểm c&aacute; nh&acirc;n v&agrave; ĐỌC VỊ CẢM X&Uacute;C của người kh&aacute;c</p>
<p>- KỸ THUẬT &ldquo;ĐỌC NGUỘI&rdquo; v&agrave; trở th&agrave;nh chuy&ecirc;n gia t&igrave;m kiếm &ldquo;manh mối&rdquo; trong giao tiếp</p>
<p>- Sự thấu hiểu cảm x&uacute;c c&ugrave;ng C&Aacute;CH D&Aacute;N NH&Atilde;N bản th&acirc;n v&agrave; người kh&aacute;c</p>
<p>- Những c&acirc;u hỏi chất lượng khiến bạn c&oacute; vẻ như biết ĐỌC THẤU SUY NGHĨ</p>', 2024, NULL, 176, 9, 4, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (123, N'Atomic Habits - Thay Đổi Tí Hon Hiệu Quả Bất Ngờ (Tái Bản 2023)', N'8932000133766', N'Bìa Mềm', CAST(100425.00 AS Decimal(12, 2)), CAST(189000.00 AS Decimal(12, 2)), CAST(154500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/_/2/_2024_-thay_doi_ti_hon_hieu_qua_bat_ngo-tb8-02.jpg', N'James Clear', N'<p><strong>Atomic Habits - Thay Đổi T&iacute; Hon Hiệu Quả Bất Ngờ (T&aacute;i Bản 2023)</strong></p>
<p>&bull; Wall Street Journal Bestseller, USA Today Bestseller, Publisher&rsquo;s Weekly Bestseller</p>
<p>&bull; Nằm trong Top 20 tựa s&aacute;ch thể loại non-fiction b&aacute;n chạy v&agrave; được t&igrave;m đọc nhiều nhất của Amazon suốt 40 tuần t&iacute;nh đến th&aacute;ng 9/2019</p>
<p>Một thay đổi t&iacute; hon c&oacute; thể biến đổi cuộc đời bạn kh&ocirc;ng?</p>
<p>Hẳn l&agrave; kh&oacute; đồng &yacute; với điều đ&oacute;. Nhưng nếu bạn thay đổi th&ecirc;m một ch&uacute;t? Một ch&uacute;t nữa? Rồi th&ecirc;m một ch&uacute;t nữa? Đến một l&uacute;c n&agrave;o đ&oacute;, bạn phải c&ocirc;ng nhận rằng cuộc sống của m&igrave;nh đ&atilde; chuyển biến nhờ v&agrave;o một thay đổi nhỏ&hellip;</p>
<p>V&agrave; đ&oacute; ch&iacute;nh l&agrave; sức mạnh của th&oacute;i quen nguy&ecirc;n tử.</p>
<p>T&aacute;c giả:</p>
<p>James Clear l&agrave; t&aacute;c giả người Mỹ, nhiếp ảnh gia, nh&agrave; khởi nghiệp, v&agrave; l&agrave; người s&aacute;ng tạo The Habits Academy.</p>
<p>Anh nghi&ecirc;n cứu về những th&oacute;i quen, việc đưa ra quyết định v&agrave; sự cải tiến li&ecirc;n tục. Trang jamesclear.com c&oacute; h&agrave;ng triệu lượt truy cập mỗi th&aacute;ng.</p>
<p>B&agrave;i viết của James Clear được đăng tr&ecirc;n New York Times, Entrepreneur, Time&hellip; Anh cũng l&agrave; diễn giả thường xuy&ecirc;n tại c&aacute;c c&ocirc;ng ty nằm trong bảng xếp hạng Fortune 500.</p>', 2023, NULL, 385, 16, 2, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (124, N'30 Tuổi - Mọi Thứ Chỉ Mới Bắt Đầu', N'8935278605546', N'Bìa Mềm', CAST(67275.00 AS Decimal(12, 2)), CAST(135000.00 AS Decimal(12, 2)), CAST(103500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935278605546.jpg', N'Lý Thượng Long', N'<p><strong>30 TUỔI - MỌI THỨ CHỈ MỚI BẮT ĐẦU</strong></p>
<p><em>&ldquo;Bởi v&igrave;, ba mươi tuổi mọi thứ chỉ mới bắt đầu. Đừng sợ đau khổ. Tất cả những khổ đau phải trải qua ở tuổi đ&ocirc;i mươi đều l&agrave; m&oacute;n qu&agrave; của cuộc sống.&rdquo;</em></p>
<p><strong>Những khởi đầu ở tuổi 30</strong></p>
<p>Ba mươi tuổi, một phần ba qu&atilde;ng thời gian cuộc đời đ&atilde; hết, cũng l&agrave; mở đầu cho qu&atilde;ng đường mới mở ra. Cuốn s&aacute;ch n&agrave;y tặng bạn ch&igrave;a kh&oacute;a đi v&agrave;o thế giới trưởng th&agrave;nh v&agrave; tiến bộ, ch&iacute;nh l&agrave; sự ki&ecirc;n tr&igrave; l&agrave;m người kh&aacute;c phải cảm động, l&agrave;m mọi kh&oacute; khăn phải lui bước!</p>
<p>Viết một cuốn tự truyện khi sắp ba mươi, chẳng phải v&igrave; qu&aacute; nhiều th&agrave;nh tựu, n&ecirc;n muốn khoe khoang một ch&uacute;t, cũng kh&ocirc;ng hẳn do y&ecirc;u m&igrave;nh. Chỉ l&agrave; ch&uacute;t gi&atilde;i b&agrave;y, để nh&igrave;n lại bản th&acirc;n, chia sẻ t&acirc;m tư c&ugrave;ng người đọc, nhắn cho những ai c&ograve;n lo lắng hay mơ hồ về thanh xu&acirc;n sắp qua, rằng mọi thứ mới chỉ đang bắt đầu. Đ&oacute; l&agrave; những g&igrave; L&yacute; Thượng Long n&oacute;i với bạn ở cuốn s&aacute;ch n&agrave;y.</p>
<p>H&atilde;y ki&ecirc;n tr&igrave; với con đường m&igrave;nh đ&atilde; chọn, ngay cả khi những người xung quanh đang đi đường tắt. Ki&ecirc;n tr&igrave; với những g&igrave; bạn y&ecirc;u th&iacute;ch, ngay cả khi người xung quanh cho rằng bạn rất cực khổ. Ki&ecirc;n tr&igrave; với con đường của m&igrave;nh ngay cả khi chỉ c&oacute; một m&igrave;nh suốt chặng.</p>
<p>Bởi những g&igrave; bạn đang trải qua đều qu&yacute; gi&aacute;, ch&iacute;nh l&agrave; cơ hội để kh&ocirc;ng ngừng trau dồi bản th&acirc;n. Mỗi ng&agrave;y, h&atilde;y tự nhủ:&nbsp;<strong>30 Tuổi - Mọi Thứ Chỉ Mới Bắt Đầu</strong>. V&agrave; bắt đầu trở n&ecirc;n ng&agrave;y c&agrave;ng vững mạnh hơn, bạn nh&eacute;!</p>', 2023, NULL, 332, 8, 12, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (125, N'Tư Duy Ngược', N'9786043440287', N'Bìa Mềm', CAST(45175.00 AS Decimal(12, 2)), CAST(139000.00 AS Decimal(12, 2)), CAST(69500.00 AS Decimal(12, 2)), N'https://res.cloudinary.com/dabxzdaf8/image/upload/v1748969784/Book_cover/jsnjsccbnwpdvouvahzw.webp', N'Nguyễn Anh Dũng', N'<p><strong>Tư Duy Ngược</strong></p>
<p>Ch&uacute;ng ta thực sự c&oacute; hạnh ph&uacute;c kh&ocirc;ng? Ch&uacute;ng ta c&oacute; đang sống cuộc đời m&igrave;nh kh&ocirc;ng? Ch&uacute;ng ta c&oacute; d&aacute;m dũng cảm chiến thắng mọi khu&ocirc;n mẫu, định kiến, đi ngược đ&aacute;m đ&ocirc;ng để khẳng định bản sắc ri&ecirc;ng của m&igrave;nh kh&ocirc;ng?. C&oacute; bao giờ bạn tự hỏi như thế, rồi c&oacute; c&acirc;u trả lời cho ch&iacute;nh m&igrave;nh?</p>
<p>T&ocirc;i biết biết, kh&ocirc;ng phải ai cũng đang sống cuộc đời của m&igrave;nh, kh&ocirc;ng phải ai cũng d&aacute;m vượt qua mọi lối m&ograve;n để s&aacute;ng tạo v&agrave; th&agrave;nh c&ocirc;ng&hellip; Dựa tr&ecirc;n việc nghi&ecirc;n cứu, t&igrave;m hiểu, chắt lọc, t&igrave;m kiếm, ghi ch&eacute;p từ c&aacute;c c&acirc;u chuyện trong đời sống, cũng như trải nghiệm của bản th&acirc;n, t&ocirc;i viết cuốn s&aacute;ch n&agrave;y.</p>
<p>Cuốn s&aacute;ch sẽ giải m&atilde; bạn l&agrave; ai, bạn cần&nbsp;<strong>Tư duy ngược</strong> để th&agrave;nh c&ocirc;ng v&agrave; hạnh ph&uacute;c như thế n&agrave;o v&agrave; c&aacute;c phương ph&aacute;p gi&uacute;p bạn dũng cảm sống cuộc đời m&agrave; bạn muốn.</p>', 2021, NULL, 242, 14, 9, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (126, N'Đi Tìm Lẽ Sống (Tái Bản 2022)', N'8935086855348', N'Bìa Mềm', CAST(45500.00 AS Decimal(12, 2)), CAST(88000.00 AS Decimal(12, 2)), CAST(70000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/t/h/thumb-01113.jpg', N'Viktor E Frankl', N'<h2 dir="ltr">ĐI T&Igrave;M LẼ SỐNG - H&Agrave;NH TR&Igrave;NH VƯỢT QUA NGHỊCH CẢNH ĐỂ T&Igrave;M &Yacute; NGHĨA CUỘC ĐỜI</h2>
<p dir="ltr">&ldquo;Khi con người c&oacute; l&yacute; do để sống, họ c&oacute; thể chịu đựng gần như mọi ho&agrave;n cảnh.&rdquo;</p>
<p dir="ltr">Bạn đ&atilde; bao giờ tự hỏi: Mục đ&iacute;ch của cuộc sống l&agrave; g&igrave;? Tại sao con người c&oacute; thể tiếp tục tồn tại d&ugrave; phải đối mặt với những nỗi đau kh&ocirc;ng tưởng? Nếu cuộc sống đầy đau khổ, liệu ta c&oacute; thể tiếp tục tồn tại?&nbsp;</p>
<p dir="ltr">"Đi T&igrave;m Lẽ Sống" của Viktor E. Frankl kh&ocirc;ng chỉ l&agrave; một cuốn s&aacute;ch, m&agrave; c&ograve;n l&agrave; ch&igrave;a kh&oacute;a gi&uacute;p bạn t&igrave;m ra c&acirc;u trả lời s&acirc;u sắc nhất.</p>', 2022, NULL, 224, 19, 10, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (127, N'Yêu Những Điều Không Hoàn Hảo', N'8935235218130', N'Bìa Mềm', CAST(73775.00 AS Decimal(12, 2)), CAST(139000.00 AS Decimal(12, 2)), CAST(113500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/4/c/4ceb6ba3bd81614df8ff4c1411b11f59.jpg', N'Hae Min', N'<p><strong>Y&ecirc;u Những Điều Kh&ocirc;ng Ho&agrave;n Hảo</strong></p>
<p>&ldquo;Ngẫm lại cuộc sống của ch&iacute;nh m&igrave;nh, ta sẽ nhận thấy rất nhiều điều kh&ocirc;ng ho&agrave;n hảo. Trước hết, chỉ nh&igrave;n v&agrave;o bản th&acirc;n m&igrave;nh th&ocirc;i ta đ&atilde; cảm nhận được nhiều thiếu s&oacute;t rồi: lời n&oacute;i v&agrave; h&agrave;nh động m&acirc;u thuẫn với nhau, vụng về trong những mối quan hệ x&atilde; hội, chuyện học h&agrave;nh, c&ocirc;ng việc kh&ocirc;ng su&ocirc;n sẻ như &yacute; muốn. Chưa kể đ&ocirc;i khi ta c&ograve;n khiến người kh&aacute;c tổn thương, thậm ch&iacute; c&ograve;n l&agrave;m những việc khiến bản th&acirc;n cảm thấy tội lỗi v&agrave; hối hận. V&agrave; khi nh&igrave;n v&agrave;o những người th&acirc;n trong gia đ&igrave;nh, bạn b&egrave;, đồng nghiệp, ta cũng nhận thấy những điều kh&ocirc;ng-ho&agrave;n-hảo tương tự như vậy.</p>
<p>Nhưng d&ugrave; đang sống giữa thế gian đầy rẫy những điều kh&ocirc;ng ho&agrave;n hảo, ta vẫn kh&ocirc;ng thể ngừng y&ecirc;u thương ch&iacute;nh những điều kh&ocirc;ng ho&agrave;n hảo ấy. Cuộc sống rất đ&aacute;ng để tr&acirc;n trọng, ta kh&ocirc;ng thể ph&iacute; ho&agrave;i cuộc sống v&agrave;o việc mỉa mai hay căm gh&eacute;t thứ g&igrave; đ&oacute; chỉ v&igrave; kh&ocirc;ng thể hiểu được n&oacute; hoặc n&oacute; kh&ocirc;ng vừa &yacute; ta.</p>
<p>Mong sao những d&ograve;ng chữ nhỏ b&eacute; của t&ocirc;i c&oacute; thể đem đến cho độc giả dũng kh&iacute;, gi&uacute;p họ chữa l&agrave;nh vết thương l&ograve;ng v&agrave; d&agrave;nh ra cho ri&ecirc;ng m&igrave;nh khoảng thời gian để y&ecirc;u bản th&acirc;n&hellip; Mong sao cuốn s&aacute;ch n&agrave;y sẽ trở th&agrave;nh b&agrave;n tay giữ lấy bạn khi bạn rơi v&agrave;o tuyệt vọng, sẽ trở th&agrave;nh khoảng lặng để bạn tạm dừng ch&acirc;n giữa những hỗn độn ồn &agrave;o.&rdquo;</p>
<p>― Đại đức Hae Min</p>', 2018, NULL, 295, 9, 10, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (128, N'Khi Mọi Điều Không Như Ý', N'8935235243965', N'Bìa Cứng', CAST(98800.00 AS Decimal(12, 2)), CAST(179000.00 AS Decimal(12, 2)), CAST(152000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/z/6/z6462915525206_ed7a60909671442fbf92e90fa0416d1e_1.jpg', N'Hae Min', N'<div class="product-essential-detail-parent">
<div id="block-content-product-detail" class="block-content-product-detail block-info-detail-2-mobile" data-ref="info_detail_2">
<div id="product_tabs_description_contents">
<div id="desc_content" class="std">
<p><strong>Khi Mọi Điều Kh&ocirc;ng Như &Yacute;</strong></p>
<p>Bạn đ&atilde; bao giờ cảm thấy như cuộc sống li&ecirc;n tục thử th&aacute;ch bạn, khiến bạn phải kh&ocirc;ng ngừng vật lộn để vượt qua những kh&oacute; khăn v&agrave; thất bại bất ngờ?</p>
<p>Từ nỗi mất m&aacute;t, đau khổ v&agrave; c&ocirc; đơn của những trải nghiệm kh&ocirc;ng như &yacute; - trong cuốn s&aacute;ch ấm &aacute;p n&agrave;y - Đại đức Hae Min &acirc;n cần dẫn dắt ch&uacute;ng ta tới nhận thức rằng những khoảnh khắc ấy thực sự c&oacute; thể l&agrave; cơ hội hiếm c&oacute; để kh&aacute;m ph&aacute; bản th&acirc;n, đ&oacute;ng vai tr&ograve; l&agrave; bước đệm cho những điều lớn lao hơn trong cuộc sống.</p>
<p>Khi cuộc sống trở n&ecirc;n bận rộn v&agrave; kh&oacute; khăn, h&atilde;y tặng cho bản th&acirc;n m&oacute;n qu&agrave; đặc biệt l&agrave; dừng lại. Dừng lại một l&aacute;t, nhắm mắt v&agrave; bước l&ugrave;i một bước. H&atilde;y quan s&aacute;t xem cơ thể bạn đang cảm thấy như thế n&agrave;o v&agrave; lắng nghe t&acirc;m tr&iacute; bạn đang n&oacute;i g&igrave; l&uacute;c n&agrave;y, như thể bạn đang nh&igrave;n m&igrave;nh trong gương vậy.</p>
<div class="clear">&nbsp;</div>
</div>
</div>
<div class="clear">&nbsp;</div>
</div>
</div>', 2025, NULL, 240, 7, 11, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (129, N'Khi Mọi Điều Không Như Ý', N'8935235243163', N'Bìa Cứng', CAST(57850.00 AS Decimal(12, 2)), CAST(109000.00 AS Decimal(12, 2)), CAST(89000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935235243163.jpg', N'Hae Min', N'<h2 dir="ltr">KHI MỌI ĐIỀU KH&Ocirc;NG NHƯ &Yacute; - LIỆU B&Igrave;NH Y&Ecirc;N C&Oacute; TỒN TẠI GIỮA GI&Ocirc;NG B&Atilde;O?&nbsp;</h2>
<p dir="ltr">C&oacute; những ng&agrave;y, mọi thứ đều chống lại ta - c&ocirc;ng việc bế tắc, c&aacute;c mối quan hệ rạn nứt, l&ograve;ng trống rỗng đến nghẹt thở. Ta tự hỏi: "Bao giờ mọi thứ mới ổn?" Nhưng liệu b&igrave;nh y&ecirc;n c&oacute; đến từ việc thay đổi ho&agrave;n cảnh, hay từ c&aacute;ch ta nh&igrave;n nhận n&oacute;? Hae Min kh&ocirc;ng cho ta một lối tho&aacute;t thần kỳ, m&agrave; l&agrave; những lời th&igrave; thầm ấm &aacute;p, gi&uacute;p ta chậm lại, thấu hiểu ch&iacute;nh m&igrave;nh v&agrave; t&igrave;m thấy sự nhẹ nh&otilde;m ngay cả khi mọi điều kh&ocirc;ng như &yacute;.&nbsp;</p>', 2025, NULL, 240, 18, 13, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (130, N'Tâm Lý Học Về Tiền', N'8936066689953', N'Bìa Mềm', CAST(94575.00 AS Decimal(12, 2)), CAST(189000.00 AS Decimal(12, 2)), CAST(145500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_220008.jpg', N'Morgan Housel', N'<p>Tiền bạc c&oacute; ở khắp mọi nơi, n&oacute; ảnh hưởng đến tất cả ch&uacute;ng ta, v&agrave; khiến phần lớn ch&uacute;ng ta bối rối. Mọi người nghĩ về n&oacute; theo những c&aacute;ch hơi kh&aacute;c nhau một ch&uacute;t. N&oacute; mang lại những b&agrave;i học c&oacute; thể được &aacute;p dụng tới rất nhiều lĩnh vực trong cuộc sống, như rủi ro, sự tự tin, v&agrave; hạnh ph&uacute;c. Rất &iacute;t chủ đề cung cấp một lăng k&iacute;nh ph&oacute;ng to đầy quyền lực gi&uacute;p giải th&iacute;ch v&igrave; sao mọi người lại h&agrave;nh xử theo c&aacute;ch họ l&agrave;m hơn l&agrave; về tiền bạc. Đ&oacute; mới l&agrave; một trong những chương tr&igrave;nh ho&agrave;nh tr&aacute;ng nhất tr&ecirc;n thế giới.</p>
<p>Ch&uacute;ng ta hiếm khi l&acirc;m v&agrave;o ho&agrave;n cảnh nợ ngập đầu ư? Biết tiết kiệm để d&agrave;nh cho l&uacute;c khốn kh&oacute; hơn ư? Chuẩn bị sẵn s&agrave;ng cho việc nghỉ hưu? C&oacute; những c&aacute;i nh&igrave;n thiết thực về mối quan hệ giữa tiền v&agrave; hạnh ph&uacute;c của ch&uacute;ng ta hơn phải kh&ocirc;ng?</p>
<p>Ch&uacute;ng ta đều l&agrave;m những điều đi&ecirc;n rồ với tiền bạc, bởi v&igrave; ch&uacute;ng ta đều c&ograve;n kh&aacute; mới mẻ với tr&ograve; chơi n&agrave;y v&agrave; điều c&oacute; vẻ đi&ecirc;n rồ với bạn lại c&oacute; khi hợp l&yacute; với t&ocirc;i. Nhưng kh&ocirc;ng ai l&agrave; đi&ecirc;n rồ cả &ndash; ch&uacute;ng ta đều đưa ra c&aacute;c quyết định dựa tr&ecirc;n những trải nghiệm độc đ&aacute;o ri&ecirc;ng c&oacute; mang vẻ hợp l&yacute; với m&igrave;nh ở bất cứ thời điểm n&agrave;o.</p>
<p>Mục đ&iacute;ch của cuốn s&aacute;ch n&agrave;y l&agrave; sử dụng những c&acirc;u chuyện ngắn để thuyết phục bạn rằng những kỹ năng mềm c&ograve;n quan trọng hơn kh&iacute;a cạnh l&yacute; thuyết của đồng tiền. Th&ocirc;ng qua một tập hợp những thử nghiệm v&agrave; sai lầm của nhiều năm ch&uacute;ng ta đ&atilde; học được c&aacute;ch trở th&agrave;nh những n&ocirc;ng d&acirc;n giỏi giang hơn, những thợ sửa ống nước nhiều kỹ năng hơn, v&agrave; những nh&agrave; h&oacute;a học ti&ecirc;n tiến hơn. Nhưng liệu việc thử nghiệm v&agrave; sai lầm c&oacute; dạy ch&uacute;ng ta trở n&ecirc;n giỏi hơn trong c&aacute;ch quản l&yacute; t&agrave;i ch&iacute;nh c&aacute; nh&acirc;n của ch&iacute;nh m&igrave;nh kh&ocirc;ng?</p>', 2022, NULL, 382, 15, 14, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (131, N'Con Người Và Biểu Tượng - Man And His Symbols', N'8935235236622', N'Bìa Cứng', CAST(239850.00 AS Decimal(12, 2)), CAST(450000.00 AS Decimal(12, 2)), CAST(369000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935235236622.jpg', N'Carl Gustav Jung', N'<p>CON NGƯỜI V&Agrave; BIỂU TƯỢNG l&agrave; t&aacute;c phẩm đầu ti&ecirc;n v&agrave; duy nhất trong đ&oacute; Carl Gustav Jung giải th&iacute;ch cho độc giả phổ th&ocirc;ng đ&oacute;ng g&oacute;p lớn nhất của &ocirc;ng cho hiểu biết về t&acirc;m tr&iacute; con người: l&yacute; thuyết về tầm quan trọng của &yacute; nghĩa biểu tượng &ndash; đặc biệt khi ch&uacute;ng được h&eacute; lộ trong những giấc mơ.</p>
<p>Nếu kh&ocirc;ng v&igrave; một giấc mơ, cuốn s&aacute;ch n&agrave;y hẳn kh&ocirc;ng bao giờ được viết ra. Giấc mơ đ&oacute; thuyết phục Jung rằng &ocirc;ng c&oacute; thể, v&agrave; thực ra n&ecirc;n, l&yacute; giải tư tưởng của &ocirc;ng cho những người kh&ocirc;ng chuy&ecirc;n về t&acirc;m l&yacute; học. Jung đ&atilde; vạch ra một kế hoạch chu to&agrave;n cho cuốn s&aacute;ch, bao gồm những phần m&agrave; &ocirc;ng mong bốn cộng sự th&acirc;n t&iacute;n nhất của &ocirc;ng viết. &Ocirc;ng đ&atilde; d&agrave;nh những th&aacute;ng cuối c&ugrave;ng của cuộc đời để bi&ecirc;n tập t&aacute;c phẩm v&agrave; kịp ho&agrave;n th&agrave;nh phần then chốt chỉ 10 ng&agrave;y trước khi nhắm mắt. Xuy&ecirc;n suốt cuốn s&aacute;ch, Jung nh&acirc;n mạnh rằng con người chỉ c&oacute; thể đạt tới một sự to&agrave;n vẹn th&ocirc;ng qua hiểu biết v&agrave; chấp nhận v&ocirc; thức - sự hiểu biết c&oacute; được nhờ những giấc mơ v&agrave; những biểu tượng xuất hiện trong đ&oacute;. Mỗi giấc mơ l&agrave; một th&ocirc;ng đạt trực tiếp, ri&ecirc;ng tư v&agrave; đầy &yacute; nghĩa với người mơ - sự th&ocirc;ng đạt d&ugrave;ng những biểu tượng chung cho cả nh&acirc;n loại nhưng lu&ocirc;n sử dụng ch&uacute;ng theo c&aacute;ch ho&agrave;n to&agrave;n c&aacute; nh&acirc;n, v&agrave; chỉ c&oacute; thể được giải m&atilde; bằng một "ch&igrave;a kh&oacute;a" ho&agrave;n to&agrave;n ri&ecirc;ng tư.</p>
<p>Với gần 500 h&igrave;nh minh họa, cuốn s&aacute;ch cung cấp một diễn giải độc đ&aacute;o về tư tưởng của Jung. Ch&uacute;ng cho thấy bản chất v&agrave; chức năng của những giấc mơ, đ&agrave;o s&acirc;u &yacute; nghĩa tượng trưng của nghệ thuật hiện đại, h&eacute; lộ những &yacute; nghĩa t&acirc;m l&yacute; của những kinh nghiệm đời thường. Ch&uacute;ng x&aacute;c quyết tư tưởng của Jung v&agrave; l&agrave; một phần kh&ocirc;ng thể thiếu của CON NGƯỜI V&Agrave; BIỂU TƯỢNG - di sản cuối c&ugrave;ng &ocirc;ng để lại cho nh&acirc;n loại.</p>', 2023, NULL, 522, 2, 1, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (132, N'How Psychology Works - Hiểu Hết Về Tâm Lý Học', N'8935235227699', N'Bìa Cứng', CAST(159900.00 AS Decimal(12, 2)), CAST(300000.00 AS Decimal(12, 2)), CAST(246000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_208345.jpg', N'Jo Hemmings', N'<p>MỘT TRONG NHỮNG CUỐN S&Aacute;CH MỞ KH&Oacute;A HỮU &Iacute;CH NHẤT VỀ TƯ DUY, K&Yacute; ỨC V&Agrave; CẢM X&Uacute;C CỦA CON NGƯỜI!<br>&Aacute;m sợ l&agrave; g&igrave;, &aacute;m sợ c&oacute; thực sự đ&aacute;ng sợ kh&ocirc;ng? Rối loạn t&acirc;m l&yacute; l&agrave; g&igrave;, l&agrave;m thế n&agrave;o để tho&aacute;t khỏi t&igrave;nh trạng suy nhược v&agrave; x&aacute;o trộn đ&oacute;? Trầm cảm l&agrave; g&igrave;, v&igrave; sao con người hiện đại thường xuy&ecirc;n gặp v&agrave; chống chọi với t&igrave;nh trạng u uất, mệt mỏi v&agrave; tuyệt vọng n&agrave;y?</p>
<p>T&igrave;m hiểu về c&aacute;c vấn đề t&acirc;m tr&iacute; của con người lu&ocirc;n đầy sức hấp dẫn v&agrave; l&ocirc;i cuốn, v&igrave; vậy m&agrave; t&acirc;m l&yacute; học ra đời, h&igrave;nh th&agrave;nh v&agrave; ph&aacute;t triển rất nhiều c&aacute;c học thuyết v&agrave; trường ph&aacute;i. Cuốn s&aacute;ch n&agrave;y dẫn dắt bạn đọc qua h&agrave;nh tr&igrave;nh t&igrave;m hiểu c&aacute;c học thuyết v&agrave; trường ph&aacute;i đ&oacute;, về c&aacute;ch c&aacute;c nh&agrave; t&acirc;m l&yacute; diễn giải h&agrave;nh xử v&agrave; t&acirc;m tr&iacute; con người. Tại sao ch&uacute;ng ta c&oacute; những h&agrave;nh vi, suy nghĩ v&agrave; cảm x&uacute;c như vậy, ch&uacute;ng diễn ra v&agrave; kết th&uacute;c như thế n&agrave;o, ch&uacute;ng ảnh hưởng l&acirc;u d&agrave;i, gi&aacute;n đoạn hay ngắn ngủỉ đến đời sống của ch&uacute;ng ta ra sao, l&agrave;m thế n&agrave;o để ch&uacute;ng ta tho&aacute;t khỏi những t&aacute;c động ti&ecirc;u cực của ch&uacute;ng?</p>
<p>Cuốn s&aacute;ch c&oacute; cấu tr&uacute;c khoa học, tr&igrave;nh b&agrave;y dễ hiểu, s&uacute;c t&iacute;ch, thiết kế v&agrave; minh họa đẹp mắt n&agrave;y sẽ mang đến cho bạn những hiểu biết về c&aacute;c học thuyết t&acirc;m l&yacute; v&agrave; c&aacute;c phương ph&aacute;p trị liệu, từ c&aacute;c vấn đề c&aacute; nh&acirc;n đến những ứng dụng thực tế.</p>', 2022, NULL, 255, 5, 2, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (133, N'2030: Những Xu Hướng Lớn Sẽ Định Hình Thế Giới Tương Lai (Tái Bản 2023)', N'8932000134497', N'Bìa Mềm', CAST(111150.00 AS Decimal(12, 2)), CAST(209000.00 AS Decimal(12, 2)), CAST(171000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/2/0/2030-nhung-xu-huong-lon-se-dinh-hinh-the-gioi-tuong-lai-tb-2023.jpg', N'Mauro F. Guillén', N'<p><strong>2030: Những Xu Hướng Lớn Sẽ Định H&igrave;nh Thế Giới Tương Lai</strong></p>
<p>THẾ GIỚI M&Agrave; BẠN BIẾT SẮP KẾT TH&Uacute;C,</p>
<p>BẠN SẼ CHUẨN BỊ G&Igrave; CHO NHỮNG ĐIỀU XẢY RA TIẾP THEO?</p>
<p>Từng c&oacute; l&uacute;c, thế giới ph&acirc;n biệt r&otilde; rệt giữa gi&agrave;u v&agrave; ngh&egrave;o. D&acirc;n số trẻ, t&agrave;i ch&iacute;nh đảm bảo, người lao động nhiều hơn người về hưu. Những c&ocirc;ng ty lớn kh&ocirc;ng thấy nhu cầu b&agrave;nh trướng ra b&ecirc;n ngo&agrave;i Mỹ v&agrave; ch&acirc;u &Acirc;u. Một người b&igrave;nh thường trong x&atilde; hội ph&aacute;t triển chỉ cần si&ecirc;ng năng l&agrave;m việc l&agrave; sẽ c&oacute; một tương lai ổn định.</p>
<p>Đến năm 2030, thế giới đ&oacute; sẽ kh&aacute;c:</p>
<p>- &Ocirc;ng b&agrave; sẽ nhiều hơn ch&aacute;u chắt</p>
<p>- Giới trung lưu ch&acirc;u &Aacute; v&agrave; ch&acirc;u Phi Hạ Sahara sẽ c&oacute; d&acirc;n số đ&ocirc;ng hơn Mỹ v&agrave; ch&acirc;u &Acirc;u cộng lại</p>
<p>- Lần đầu ti&ecirc;n trong lịch sử, kinh tế to&agrave;n cầu sẽ bị điều khiển bởi nhu cầu phi-phương T&acirc;y</p>
<p>- Nữ sẽ sở hữu t&agrave;i sản nhiều hơn nam</p>
<p>- Sẽ c&oacute; nhiều robot hơn người lao động</p>
<p>Năm 2030, kh&ocirc;ng c&ograve;n l&agrave; một thời điểm xa x&ocirc;i trong tương lai m&ugrave; mịt, n&oacute; đang đến rất gần, v&agrave; ch&uacute;ng ta cần phải gấp r&uacute;t tự trang bị trước những cơ hội lẫn th&aacute;ch thức. Cuốn s&aacute;ch n&agrave;y sẽ hướng dẫn ch&uacute;ng ta nắm bắt &yacute; nghĩa của những chuyển biến, đưa ra th&ocirc;ng điệp lạc quan về tương lai (d&ugrave; vẫn phải đối mặt với những lo lắng hiện tại); hỗ trợ ch&uacute;ng ta vượt qua cơn biến động mang t&iacute;nh lịch sử, chỉ ra điều g&igrave; cần l&agrave;m v&agrave; điều g&igrave; n&ecirc;n tr&aacute;nh trước những ho&agrave;n cảnh mới mẻ, lạ l&ugrave;ng n&agrave;y.</p>
<p>Cuốn s&aacute;ch l&agrave; bản ph&acirc;n t&iacute;ch đột ph&aacute; từ một trong những chuy&ecirc;n gia h&agrave;ng đầu thế giới về c&aacute;c xu hướng to&agrave;n cầu, bao gồm cả c&aacute;ch Covid-19 đang đẩy nhanh tất cả những thay đổi lớn đang diễn ra cho thế giới của ch&uacute;ng ta.</p>', 2023, NULL, 260, 9, 5, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (134, N'Đại Dương Đen (Tái Bản 2025)', N'8938539539505', N'Bìa Mềm', CAST(102700.00 AS Decimal(12, 2)), CAST(198000.00 AS Decimal(12, 2)), CAST(158000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8938539539505.jpg', N'Đặng Hoàng Giang', N'<p><strong>Đại Dương Đen (T&aacute;i Bản 2025)</strong></p>
<p><strong>Giới thiệu t&aacute;c giả</strong></p>
<p>Tiến sĩ Đặng Ho&agrave;ng Giang l&agrave; nh&agrave; hoạt động x&atilde; hội v&agrave; t&aacute;c giả phi hư cấu, viết về c&aacute;c chủ đề x&atilde; hội đương đại. &Ocirc;ng ti&ecirc;n phong trong c&aacute;c hoạt động nhằm n&acirc;ng cao nhận thức của cộng đồng về sức khỏe tinh thần, ph&aacute; bỏ định kiến v&agrave; kỳ thị. &Ocirc;ng nỗ lực mở rộng kh&ocirc;ng gian x&atilde; hội d&acirc;n sự, g&oacute;p phần x&acirc;y dựng một x&atilde; hội gi&agrave;u l&ograve;ng khoan dung v&agrave; trắc ẩn.</p>
<p>T&aacute;c giả Đặng Ho&agrave;ng Giang c&oacute; bằng kỹ sư tin học của Đại học C&ocirc;ng nghệ IImenau, Đức, v&agrave; bằng tiến sĩ kinh tế ph&aacute;t triển của Đại học C&ocirc;ng nghệ Vienna, &Aacute;o. Những cuốn s&aacute;ch v&agrave; b&agrave;i viết của &ocirc;ng c&oacute; sức ảnh hưởng rộng r&atilde;i trong x&atilde; hội.</p>
<p>Đại dương đen - D&agrave;nh tặng người trầm cảm - Bạn xứng đ&aacute;ng c&oacute; một cuộc sống tốt đẹp&nbsp;</p>
<p>- Chia sẻ những c&acirc;u chuyện CH&Acirc;N THẬT về thế giới của người trầm cảm</p>
<p>- L&agrave;m R&Uacute;NG ĐỘNG t&acirc;m can người đọc khi tiếp cận những lớp lang cảm x&uacute;c v&agrave; c&acirc;u chuyện cay nghiệt m&agrave; người trầm cảm phải đối diện v&agrave; vật lộn mỗi ng&agrave;y</p>
<p>- PHƠI B&Agrave;Y những định kiến m&agrave; x&atilde; hội, gia đ&igrave;nh v&agrave; người th&acirc;n đặt l&ecirc;n người trầm cảm, khiến h&agrave;nh tr&igrave;nh chữa trị c&agrave;ng gian tru&acirc;n Chia sẻ những KIẾN THỨC khoa học căn bản về trầm cảm để gi&uacute;p người trầm cảm v&agrave; người th&acirc;n c&oacute; thể t&igrave;m ra lối tho&aacute;t&nbsp;</p>
<p>- Đưa ra những chỉ dẫn THIẾT THỰC trong việc chăm s&oacute;c, d&agrave;nh cho c&aacute; nh&acirc;n v&agrave; gia đ&igrave;nh c&oacute; người trầm cảm</p>', 2024, NULL, 468, 1, 12, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (135, N'Định Luật Murphy - Mọi Bí Mật Tâm Lý Thao Túng Cuộc Đời Bạn', N'8935325009600', N'Bìa Mềm', CAST(59475.00 AS Decimal(12, 2)), CAST(119000.00 AS Decimal(12, 2)), CAST(91500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/p/h/ph_t-h_nh-_nh-lu_t-murphybia-1.jpg', N'Từ Thính Phong', N'<p>Định Luật Murphy &ndash; Mọi B&iacute; Mật T&acirc;m L&yacute; Thao T&uacute;ng Cuộc Đời Bạn</p>
<p><strong><em>Nếu một điều tồi tệ c&oacute; thể xảy ra, n&oacute; sẽ xảy ra!</em></strong></p>
<p><em>Khi</em>&nbsp;<em>một m&oacute;n đồ quan trọng bị rơi, n&oacute; c&oacute; xu hướng lăn tới dưới ngăn tủ nặng nhất.</em></p>
<p><em>Khi hai tay bạn cầm đầy đồ đạc, mũi bạn bắt đầu ngứa.&nbsp;</em></p>
<p><em>Khi bạn sợ gặp một người n&agrave;o đ&oacute; ở b&ecirc;n ngo&agrave;i, bạn lu&ocirc;n v&ocirc; t&igrave;nh gặp phải</em><em>&nbsp;người đ&oacute;</em><em>.</em></p>
<p><em>&hellip;</em></p>
<p>C&oacute; phải hằng ng&agrave;y bạn hay gặp những chuyện dở kh&oacute;c dở cười tương tự như vậy? Những hiện tượng n&agrave;y đều c&oacute; thể giải th&iacute;ch bằng một kh&aacute;i niệm t&acirc;m l&yacute; học th&uacute; vị:&nbsp;<strong>Định luật Murphy</strong>. N&oacute; nhắc nhở ch&uacute;ng ta rằng việc xấu lu&ocirc;n c&oacute; &ldquo;cơ may&rdquo; cao hơn v&agrave; sai lầm lu&ocirc;n l&agrave; một phần của thế giới n&agrave;y. D&ugrave; cho mỗi ch&uacute;ng ta đều cố gắng hết sức để tr&aacute;nh khỏi sai lầm, nhưng tr&ecirc;n thực tế đ&oacute; l&agrave; điều bất khả thi.</p>
<p>Tuy nhi&ecirc;n, định luật Murphy mang t&iacute;nh cảnh tỉnh v&agrave; dẫn dắt rất lớn trong cuộc sống hằng ng&agrave;y. Cuốn s&aacute;ch n&agrave;y giới thiệu đến với bạn đọc về kiến thức cơ bản, hiện tượng thường gặp c&ugrave;ng với c&aacute;c hiệu ứng t&acirc;m l&yacute; học biểu hiện trong &yacute; thức c&aacute; nh&acirc;n, t&iacute;nh cạnh tranh, quan hệ x&atilde; hội,&hellip; của định luật Murphy th&ocirc;ng qua g&oacute;c nh&igrave;n thực tiễn. Từ đ&oacute; gi&uacute;p bạn đọc hiểu được bản chất con người, bản chất x&atilde; hội rồi ứng dụng n&oacute; v&agrave;o giải quyết c&aacute;c vấn đề gặp phải trong cuộc sống.</p>', 2022, NULL, 280, 17, 3, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (136, N'Tâm Lý Học Tội Phạm - Phác Họa Chân Dung Kẻ Phạm Tội', N'8935325001819', N'Bìa Mềm', CAST(72475.00 AS Decimal(12, 2)), CAST(145000.00 AS Decimal(12, 2)), CAST(111500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/p/h/ph_c-h_a-ch_n-dung-k_-ph_m-t_i.jpg', N'Diệp Hồng Vũ', N'<p><strong>T&Acirc;M L&Yacute; HỌC TỘI PHẠM - PH&Aacute;C HỌA CH&Acirc;N DUNG KẺ PHẠM TỘI</strong></p>
<p>Tội phạm, nhất l&agrave; những vụ &aacute;n mạng, lu&ocirc;n l&agrave; một chủ đề thu h&uacute;t sự quan t&acirc;m của c&ocirc;ng ch&uacute;ng, khơi gợi sự hiếu kỳ của bất cứ ai. Một khi đ&atilde; bắt đầu theo d&otilde;i vụ &aacute;n, hẳn bạn kh&ocirc;ng thể kh&ocirc;ng quan t&acirc;m tới kết cục, đặc biệt l&agrave; c&aacute;ch thức v&agrave; động cơ của kẻ s&aacute;t nh&acirc;n, từ những vụ &aacute;n phạm vi hẹp cho đến những vụ &aacute;n l&agrave;m r&uacute;ng động cả thế giới.</p>
<p>Lấy 36 vụ &aacute;n C&Oacute; THẬT kinh điển nhất trong hồ sơ tội phạm của FBI, &ldquo;T&acirc;m l&yacute; học tội phạm - ph&aacute;c họa ch&acirc;n dung kẻ phạm tội&rdquo; mang đến c&aacute;i nh&igrave;n to&agrave;n cảnh của c&aacute;c chuy&ecirc;n gia về ch&acirc;n dung t&acirc;m l&yacute; tội phạm. Trả lời cho c&acirc;u hỏi: L&agrave;m thế n&agrave;o ph&acirc;n t&iacute;ch được t&acirc;m l&yacute; v&agrave; h&agrave;nh vi tội phạm, từ đ&oacute; kh&ocirc;i phục sự thật th&ocirc;ng qua c&aacute;c manh mối, từ hiện trường vụ &aacute;n, thời gian, dấu t&iacute;ch,&hellip; để t&igrave;m ra kẻ s&aacute;t nh&acirc;n thực sự.&nbsp;</p>
<p>Đằng sau m&aacute;u v&agrave; nước mắt l&agrave; c&aacute;c c&acirc;u chuyện rợn t&oacute;c g&aacute;y về tội &aacute;c, g&oacute;c khuất x&atilde; hội v&agrave; những m&agrave;n đấu tr&iacute; đầy gay cấn giữa điều tra vi&ecirc;n v&agrave; kẻ phạm tội. Trong số đ&oacute; c&oacute; những con quỷ ăn thịt người; những c&ocirc; g&aacute;i xinh đẹp nhưng xảo quyệt; v&agrave; cả c&aacute;ch trả th&ugrave; đầy man rợ của c&aacute;c nh&agrave; khoa học,&hellip; Một số đ&atilde; sa v&agrave;o lưới ph&aacute;p luật ngay khi ch&uacute;ng vừa ra tay, nhưng cũng c&oacute; những kẻ cứ vậy ngủ y&ecirc;n hơn hai mươi năm.&nbsp;</p>
<p>Bằng giọng văn sắc b&eacute;n, &ldquo;T&acirc;m l&yacute; học tội phạm - ph&aacute;c họa ch&acirc;n dung kẻ phạm tội&rdquo; hứa hẹn dẫn dắt người đọc đi qua c&aacute;c cung bậc cảm x&uacute;c từ t&ograve; m&ograve;, ngạc nhi&ecirc;n đến sợ h&atilde;i, hoang mang tận c&ugrave;ng. Ch&uacute;ng ta sẽ lần t&igrave;m về qu&aacute; khứ để từng bước gỡ những n&uacute;t thắt chưa được giải, khiến ta "ngạt thở" đọc tới tận trang cuối c&ugrave;ng.&nbsp;</p>
<p>Hy vọng cuốn s&aacute;ch sẽ gi&uacute;p bạn c&oacute; c&aacute;i nh&igrave;n s&acirc;u sắc, r&otilde; r&agrave;ng hơn về bộ m&ocirc;n t&acirc;m l&yacute; học tội phạm v&agrave; c&oacute; thể r&egrave;n luyện th&ecirc;m sự tư duy, nhạy b&eacute;n.</p>', 2021, NULL, 280, 20, 9, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (137, N'Dám Bị Ghét', N'8935235239159', N'Bìa Mềm', CAST(63375.00 AS Decimal(12, 2)), CAST(119000.00 AS Decimal(12, 2)), CAST(97500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/y/h/yho27ekd.jpg', N'Kishimi Ichiro, Koga Fumitake', N'<p><strong>D&aacute;m Bị Gh&eacute;t</strong></p>
<p>C&aacute;c mối quan hệ x&atilde; hội thật mệt mỏi.</p>
<p>Cuộc sống sao m&agrave; nhạt nhẽo v&agrave; v&ocirc; nghĩa.</p>
<p>Bản th&acirc;n m&igrave;nh xấu x&iacute; v&agrave; k&eacute;m cỏi.</p>
<p>Qu&aacute; khứ đầy buồn đau c&ograve;n tương lai th&igrave; mờ mịt.</p>
<p>Y&ecirc;u cầu của người kh&aacute;c thật khắc nghiệt v&agrave; phi l&yacute;.</p>
<p>TẠI SAO BẠN CỨ PHẢI SỐNG THEO KHU&Ocirc;N MẪU NGƯỜI KH&Aacute;C ĐẶT RA?</p>
<p>Dưới h&igrave;nh thức một cuộc đối thoại giữa Ch&agrave;ng thanh ni&ecirc;n v&agrave; Triết gia, cuốn s&aacute;ch tr&igrave;nh b&agrave;y một c&aacute;ch sinh động v&agrave; hấp dẫn những n&eacute;t ch&iacute;nh trong tư tưởng của nh&agrave; t&acirc;m l&yacute; học Alfred Adler, người được mệnh danh l&agrave; một trong &ldquo;ba người khổng lồ của t&acirc;m l&yacute; học hiện đại&rdquo;, s&aacute;nh ngang với Freud v&agrave; Jung. Kh&aacute;c với Freud cho rằng qu&aacute; khứ v&agrave; ho&agrave;n cảnh l&agrave; động lực l&agrave;m n&ecirc;n con người ta của hiện tại, Adler chủ trương &ldquo;cuộc đời ta l&agrave; do ta lựa chọn&rdquo;, v&agrave; t&acirc;m l&yacute; học Adler được gọi l&agrave; &ldquo;t&acirc;m l&yacute; học của l&ograve;ng can đảm&rdquo;.</p>
<p>Bạn bất hạnh kh&ocirc;ng phải do qu&aacute; khứ v&agrave; ho&agrave;n cảnh, c&agrave;ng kh&ocirc;ng phải do thiếu năng lực. Bạn chỉ thiếu &ldquo;can đảm&rdquo; m&agrave; th&ocirc;i. N&oacute;i một c&aacute;ch kh&aacute;c, bạn kh&ocirc;ng đủ &ldquo;can đảm để d&aacute;m hạnh ph&uacute;c&rdquo;. [...] Bởi can đảm để d&aacute;m hạnh ph&uacute;c bao gồm cả &ldquo;can đảm để d&aacute;m bị gh&eacute;t&rdquo; nữa. [...] Chỉ khi d&aacute;m bị người kh&aacute;c gh&eacute;t bỏ, ch&uacute;ng ta mới c&oacute; được tự do, c&oacute; được hạnh ph&uacute;c.</p>', 2023, NULL, 333, 8, 13, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (138, N'Cẩm Nang Tuổi Dậy Thì Dành Cho Bạn Trai (Tái Bản 2023)', N'8936067608748', N'Bìa Mềm', CAST(38025.00 AS Decimal(12, 2)), CAST(90000.00 AS Decimal(12, 2)), CAST(58500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8936067608748.jpg', N'Hà Minh', N'<p><strong>Cẩm Nang Tuổi Dậy Th&igrave; D&agrave;nh Cho Bạn Trai</strong></p>
<p>Cho d&ugrave; c&oacute; l&agrave; cậu b&eacute; v&ocirc; tư đến thế n&agrave;o đi chăng nữa th&igrave; chắc hẳn khi bước v&agrave;o tuổi dậy th&igrave; c&aacute;c em cũng sẽ cảm nhận v&agrave; ch&uacute; &yacute; đến những biến đổi về t&acirc;m sinh l&iacute; của bản th&acirc;n v&agrave; thấy ch&uacute;ng cũng v&ocirc; c&ugrave;ng rắc rối. Trong khi rất nhiều chuyện mới chỉ hiểu biết nửa vời, c&aacute;c em đ&atilde; phải đối diện với nhiều vấn đề như chuyện cơ thể dậy th&igrave;, chuyện quan hệ t&igrave;nh cảm hay những tr&aacute;ch nhiệm m&agrave; giới t&iacute;nh của c&aacute;c em phải g&aacute;nh v&aacute;c, thậm ch&iacute; c&ograve;n phải đối diện với những mối nguy hiểm v&agrave; c&aacute;m dỗ xấu xa. Phải l&agrave;m thế n&agrave;o mới c&oacute; thể h&oacute;a giải những b&iacute; ẩn n&agrave;y? N&ecirc;n giữ k&iacute;n trong l&ograve;ng hay t&acirc;m sự với bạn b&egrave;? N&ecirc;n thẳng thắn hỏi bố mẹ, thầy c&ocirc; hay vụng trộm t&igrave;m hiểu từ những k&ecirc;nh th&ocirc;ng tin &ldquo;ngầm&rdquo;&hellip; H&atilde;y đọc cuốn s&aacute;ch n&agrave;y nh&eacute;!</p>', 2023, NULL, 268, 19, 6, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (139, N'Cẩm Nang Tuổi Dậy Thì Dành Cho Bạn Gái (Tái Bản 2023)', N'8936067608663', N'Bìa Mềm', CAST(42250.00 AS Decimal(12, 2)), CAST(100000.00 AS Decimal(12, 2)), CAST(65000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8936067608663.jpg', N'Hà Minh', N'<p><strong>Cẩm Nang Tuổi Dậy Th&igrave; D&agrave;nh Cho Bạn G&aacute;i</strong></p>
<p>Bước v&agrave;o lứa tuổi dậy th&igrave;, c&aacute;c bạn g&aacute;i sẽ dần cảm nhận được những biến đổi cả về t&acirc;m l&iacute; v&agrave; sinh l&iacute;. Những biến đổi đ&oacute; kh&ocirc;ng chỉ khiến bạn g&aacute;i cảm thấy bất ngờ th&uacute; vị m&agrave; c&ograve;n l&agrave;m c&aacute;c bạn thấy t&ograve; m&ograve;, xấu hổ, c&ugrave;ng với một ch&uacute;t bỡ ngỡ, lo lắng; biết bao nhi&ecirc;u điều c&aacute;c bạn muốn biết, cần biết nhưng lại ngại ng&ugrave;ng kh&ocirc;ng d&aacute;m hỏi bố mẹ, thầy c&ocirc;. Những c&acirc;u hỏi đ&oacute; dần trở th&agrave;nh một dấu hỏi lớn m&agrave; mỗi bạn giấu k&iacute;n trong l&ograve;ng, chỉ d&aacute;m nhỏ to t&acirc;m sự c&ugrave;ng bạn b&egrave; th&acirc;n thiết nhất m&agrave; th&ocirc;i.</p>
<p>H&atilde;y để cuốn s&aacute;ch n&agrave;y bầu bạn v&agrave; gi&uacute;p b&eacute; c&oacute; một tuổi dậy th&igrave; kh&ocirc;ng kh&oacute; khăn!</p>', 2023, NULL, 288, 11, 12, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (140, N'BộHọc Cho Ai? Học Để Làm Gì? - Tập 1 (Tái Bản 2019)', N'8935244820607', N'Bìa Mềm', CAST(22425.00 AS Decimal(12, 2)), CAST(40000.00 AS Decimal(12, 2)), CAST(34500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_183175.jpg', N'Tiêu Vệ, Lê Tâm', N'<p>Ch&uacute;ng ta kh&ocirc;ng thể lựa chọn được xuất th&acirc;n của m&igrave;nh, nhưng bằng sự cần c&ugrave; chăm chỉ, c&ugrave;ng với nghị lực ki&ecirc;n định v&agrave; tinh thần kh&ocirc;ng khuất phục trước kh&oacute; khăn, ch&uacute;ng ta c&oacute; thể lựa chọn việc kh&ocirc;ng ngừng học tập, d&ugrave;ng tri thức v&agrave; năng lực để thay đổi cuộc đời. Cuộc sống ph&iacute;a trước đầy thử th&aacute;ch v&agrave; cơ hội. Một người nếu c&oacute; t&agrave;i năng v&agrave; sở trường m&agrave; x&atilde; hội cần đến th&igrave; d&ugrave; anh ta ở bất k&igrave; ho&agrave;n cảnh n&agrave;o trong x&atilde; hội, sớm muộn sẽ c&oacute; một ng&agrave;y được thi thố t&agrave;i năng, gi&uacute;p &iacute;ch cho đời.</p>
<p>Cuốn s&aacute;ch Học cho ai? Học để l&agrave;m g&igrave;? gi&uacute;p c&aacute;c em hiểu được &yacute; nghĩa của việc học, khơi dậy tiềm năng học tập của bản th&acirc;n, trở th&agrave;nh những học tr&ograve; th&iacute;ch học v&agrave; học giỏi, đặt nền tảng vững chắc cho con đường đi tới tương lai.</p>', 2019, NULL, 176, 10, 10, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (141, N'Cẩm Nang Tuổi Dậy Thì - Lớn Lên Thật Tuyệt - Dành Cho Bạn Trai', N'8935244876161', N'Bìa Mềm', CAST(65000.00 AS Decimal(12, 2)), CAST(115000.00 AS Decimal(12, 2)), CAST(100000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935244876161.jpg', N'Scott Todnem, Anjan Sarkar', N'<p>Hẳn bạn trẻ n&agrave;o cũng từng nghe đến hoặc đang trải qua một trong những khoảng thời gian kh&oacute; khăn nhất trong cuộc đời: tuổi dậy th&igrave;. Đang l&agrave; một cậu nh&oacute;c b&igrave;nh thường, l&agrave;m những thứ m&agrave; đ&aacute;m trẻ con thường l&agrave;m, rồi &ndash; B&Ugrave;M! &ndash; dậy th&igrave; ập đến. Biết bao thay đổi về cơ thể v&agrave; t&acirc;m l&iacute;, biết bao k&igrave; vọng từ bạn b&egrave;, gia đ&igrave;nh, trường lớp, sở th&iacute;ch c&aacute; nh&acirc;n v&agrave; c&aacute;c mối quan hệ x&atilde; hội... dường như đổ xuống c&ugrave;ng l&uacute;c.</p>
<p>Nếu bạn đang băn khoăn trăn trở về tất cả những thay đổi đang diễn ra, th&igrave; đừng lo &ndash;&nbsp;<strong><em>Lớn L&ecirc;n Thật Tuyệt! &ndash; D&agrave;nh Cho Bạn Trai</em></strong>&nbsp;c&oacute; tất cả những g&igrave; bạn cần biết để c&oacute; thể tự tin trưởng th&agrave;nh hết &yacute;. Cuốn s&aacute;ch sẽ l&agrave; kim chỉ nam đồng h&agrave;nh c&ugrave;ng bạn tr&ecirc;n h&agrave;nh tr&igrave;nh xoay xở với v&ocirc; v&agrave;n đảo lộn về thể chất v&agrave; cảm x&uacute;c.</p>
<p>-&nbsp;<strong><em>Tri thức l&agrave; sức mạnh</em></strong>: S&aacute;ch cung cấp những th&ocirc;ng tin chi tiết, dễ hiểu để đ&oacute;n nhận những thay đổi thể chất trong h&agrave;nh tr&igrave;nh băng qua dậy th&igrave;.</p>
<p>-&nbsp;<strong><em>Đ&oacute;n nhận mọi cảm x&uacute;c</em></strong>: Gi&uacute;p bạn biết c&aacute;ch đối diện với những cảm x&uacute;c mạnh, bằng c&aacute;ch viện đến tr&iacute; s&aacute;ng tạo, thể dục thể thao&hellip;</p>
<p>-&nbsp;<strong><em>Chia sẻ những vấn đề gần gũi</em></strong>: Nhận lời khuy&ecirc;n về c&aacute;ch đối mặt với những thử th&aacute;ch ng&agrave;y nay như mạng x&atilde; hội, &aacute;p lực đồng trang lứa, v.v...</p>', 2022, NULL, 152, 8, 7, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (142, N'Từ Cô Bé Đến Cô Nàng - Tuổi Dậy Thì Và Những Thay Đổi Diệu Kỳ', N'8935212369893', N'Bìa Mềm', CAST(36725.00 AS Decimal(12, 2)), CAST(69000.00 AS Decimal(12, 2)), CAST(56500.00 AS Decimal(12, 2)), N'https://res.cloudinary.com/dabxzdaf8/image/upload/v1748970514/Book_cover/xuiysymoexozps6vo0v7.webp', N'Phương Phương', N'<p><strong>Từ C&ocirc; B&eacute; Đến C&ocirc; N&agrave;ng - Tuổi Dậy Th&igrave; V&agrave; Những Thay Đổi Diệu Kỳ</strong></p>
<p>Tuổi dậy th&igrave; v&agrave; những thay đổi diệu kỳ sẽ đồng h&agrave;nh c&ugrave;ng em, mang đến cho em những lời khuy&ecirc;n hữu &iacute;ch, gi&uacute;p em giải đ&aacute;p những vấn đề kh&oacute; n&oacute;i ở tuổi dậy th&igrave;.</p>
<p>Với 6 chương, 12 chủ đề lớn, hơn 130 vấn đề được đưa ra xoay quanh những thay đổi của cơ thể, t&acirc;m sinh l&yacute; lứa tuổi dậy th&igrave;, vừa mang đến c&aacute;i nh&igrave;n tổng quan song cũng rất chi tiết về giai đoạn đ&aacute;ng nhớ n&agrave;y.</p>
<p>Thay v&igrave; hoang mang v&agrave; lo lắng khi thấy những thay đổi bất ngờ của cơ thể, giờ đ&acirc;y c&aacute;c em sẽ c&oacute; những kiến thức nền tảng để tự chăm s&oacute;c bản th&acirc;n, tự tin kh&ocirc;n lớn.</p>', 2024, NULL, 184, 6, 5, 100)
