INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (166, N'Chú Cá Con Và Ngôi Sao Nhỏ', N'9786042244268', N'Bìa Mềm', CAST(30875.00 AS Decimal(12, 2)), CAST(55000.00 AS Decimal(12, 2)), CAST(47500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/c/h/chu-ca-va-ngoi-sao-nho_bia.jpg', N'Phạm Anh Xuân', N'<p><strong>Ch&uacute; C&aacute; Con V&agrave; Ng&ocirc;i Sao Nhỏ</strong></p>
<p>&ldquo;Thơ ca l&agrave; &ldquo;hạt giống&rdquo; đầu ti&ecirc;n của t&acirc;m hồn. Những b&agrave;i đồng dao hay điệu h&aacute;t ru ch&iacute;nh l&agrave; dạng thức của thơ ca đ&atilde; trao truyền biết bao thế hệ. Những đứa trẻ c&ograve;n chưa biết đọc, chưa biết viết; nhưng đ&atilde; c&oacute; thể nghe, hiểu, thuộc v&agrave; nhớ ng&ocirc;n ngữ, h&igrave;nh ảnh, c&acirc;u chuyện v&agrave; tạo n&ecirc;n cảm x&uacute;c. T&ocirc;i lu&ocirc;n viết thơ cho trẻ với t&acirc;m niệm: Ng&ocirc;n ngữ dễ hiểu, c&acirc;u chuyện dễ nhớ, h&igrave;nh ảnh gần gũi v&agrave; đặc biệt l&agrave; cần tạo n&ecirc;n cảm x&uacute;c t&iacute;ch cực. V&agrave; t&ocirc;i tin thơ ca g&oacute;p phần vun đắp t&acirc;m hồn hạnh ph&uacute;c trẻ thơ!&rdquo; - PHẠM ANH XU&Acirc;N</p>
<p>T&Aacute;C PHẨM DỰ GIẢI THƯỞNG VĂN HỌC KIM ĐỒNG LẦN THỨ NHẤT 2023-2025</p>
<p>---</p>
<p><strong>Nh&agrave; b&aacute;o, nh&agrave; thơ Phạm Anh Xu&acirc;n</strong>&nbsp;hiện đang sống v&agrave; l&agrave;m việc tại H&agrave; Nội.</p>
<p>Anh c&oacute; những s&aacute;ng t&aacute;c từ khi c&ograve;n rất trẻ. Y&ecirc;u qu&yacute; c&aacute;c bạn nhỏ, những t&aacute;c phẩm của anh lu&ocirc;n hướng về trẻ thơ. Một số b&agrave;i thơ của anh được chọn giới thiệu trong s&aacute;ch gi&aacute;o khoa Ngữ văn.</p>
<p>Anh đoạt Giải thưởng của Hội đồng Gi&aacute;m khảo GIẢI DẾ M&Egrave;N về văn học thiếu nhi năm 2023 cho t&aacute;c phẩm &ldquo;Ngh&eacute; Ọ hai xo&aacute;y&rdquo;</p>
<p><strong><em>C&aacute;c t&aacute;c phẩm đ&atilde; xuất bản</em></strong><strong><em>:</em></strong></p>
<p><strong>Thơ:</strong></p>
<p>&bull; Ấm &ecirc;m ngộ nghĩnh</p>
<p>&bull; Tuổi thơ trong trẻo</p>
<p>&bull; Trồng nụ trồng hoa</p>
<p>&bull; Bởi v&igrave; y&ecirc;u thương</p>
<p><strong>Truyện d&agrave;i:</strong></p>
<p>&bull; Ngh&eacute; Ọ hai xo&aacute;y</p>
<p>&bull; Con Tun tai vểnh</p>', 2025, NULL, 64, 15, 6, 99)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (167, N'Bộ Sách Fox Chú Cáo Tinh Nghịch (Bộ 8 Cuốn)', N'8935333710475', N'Bìa Mềm', CAST(185250.00 AS Decimal(12, 2)), CAST(348000.00 AS Decimal(12, 2)), CAST(285000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935333710475.jpg', N'Corey R. Talor', N'<p><strong>Bộ S&aacute;ch Fox Ch&uacute; C&aacute;o Tinh Nghịch (Bộ 8 Cuốn)</strong></p>
<p><em>C&aacute;o lu&ocirc;n đầu t&ecirc;u những tr&ograve; nghịch ngợm. Một ng&agrave;y C&aacute;o ta muốn biến th&agrave;nh hổ, ng&agrave;y kia lại chiến đấu với m&ugrave;a đ&ocirc;ng, ng&agrave;y kh&aacute;c lại lướt v&egrave;o v&egrave;o tr&ecirc;n v&aacute;n trượt để kịp giờ ăn trưa. Liệu ch&uacute; C&aacute;o tinh nghịch n&agrave;y c&ograve;n &ldquo;ủ mưu&rdquo; g&igrave; nữa đ&acirc;y? Ba mẹ h&atilde;y c&ugrave;ng b&eacute; lật mở bộ truyện song ngữ n&agrave;y v&agrave; kh&aacute;m ph&aacute; nh&eacute;!</em></p>
<p>Bộ s&aacute;ch&nbsp;<strong>CH&Uacute; C&Aacute;O TINH NGHỊCH</strong>&nbsp;được in tr&ecirc;n giấy offset 150 d&agrave;y dặn, kh&ocirc;ng l&oacute;a mắt khi nh&igrave;n l&acirc;u. B&igrave;a s&aacute;ch l&agrave; giấy Ivory, c&aacute;n mờ, phủ UV. s&aacute;ch song ngữ Việt Anh với:</p>
<p>- Th&ocirc;ng điệp gi&aacute;o dục nhẹ nh&agrave;ng, kh&ocirc;ng gi&aacute;o điều: dạy con y&ecirc;u bản th&acirc;n, vượt qua nỗi sợ b&oacute;ng tối, t&igrave;m thấy niềm vui giữa những điều nhỏ b&eacute;.</p>
<p>- T&igrave;nh tiết h&agrave;i hước, l&ocirc;i cuốn: đưa con v&agrave;o thế giới của tiếng cười với những nh&acirc;n vật gần gũi.</p>
<p>- H&igrave;nh ảnh sinh động, bắt mắt: nu&ocirc;i dưỡng t&acirc;m hồn nghệ thuật trong con ngay từ những năm đầu đời.</p>
<p>- B&igrave;a cứng bền v&agrave; đẹp: con thoải m&aacute;i lật mở nhiều lần, đọc đi đọc lại trong suốt h&agrave;nh tr&igrave;nh tuổi thơ m&agrave; kh&ocirc;ng sợ l&agrave;m quăn, l&agrave;m nh&agrave;u s&aacute;ch.</p>
<p>- Lời kể song ngữ: con vừa thấm nhuần tiếng mẹ đẻ, vừa tiếp x&uacute;c với ngoại ngữ ngay từ những cuốn s&aacute;ch đầu ti&ecirc;n.</p>', 2025, NULL, 256, 8, 1, 100)
