INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (174, N'Ferda - Chú Kiến Tài Ba', N'8935333710383', N'Bìa Mềm', CAST(69225.00 AS Decimal(12, 2)), CAST(130000.00 AS Decimal(12, 2)), CAST(106500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935333710383.jpg', N'Ondřej Sekora', N'<p><strong>Ferda - Ch&uacute; Kiến T&agrave;i Ba</strong></p>
<p>Tr&ocirc;ng k&igrave;a! Đứng tr&ecirc;n b&atilde;i cỏ l&agrave; một ch&uacute; kiến cổ qu&agrave;ng khăn, lưng đeo t&uacute;i. Kh&ocirc;ng ai kh&aacute;c đ&oacute; ch&iacute;nh l&agrave; Ferda &ndash; ch&uacute; kiến t&agrave;i ba sẵn s&agrave;ng nhận mọi nhiệm vụ từ sửa chữa, x&acirc;y lắp đến khu&acirc;n v&aacute;c,&hellip; Với đ&ocirc;i tay kh&eacute;o l&eacute;o, thoắt c&aacute;i ch&uacute; l&agrave;m ra cỗ xe, thoắt c&aacute;i ch&uacute; sửa xong đ&agrave;i cho b&aacute;c Dế, thoắt c&aacute;i lại x&acirc;y cả một c&ocirc;ng vi&ecirc;n giải tr&iacute; cho đ&aacute;m nh&oacute;c bọ.</p>
<p>C&ugrave;ng Ferda gặp gỡ cậu Bọ T&uacute;i biết tuốt, b&aacute;c Dế h&agrave;o ph&oacute;ng, c&ocirc; Bọ X&iacute;t Lửa ngại ng&ugrave;ng, n&agrave;ng Bọ R&ugrave;a đỏng đảnh v&agrave; bước v&agrave;o chuỗi phi&ecirc;u lưu k&igrave; th&uacute; bậc nhất nền văn học thiếu nhi S&eacute;c.</p>
<p>S&aacute;ch in m&agrave;u, h&igrave;nh vẽ xinh xắn, chi tiết</p>
<p>&ndash; S&aacute;ch khổ lớn, chữ in to, chất liệu giấy th&acirc;n thiện với trẻ</p>
<p>&ndash; Chuỗi truyện về nh&acirc;n vật Kiến Ferda gồm 6 cuốn, hiện đ&atilde; được dịch ra 25 ng&ocirc;n ngữ.</p>
<p>&ndash; Bộ truyện đ&atilde; được chuyển thể th&agrave;nh phim hoạt h&igrave;nh 52 tập, do T&acirc;y Đức sản xuất v&agrave; được chiếu ở nhiều nước.</p>
<p>&ndash; S&aacute;ch nằm trong chương tr&igrave;nh quảng b&aacute; văn ho&aacute; của Bộ Văn ho&aacute; Cộng ho&agrave; S&eacute;c nhằm giới thiệu những t&aacute;c phẩm ti&ecirc;u biểu nhất của nền xuất bản S&eacute;c tới Việt Nam.</p>', 2024, NULL, 72, 19, 5, 100)
