INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (197, N'BộTô Màu Phát Triển Não Bộ Cho Bé 1-5 Tuổi - Tập 5', N'8935235235526', N'Bìa Mềm', CAST(8450.00 AS Decimal(12, 2)), CAST(16000.00 AS Decimal(12, 2)), CAST(13000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935235235526.jpg', N'Phạm Ngọc Điệp', N'<p>S&Aacute;CH T&Ocirc; M&Agrave;U PH&Aacute;T TRIỂN N&Atilde;O BỘ&nbsp;<br>D&agrave;nh cho b&eacute; 1-5 tuổi:</p>
<p>Bố mẹ biết chứ, trẻ dưới 18 th&aacute;ng đ&atilde; c&oacute; khả năng chuyển tải suy nghĩ v&agrave; cảm x&uacute;c bằng h&igrave;nh ảnh c&oacute; m&agrave;u sắc. T&ocirc; m&agrave;u gi&uacute;p trẻ r&egrave;n kỹ năng điều khiển vận động của đ&ocirc;i tay, tăng khả năng quan s&aacute;t, được s&aacute;ng tạo v&agrave; tưởng tượng một c&aacute;ch tự nhi&ecirc;n, được luyện khả năng tập trung v&agrave; ki&ecirc;n tr&igrave;, tăng khả năng thưởng thức c&aacute;i đẹp trong cuộc sống. Với trẻ nhỏ tuổi, học l&agrave; chơi v&agrave; chơi l&agrave; học. Tranh t&ocirc; m&agrave;u ch&iacute;nh l&agrave; những "b&agrave;i học" c&oacute; sức mạnh to lớn với trẻ, bố mẹ ạ!</p>', 2022, NULL, 20, 15, 14, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (198, N'Tô Màu Ước Mơ - Lớp Học Mật Ngữ -Tặng Kèm 1 Sticker + 2 Poster', N'9786044135090', N'Bìa Mềm', CAST(23400.00 AS Decimal(12, 2)), CAST(40000.00 AS Decimal(12, 2)), CAST(36000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/b/i/bia1_tomau3.jpg', N'B.R.O Group', N'<p><strong>T&ocirc; M&agrave;u Ước Mơ - Lớp Học Mật Ngữ</strong></p>
<p>M&ugrave;a H&egrave; n&agrave;y, Lớp Học Mật Ngữ đem đến một ấn phẩm tương t&aacute;c th&uacute; vị cho độc giả tuổi tween: S&aacute;ch t&ocirc; m&agrave;u v&agrave; hướng dẫn vẽ c&aacute;c cung ho&agrave;ng đạo.</p>
<p><strong>Top những l&yacute; do cần c&oacute; đặc san n&agrave;y</strong></p>
<p>S&aacute;ch t&ocirc; m&agrave;u (coloring book) của Lớp Học Mật Ngữ hội tụ 7749 &ldquo;c&ocirc;ng năng m&agrave;u nhiệm&rdquo; như:</p>
<p>- C&aacute;nh cửa thần kỳ đưa bạn đến thế giới xinh xỉu của 12 cung ho&agrave;ng đạo.</p>
<p>- Tấm thảm bay chuy&ecirc;n chở ch&uacute;ng ta đến ch&acirc;n trời s&aacute;ng tạo, tha hồ chơi đ&ugrave;a với m&agrave;u sắc v&agrave; khơi gợi người nghệ sĩ trong bạn.</p>
<p>- C&ocirc;ng cụ đa năng vừa thư gi&atilde;n, giải tr&iacute; vừa k&iacute;ch th&iacute;ch sự tập trung, &ldquo;l&uacute;c lắc&rdquo; tr&iacute; &oacute;c.</p>
<p>- Sản phẩm sau khi ho&agrave;n th&agrave;nh c&oacute; thể d&ugrave;ng để treo tường, lưu lại ảnh hoặc sưu tập th&agrave;nh bộ để flex kh&eacute;o khả năng mỹ thuật.</p>
<p><strong>Si&ecirc;u cẩm nang n&acirc;ng tr&igrave;nh họa sĩ</strong></p>
<p>B&ecirc;n cạnh khu vực t&ocirc; m&agrave;u quen thuộc, ấn phẩm c&ograve;n c&oacute; bộ cẩm nang tuyệt đỉnh gi&uacute;p bạn nắm hết b&iacute; thuật của nh&oacute;m họa sĩ B.R.O - t&aacute;c giả vẽ 24 nh&acirc;n vật của lớp học Ho&agrave;ng Đạo v&agrave; Ho&agrave;ng Cung.</p>
<p>&ldquo;Vũ trụ&rdquo; ho&agrave;ng đạo cả c&aacute;c nh&acirc;n vật nam v&agrave; nữ của từng cung đều sẽ được hướng dẫn vẽ chi tiết đến từng m&aacute;i t&oacute;c, phục trang. Từ nay, bạn đ&atilde; c&oacute; thể tự vẽ cung ho&agrave;ng đạo y&ecirc;u th&iacute;ch của m&igrave;nh cực dễ d&agrave;ng.</p>', 2024, NULL, 50, 2, 12, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (199, N'Vở Ô Ly Tập Tô Chữ - Chữ Cái Viết Thường (Dành Cho Bé Chuẩn Bị Vào Lớp 1)', N'8931805616122', N'Bìa Mềm', CAST(6175.00 AS Decimal(12, 2)), CAST(12000.00 AS Decimal(12, 2)), CAST(9500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_217655.jpg', N'Chính An', N'<p>Luyện chữ đẹp, r&egrave;n t&iacute;nh nết.</p>
<p>C&aacute;c em ch&uacute; &yacute;:</p>
<p>1. Tư thế ngồi viết</p>
<p>Đầu hơi c&uacute;i, kh&ocirc;ng t&igrave; ngực xuống b&agrave;n</p>
<p>Mắt c&aacute;ch vở khoảng 20-25cm</p>
<p>Tay phải cầm b&uacute;t, tay tr&aacute;i t&igrave; nhẹ l&ecirc;n m&eacute;p vở để giữ.</p>
<p>Lưng thẳng</p>
<p>Hai ch&acirc;n song song thoải m&aacute;i</p>
<p>2. C&aacute;ch cầm b&uacute;t</p>
<p>Cầm b&uacute;t bằng ba ng&oacute;n tay: ng&oacute;n c&aacute;i, ng&oacute;n trỏ, ng&oacute;n giữa.</p>
<p>Khi viết d&ugrave;ng ba ng&oacute;n tay di chuyển b&uacute;t từ tr&aacute;i sang phải, cầm b&uacute;t nghi&ecirc;ng về b&ecirc;n phải, cổ tay, khủy tay v&agrave; c&aacute;nh tay cử động th&ecirc;m mềm mại, thoải m&aacute;i</p>
<p>Kh&ocirc;ng n&ecirc;n cầm b&uacute;t tay tr&aacute;i.</p>', 2020, NULL, 31, 11, 7, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (200, N'BộBé Yêu Tô Màu - Đội Chó Cứu Hộ Paw Patrol - Tập 2', N'8935072954130', N'Bìa Mềm', CAST(5460.00 AS Decimal(12, 2)), CAST(12000.00 AS Decimal(12, 2)), CAST(8400.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935072954130.jpg', N'Trần Ngọc Bảo Hân', N'<p><strong>B&eacute; Y&ecirc;u T&ocirc; M&agrave;u - Đội Ch&oacute; Cứu Hộ Paw Patrol - Tập 2</strong></p>
<p>Tập t&ocirc; m&agrave;u l&agrave; hoạt động ưa th&iacute;ch của c&aacute;c b&eacute;. Hoạt động n&agrave;y kh&ocirc;ng những gi&uacute;p r&egrave;n luyện đ&ocirc;i tay kh&eacute;o l&eacute;o, đức t&iacute;nh ki&ecirc;n tr&igrave; m&agrave; c&ograve;n c&oacute; thể bồi dưỡng cho b&eacute; khả năng nhận biết m&agrave;u sắc, ph&aacute;t triển &oacute;c s&aacute;ng tạo. Mỗi khi ho&agrave;n th&agrave;nh một bức tranh t&ocirc; m&agrave;u, b&eacute; sẽ dễ d&agrave;ng khắc s&acirc;u h&igrave;nh ảnh thế giới xung quanh h&igrave;nh th&agrave;nh n&ecirc;n quan niệm thẩm mỹ về thế giới quan.</p>
<p>Bộ s&aacute;ch được thực hiện với mong muốn vừa thỏa m&atilde;n sở th&iacute;ch, vừa mang lại cho b&eacute; cơ hội bồi dưỡng kiến thức đầy hữu &iacute;ch.</p>
<p>Mỗi trang t&ocirc; m&agrave;u gồm c&oacute; 2 phần:</p>
<p>Phần h&igrave;nh mẫu (in m&agrave;u)</p>
<p>Phần h&igrave;nh t&ocirc; với k&iacute;ch thước lớn, đường n&eacute;t r&otilde; r&agrave;ng.</p>', 2020, NULL, 16, 2, 1, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (201, N'Hay Vẽ Thì Vẽ Hay - Tập 3 - Nhân Vật Chibi Dễ Thương', N'8936071299833', N'Bìa Mềm', CAST(13650.00 AS Decimal(12, 2)), CAST(25000.00 AS Decimal(12, 2)), CAST(21000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/3/_/3_cover1.jpg', N'Phan Thị', N'<p><strong>Hay Vẽ Th&igrave; Vẽ Hay - Tập 3 - Nh&acirc;n Vật Chibi Dễ Thương</strong></p>
<p>Chỉ bằng v&agrave;i bước đơn giản, b&eacute; c&oacute; thể vẽ những g&igrave; b&eacute; th&iacute;ch. Cuốn s&aacute;ch<strong>&nbsp;Hay Vẽ Th&igrave; Vẽ Hay</strong>&nbsp;sẽ gi&uacute;p b&eacute; tạo ra những h&igrave;nh ảnh ngộ nghĩnh, đ&aacute;ng y&ecirc;u với c&aacute;c chủ đề gần gũi, phong ph&uacute; về động vật, thi&ecirc;n nhi&ecirc;n, đồ d&ugrave;ng, con người,&hellip;&nbsp;<strong><em>S&aacute;ch tập vẽ</em></strong>&nbsp;n&agrave;y c&oacute; hướng dẫn từng bước cho c&aacute;c họa sĩ nh&iacute; bắt tay v&agrave;o vẽ bức tranh đầu đời.</p>
<p>Trong phong c&aacute;ch nghệ thuật chibi c&aacute;c đặc điểm của nh&acirc;n vật thường bị biến dạng một c&aacute;ch đ&aacute;ng y&ecirc;u v&agrave; h&agrave;i hước. Những n&eacute;t vẽ đơn giản; tỉ lệ với đầu to v&agrave; cơ thể nhỏ hơn; tạo ra vẻ đ&aacute;ng y&ecirc;u v&agrave; hồn nhi&ecirc;n cho nh&acirc;n vật. Đ&ocirc;i khi, chibi c&oacute; thể thể hiện c&aacute;c cảm x&uacute;c hoặc t&igrave;nh huống một c&aacute;ch rất h&agrave;i hước v&agrave; độc đ&aacute;o.</p>', 2024, NULL, 30, 14, 2, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (202, N'200 Miếng Bóc Dán Thông Minh - Bảng Chữ Cái (Tái Bản 2018)', N'8935212339155', N'Bìa Mềm', CAST(26812.50 AS Decimal(12, 2)), CAST(55000.00 AS Decimal(12, 2)), CAST(41250.00 AS Decimal(12, 2)), N'https://res.cloudinary.com/dabxzdaf8/image/upload/v1748965517/Book_cover/uzfsfhedvfgtgczwi4rz.webp', N'Nhiều tác giả', N'<p>Đ&acirc;y l&agrave; cuốn s&aacute;ch được tuyển chọn v&agrave; những tr&ograve; chơi d&aacute;n h&igrave;nh, gi&uacute;p cho đ&ocirc;i tay của c&aacute;c em th&ecirc;m linh hoạt, kh&eacute;o l&eacute;o, nhận biết được c&aacute;c h&igrave;nh để b&oacute;c v&agrave; d&aacute;n cho đ&uacute;ng chỗ...<br>Trong s&aacute;ch c&oacute; tặng k&egrave;m hơn 80 miếng b&oacute;c d&aacute;n. Xin tr&acirc;n trọng giới thiệu.</p>', 2018, NULL, 36, 18, 6, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (203, N'300 Miếng Bóc Dán Thông Minh - Phát Triển Tư Duy', N'8935212351133', N'Bìa Mềm', CAST(14625.00 AS Decimal(12, 2)), CAST(30000.00 AS Decimal(12, 2)), CAST(22500.00 AS Decimal(12, 2)), N'https://res.cloudinary.com/dabxzdaf8/image/upload/v1748965573/Book_cover/utzkqkepsaiihtvbra9y.webp', N'Ưu Ưu Thử', N'<p>3-6 tuổi l&agrave; giai đoạn bộ n&atilde;o của trẻ ph&aacute;t triển nhanh nhất để c&oacute; thể nhận thức được m&agrave;u sắc, h&igrave;nh khối, đồ vật, ph&aacute;t triển mạnh mẽ về cả ng&ocirc;n ngữ, tư duy logic v&agrave; khả năng s&aacute;ng tạo... Cũng bởi thế m&agrave; trẻ cần c&oacute; những "c&ocirc;ng cụ" ph&ugrave; hợp để c&oacute; thể n&acirc;ng cao được to&agrave;n diện những kỹ năng của m&igrave;nh. Bộ s&aacute;ch&nbsp;<em><strong>300 miếng b&oacute;c d&aacute;n th&ocirc;ng minh</strong></em>&nbsp;l&agrave; một "thiết kế" đặc biệt ph&ugrave; hợp cho trẻ ở độ tuổi n&agrave;y. Bộ s&aacute;ch gồm 6 cuốn, bao h&agrave;m tổng qu&aacute;t c&aacute;c lĩnh vực ph&aacute;t triển tư duy cần thiết, sẽ gi&uacute;p trẻ:</p>
<p>* Ph&aacute;t huy tối đa khả năng nhận biết thế giới xung quanh, c&aacute;c h&igrave;nh khối, đồ vật.</p>
<p>* N&acirc;ng cao khả năng s&aacute;ng tạo v&agrave; tư duy logic, gi&uacute;p b&eacute; tạo ra những &ldquo;t&aacute;c phẩm&rdquo; độc đ&aacute;o mang c&aacute; t&iacute;nh ri&ecirc;ng.</p>
<p>* Nhận biết v&agrave; ph&acirc;n biệt được ch&iacute;nh x&aacute;c giữa cơ thể người v&agrave; động vật.</p>
<p>* R&egrave;n luyện khả năng ng&ocirc;n ngữ linh hoạt, biết vận dụng ng&ocirc;n ngữ th&iacute;ch hợp trong mỗi t&igrave;nh huống.</p>
<p>* R&egrave;n luyện th&oacute;i quen sinh hoạt nề nếp v&agrave; khoa học.</p>', 2020, NULL, 20, 6, 4, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (204, N'Từ Điển Bằng Tranh - Thế Giới Động Vật (Tái Bản)', N'8935236428392', N'Bìa Cứng', CAST(63700.00 AS Decimal(12, 2)), CAST(120000.00 AS Decimal(12, 2)), CAST(98000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935236428392.jpg', N'Phan Minh Đạo', N'<p>Cuốn s&aacute;ch với nhiều h&igrave;nh ảnh sinh động về c&aacute;c lo&agrave;i động vật gần gũi v&agrave; quen thuộc m&agrave; b&eacute; bắt gặp hằng ng&agrave;y hay những lo&agrave;i vật m&agrave; b&eacute; &iacute;t được biết đến như: c&aacute; mao ti&ecirc;n, rắn san h&ocirc;, chim hồng tước, c&aacute; nh&iacute;m&hellip; gi&uacute;p b&eacute; ph&aacute;t triển khả năng nhận biết.</p>
<p>Cuốn s&aacute;ch c&ograve;n l&agrave; bộ sưu tập thu nhỏ với nhiều h&igrave;nh ảnh gần gũi quen thuộc v&agrave; mới lạ gi&uacute;p b&eacute; trở n&ecirc;n th&iacute;ch th&uacute;.</p>
<p>B&ecirc;n cạnh đ&oacute; h&igrave;nh thức song ngữ gi&uacute;p b&eacute; gia tăng vốn từ vựng cả về Tiếng Việt lẫn Tiếng Anh. Cuốn s&aacute;ch cũng l&agrave; t&agrave;i liệu học từ vựng cho bất cứ bạn nhỏ n&agrave;o y&ecirc;u th&iacute;ch m&ocirc;n Tiếng Anh. C&aacute;c bạn nhỏ c&oacute; thể vừa học được từ vựng vừa học được c&aacute;ch ph&aacute;t &acirc;m.</p>
<p>Bộ s&aacute;ch c&oacute; thiết kế hợp l&yacute;, h&igrave;nh ảnh đẹp, m&agrave;u sắc bắt mắt gi&uacute;p b&eacute; h&agrave;o hứng tiếp cận c&aacute;c kiến thức dễ d&agrave;ng v&agrave; hiệu quả v&agrave; đ&acirc;y kh&ocirc;ng c&ograve;n l&agrave; những trang s&aacute;ch đầy chữ d&agrave;y cộm, kh&ocirc; cứng. Cuốn Từ điển bằng tranh theo phương ph&aacute;p gi&aacute;o dục sớm GLENN DOMAN cho học sinh l&agrave; một sự thay đổi bước ngoặt để đưa từ điển đến gần với học sinh, tạo cảm hứng học tập, hứng khởi t&igrave;m hiểu, th&ocirc;ng qua h&igrave;nh ảnh minh họa để học từ vựng. S&aacute;ch được in đẹp theo ti&ecirc;u chuẩn của Anh quốc, gi&aacute; b&igrave;a thấp để c&oacute; thể đến tay nhiều đối tượng người đọc hơn.</p>', 2022, NULL, 28, 4, 3, 100)
