INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (210, N'Từ Điển Bằng Hình Đầu Tiên Của Bé', N'9786043759006', N'Bìa Mềm', CAST(48256.00 AS Decimal(12, 2)), CAST(128000.00 AS Decimal(12, 2)), CAST(74240.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786043759006.jpg', N'Song Nghi', N'<p>&ldquo;Từ Điển Bằng H&igrave;nh Đầu Ti&ecirc;n Của B&eacute;&rdquo; l&agrave; m&oacute;n qu&agrave; hay v&agrave; &yacute; nghĩa m&agrave; c&aacute;c bậc phụ huynh d&agrave;nh cho c&aacute;c b&eacute;.</p>
<p>Với h&igrave;nh ảnh dễ thương từ nhiều chủ để kh&aacute;c nhau, cuốn s&aacute;ch sẽ gi&uacute;p c&aacute;c b&eacute; x&acirc;y dựng được vốn từ vựng cơ bản.</p>
<p>Cuốn s&aacute;ch l&agrave; tổng hợp từ nhiều chủ đề đa dạng gắn liền với cuộc sống xung quanh, b&eacute; sẽ dễ d&agrave;ng l&agrave;m quen v&agrave; hứng th&uacute; hơn với việc học ngoại ngữ như: Giao th&ocirc;ng, cơ thể, động vật,&hellip;, C&aacute;c bậc phụ huynh sẽ l&agrave; người bạn đồng h&agrave;nh c&ugrave;ng c&aacute;c b&eacute; để l&agrave;m quen v&agrave; chơi với c&aacute;c b&eacute;.</p>
<p>Đ&acirc;y l&agrave; phương ph&aacute;p gi&aacute;o dục trực quan sinh động mới mẻ gi&uacute;p con bạn ng&agrave;y c&agrave;ng h&agrave;o hứng, say m&ecirc;, t&igrave;m hiểu về thế giới xung quanh cũng như l&agrave;m quen với một ng&ocirc;n ngữ mới theo c&aacute;ch tự nhi&ecirc;n nhất.</p>', 2023, NULL, 33, 9, 13, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (211, N'Từ Điển Bằng Hình Của Tôi - Em Thích Miêu Tả (Dành Cho Trẻ Từ 4 - 6 Tuổi)', N'8936067594690', N'Bìa Cứng', CAST(32110.00 AS Decimal(12, 2)), CAST(76000.00 AS Decimal(12, 2)), CAST(49400.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8936067594690_2.jpg', N'Nguyễn Trí Dũng', N'<p>Với nội dung phong ph&uacute;, s&aacute;ch sẽ l&agrave; m&oacute;n qu&agrave; đặc biệt d&agrave;nh tặng cho c&aacute;c em trong việc kh&aacute;m ph&aacute; v&agrave; t&igrave;m hiểu tri thức. Bộ s&aacute;ch kh&ocirc;ng nhằm mục đ&iacute;ch đưa ra c&aacute;c kh&aacute;i niệm v&agrave; định nghĩa, m&agrave; chỉ th&ocirc;ng qua c&aacute;c n&eacute;t đặc trưng cơ bản gi&uacute;p c&aacute;c em dễ d&agrave;ng học được c&aacute;ch nhận biết v&agrave; mi&ecirc;u tả c&aacute;c h&agrave;nh động, sự vật, sự việc,.. Bộ s&aacute;ch c&ograve;n được minh họa bằng h&igrave;nh ảnh 3D đẹp mắt, sinh động, chắc chắn sẽ v&ocirc; c&ugrave;ng hấp dẫn đối với c&aacute;c em.</p>', 2015, NULL, 56, 13, 3, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (212, N'Từ Vựng Đầu Đời Của Bé - 100 Con Số Đầu Tiên', N'8935210306708', N'Bìa Mềm', CAST(49595.00 AS Decimal(12, 2)), CAST(109000.00 AS Decimal(12, 2)), CAST(76300.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935210306708.jpg', N'Nhiều Tác Giả', N'<p>C&aacute;c nh&agrave; khoa học đ&atilde; chứng minh từ 0 đến 6 tuổi l&agrave; độ tuổi quan trọng nhất trong việc h&igrave;nh th&agrave;nh v&agrave; ph&aacute;t triển nh&acirc;n c&aacute;ch, tr&iacute; tuệ của trẻ. Ở giai đoạn n&agrave;y, cha mẹ cần ch&uacute; trọng dạy con những kiến thức v&agrave; từ vựng cơ bản. Những c&acirc;u n&oacute;i đầu đời của con sẽ quyết định vốn từ v&agrave; khả năng giao tiếp của con sau n&agrave;y.</p>
<p>Nhằm hỗ trợ ba mẹ trong việc tăng vốn từ vựng cho trẻ, Bộ s&aacute;ch từ vựng đầu đời của b&eacute; được T&acirc;n Việt Books xuất bản, mang đến những b&agrave;i học cơ bản cho trẻ về những chữ c&aacute;i, số đếm, từ ngữ đầu ti&ecirc;n về nhiều lĩnh vực.</p>
<p>Bộ s&aacute;ch gồm 6 cuốn:&nbsp;<em>100 con số đầu ti&ecirc;n</em>;<em>&nbsp;100 lo&agrave;i động vật đầu ti&ecirc;n</em>;<em>&nbsp;100 phương tiện đầu ti&ecirc;n của b&eacute;</em>;<em>&nbsp;100 từ vựng đầu ti&ecirc;n; 100 từ vựng đầu ti&ecirc;n về trang trại; Số đếm, M&agrave;u sắc, H&igrave;nh dạng.</em></p>
<p>Mỗi cuốn đều gồm nhiều h&igrave;nh minh họa sinh động, ngộ nghĩnh theo chủ đề đa dạng nhằm mang đến hứng th&uacute; cho c&aacute;c b&eacute; trong việc đọc s&aacute;ch. Qua đ&oacute;, bộ s&aacute;ch khuyến kh&iacute;ch c&aacute;c bạn nhỏ học hỏi những kiến thức đầu đời theo c&aacute;ch th&uacute; vị v&agrave; dễ nhớ.</p>
<p>Điểm cộng của bộ s&aacute;ch n&agrave;y c&ograve;n l&agrave; yếu tố song ngữ Anh - Việt hấp dẫn, giới thiệu những từ vựng, h&igrave;nh ảnh, kiến thức cơ bản, gần gũi đầu ti&ecirc;n d&agrave;nh cho b&eacute;.</p>
<p>Mỗi cuốn trong bộ s&aacute;ch chứa đựng một chủ đề thiết thực kh&aacute;c nhau, từ c&aacute;c lo&agrave;i động vật, chữ số, m&agrave;u sắc, h&igrave;nh dạng đến phương tiện di chuyển. Mỗi chủ đề lớn lại được chia th&agrave;nh c&aacute;c chủ đề nhỏ hơn để b&eacute; dễ d&agrave;ng ghi nhớ.</p>
<p>Bộ s&aacute;ch chắc chắn sẽ l&agrave; trợ thủ đắc lực của ba mẹ tr&ecirc;n h&agrave;nh tr&igrave;nh dạy con những kiến thức cơ bản đầu đời, tạo h&agrave;nh trang cho con tr&ecirc;n chặng đường kh&aacute;m ph&aacute; ch&acirc;n trời tri thức.</p>', 2023, NULL, 16, 3, 5, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (213, N'Từ Điển Hình Ảnh Cho Bé - Động Vật (Tái Bản 2019)', N'8935244828498', N'Bìa Mềm', CAST(16900.00 AS Decimal(12, 2)), CAST(30000.00 AS Decimal(12, 2)), CAST(26000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_188750.jpg', N'Lê Bích Thuỷ, Hiếu Minh', N'<p>Bộ s&aacute;ch gồm 10 cuốn, với c&aacute;c chủ đề: Chữ c&aacute;i, Số đếm, M&agrave;u sắc v&agrave; h&igrave;nh dạng, Động vật; Hoa, Tr&aacute;i c&acirc;y, Rau củ, Phương tiện, Đồ d&ugrave;ng, Đồ chơi. Mỗi chủ đề gồm 14 h&igrave;nh ảnh quen thuộc gần gũi với b&eacute; v&agrave; c&aacute;c từ tương ứng với n&oacute; (bằng cả tiếng Việt v&agrave; tiếng Anh) nhằm gi&uacute;p c&aacute;c b&eacute; từ 0-3 tuổi c&oacute; được vốn từ cần thiết, để b&eacute; c&oacute; những h&igrave;nh dung bước đầu về thế giới xung quanh; đồng thời với vốn từ nho nhỏ n&agrave;y b&eacute; sẽ biểu đạt &yacute; nghĩ của m&igrave;nh tốt hơn. Bộ s&aacute;ch c&oacute; thể coi l&agrave; những cuốn s&aacute;ch gi&aacute;o khoa đầu đời dạy b&eacute; những b&agrave;i học đầu ti&ecirc;n đơn giản m&agrave; v&ocirc; c&ugrave;ng &yacute; nghĩa; từ đ&oacute; b&eacute; c&oacute; thể tự tin trong&nbsp; giao tiếp.</p>
<p>S&aacute;ch in tr&ecirc;n giấy Ivory, h&igrave;nh ảnh tươi s&aacute;ng, vui mắt, phần từ ngữ in to dễ đọc, khổ 12,5 x 12,5 cm th&iacute;ch hợp vừa l&agrave;m s&aacute;ch vừa l&agrave;m đồ chơi bền bỉ cho c&aacute;c b&eacute; 0-3 tuổi.</p>', 2019, NULL, 12, 8, 12, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (214, N'Hồi Ký Nguyễn Thị Bình - Gia Đình, Bạn Bè Và Đất Nước', N'8935279173471', N'Bìa Mềm', CAST(98182.50 AS Decimal(12, 2)), CAST(159000.00 AS Decimal(12, 2)), CAST(151050.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/b/_/b_a-gia-_nh_-b_n-b_-v_-_t-n_c_1.jpg', N'Nguyễn Thị Bình', N'<p><strong>NỘI DUNG CH&Iacute;NH</strong></p>
<p>Đ&acirc;y l&agrave; cuốn hồi k&yacute; của b&agrave; Nguyễn Thị B&igrave;nh, nguy&ecirc;n Ph&oacute; Chủ tịch nước, nữ Bộ trưởng Ngoại giao đầu ti&ecirc;n, Trưởng đo&agrave;n đ&agrave;m ph&aacute;n của Ch&iacute;nh phủ C&aacute;ch mạng L&acirc;m thời Cộng h&ograve;a miền Nam Việt Nam tại H&ograve;a đ&agrave;m Paris.</p>
<p>Cuốn s&aacute;ch t&aacute;i hiện cuộc đời của b&agrave;, một nh&acirc;n chứng sống đ&atilde; tham gia, chứng kiến những chuyển biến thăng trầm của lịch sử, từ thời thơ ấu cho đến khi tham gia hoạt động c&aacute;ch mạng, những dấu mốc quan trọng trong cuộc đấu tranh gi&agrave;nh độc lập d&acirc;n tộc v&agrave; cả khi đ&atilde; nghỉ hưu, như b&agrave; đ&atilde; chọn một đầu đề thật giản dị: &ldquo;Gia đ&igrave;nh, bạn b&egrave; v&agrave; đất nước&rdquo; - những nguồn gốc đ&atilde; tạo n&ecirc;n sức mạnh đặc biệt trong b&agrave;.</p>
<p>&ldquo;C&oacute; lẽ b&agrave; l&agrave; người Việt Nam c&oacute; nhiều bạn b&egrave; nhất tr&ecirc;n thế giới, từ những người d&acirc;n thường cho đến c&aacute;c nguy&ecirc;n thủ quốc gia nổi tiếng v&agrave; thuộc nhiều chế độ ch&iacute;nh trị kh&aacute;c nhau. Những năm th&aacute;ng ấy, b&agrave; c&oacute; mặt ở hầu khắp h&agrave;nh tinh, v&agrave; thật lạ, thật đẹp, h&igrave;nh ảnh của một Việt Nam đang chiến đấu khốc liệt lại được đại diện kh&ocirc;ng phải bằng một chiến binh đằng đằng s&aacute;t kh&iacute; m&agrave; l&agrave; một phụ nữ nhỏ nhắn, khi&ecirc;m nhường m&agrave; uy&ecirc;n b&aacute;c, gần gũi m&agrave; sang trọng, sự ki&ecirc;n định kh&ocirc;ng g&igrave; lay chuyển nổi lại được thể hiện ch&iacute;nh bằng một vẻ thong dong đầy tự tin... B&agrave; đem bạn b&egrave; về cho d&acirc;n tộc. V&agrave; đấy l&agrave; một trong những nh&acirc;n tố quan trọng nhất quyết định thắng lợi kỳ lạ của Việt Nam trong thế kỷ qua." (Nh&agrave; văn Nguy&ecirc;n Ngọc)</p>
<p>Trong lịch sử ngoại giao thế giới, Hội nghị Paris về Việt Nam l&agrave; cuộc hội đ&agrave;m k&eacute;o d&agrave;i ng&agrave;y nhất, r&ograve;ng r&atilde; 4 năm, từ năm 1968 đến năm 1973. Hội nghị c&oacute; 4 trưởng đo&agrave;n, trong đ&oacute; c&oacute; duy nhất một nữ trưởng đo&agrave;n - b&agrave; Nguyễn Thị B&igrave;nh - Bộ trưởng Bộ Ngoại giao &ndash; Trưởng đo&agrave;n đ&agrave;m ph&aacute;n của Ch&iacute;nh phủ C&aacute;ch mạng l&acirc;m thời Cộng h&ograve;a miền Nam Việt Nam tại Hội nghị Paris về Việt Nam. . Để c&oacute; được chiến thắng ngoại giao mang t&iacute;nh lịch sử n&agrave;y, c&oacute; sự đ&oacute;ng g&oacute;p hi sinh của cả d&acirc;n tộc Việt Nam, trong đ&oacute; kh&ocirc;ng thể kh&ocirc;ng nhắc đến b&agrave; Nguyễn Thị B&igrave;nh &ndash; một trong những người đại diện c&aacute;c b&ecirc;n k&yacute; hiệp định Paris năm 1973 v&agrave; l&agrave; người phụ nữ duy nhất đặt b&uacute;t k&yacute; v&agrave;o Hiệp định n&agrave;y.</p>
<p>Cuốn s&aacute;ch được b&agrave; Nguyễn Thị B&igrave;nh bắt tay viết từ năm 2007, ho&agrave;n th&agrave;nh v&agrave;o cuối năm 2009 v&agrave; được bổ sung, chỉnh sửa qua c&aacute;c năm 2013, 2014, 2023. Từng trang hồi k&yacute; được thể hiện bằng ng&ocirc;n từ giản dị, kh&ocirc;ng triết l&yacute; cao si&ecirc;u m&agrave; gần gũi, s&acirc;u lắng, nhưng đ&atilde; to&aacute;t l&ecirc;n được tinh thần y&ecirc;u nước, &yacute; thức tr&aacute;ch nhiệm, tấm l&ograve;ng v&igrave; nước v&igrave; d&acirc;n, tạo n&ecirc;n sức nặng trong từng c&acirc;u, từng chữ của cuốn hồi k&yacute;.</p>', 2025, NULL, 268, 5, 13, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (215, N'Sách Điệp Viên Hoàn Hảo X6 - Phạm Xuân Ẩn (Trọn bộ)', N'8935086855737', N'Bìa Mềm', CAST(92300.00 AS Decimal(12, 2)), CAST(178000.00 AS Decimal(12, 2)), CAST(142000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935086855737.jpg', N'Larry Berman', N'https://www.fahasa.com/diep-vien-hoan-hao-x6-pham-xuan-an.html?fhs_campaign=CATEGORY', 2022, NULL, 392, 21, 2, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (216, N'Hồi Ký Nguyễn Thị Bình - Gia Đình, Bạn Bè Và Đất Nước', N'8935279173488', N'Bìa Cứng', CAST(138125.00 AS Decimal(12, 2)), CAST(224000.00 AS Decimal(12, 2)), CAST(212500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/b/_/b_a-gia-_nh_-b_n-b_-v_-_t-n_c_1_1.jpg', N'Nguyễn Thị Bình', N'https://www.fahasa.com/hoi-ky-nguyen-thi-binh-gia-dinh-ban-be-va-dat-nuoc-bia-cung.html?fhs_campaign=CATEGORY', 2025, NULL, 268, 15, 8, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (217, N'Người Thầy (Tái Bản 2023)', N'9786045193327', N'Bìa Mềm', CAST(133575.00 AS Decimal(12, 2)), CAST(267000.00 AS Decimal(12, 2)), CAST(205500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786045193327.jpg', N'Nguyễn Chí Vịnh', N'<p><strong>Người Thầy</strong></p>
<p>Nh&acirc;n vật trung t&acirc;m trong cuốn s&aacute;ch l&agrave; &ocirc;ng Ba Quốc, tức Thiếu tướng, Anh h&ugrave;ng Lực lượng vũ trang (LLVT) nh&acirc;n d&acirc;n Đặng Trần Đức, một nh&agrave; t&igrave;nh b&aacute;o xuất sắc của t&igrave;nh b&aacute;o quốc ph&ograve;ng Việt Nam, một c&aacute;n bộ t&igrave;nh b&aacute;o t&agrave;i năng, hội tụ đầy đủ những phẩm chất của một điệp vi&ecirc;n "chui s&acirc;u, leo cao" ho&agrave;n hảo, một nh&agrave; chỉ huy c&oacute; tầm nh&igrave;n chiến lược, sắc sảo, quyết liệt v&agrave; l&agrave; một người thầy c&oacute; c&aacute; t&iacute;nh đặc biệt, nghi&ecirc;m khắc nhưng v&ocirc; c&ugrave;ng nh&acirc;n văn, s&acirc;u sắc.</p>
<p>Với 500 trang khổ lớn, được bố cục th&agrave;nh 7 chương theo phong c&aacute;ch hiện đại, cuốn s&aacute;ch "Người thầy" kh&ocirc;ng chỉ kể về những đ&oacute;ng g&oacute;p quan trọng của &ocirc;ng Ba Quốc đối với ng&agrave;nh T&igrave;nh b&aacute;o quốc ph&ograve;ng m&agrave; c&ograve;n n&oacute;i về sự mất m&aacute;t, hy sinh thầm lặng của c&aacute; nh&acirc;n &ocirc;ng v&agrave; gia đ&igrave;nh, người th&acirc;n. Cuốn s&aacute;ch đồng thời cũng đem đến cho bạn đọc những c&acirc;u chuyện cuộc đời, những điệp vụ, chiến c&ocirc;ng của một số nh&acirc;n vật nổi tiếng, những nh&agrave; t&igrave;nh b&aacute;o lỗi lạc cũng như những người chỉ huy trực tiếp v&agrave; những đồng đội &ldquo;v&agrave;o sinh ra tử&rdquo; của t&aacute;c giả.</p>
<p>Dưới g&oacute;c nh&igrave;n của t&aacute;c giả, Thiếu tướng Đặng Trần Đức l&agrave; một người sẵn s&agrave;ng hy sinh v&igrave; đất nước dưới sự l&atilde;nh đạo của Đảng, hết m&igrave;nh v&igrave; nhiệm vụ, nghi&ecirc;m khắc về c&ocirc;ng việc nhưng cũng rất đời thường, quan t&acirc;m v&agrave; s&acirc;u s&aacute;t đối với thế hệ trẻ. Với tấm l&ograve;ng k&iacute;nh trọng, cảm phục về người thầy của m&igrave;nh, Thượng tướng Nguyễn Ch&iacute; Vịnh đ&atilde; truyền lửa cho đo&agrave;n vi&ecirc;n, thanh ni&ecirc;n, thế hệ trẻ về t&igrave;nh y&ecirc;u, l&yacute; tưởng c&aacute;ch mạng của Thiếu tướng Đặng Trần Đức, về niềm tin đối với thế hệ trẻ của lớp người đi trước.</p>
<p>Thượng tướng Nguyễn Ch&iacute; Vịnh t&acirc;m sự đ&acirc;y l&agrave; cuốn s&aacute;ch &ocirc;ng viết d&agrave;nh cho c&aacute;c bạn trẻ. C&acirc;u chuyện về Thiếu tướng Đặng Trần Đức cũng như những người đồng đội của &ocirc;ng, kh&ocirc;ng chỉ l&agrave; c&acirc;u chuyện về ri&ecirc;ng &ocirc;ng, về ng&agrave;nh t&igrave;nh b&aacute;o quốc ph&ograve;ng, m&agrave; c&ograve;n l&agrave; những c&acirc;u chuyện về thế hệ Hồ Ch&iacute; Minh, kh&ocirc;ng chỉ l&agrave; lịch sử m&agrave; c&ograve;n l&agrave; gi&aacute; trị của d&acirc;n tộc, của đất nước phải giữ g&igrave;n. Đ&oacute; cũng ch&iacute;nh l&agrave; l&yacute; do để cuốn s&aacute;ch ra mắt bạn đọc.</p>
<p>T&aacute;c giả cũng mong muốn cuốn s&aacute;ch &ldquo;Người thầy&rdquo; đến với bạn đọc n&oacute;i chung, thế hệ trẻ n&oacute;i ri&ecirc;ng như một mảnh gh&eacute;p rất nhỏ về qu&aacute; khứ, qua đ&oacute; để bạn đọc hiểu r&otilde; hơn về gi&aacute; trị của h&ograve;a b&igrave;nh.</p>', 2023, NULL, 498, 19, 14, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (218, N'Sách Điệp Viên Hoàn Hảo X6 - Phạm Xuân Ẩn (Trọn bộ)', N'8935086855720', N'Bìa Cứng', CAST(102700.00 AS Decimal(12, 2)), CAST(198000.00 AS Decimal(12, 2)), CAST(158000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935086855720.jpg', N'Larry Berman', N'<p>Phạm Xu&acirc;n Ẩn, một c&aacute;i t&ecirc;n chứa biết bao điều b&iacute; ẩn, kh&ocirc;ng chỉ với người Việt Nam, m&agrave; đối với cả rất nhiều ch&iacute;nh kh&aacute;ch v&agrave; b&aacute;o ch&iacute; thế giới, đặc biệt l&agrave; b&aacute;o ch&iacute; Mỹ. Người ta đ&atilde; b&igrave;nh luận, tranh c&atilde;i, phỏng đo&aacute;n v&agrave; viết rất nhiều về &ocirc;ng, thậm ch&iacute; c&ograve;n l&agrave;m phim t&agrave;i liệu nhiều tập về &ocirc;ng, nhưng dường như c&ograve;n c&oacute; qu&aacute; nhiều điều vẫn chưa được l&agrave;m s&aacute;ng tỏ. Cho đến khi một người Mỹ bắt tay v&agrave;o cuộc&hellip; Đ&oacute; ch&iacute;nh l&agrave; Larry Berman, nh&agrave; sử học, gi&aacute;o sư ch&iacute;nh trị học thuộc đại học California, một chuy&ecirc;n gia xuất sắc chuy&ecirc;n nghi&ecirc;n cứu về cuộc chiến tranh x&acirc;m lược Việt Nam của Mỹ.</p>
<p>Năm 2007, quyển s&aacute;ch Perfect Spy - The Incredible Double Life of PHAM XUAN AN Time Magazine Reporter &amp; Vietnamese Communist Agent (Điệp vi&ecirc;n ho&agrave;n hảo &ndash; Hai cuộc đời kh&oacute; tin (hay cuộc đời hai mặt theo c&aacute;ch gọi của Phương T&acirc;y về&nbsp;&nbsp; Phạm Xu&acirc;n Ẩn, ph&oacute;ng vi&ecirc;n tạp ch&iacute; Reuters, Time v&agrave; tướng t&igrave;nh b&aacute;o Cộng sản Việt Nam)) của Larry Berman được xuất bản lần đầu ti&ecirc;n tại Mỹ đ&atilde; g&acirc;y chấn động dư luận Mỹ, kiều b&agrave;o Việt Nam ở Mỹ v&agrave; cả ở Việt Nam. V&igrave; trước khi quyển s&aacute;ch n&agrave;y ra đời, rất &iacute;t người biết v&agrave; hiểu về tướng t&igrave;nh b&aacute;o Phạm Xu&acirc;n Ẩn, mặc d&ugrave; &ocirc;ng l&agrave; một nh&acirc;n vật huyền thoại của chiến tranh Việt Nam. C&oacute; lẽ bởi v&igrave; cuộc đời của Phạm Xu&acirc;n Ẩn, cũng giống như t&ecirc;n của &ocirc;ng, chứa đựng nhiều b&iacute; ẩn về con người v&agrave; sự nghiệp của một nh&agrave; t&igrave;nh b&aacute;o vĩ đại, t&agrave;i năng v&agrave; bản lĩnh nhưng lại v&ocirc; c&ugrave;ng khi&ecirc;m nhường, b&igrave;nh dị.</p>
<p>Phạm Xu&acirc;n Ẩn (sinh ng&agrave;y 12/9/1927, mất ng&agrave;y 20/9/2006) tham gia hoạt động c&aacute;ch mạng từ đầu thập ni&ecirc;n 1950, năm 1953 được kết nạp Đảng v&agrave; được giao nhiệm vụ hoạt động điệp b&aacute;o. Nhằm tạo vỏ bọc tốt hơn để c&oacute; thể th&acirc;m nhập s&acirc;u hơn v&agrave;o giới chức ch&iacute;nh quyền v&agrave; qu&acirc;n đội S&agrave;i G&ograve;n, năm 1957 &ocirc;ng được cấp tr&ecirc;n bố tr&iacute; cho sang Mỹ học ng&agrave;nh b&aacute;o ch&iacute;. Năm 1959, Phạm Xu&acirc;n Ẩn về nước, l&agrave;m việc cho H&atilde;ng tin Reuters v&agrave; sau đ&oacute; l&agrave; tạp ch&iacute; h&agrave;ng đầu Time, New York Herald Tribune của Mỹ. Với kiến thức uy&ecirc;n b&aacute;c, hiểu biết rộng, cương trực v&agrave; t&agrave;i năng giao tiếp, ngoại giao kh&aacute;c biệt, độc đ&aacute;o theo kiểu l&atilde;ng tử, h&agrave;o hoa, ngang t&agrave;ng, &ldquo;chửi thề như bắp rang&rdquo;, xuất hiện với phong c&aacute;ch thượng lưu, thừa hưởng văn h&oacute;a được đ&agrave;o tạo ch&iacute;nh qui từ Mỹ, &ocirc;ng đ&atilde; th&acirc;m nhập v&agrave; l&agrave; bạn tri kỷ với c&aacute;c tướng lĩnh, tr&ugrave;m an ninh mật vụ cả Mỹ v&agrave; S&agrave;i G&ograve;n, giới b&aacute;o ch&iacute; Việt Nam Cộng H&ograve;a v&agrave; Mỹ cũng như c&aacute;c ch&iacute;nh kh&aacute;ch ch&oacute;p bu của ch&iacute;nh quyền S&agrave;i G&ograve;n để khai th&aacute;c những th&ocirc;ng tin tuyệt mật mang tầm chiến lược cho cuộc đối đầu của Bắc Việt Nam với Mỹ v&agrave; ch&iacute;nh quyền S&agrave;i G&ograve;n.</p>
<p>Cuộc đời hoạt động t&igrave;nh b&aacute;o đầy ly kỳ hấp dẫn nhưng cũng v&ocirc; c&ugrave;ng hiểm nguy của Phạm Xu&acirc;n Ẩn với b&iacute; danh X6 thuộc cụm t&igrave;nh b&aacute;o H63 được thể hiện một c&aacute;ch trung thực, sinh động trong cuốn&nbsp;<strong>Điệp vi&ecirc;n ho&agrave;n hảo X6</strong>&nbsp;được bổ sung cập nhật mới. Sau 6 năm, cuốn s&aacute;ch với những th&ocirc;ng tin c&oacute; gi&aacute; trị lịch sử giờ đ&acirc;y lại được ra mắt bạn đọc qua một bản dịch đầy đủ v&agrave; cập nhật nhiều th&ocirc;ng tin chưa từng được c&ocirc;ng bố do ch&iacute;nh Phạm Xu&acirc;n Ẩn tiết lộ với t&aacute;c giả Larry Berman c&oacute; ghi &acirc;m.</p>
<p>Với lời hứa chỉ được c&ocirc;ng bố những th&ocirc;ng tin n&agrave;y từng giai đoạn sau khi Phạm Xu&acirc;n Ẩn mất, Larry Berman đ&atilde; mất 6 năm để c&acirc;n nhắc để từng bước c&ocirc;ng bố th&ocirc;ng tin của người đ&atilde; khuất. Trong ấn bản lần n&agrave;y, ở đầu s&aacute;ch c&oacute; lời cảm nhận của nguy&ecirc;n Ph&oacute; Thủ tướng Trương Vĩnh Trọng, với tựa đề &ldquo;Nhớ m&atilde;i một con người&rdquo;, trong đ&oacute; c&oacute; đoạn: &ldquo;Phạm Xu&acirc;n Ẩn l&agrave; nh&agrave; t&igrave;nh b&aacute;o chiến lược cực kỳ quan trọng. Anh đ&atilde; sống một cuộc đời đầy nhiệt huyết giữa hai chiến tuyến, hai l&agrave;n đạn. Một nh&agrave; b&aacute;o Reuters v&agrave; Time được cả ch&iacute;nh kh&aacute;ch Mỹ nể trọng. Một t&igrave;nh b&aacute;o, một người y&ecirc;u nước thật sự đ&atilde; đ&oacute;ng g&oacute;p rất nhiều cho sự nghiệp giải ph&oacute;ng d&acirc;n tộc với một nh&acirc;n c&aacute;ch đặc biệt, một tấm l&ograve;ng của một người Việt Nam ch&acirc;n ch&iacute;nh. Hiếm c&oacute; một nh&agrave; t&igrave;nh b&aacute;o n&agrave;o tr&ecirc;n thế giới để lại những b&iacute; ẩn v&agrave; t&igrave;nh cảm tốt đẹp cho mọi người từ cả hai ph&iacute;a như nh&agrave; t&igrave;nh b&aacute;o Phạm Xu&acirc;n Ẩn&rdquo;.</p>
<p>Trong b&agrave;i Một phần của h&igrave;nh h&agrave;i Tổ quốc viết cho ấn bản mới cuốn Điệp vi&ecirc;n ho&agrave;n hảo, &ocirc;ng Đ&agrave;o Văn Lừng, Vụ trưởng, Trưởng cơ quan Thường trực Ban Tuy&ecirc;n gi&aacute;o Trung ương tại Th&agrave;nh phố Hồ Ch&iacute; Minh khẳng định: &ldquo;Thiếu tướng-Anh h&ugrave;ng LLVT - đ&oacute; l&agrave; sự vinh danh của Tổ quốc d&agrave;nh cho nh&agrave; t&igrave;nh b&aacute;o chiến lược Phạm Xu&acirc;n Ẩn. Nhưng t&ecirc;n tuổi của &Ocirc;ng c&ograve;n đi xa hơn thế, đặc biệt với những người b&ecirc;n kia chiến tuyến. Điều lạ l&ugrave;ng l&agrave; ngay cả khi nhiệm vụ thực sự của &Ocirc;ng được c&ocirc;ng bố, Phạm Xu&acirc;n Ẩn vẫn gi&agrave;nh được sự k&iacute;nh trọng v&agrave; ngưỡng mộ tuyệt đối từ những đối thủ của m&igrave;nh! H&agrave;ng loạt c&aacute;c ch&iacute;nh kh&aacute;ch, nh&agrave; ngoại giao, nh&agrave; nghi&ecirc;n cứu&hellip; từ Mỹ nva2 tr&ecirc;n thế giới khi đến Việt Nam đều mong muốn được diện kiến &ocirc;ng l&agrave; một minh chứng!</p>', 2022, NULL, 391, 4, 13, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (222, N'Cát Bụi Chân Ai - Tặng Kèm Bookmark Bồi Cứng', N'8938536458953', N'Bìa Mềm', CAST(89375.00 AS Decimal(12, 2)), CAST(179000.00 AS Decimal(12, 2)), CAST(137500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/z/6/z6604030037630_d9e236fa3aa83bd7bbcc38178e38933a.jpg', N'Tô Hoài', N'<p><strong>C&aacute;t Bụi Ch&acirc;n Ai</strong></p>
<p>Cuốn hồi k&yacute; được xuất bản lần đầu v&agrave;o năm 1992 đ&atilde; khắc hoạ th&agrave;nh c&ocirc;ng v&agrave; sống động về ch&acirc;n dung c&aacute;c nh&agrave; văn nổi tiếng Nguyễn Tu&acirc;n, Nguy&ecirc;n Hồng, Nguyễn B&iacute;nh, Xu&acirc;n Diệu,.. đồng thời gi&uacute;p ch&uacute;ng ta hiểu r&otilde; hơn về một thời đại văn học.</p>
<p>&ldquo;Đem c&aacute;i duy&ecirc;n đẹp đẽ mọi bề qu&agrave;ng cho Nguyễn Tu&acirc;n c&oacute; thể chưa k&iacute;n nghĩa, m&agrave; cũng kh&ocirc;ng hẳn đ&uacute;ng. Về văn v&agrave; cả về đời. C&oacute; người m&ecirc; Nguyễn Tu&acirc;n như điếu đổ, từng chữ. C&oacute; người chỉ lướt một đoạn đ&atilde; kh&ocirc;ng chịu được c&aacute;i giọng khụng khiệng, khệnh khạng. Triết l&yacute; v&agrave; c&acirc;u văn Nguyễn Tu&acirc;n kh&ocirc;ng giống vị ho&agrave;i sơn trong thang thuốc bắc, ghẻ bổ một t&yacute;, lại v&ocirc; thưởng v&ocirc; phạt. C&aacute;i chơi của Nguyễn Tu&acirc;n cũng thế. Với người n&agrave;y, kh&ocirc;ng thể thiếu Nguyễn Tu&acirc;n. Người kia th&igrave; kh&ocirc;ng chịu đựng được. &Ocirc; hay, người ta ra người ta th&igrave; người ta phải l&agrave; người ta đ&atilde; chứ.&rdquo;</p>', 2025, NULL, 376, 8, 8, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (223, N'Từ Sông Bến Hải Đến Dinh Độc Lập', N'8935251422320', N'Bìa Mềm', CAST(120900.00 AS Decimal(12, 2)), CAST(219000.00 AS Decimal(12, 2)), CAST(186000.00 AS Decimal(12, 2)), N'https://res.cloudinary.com/dabxzdaf8/image/upload/v1748966514/Book_cover/ys46mftkrgelefh5yrv7.webp', N'Thiếu Tướng Hoàng Đan', N'<p><strong>Đ&Aacute;NH GI&Aacute; CỦA BTV VỀ CUỐN S&Aacute;CH</strong></p>
<p>Cuốn&nbsp;<em>Từ s&ocirc;ng Bến Hải đến Dinh Độc Lập</em>&nbsp;nổi bật nhờ g&oacute;c nh&igrave;n trực tiếp của một vị tướng chỉ huy tr&ecirc;n chiến trường, mang đến những ph&acirc;n t&iacute;ch chiến thuật s&acirc;u sắc v&agrave; chi tiết. Thiếu tướng Ho&agrave;ng Đan kh&ocirc;ng chỉ m&ocirc; tả c&aacute;c trận đ&aacute;nh m&agrave; c&ograve;n giải th&iacute;ch r&otilde; r&agrave;ng c&aacute;ch tổ chức, triển khai v&agrave; đối ph&oacute; với những t&igrave;nh huống thực tế, gi&uacute;p người đọc hiểu r&otilde; hơn về nghệ thuật qu&acirc;n sự Việt Nam. Ngo&agrave;i yếu tố chiến lược, cuốn s&aacute;ch c&ograve;n c&oacute; gi&aacute; trị nh&acirc;n văn khi khắc họa tinh thần chiến đấu, sự hy sinh v&agrave; những trăn trở của người l&iacute;nh. Giọng văn ch&acirc;n thực, kh&ocirc;ng khoa trương, kết hợp giữa tư liệu lịch sử v&agrave; trải nghiệm c&aacute; nh&acirc;n gi&uacute;p t&aacute;c phẩm c&oacute; sức thuyết phục mạnh mẽ.</p>
<p><strong>T&Oacute;M TẮT S&Aacute;CH</strong></p>
<p>Cuốn&nbsp;<em>Từ s&ocirc;ng Bến Hải đến Dinh Độc Lập</em>&nbsp;l&agrave; hồi k&yacute; của Thiếu tướng Ho&agrave;ng Đan, ghi lại những trải nghiệm chiến đấu v&agrave; chỉ huy của &ocirc;ng trong c&aacute;c chiến dịch lớn của Qu&acirc;n đội Nh&acirc;n d&acirc;n Việt Nam. Cuốn s&aacute;ch t&aacute;i hiện ch&acirc;n thực những trận đ&aacute;nh quan trọng từ cuộc kh&aacute;ng chiến chống Mỹ, đặc biệt l&agrave; Chiến dịch Quảng Trị 1972, nơi Sư đo&agrave;n 304 do &ocirc;ng chỉ huy đ&atilde; chiến đấu &aacute;c liệt để giữ vững trận địa, v&agrave; Chiến dịch Hồ Ch&iacute; Minh 1975, khi qu&acirc;n ta tiến v&agrave;o S&agrave;i G&ograve;n, giải ph&oacute;ng miền Nam.</p>
<p>B&ecirc;n cạnh c&aacute;c ph&acirc;n t&iacute;ch chiến thuật, s&aacute;ch c&ograve;n phản &aacute;nh tinh thần quả cảm của bộ đội Việt Nam, những hy sinh lớn lao v&agrave; cả những trăn trở của một người l&iacute;nh tr&ecirc;n chiến trường. Qua từng trang s&aacute;ch, độc giả kh&ocirc;ng chỉ hiểu r&otilde; hơn về lịch sử chiến tranh m&agrave; c&ograve;n cảm nhận được tấm l&ograve;ng của một vị tướng tận t&acirc;m với đất nước v&agrave; đồng đội.</p>
<p><strong>CUỐN S&Aacute;CH C&Oacute; G&Igrave; ĐẶC BIỆT</strong></p>
<p>Cuốn&nbsp;<em>Từ s&ocirc;ng Bến Hải đến Dinh Độc Lập</em>&nbsp;đặc biệt ở chỗ kh&ocirc;ng chỉ l&agrave; một cuốn hồi k&yacute; c&aacute; nh&acirc;n m&agrave; c&ograve;n l&agrave; một c&ocirc;ng tr&igrave;nh qu&acirc;n sự gi&aacute; trị. Với tư c&aacute;ch l&agrave; một người chỉ huy trực tiếp tr&ecirc;n chiến trường, Thiếu tướng Ho&agrave;ng Đan mang đến g&oacute;c nh&igrave;n sắc b&eacute;n về chiến lược v&agrave; chiến thuật, gi&uacute;p người đọc hiểu r&otilde; hơn c&aacute;ch Qu&acirc;n đội Nh&acirc;n d&acirc;n Việt Nam tổ chức v&agrave; triển khai c&aacute;c chiến dịch lớn. Những trận đ&aacute;nh quan trọng như Quảng Trị 1972 hay Chiến dịch Hồ Ch&iacute; Minh 1975 được m&ocirc; tả ch&acirc;n thực, kh&ocirc;ng chỉ ở kh&iacute;a cạnh chiến thắng m&agrave; c&ograve;n qua những kh&oacute; khăn, mất m&aacute;t v&agrave; quyết định chiến thuật quan trọng.</p>
<p>B&ecirc;n cạnh yếu tố qu&acirc;n sự, cuốn s&aacute;ch c&ograve;n mang đậm t&iacute;nh nh&acirc;n văn khi t&aacute;i hiện tinh thần quả cảm của người l&iacute;nh, sự hy sinh v&agrave; những trăn trở của một vị tướng tr&ecirc;n chiến trường. Kh&ocirc;ng chỉ kể lại lịch sử, t&aacute;c phẩm c&ograve;n gi&uacute;p thế hệ sau thấu hiểu s&acirc;u sắc hơn về gi&aacute; trị của độc lập, h&ograve;a b&igrave;nh v&agrave; những b&agrave;i học lớn từ chiến tranh. Sự kết hợp giữa hồi k&yacute; c&aacute; nh&acirc;n v&agrave; ph&acirc;n t&iacute;ch chiến thuật khiến cuốn s&aacute;ch trở th&agrave;nh một tư liệu qu&yacute; cho cả người y&ecirc;u lịch sử v&agrave; những ai nghi&ecirc;n cứu về nghệ thuật qu&acirc;n sự Việt Nam.</p>', 2025, NULL, 400, 9, 2, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (224, N'Người Lính Phi Công Kể Chuyện', N'8935244881615', N'Bìa Mềm', CAST(17062.50 AS Decimal(12, 2)), CAST(35000.00 AS Decimal(12, 2)), CAST(26250.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935244881615.jpg', N'Nguyễn Công Huy', N'<p>Trong 12 ng&agrave;y đ&ecirc;m cuối năm 1972, dưới sự l&atilde;nh đạo của Đảng, qu&acirc;n v&agrave; d&acirc;n ta đ&atilde; đ&aacute;nh bại cuộc tập k&iacute;ch đường kh&ocirc;ng chiến lược bằng m&aacute;y bay B-52 của đế quốc Mỹ tr&ecirc;n bầu trời miền Bắc, lập n&ecirc;n chiến thắng&nbsp;<strong>H&agrave; Nội - Điện Bi&ecirc;n Phủ tr&ecirc;n kh&ocirc;ng</strong>, buộc đế quốc Mỹ phải k&iacute; Hiệp định Paris về chấm dứt chiến tranh, lập lại ho&agrave; b&igrave;nh ở Việt Nam, tạo bước ngoặt cho cuộc kh&aacute;ng chiến chống Mỹ, cứu nước đi đến thắng lợi ho&agrave;n to&agrave;n.</p>
<p>G&oacute;p phần trong chiến thắng vang dội n&agrave;y, c&oacute; sự đ&oacute;ng g&oacute;p kh&ocirc;ng nhỏ của Lực lượng Kh&ocirc;ng qu&acirc;n Ti&ecirc;m k&iacute;ch của Qu&acirc;n chủng Ph&ograve;ng kh&ocirc;ng &ndash; Kh&ocirc;ng qu&acirc;n. Cựu phi c&ocirc;ng m&aacute;y bay ti&ecirc;m k&iacute;ch Nguyễn C&ocirc;ng Huy l&agrave; một nh&acirc;n chứng sống, đ&atilde; trực tiếp tham gia chiến đấu tr&ecirc;n bầu trời Thủ đ&ocirc; v&agrave;o những ng&agrave;y th&aacute;ng &aacute;c liệt nhất ấy. T&aacute;c giả đ&atilde; kể lại h&agrave;nh tr&igrave;nh của một người l&iacute;nh phi c&ocirc;ng, từ khi chập chững bước ch&acirc;n v&agrave;o đời l&iacute;nh, đến những ng&agrave;y đầu ti&ecirc;n bỡ ngỡ với bầu trời, cho đến những trận kh&ocirc;ng chiến nảy lửa năm 1972.</p>
<p>D&otilde;i theo h&agrave;nh tr&igrave;nh ấy, độc giả sẽ được hiểu hơn về cuộc sống của những người l&iacute;nh bay, đặc th&ugrave; của những cuộc chiến tr&ecirc;n kh&ocirc;ng, để th&ecirc;m kh&acirc;m phục trước tr&iacute; tuệ, bản lĩnh của người l&iacute;nh, x&uacute;c động trước những hi sinh v&agrave; sự khốc liệt của chiến tranh. D&ugrave; kể về chiến tranh, nhưng trong cuốn s&aacute;ch vẫn hiện l&ecirc;n đ&acirc;u đ&oacute; những h&agrave;o sảng, nụ cười người l&iacute;nh phi c&ocirc;ng giữa hiện thực khắc nghiệt của thời chiến.</p>
<p>Cuốn s&aacute;ch bắt đầu từ thời điểm người thanh ni&ecirc;n trẻ tuổi Nguyễn C&ocirc;ng Huy rời l&agrave;ng qu&ecirc; v&agrave; m&aacute;i trường phổ th&ocirc;ng theo tiếng gọi thi&ecirc;ng li&ecirc;ng của Tổ quốc để nhập ngũ. Anh l&agrave; một trong số c&aacute;c chiến sĩ được cử đi Li&ecirc;n X&ocirc; học l&aacute;i m&aacute;y bay chiến đấu. Vượt qua nhiều kh&oacute; khăn của cuộc sống học tập nơi xa xứ, c&aacute;c học vi&ecirc;n bay trẻ tuổi đều một l&ograve;ng quyết t&acirc;m sớm l&agrave;m chủ m&aacute;y bay v&agrave; bầu trời, t&ocirc;i luyện &yacute; ch&iacute; để trở về qu&ecirc; nh&agrave; chiến đấu bảo vệ Tổ quốc. Phần sau của cuốn s&aacute;ch l&agrave; kh&ocirc;ng kh&iacute; chiến đấu sục s&ocirc;i của c&aacute;c phi c&ocirc;ng ti&ecirc;m k&iacute;ch Việt Nam trong 12 ng&agrave;y đ&ecirc;m cuối năm 1972.&nbsp;</p>
<p>Qua lời kể của t&aacute;c giả Nguyễn C&ocirc;ng Huy, người đọc sẽ phần n&agrave;o h&igrave;nh dung ra sự &aacute;c liệt tr&ecirc;n bầu trời miền Bắc, khi lực lượng kh&ocirc;ng qu&acirc;n ti&ecirc;m k&iacute;ch non trẻ của ta đối đầu với kh&ocirc;ng qu&acirc;n Mỹ h&ugrave;ng hậu, thiện chiến. Từng khoảnh khắc chiến đấu của c&aacute;c phi c&ocirc;ng Phạm Tu&acirc;n, Vũ Xu&acirc;n Thiều&hellip; sẽ khiến ta th&ecirc;m kh&acirc;m phục v&agrave; x&uacute;c động trước bản lĩnh v&agrave; &yacute; ch&iacute; của c&aacute;c bậc cha anh.</p>
<p>Cuộc chiến đ&atilde; qua đi, những người l&iacute;nh người c&ograve;n, người mất, người đ&atilde; ở tuổi &ldquo;xưa nay hiếm&rdquo;. Được nghe v&agrave; đọc những hồi ức từ thế hệ cha anh l&agrave; điều qu&yacute; gi&aacute; cho thế hệ trẻ h&ocirc;m nay. Với &yacute; nghĩa ấy, nh&acirc;n dịp kỉ niệm 50 năm chiến thắng H&agrave; Nội - Điện Bi&ecirc;n Phủ tr&ecirc;n kh&ocirc;ng (1972-2022), Nh&agrave; xuất bản Kim Đồng tr&acirc;n trọng gửi tới độc giả cuốn s&aacute;ch n&agrave;y. Hi vọng bạn đọc h&ocirc;m nay sẽ th&ecirc;m tự h&agrave;o về cha anh đi trước v&agrave; tiếp nối xứng đ&aacute;ng những bước ch&acirc;n anh h&ugrave;ng.</p>', 2022, NULL, 132, 9, 4, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (225, N'Thoát Khỏi Địa Ngục Khmer Đỏ - Hồi Ký Của Một Người Còn Sống', N'8935279163403', N'Bìa Mềm', CAST(37375.00 AS Decimal(12, 2)), CAST(73000.00 AS Decimal(12, 2)), CAST(57500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935279163403.jpg', N'Denise Affonco', N'<p><strong>Tho&aacute;t Khỏi Địa Ngục Khmer Đỏ - Hồi K&yacute; Của Một Người C&ograve;n Sống</strong></p>
<p>Cuốn s&aacute;ch&nbsp;<strong><em>Tho&aacute;t khỏi địa ngục Khmer đỏ &ndash; Hồi k&yacute; của một người c&ograve;n sống</em></strong>&nbsp;l&agrave; cuốn hồi k&yacute; đẫm nước mắt viết về những năm th&aacute;ng kiệt quệ cả về thể x&aacute;c lẫn tinh thần m&agrave; Denise Affon&ccedil;o đ&atilde; phải trải qua. Bằng giọng văn &yacute; nhị nhưng r&otilde; r&agrave;ng, t&aacute;c giả đ&atilde; kể lại kh&aacute; chi tiết, ch&acirc;n thực v&agrave; th&agrave;nh c&ocirc;ng một giai đoạn đặc biệt v&agrave; phi thường của cuộc đời m&igrave;nh, những mất m&aacute;t v&agrave; khổ đau m&agrave; b&agrave; đ&atilde; trải qua trong những năm bị đ&agrave;y ải dưới sự k&igrave;m kẹp của Khmer đỏ cũng như trong thời gian 11 th&aacute;ng sau khi bộ đội Việt Nam v&agrave;o giải ph&oacute;ng nh&acirc;n d&acirc;n Campuchia.</p>
<p>Cuốn s&aacute;ch với lời văn sinh động, ch&acirc;n thực qua lời kể của một người đ&atilde; từng trải qua những năm th&aacute;ng địa ngục ở Campuchia sẽ gi&uacute;p những thế hệ đi sau hiểu hơn, từ đ&oacute; kh&ocirc;ng l&atilde;ng qu&ecirc;n một giai đoạn tang thương của người Campuchia dưới tội &aacute;c diệt chủng của ch&iacute;nh quyền Khmer đỏ, cũng như t&ocirc;n vinh những đ&oacute;ng g&oacute;p to lớn của bộ đội t&igrave;nh nguyện Việt Nam trong sự nghiệp quốc tế cao cả, gi&uacute;p giải ph&oacute;ng đất nước Campuchia, gi&uacute;p người d&acirc;n Campuchia tho&aacute;t khỏi họa diệt chủng, nhưng hiện đang bị một số thế ực t&igrave;m c&aacute;ch phủ nhận.</p>
<p>T&aacute;c giả cuốn s&aacute;ch l&agrave; người mang quốc tịch Ph&aacute;p, l&agrave;m việc tại Đại sứ qu&aacute;n Ph&aacute;p ở Campuchia trước khi qu&acirc;n Khmer đỏ chiếm Thủ đ&ocirc; Phnom Penh n&ecirc;n d&ugrave; rất biết ơn bộ đội Việt Nam đ&atilde; giải ph&oacute;ng b&agrave; v&agrave; người d&acirc;n Campuchia khỏi tay qu&acirc;n Khmer đỏ, nhưng b&agrave; vẫn c&oacute; một số quan điểm, c&aacute;ch nh&igrave;n nhận kh&aacute;c với quan điểm ch&iacute;nh thống của Việt Nam về chủ nghĩa x&atilde; hội, chủ nghĩa cộng sản. T&ocirc;n trọng &yacute; kiến của t&aacute;c giả trong bối cảnh lịch sử cụ thể khi đ&oacute;, ch&uacute;ng t&ocirc;i cố gắng giữ &yacute; kiến của t&aacute;c giả v&agrave; khẳng định đ&oacute; l&agrave; &yacute; kiến ri&ecirc;ng của t&aacute;c giả, kh&ocirc;ng phản &aacute;nh quan điểm của Nh&agrave; xuất bản Ch&iacute;nh trị quốc gia Sự thật.</p>', 2024, NULL, 248, 17, 2, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (226, N'Sách Bác Hồ (Trọn Bộ)', N'8935352616291', N'Bìa Mềm', CAST(28275.00 AS Decimal(12, 2)), CAST(50000.00 AS Decimal(12, 2)), CAST(43500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/t/h/thu-ki-bac-ho-ke-chuyen_bia.jpg', N'Vitali Bianki, Vladimir Sevchenko', N'<p><strong>Thư K&iacute; B&aacute;c Hồ Kể Chuyện</strong></p>
<p>Trải qua 24 năm l&agrave;m thư k&iacute; tận tụy phục vụ B&aacute;c Hồ, 35 năm giữ g&igrave;n v&agrave; ph&aacute;t huy di sản Hồ Ch&iacute; Minh, d&ugrave; đảm nhiệm cương vị n&agrave;o, d&ugrave; hoạt động ở lĩnh vực c&ocirc;ng t&aacute;c n&agrave;o, đồng ch&iacute; Vũ Kỳ lu&ocirc;n lu&ocirc;n thể hiện l&agrave; một người cộng sản trung ki&ecirc;n, vững v&agrave;ng trong mọi thử th&aacute;ch, n&ecirc;u cao tr&aacute;ch nhiệm trước nh&acirc;n d&acirc;n, tận tụy với c&ocirc;ng việc, đo&agrave;n kết th&acirc;n &aacute;i với mọi người, d&igrave;u dắt gi&aacute;o dục v&agrave; đ&agrave;o tạo thế hệ c&aacute;n bộ kế tục sự nghiệp giữ g&igrave;n v&agrave; ph&aacute;t huy gi&aacute; trị di sản của B&aacute;c Hồ để lại cho h&ocirc;m nay, mai sau v&agrave; m&atilde;i m&atilde;i về sau n&agrave;y.</p>
<p>Kỉ niệm 55 ng&agrave;y mất của Chủ tịch Hồ Ch&iacute; Minh (1969-2024), th&acirc;n gửi tới bạn đọc cuốn s&aacute;ch Thư k&iacute; B&aacute;c Hồ kể chuyện &ndash; một phần di sản kh&ocirc;ng hề nhỏ về B&aacute;c Hồ m&agrave; đồng ch&iacute; Vũ Kỳ đ&atilde; lưu giữ v&agrave; mong muốn trao gửi tới nhiều thế hệ sau.</p>
<p><em>&ldquo;Một phế t&iacute;ch d&ugrave; c&oacute; to lớn đến mấy, một khi c&oacute; tiền, c&oacute; kĩ thuật v&agrave; c&oacute; thời gian th&igrave; đều phục dựng lại được. Nhưng mỗi con người một khi đ&atilde; nằm xuống th&igrave; m&atilde;i m&atilde;i mọi c&aacute;i ở trong đầu con người ấy sẽ tan biến v&agrave; kh&ocirc;ng bao giờ c&oacute; thể lấy lại được nữa. Chẳng c&oacute; người từng v&iacute;, mỗi người gi&agrave; nằm xuống l&agrave; mất đi một pho s&aacute;ch qu&yacute;. M&agrave; với Vũ Kỳ, hẳn đ&oacute; phải l&agrave; một pho s&aacute;ch rất qu&yacute;. Bởi lẽ như một định mệnh, cuộc đời của &ocirc;ng gắn b&oacute; với t&ecirc;n tuổi một Con Người gắn với cả một thời đại lịch sử của d&acirc;n tộc, một người đ&atilde; được thế giới đ&aacute;nh gi&aacute; l&agrave; g&oacute;p phần l&agrave;m thay đổi diện mạo h&agrave;nh tinh của ch&uacute;ng ta trong thế kỉ XX. Đ&oacute; l&agrave; Chủ tịch Hồ Ch&iacute; Minh.&rdquo;</em>&nbsp;&ndash; DƯƠNG TRUNG QUỐC</p>
<p>---</p>
<p><strong>VŨ KỲ (1921-2005)</strong></p>
<p>Nguy&ecirc;n qu&aacute;n tại x&atilde; Nguyễn Tr&atilde;i, huyện Thường T&iacute;n, H&agrave; T&acirc;y, nay thuộc H&agrave; Nội.</p>
<p>4/1956 &ndash; 1969: Ch&aacute;nh Văn ph&ograve;ng Chủ tịch nước ki&ecirc;m Thư k&iacute; của Chủ tịch Hồ Ch&iacute; Minh.</p>
<p>1987 &ndash; 1990: Gi&aacute;m đốc Bảo t&agrave;ng Hồ Ch&iacute; Minh.</p>
<p>Được tặng thưởng: Hu&acirc;n chương Hồ Ch&iacute; Minh; Hu&acirc;n chương Kh&aacute;ng chiến hạng Nhất, Nh&igrave;; Bằng khen của Chủ tịch nước T&ocirc;n Đức Thắng&hellip;</p>
<p>&Ocirc;ng qua đời ng&agrave;y 16/4/2005. Cuộc đời v&agrave; sự nghiệp của &ocirc;ng lu&ocirc;n gắn liền với việc g&igrave;n giữ, ph&aacute;t huy gi&aacute; trị l&acirc;u d&agrave;i di sản của B&aacute;c Hồ để lại.</p>', 2024, NULL, 208, 21, 4, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (228, N'Tổng Hành Dinh Trong Mùa Xuân Toàn Thắng - Hồi Ức', N'8935279172863', N'Bìa Mềm', CAST(60450.00 AS Decimal(12, 2)), CAST(118000.00 AS Decimal(12, 2)), CAST(93000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935279172863.jpg', N'Đại Tướng Võ Nguyên Giáp, Phạm Chí Nhân', N'<p><strong>Tổng H&agrave;nh Dinh Trong M&ugrave;a Xu&acirc;n To&agrave;n Thắng - Hồi Ức</strong></p>
<p>Cuốn hồi ức Tổng h&agrave;nh dinh trong m&ugrave;a Xu&acirc;n to&agrave;n thắng gồm 10 chương, trong đ&oacute; Đại tướng d&agrave;nh ch&iacute;n chương viết về c&aacute;c sự kiện lịch sử lớn của d&acirc;n tộc v&agrave; chương cuối c&ugrave;ng tr&igrave;nh b&agrave;y những điều t&acirc;m huyết, đ&uacute;c kết cuộc đời cầm qu&acirc;n quang vinh của m&igrave;nh qua những năm th&aacute;ng khốc liệt của chiến tranh. Cuốn s&aacute;ch gi&uacute;p độc giả thấy r&otilde; bản lĩnh v&agrave; tr&iacute; tuệ Việt Nam ở những thời điểm lịch sử quyết định: nhạy b&eacute;n, s&aacute;ng tạo, quyết đo&aacute;n, nắm bắt thời cơ v&agrave; nỗ lực cao độ nhằm qu&eacute;t sạch qu&acirc;n th&ugrave;.</p>', 2025, NULL, 368, 21, 5, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (229, N'100 Nhà Khoa Học Vĩ Đại Thay Đổi Thế Giới', N'8935210306135', N'Bìa Mềm', CAST(109200.00 AS Decimal(12, 2)), CAST(205000.00 AS Decimal(12, 2)), CAST(168000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/b/_/b_a-1_100-nha-khoa-hoc-vi-dai.jpg', N'Jon Balchin', N'<p><strong>100 Nh&agrave; Khoa Học Vĩ Đại Thay Đổi Thế Giới</strong></p>
<p>Cuộc sống hiện đại ng&agrave;y nay được lấp đầy bởi v&ocirc; v&agrave;n sản phẩm của tr&iacute; tuệ v&agrave; khoa học. Ch&iacute;nh những sản phẩm ấy c&ugrave;ng c&aacute;c phương ph&aacute;p khoa học đ&atilde; tạo n&ecirc;n cuộc c&aacute;ch mạng l&agrave;m thay đổi cả thế giới.</p>
<p>Tuy nhi&ecirc;n, để l&agrave;m được điều đ&oacute; phải kể đến những nh&agrave; khoa học xuất sắc, những người đ&atilde; cống hiến kh&ocirc;ng ngừng cho sự ph&aacute;t triển của nh&acirc;n loại. Nhằm gi&uacute;p mọi người c&oacute; th&ecirc;m hiểu biết về những con người vĩ đại n&agrave;y, t&aacute;c giả Jon Balchin đ&atilde; cho ra đời cuốn s&aacute;ch&nbsp;<em>100 nh&agrave; khoa học vĩ đại thay đổi thế giới</em>.</p>
<p>Trong cuốn s&aacute;ch n&agrave;y, Jon Balchin đ&atilde; giới thiệu một c&aacute;ch ngắn gọn nhưng đầy đủ, dễ nhớ về tiểu sử c&ugrave;ng những th&agrave;nh tựu ti&ecirc;u biểu nhất của 100 &ldquo;người khổng lồ&rdquo; c&oacute; tầm ảnh hưởng tr&ecirc;n thế giới. Với những nỗ lực kh&ocirc;ng ngừng nghỉ trong lĩnh vực khoa học (từ vũ trụ học của Copernicus v&agrave; Galileo đến nhiều cuộc c&aacute;ch mạng thời Trung Cổ của Hippocrates v&agrave; Galen, hay c&acirc;u chuyện của anh em nh&agrave; Wright, nh&agrave; nữ khoa học &ndash; người ti&ecirc;n phong chất ph&oacute;ng xạ Marie Curie v&agrave; thi&ecirc;n t&agrave;i Vật l&yacute; Albert Einstein, Stephen Hawking&hellip;), t&aacute;c giả đ&atilde; khai th&aacute;c rất nhiều lĩnh vực quan trọng trong cuộc sống như vật l&yacute;, sinh học, h&oacute;a học v&agrave; gen.</p>
<p>Mỗi lĩnh vực gồm nhiều ph&aacute;t hiện th&uacute; vị, chẳng hạn như kh&aacute;m ph&aacute; về h&igrave;nh học (Euclid), m&aacute;y in (Gutenberg), k&iacute;nh viễn vọng (Galileo), thuốc nổ (Alfred Nobel), điện thoại (Alexander Graham Bell), ph&acirc;n t&acirc;m học (Freud), radium (Marie Curie) v&agrave; penicillin (Alexander Fleming)&hellip;</p>
<p>Mỗi nh&agrave; khoa học trong cuốn s&aacute;ch được giới thiệu th&ocirc;ng qua 3 &yacute; ch&iacute;nh:</p>
<p><strong>Mốc sự kiện/Ghi ch&uacute; về ng&agrave;y th&aacute;ng</strong>: T&oacute;m tắt những dấu mốc quan trọng trong cuộc đời nghi&ecirc;n cứu của mỗi nh&agrave; khoa học/cặp đ&ocirc;i nh&agrave; khoa học.</p>
<p><strong>Nội dung</strong>:giới thiệu qua về tiểu sử/c&acirc;u chuyện c&aacute; nh&acirc;n, qu&aacute; tr&igrave;nh kh&aacute;m ph&aacute;, tầm quan trọng trong những kh&aacute;m ph&aacute; ti&ecirc;u biểu nhất của họ v&agrave; n&ecirc;u l&ecirc;n tầm ảnh hưởng của những kh&aacute;m ph&aacute; đ&oacute; đối với thế giới.</p>
<p><strong>Di sản/Ảnh hưởng</strong>:cung cấp th&ecirc;m những th&ocirc;ng tin bổ sung về nh&agrave; khoa học được nhắc đến.</p>
<p>Đan xen giữa c&aacute;c th&ocirc;ng tin tr&ecirc;n l&agrave; những c&acirc;u chuyện đầy th&uacute; vị v&agrave; g&acirc;y t&ograve; m&ograve; về sự đột ph&aacute; khoa học. Th&ocirc;ng qua đ&oacute;, bạn đọc c&oacute; thể thấy rằng những nh&agrave; khoa học d&ugrave; phải chịu sự ho&agrave;i nghi v&agrave; những chỉ tr&iacute;ch đầy khắc nghiệt, nhưng vẫn vươn l&ecirc;n v&agrave; th&agrave;nh c&ocirc;ng, x&oacute;a mờ c&aacute;c đường bi&ecirc;n giới giới hạn kho tri thức của nh&acirc;n loại.</p>
<p>Với bố cục được tr&igrave;nh b&agrave;y theo tr&igrave;nh tự thời gian, h&igrave;nh ảnh sinh động v&agrave; nội dung dễ hiểu,&nbsp;<em>100 nh&agrave; khoa học vĩ đại thay đổi thế giới&nbsp;</em>l&agrave; cuốn s&aacute;ch vừa để giải tr&iacute;, vừa cung cấp những th&ocirc;ng tin v&ocirc; c&ugrave;ng thiết thực cho độc giả trong độ tuổi 10+.</p>
<p>C&oacute; thể n&oacute;i, cuốn s&aacute;ch l&agrave; c&acirc;u chuyện về những s&aacute;ng kiến đ&atilde; định h&igrave;nh thế giới ng&agrave;y nay v&agrave; những &yacute; tưởng sẽ định h&igrave;nh tương lai của to&agrave;n nh&acirc;n loại sau n&agrave;y.</p>
<p class="hrqhmh">------</p>
<p class="hrqhmh"><strong>Th&ocirc;ng tin t&aacute;c giả</strong>:</p>
<p class="hrqhmh">Jon Balchin l&agrave; cử nh&acirc;n danh dự tại Đại học London năm 1997. Sau đ&oacute;, &ocirc;ng l&agrave;m việc cho Tập đo&agrave;n dầu kh&iacute; đa quốc gia ExxonMobil một thời gian rồi chuyển sang viết s&aacute;ch to&agrave;n thời gian. Hiện tại, &ocirc;ng l&agrave;m việc v&agrave; sinh sống ở hạt Surrey, Anh.</p>
<p class="hrqhmh">------</p>', 2022, NULL, 208, 15, 5, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (230, N'Sách Bác Hồ (Trọn Bộ)', N'8935352625484', N'Bìa Mềm', CAST(19500.00 AS Decimal(12, 2)), CAST(35000.00 AS Decimal(12, 2)), CAST(30000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/n/h/nhung-ngay-song-gan-bac_bia.jpg', N'Vitali Bianki, Vladimir Sevchenko', N'<p><strong>Những Ng&agrave;y Sống Gần B&aacute;c</strong></p>
<p>Cuốn hồi k&iacute; mộc mạc kể về thời gian hoạt động b&iacute; mật tại n&uacute;i rừng P&aacute;c B&oacute;, c&ugrave;ng một số đồng ch&iacute;, b&agrave; N&ocirc;ng Thị Trưng, một phụ nữ d&acirc;n tộc T&agrave;y, đ&atilde; c&oacute; những th&aacute;ng ng&agrave;y được sống gần B&aacute;c. Được B&aacute;c gi&aacute;o dục, đ&agrave;o tạo, b&agrave; dần trưởng th&agrave;nh, vượt qua những ch&ocirc;ng gai trong cuộc sống ri&ecirc;ng tư v&agrave; c&ocirc;ng việc, trở th&agrave;nh nữ c&aacute;n bộ gương mẫu, nhiệt huyết.</p>
<p><em>&ldquo;Suốt thời gian được sống gần Ch&uacute; Thu, mỗi ng&agrave;y t&ocirc;i c&agrave;ng nhận thấy r&otilde; hơn t&aacute;c phong, nếp sống giản dị của Ch&uacute;. Bao giờ cũng thế, Ch&uacute; chỉ mặc bộ quần &aacute;o N&ugrave;ng bằng vải ch&agrave;m, ống tay rộng, tr&ocirc;ng thật gọn g&agrave;ng giản dị, h&ograve;a hợp với b&agrave; con địa phương P&aacute;c B&oacute;.&rdquo;<br></em>- N&Ocirc;NG THỊ TRƯNG</p>
<p><strong>---</strong></p>
<p><strong>B&agrave; N&Ocirc;NG THỊ TRƯNG</strong></p>
<p>B&agrave; t&ecirc;n thật l&agrave; N&ocirc;ng Thị B&agrave;y, d&acirc;n tộc T&agrave;y, sinh năm 1920, qu&ecirc; x&atilde; Ph&ugrave; Ngọc, huyện h&agrave; Quảng, tỉnh Cao Bằng.</p>
<p>B&agrave; tham gia c&aacute;ch mạng từ khi c&ograve;n rất trẻ, trong những năm 1941-1945, b&agrave; l&agrave; một trong những thanh ni&ecirc;n được l&atilde;nh tụ Nguyễn &Aacute;i Quốc đ&agrave;o tạo tại căn cứ P&aacute;c B&oacute;. Sau c&aacute;ch mạng, b&agrave; l&agrave;m c&ocirc;ng t&aacute;c hội Phụ nữ. Từ năm 1964 đến năm 1980, b&agrave; l&agrave; Ch&aacute;nh &aacute;n T&ograve;a &aacute;n Tỉnh Cao Bằng. B&agrave; nghỉ hưu v&agrave; mất tại Cao Bằng v&agrave;o đầu năm 2003.</p>', 2025, NULL, 120, 17, 14, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (231, N'Sách Bác Hồ (Trọn Bộ)', N'8935352616307', N'Bìa Mềm', CAST(22425.00 AS Decimal(12, 2)), CAST(40000.00 AS Decimal(12, 2)), CAST(34500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/h/o/hoi-ki-ve-bac-ho_gan-ben-bac-va-hoc-o-bac.jpg', N'Vitali Bianki, Vladimir Sevchenko', N'<p><strong>Hồi K&iacute; Về B&aacute;c Hồ - Gần B&ecirc;n B&aacute;c V&agrave; Học Ở B&aacute;c</strong></p>
<p><strong>Hồi K&iacute; Về B&aacute;c Hồ - Gần B&ecirc;n B&aacute;c V&agrave; Học Ở B&aacute;c&nbsp;</strong>tuyển chọn lời kể của một số c&aacute;n bộ cảnh vệ, cận vệ được bảo vệ, kề cận B&aacute;c trong c&aacute;c chiến dịch kh&aacute;ng chiến hoặc khi Người ở tại Phủ Chủ tịch. C&ugrave;ng với đ&oacute; l&agrave; ấn tượng s&acirc;u sắc của những nh&agrave; l&atilde;nh đạo c&aacute;c bộ, ng&agrave;nh về B&aacute;c khi được Người chỉ dạy c&aacute;ch tư duy, l&agrave;m việc v&agrave; phục vụ nh&acirc;n d&acirc;n.</p>
<p>Từ rất sớm, ngay sau th&agrave;nh c&ocirc;ng của C&aacute;ch mạng th&aacute;ng T&aacute;m, B&aacute;c đ&atilde; lu&ocirc;n quan t&acirc;m, động vi&ecirc;n c&aacute;c chị em phụ nữ v&agrave; c&aacute;c ch&aacute;u thiếu ni&ecirc;n, nhi đồng phải mạnh mẽ, độc lập, hết m&igrave;nh vươn l&ecirc;n v&agrave; chứng minh sức lực, tiềm năng lớn lao của m&igrave;nh. Sự quan t&acirc;m n&agrave;y của Người thể hiện trong một g&oacute;c hồi tưởng nhỏ của những vị nữ tướng, nữ c&aacute;n bộ, c&aacute;c em thiếu ni&ecirc;n vừa học vừa l&agrave;m ở phần II của tập s&aacute;ch.</p>
<p><em>&ldquo;Nhớ lại H&agrave; Nội thời chống Mĩ, cuối buổi l&agrave;m việc thứ ba trong ng&agrave;y, gần 23 giờ, mọi người ra về c&ugrave;ng vợ con, gia đ&igrave;nh, nh&agrave; s&agrave;n của B&aacute;c vẫn chiếu ra &aacute;nh đ&egrave;n, nơi ấy c&oacute; lần B&aacute;c bảo đồng ch&iacute; gi&uacute;p việc dẫu đ&atilde; khuya cũng đừng tắt đ&agrave;i đi, cứ để đấy c&oacute; tiếng người cho đỡ vắng. B&aacute;c đ&atilde; nghĩ g&igrave; trước những lưỡi lửa chiến khu v&agrave; trong &aacute;nh đ&egrave;n H&agrave; Nội, về những c&ocirc;ng việc hằng ng&agrave;y, về những con người quanh m&igrave;nh, về d&acirc;n tộc, về thế giới, về c&aacute;i m&ecirc;nh mang s&acirc;u thẳm của đời người?&rdquo;-</em><strong>&nbsp;VIỆT PHƯƠNG</strong></p>
<p><em>&ldquo;Hồ Ch&iacute; Minh l&agrave; tượng trưng cho những gi&aacute; trị cao đẹp trong quan hệ giữa con người với con người: K&iacute;nh gi&agrave;, y&ecirc;u trẻ, t&ocirc;n trọng phụ nữ. Người quan t&acirc;m nhưng lại kh&ocirc;ng x&oacute;t một ai, hi sinh cho tất cả, nhưng lại kh&ocirc;ng m&agrave;ng ch&uacute;t danh lợi n&agrave;o cho bản th&acirc;n. Suốt đời Người sống khi&ecirc;m tốn, giản dị, thanh bạch, tao nh&atilde;.&rdquo;&nbsp;</em>- ĐẠI TƯỚNG&nbsp;<strong>V&Otilde; NGUY&Ecirc;N GI&Aacute;P</strong></p>
<p>---</p>
<p>Chủ tịch Hồ Ch&iacute; Minh đ&atilde; ra đi tr&ograve;n 55 m&ugrave;a xu&acirc;n, song k&iacute; ức về Người vẫn lu&ocirc;n sống động, vẹn nguy&ecirc;n trong lời kể của nhiều tầng lớp nh&acirc;n d&acirc;n từng được tiếp x&uacute;c v&agrave; đồng h&agrave;nh c&ugrave;ng Người, d&ugrave; trong ph&uacute;t gi&acirc;y rất ngắn hay chặng đường d&agrave;i. Rất nhiều lời kể đ&oacute; đ&atilde; v&agrave; đang tiếp tục được tập hợp, bi&ecirc;n soạn th&agrave;nh những cuốn s&aacute;ch, d&agrave;y dặn c&oacute;, nhỏ gọn c&oacute; để trao tới tay lớp lớp người đọc, để ai cũng c&oacute; thể h&igrave;nh dung một Hồ Ch&iacute; Minh sao th&acirc;n thuộc, đời thường, gần gũi m&agrave; đ&aacute;ng k&iacute;nh.</p>
<p>Năm 2009, nh&acirc;n dịp 40 năm thực hiện di ch&uacute;c của B&aacute;c, Nh&agrave; xuất bản Kim Đồng đ&atilde; tiến h&agrave;nh bi&ecirc;n soạn một bộ s&aacute;ch gồm 06 cuốn s&aacute;ch lấy đề t&agrave;i như vậy, với mong muốn trao gửi tới đối tượng bạn đọc thiếu ni&ecirc;n nhi đồng của nh&agrave; xuất bản những c&acirc;u chuyện giản dị, &yacute; nghĩa, h&agrave;m chứa nhiều điều b&igrave;nh dị m&agrave; lớn lao về vị l&atilde;nh tụ của d&acirc;n tộc. Tới nay, sau 15 năm xuất bản, bộ s&aacute;ch được t&aacute;i bản với h&igrave;nh thức, bố cục mới, gồm 02 tập:&nbsp;<em>Hồi K&iacute; Về B&aacute;c Hồ - Gần B&ecirc;n B&aacute;c V&agrave; Học Ở B&aacute;c&nbsp;</em>v&agrave;&nbsp;<em>Hồi K&iacute; Về B&aacute;c Hồ - M&atilde;i Nhớ Ơn Người.</em></p>', 2024, NULL, 168, 19, 5, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (232, N'Phan Tây Hồ Tiên Sinh Lịch Sử', N'9786045855256', N'Bìa Mềm', CAST(15925.00 AS Decimal(12, 2)), CAST(35000.00 AS Decimal(12, 2)), CAST(24500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786045855256.jpg', N'Huỳnh Thúc Kháng', N'<p><span class="apple-converted-space">T&aacute;c giả Minh Vi&ecirc;n Huỳnh Th&uacute;c Kh&aacute;ng đ&atilde; viết về người bạn th&acirc;m giao Phan T&acirc;y Hồ (Phan Chu Trinh) như sau: &ldquo;C&ugrave;i cụi một m&igrave;nh, x&ocirc;ng pha trăm ngả, g&acirc;y th&ugrave; ch&aacute;c o&aacute;n, ngậm đắng nuốt cay; c&agrave;ng ng&atilde; xuống, c&agrave;ng đứng l&ecirc;n, c&agrave;ng bị thua, c&agrave;ng hăng h&aacute;i, trước sau &ocirc;m một chủ nghĩa, lăn m&igrave;nh v&agrave;o c&aacute;i cảnh khổ... m&agrave; t&igrave;m một con đường rộng c&ugrave;ng &ocirc;ng S&agrave;o Nam chia đường đưa tới để cắm n&ecirc;u chỉ lối cho người sau.</span></p>
<p><span class="apple-converted-space">Ấy, dầu như đởm thức kh&ocirc;ng đủ, nhiệt th&agrave;nh kh&ocirc;ng tới nơi, l&agrave;m sao lui m&agrave; địch với x&atilde; hội, tới m&agrave; dẫn đ&agrave;ng cho x&atilde; hội, m&agrave; l&agrave;m một đấng ti&ecirc;n thời nh&acirc;n vật &iacute;t ỏi như thế?</span></p>
<p><span class="apple-converted-space">...Vậy t&oacute;m cả sự t&iacute;ch một đời ti&ecirc;n sinh, chia mấy thời kỳ l&agrave;m một quyển sử, trước biểu bạch t&acirc;m sự một người đại ch&iacute; sĩ, sau c&ugrave;ng để l&agrave;m gương cho người sau, ấy cũng l&agrave; nghĩa vụ một người học giả đối với quốc d&acirc;n m&agrave; phải gắng vậy.&rdquo;</span></p>', 2016, NULL, 98, 4, 1, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (233, N'Khắc Đi Khắc Đến - Hồi Ký', N'9786044835167', N'Bìa Mềm', CAST(75075.00 AS Decimal(12, 2)), CAST(150000.00 AS Decimal(12, 2)), CAST(115500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786044835167.jpg', N'Xuân Phượng', N'<p><strong>Khắc Đi Khắc Đến - Hồi K&yacute;</strong></p>
<p>Kể từ bước đầu ti&ecirc;n v&aacute;c chu&ocirc;ng đi đ&aacute;nh xứ người đầy vấp v&aacute;p, thiếu kinh nghiệm của năm 2001, trong 20 năm đi triển l&atilde;m tranh ở một số nước ch&acirc;u &Aacute;, Ch&acirc;u &Acirc;u, Ch&acirc;u &Uacute;c đến Ch&acirc;u Mỹ, c&agrave;ng d&agrave;y dặn kinh nghiệm c&agrave;ng c&oacute; th&ecirc;m th&agrave;nh tựu.</p>
<p>Nhưng ph&iacute;a sau những nụ cười, những th&agrave;nh c&ocirc;ng ấy l&agrave; những ch&ocirc;ng gai, cạm bẫy r&igrave;nh rập. Gai nhọn hoắt bất ngờ đ&acirc;m thẳng v&agrave;o người, cạm bẫy kh&eacute;o l&eacute;o đua m&igrave;nh v&agrave;o tr&ograve;ng. Đấy l&agrave; những gi&acirc;y ph&uacute;t bang ho&agrave;ng, đi&ecirc;u đứng, lảo đảo gắng gượng kh&ocirc;n c&ugrave;ng để n&iacute;u giữ cho bằng được cuộc sống của ph&ograve;ng tranh than y&ecirc;u, cuộc sống nửa đời sau của t&ocirc;i bước v&agrave; tuổi hưu. Chỉ xin kể v&agrave;i chuyến đi c&ograve;n để lại những điều kh&oacute; qu&ecirc;n&hellip;</p>', 2024, NULL, 220, 10, 3, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (234, N'BộChuyện Tình Các Danh Nhân Việt Nam (Tập 2)', N'9786045859100', N'Bìa Mềm', CAST(52325.00 AS Decimal(12, 2)), CAST(115000.00 AS Decimal(12, 2)), CAST(80500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786045859100_1.jpg', N'Lê Minh Quốc', N'<p>Chuyện T&igrave;nh C&aacute;c Danh Nh&acirc;n Việt Nam (Tập 2)</p>
<p>S&aacute;ch&nbsp;<strong>CHUYỆN T&Igrave;NH C&Aacute;C DANH NH&Acirc;N VIỆT NAM</strong>&nbsp;(hai tập) gi&uacute;p bạn đọc hiểu th&ecirc;m t&igrave;nh cảm s&acirc;u k&iacute;n - những t&igrave;nh cảm rất thật trong đời thường v&agrave; rất đ&aacute;ng cho hậu thế ch&uacute;ng ta tr&acirc;n trọng cũng như cần biết khi nghi&ecirc;n cứu, t&igrave;m hiểu sự nghiệp của c&aacute;c danh nh&acirc;n Việt Nam. Qua đ&oacute;, c&oacute; thể thấy được những t&igrave;nh cảm trong s&aacute;ng, những rung động đầu đời rất m&atilde;nh liệt; những mối t&igrave;nh thủy chung son sắt đ&aacute;ng cho đời sau nhớ m&atilde;i.</p>
<p>L&agrave;m sao c&oacute; thể qu&ecirc;n được những giai nh&acirc;n đ&atilde; g&oacute;p phần kh&ocirc;ng nhỏ cho c&aacute;c bậc danh nh&acirc;n l&agrave;m n&ecirc;n sự nghiệp lớn? C&oacute; thể khẳng định, họ l&agrave; những người lặng lẽ đứng ph&iacute;a sau, nhiều l&uacute;c kh&ocirc;ng ghi lại tuổi t&ecirc;n, nhưng c&ocirc;ng đức của họ thật lớn lao.</p>
<p>Nếu kh&ocirc;ng c&oacute; những phụ nữ biết qu&ecirc;n m&igrave;nh, biết chịu đựng để lo toan cho chồng như b&agrave; Dương Như Ngọc (vợ Ng&ocirc; Quyền), b&agrave; Ba Cẩn (vợ Đề Th&aacute;m), b&agrave; L&ecirc; Thị Tỵ (vợ Phan Ch&acirc;u Trinh), b&agrave; L&ecirc; Thị Lễ (vợ Lương Văn Can), v.v&hellip; liệu c&aacute;c danh nh&acirc;n n&agrave;y c&oacute; để lại sự nghiệp hiển h&aacute;ch như ng&agrave;y nay?</p>
<p>Điều khiến ch&uacute;ng ta cảm động, d&ugrave; kh&ocirc;ng lưu lại tuổi t&ecirc;n như người t&igrave;nh đầu, người vợ của Vũ Kh&acirc;m L&acirc;n, Cao B&aacute; Qu&aacute;t, T&uacute; Xương v.v&hellip; nhưng họ m&atilde;i m&atilde;i l&agrave; h&igrave;nh ảnh đ&aacute;ng tự h&agrave;o của phụ nữ nước Nam ta. V&agrave; cũng qua c&aacute;c mối t&igrave;nh n&agrave;y, ta thấy được tấm l&ograve;ng thủy chung son sắt của b&agrave; Đặng Thị Cẩn, L&ecirc; Ngọc H&acirc;n, B&ugrave;i Thị Xu&acirc;n, Trương Thị S&aacute;u, v.v&hellip; khi d&agrave;nh cho người t&igrave;nh đầu, người chồng của họ.</p>', 2017, NULL, 420, 18, 7, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (235, N'Điệu Nhảy Moon Walk', N'8935352613573', N'Bìa Mềm', CAST(70525.00 AS Decimal(12, 2)), CAST(125000.00 AS Decimal(12, 2)), CAST(108500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/d/i/dieu-nhay-moonwalk_bia.jpg', N'Micheal Jackson', N'<p><strong>Điệu Nhảy Moon Walk</strong></p>
<p>Cuốn tự truyện duy nhất của Michael Jackson, kể về tuổi thơ &ldquo;dường như kh&ocirc;ng c&oacute;&rdquo; v&agrave; tuổi trẻ với những th&agrave;nh c&ocirc;ng &ldquo;chưa từng c&oacute;&rdquo;.</p>
<p>Đam m&ecirc; s&aacute;ng tạo v&ocirc; bờ bến với ca h&aacute;t, s&aacute;ng t&aacute;c, nhảy m&uacute;a, biểu diễn v&agrave; c&ocirc;ng nghệ tr&igrave;nh diễn; ch&acirc;n th&agrave;nh đối diện với những tin đồn; khổ luyện ph&aacute;t triển phong c&aacute;ch đặc trưng; những mối quan hệ c&aacute; nh&acirc;n rất ri&ecirc;ng tư với gia đ&igrave;nh, người th&acirc;n v&agrave; c&aacute;c ng&ocirc;i sao nghệ thuật &ndash; Điệu nhảy Moonwalk (Moonwalk) &ndash; h&eacute; mở c&aacute;nh cửa cuộc đời Vua nhạc Pop&hellip;</p>', 2024, NULL, 352, 3, 13, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (236, N'Châu Nhuận Phát - Đại Hiệp Hồng Kông', N'8935086854327', N'Bìa Mềm', CAST(76440.00 AS Decimal(12, 2)), CAST(168000.00 AS Decimal(12, 2)), CAST(117600.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/d/a/daihiephongkongchaunhuanphat_168k_bia-01.jpg', N'Lin Feng', N'<p><strong><em>h&acirc;u Nhuận Ph&aacute;t - Đại hiệp Hồng K&ocirc;ng</em></strong></p>
<p>Cuốn s&aacute;ch đầy đủ v&agrave; chi tiết nhất về ng&ocirc;i sao điện ảnh Hồng K&ocirc;ng Ch&acirc;u Nhuận Ph&aacute;t từng được ph&aacute;t h&agrave;nh tr&ecirc;n thế giới.</p>
<p>Với mong muốn mang đến một bức tranh to&agrave;n diện, s&acirc;u sắc về cuộc đời diễn vi&ecirc;n Ch&acirc;u Nhuận Ph&aacute;t, First News - Tr&iacute; Việt kh&ocirc;ng chỉ dịch từ một khảo cứu điện ảnh Hồng K&ocirc;ng dựa tr&ecirc;n sự nghiệp Ch&acirc;u Nhuận Ph&aacute;t của Tiến sĩ Lin Feng -&nbsp;<em>&ldquo;Chow Yun-Fat and Territories of Hong Kong Stardom&rdquo;,&nbsp;</em>m&agrave; c&ograve;n tổng hợp, ph&acirc;n t&iacute;ch th&ecirc;m rất nhiều tư liệu qu&yacute; về diễn vi&ecirc;n huyền thoại n&agrave;y để ra mắt độc giả Việt Nam.</p>
<p>Ch&acirc;u Nhuận Ph&aacute;t kh&ocirc;ng chỉ l&agrave; một người được c&ocirc;ng ch&uacute;ng đặc biệt y&ecirc;u mến m&agrave; c&ograve;n l&agrave; biểu tượng lớn của nền điện ảnh mang đậm bản sắc Hồng K&ocirc;ng. Điều n&agrave;y được khẳng định kh&ocirc;ng chỉ bởi t&agrave;i năng v&agrave; sự cống hiến hơn 40 năm tr&ecirc;n m&agrave;n ảnh, m&agrave; c&ograve;n bởi đức độ, nh&acirc;n c&aacute;ch, kh&iacute; chất, nghĩa kh&iacute; v&agrave; sự khi&ecirc;m nhường hiếm c&oacute; của &ldquo;người h&ugrave;ng&rdquo; Ch&acirc;u Nhuận Ph&aacute;t.</p>
<p>&nbsp;Để vinh danh những cống hiến của Ch&acirc;u Nhuận Ph&aacute;t, Đại học Hồng K&ocirc;ng đ&atilde; trao bằng Tiến sĩ Danh dự cho &ocirc;ng v&agrave;o năm 2001. Năm 2003, một nội dung mới về sự nghiệp Ch&acirc;u Nhuận Ph&aacute;t được đưa v&agrave;o trong s&aacute;ch gi&aacute;o khoa tại Hồng K&ocirc;ng. &Ocirc;ng l&agrave; nghệ sĩ Hồng K&ocirc;ng duy nhất c&oacute; được vinh dự n&agrave;y. Ng&agrave;nh Gi&aacute;o dục Hồng K&ocirc;ng cho rằng ch&iacute;nh sự &ldquo;chăm chỉ nỗ lực&rdquo;, &ldquo;khi&ecirc;m tốn&rdquo;, &ldquo;hiếu thảo&rdquo;, &ldquo;tinh thần học hỏi suốt đời&rdquo;, &ldquo;khả năng tự ho&agrave;n thiện&rdquo; v&agrave; &ldquo;t&iacute;nh ch&iacute;nh trực&rdquo; khiến Ch&acirc;u Nhuận Ph&aacute;t trở th&agrave;nh một tấm gương cho lớp trẻ, sinh vi&ecirc;n, học sinh noi theo.</p>
<p>Kh&ocirc;ng chỉ ghi dấu ấn ở tất cả mọi bước ngoặt quan trọng của điện ảnh Hồng K&ocirc;ng, Ch&acirc;u Nhuận Ph&aacute;t c&ograve;n g&oacute;p phần th&uacute;c đẩy cuộc c&aacute;ch mạng vượt giai cấp, truyền cảm hứng cho người Hồng K&ocirc;ng ở mọi tầng lớp vươn l&ecirc;n trong x&atilde; hội. Khi Ch&acirc;u Nhuận Ph&aacute;t tuy&ecirc;n bố hiến tặng to&agrave;n bộ t&agrave;i sản hơn 700 triệu USD của m&igrave;nh cho người ngh&egrave;o, c&oacute; thể n&oacute;i rằng Ch&acirc;u Nhuận Ph&aacute;t ch&iacute;nh l&agrave; một trong những nh&acirc;n vật ti&ecirc;u biểu g&oacute;p phần tạo dựng n&ecirc;n &ldquo;Niềm tự h&agrave;o Hồng K&ocirc;ng&rdquo;.</p>
<p><strong>Ch&acirc;u Nhuận Ph&aacute;t - Đại hiệp Hồng K&ocirc;ng</strong><em>&nbsp;</em>mang đến cho độc giả bức tranh đa dạng của văn h&oacute;a, x&atilde; hội, điện ảnh Hồng K&ocirc;ng từ những năm 1950 cho đến nay. Th&ocirc;ng qua chặng đường điện ảnh v&agrave; sự tương t&aacute;c của Ch&acirc;u Nhuận Ph&aacute;t đến văn h&oacute;a - x&atilde; hội Hồng K&ocirc;ng v&agrave; khu vực, ch&uacute;ng ta hiểu được v&igrave; sao Hồng K&ocirc;ng lại vươn m&igrave;nh trở th&agrave;nh một con rồng ch&acirc;u &Aacute; với những ph&aacute;t triển vượt trội về kinh tế, gi&aacute;o dục; v&agrave; v&igrave; sao người Hồng K&ocirc;ng, giới trẻ Hồng K&ocirc;ng lại l&agrave; những c&ocirc;ng d&acirc;n ưu t&uacute; v&agrave; c&oacute; &yacute; thức về tương lai Hồng K&ocirc;ng.</p>
<p>Một Hương Cảng Hồng K&ocirc;ng đầy sống động v&agrave; thăng trầm hiện l&ecirc;n trong h&agrave;nh tr&igrave;nh của Ch&acirc;u Nhuận Ph&aacute;t với đủ h&agrave;o kh&iacute;, nghĩa t&igrave;nh, bi kịch, nụ cười v&agrave; nước mắt. Sức hấp dẫn của thi&ecirc;n đường mua sắm Hồng K&ocirc;ng, sức hấp dẫn của những ng&ocirc;i sao điện ảnh lừng lẫy một thời như Ch&acirc;u Nhuận Ph&aacute;t, Mai Diễm Phương, Trương Quốc Vinh, Lưu Đức Hoa&hellip; vẫn c&ograve;n trong k&yacute; ức của ch&uacute;ng ta rất l&acirc;u. Do đ&oacute;,&nbsp;<em>&ldquo;Ch&acirc;u Nhuận Ph&aacute;t - Đại hiệp Hồng K&ocirc;ng&rdquo;</em>&nbsp;kh&ocirc;ng chỉ l&agrave; cuốn s&aacute;ch d&agrave;nh cho những người h&acirc;m mộ Ch&acirc;u Nhuận Ph&aacute;t v&agrave; điện ảnh Hồng K&ocirc;ng, cho những ai y&ecirc;u Hồng K&ocirc;ng m&agrave; c&ograve;n cho cả những ai đang đi t&igrave;m một h&igrave;nh mẫu nh&acirc;n c&aacute;ch l&yacute; tưởng để học hỏi. X&eacute;t ở phạm vi to&agrave;n cầu, Ch&acirc;u Nhuận Ph&aacute;t của Hồng K&ocirc;ng chắc chắn nằm trong số những nh&acirc;n vật &ldquo;v&ocirc; tiền kho&aacute;ng hậu&rdquo; đ&atilde; để lại dấu ấn kh&oacute; qu&ecirc;n trong văn h&oacute;a đại ch&uacute;ng.</p>
<p>Nhận định về cuốn s&aacute;ch, Gi&aacute;o sư Julian Stringer của Đại học Nottingham đ&atilde; n&oacute;i:&nbsp;<em>&ldquo;Với nhiều năm nghi&ecirc;n cứu h&igrave;nh tượng - ng&ocirc;i sao xuy&ecirc;n quốc gia Ch&acirc;u Nhuận Ph&aacute;t, t&aacute;c giả Lin Feng đ&atilde; cho ch&uacute;ng ta thấu hiểu h&agrave;nh tr&igrave;nh v&ocirc; tiền kho&aacute;ng hậu của một nghệ sĩ lớn chưa từng c&oacute; tiền lệ tại Hồng K&ocirc;ng, đồng thời kh&aacute;m ph&aacute; những chuyển m&igrave;nh lớn lao của Hồng K&ocirc;ng để trở th&agrave;nh một biểu tượng tỏa s&aacute;ng của ch&acirc;u &Aacute;. Hơn bất kỳ một ai, Ch&acirc;u Nhuận Ph&aacute;t ch&iacute;nh l&agrave; người đ&atilde; l&agrave;m thay đổi &yacute; nghĩa văn h&oacute;a ng&ocirc;i sao kh&ocirc;ng chỉ ở Hồng K&ocirc;ng&rdquo;.</em></p>', 2021, NULL, 364, 10, 2, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (238, N'Trịnh Công Sơn - Thư Tình Gửi Một Người', N'8934974175230', N'Bìa Mềm', CAST(106275.00 AS Decimal(12, 2)), CAST(195000.00 AS Decimal(12, 2)), CAST(163500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8934974175230.jpg', N'Trịnh Công Sơn', N'<p><strong>Trịnh C&ocirc;ng Sơn - Thư T&igrave;nh Gửi Một Người</strong></p>
<p>Tập Thư t&igrave;nh gửi một người của Nh&agrave; xuất bản Trẻ ra mắt nh&acirc;n kỷ niệm mười năm ng&agrave;y nhạc sĩ Trịnh C&ocirc;ng Sơn từ trần (1/4/2001 - 1/4/2011); đầu s&aacute;ch n&agrave;y cũng ở trong số c&aacute;c ấn phẩm đặc biệt ra đời trong th&aacute;ng kỷ niệm 30 năm ng&agrave;y th&agrave;nh lập Nh&agrave; xuất bản Trẻ (1981 - 2011).</p>
<p>Th&ocirc;ng qua những l&aacute; thư của nhạc sĩ Trịnh C&ocirc;ng Sơn gửi c&ocirc; g&aacute;i Huế c&oacute; t&ecirc;n Ng&ocirc; Vũ Dao &Aacute;nh, người đọc kh&ocirc;ng chỉ t&igrave;m thấy vẻ đẹp kỳ diệu của một t&igrave;nh y&ecirc;u huyền nhiệm m&agrave; c&ograve;n hiểu được những lo &acirc;u, dằn vặt triền mi&ecirc;n của nhạc sĩ về kiếp người, về l&ograve;ng tin v&agrave; những điều tốt đẹp đang bị mai một dần trong c&otilde;i nh&acirc;n gian. B&ecirc;n cạnh gia t&agrave;i đồ sộ về &acirc;m nhạc của Trịnh C&ocirc;ng Sơn, đ&acirc;y c&oacute; thể được xem l&agrave; một &aacute;ng văn chương thật ấn tượng trong đời hoạt động nghệ thuật của &ocirc;ng.</p>
<p>Tập Thư t&igrave;nh gửi một người n&agrave;y được thực hiện với hai loại ấn bản: th&ocirc;ng thường v&agrave; đặc biệt.</p>
<p>Trong những l&aacute; thư, c&oacute; kh&aacute; nhiều từ tiếng Ph&aacute;p cũng như c&oacute; nhiều tr&iacute;ch dẫn cần được chuyển sang Việt ngữ hoặc ch&uacute; giải; c&ocirc;ng việc tạm dịch nghĩa v&agrave; ch&uacute; giải c&oacute; thể chưa ho&agrave;n to&agrave;n ch&iacute;nh x&aacute;c với những g&igrave; nhạc sĩ Trịnh C&ocirc;ng Sơn muốn n&oacute;i trong thư. Rất mong được bạn đọc g&oacute;p &yacute; để nếu ấn phẩm t&aacute;i bản trong tương lai sẽ ho&agrave;n chỉnh hơn.</p>', 2022, NULL, 356, 14, 11, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (239, N'Bật Khóc Ở H Mart', N'9786043721911', N'Bìa Mềm', CAST(74425.00 AS Decimal(12, 2)), CAST(140000.00 AS Decimal(12, 2)), CAST(114500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786043721911.jpg', N'Michelle Zauner', N'<p>Một cuốn s&aacute;ch vừa khơi gợi t&acirc;m tr&iacute; tận hưởnghương vị ẩm thực H&agrave;n Quốc đa sắc vừa khiến tr&aacute;i tim đau đ&aacute;u về một c&acirc;u chuyện gia đ&igrave;nh cảm động.</p>
<p>&ldquo;Từ khi mẹ qua đời, t&ocirc;i thường bật kh&oacute;c ở H Mart.&rdquo; Michelle Zauner mở đầu cuốn hồi k&yacute; đầu tay của c&ocirc;, cũng l&agrave; b&agrave;i viết nổi tiếng tr&ecirc;n tờ The New Yorker, &ldquo;Bật kh&oacute;c ở H Mart&rdquo;,bằng một lời tự sự ch&acirc;n th&agrave;nh buồn b&atilde;.Sau sự ra đi đầy đau đớn của người mẹ, Michelle thường đến H Mart &ndash; chuỗi si&ecirc;u thị H&agrave;n Quốc(v&agrave; ch&acirc;u &Aacute;) lớn ở Mỹ &ndash; để giải tỏa v&agrave; t&igrave;m lại bản th&acirc;n, t&igrave;m lại bằng chứng về một nửa d&ograve;ng m&aacute;u H&agrave;n Quốc trong m&igrave;nh. C&ocirc; giận dữ khi nh&igrave;n thấy một người phụ nữ H&agrave;n c&oacute; thể sống l&acirc;u hơn mẹ, chạnh l&ograve;ng khi nh&igrave;n thấy h&igrave;nh ảnh những người th&acirc;n trong c&ugrave;ng một gia đ&igrave;nh chia sẻ những m&oacute;n ăn&hellip; Michelle cảm thấy hoảng sợ khi nh&igrave;n sự ra đi của mẹ đồng nghĩa với sự mất m&aacute;t vĩnh viễn một nửa gốc g&aacute;c H&agrave;n của c&ocirc;, n&ecirc;n xuy&ecirc;n suốt cuốn truyện l&agrave; h&agrave;nh tr&igrave;nh c&ocirc; cố gắng từng ch&uacute;t, từng ch&uacute;t một đi t&igrave;m lại nguồn cội của bản th&acirc;n.<br>Đ&uacute;ng như t&ecirc;n gọi, &ldquo;Bật kh&oacute;c ở H Mart&rdquo; l&agrave; một cuốn s&aacute;ch đẫm nước mắt. N&oacute; xo&aacute;y s&acirc;u v&agrave;o nỗi đaubuồn thăm thẳm của người nghệ sĩ chứng kiến người mẹ kiệt quệ rồi mất v&igrave; căn bệnh ung thư qu&aacute;i &aacute;c. Nhưng kh&ocirc;ng chỉ c&oacute; nước mắt, từng trang hồi k&yacute; của c&ocirc; g&aacute;i trẻ n&agrave;ythấm đẫmc&aacute;c cung bậc cảm x&uacute;c:l&agrave; c&aacute;i ấm &aacute;p củat&igrave;nh y&ecirc;u đ&ocirc;i lứa c&ugrave;ng nắm tay nhau vượt qua biến cố, l&agrave; những xung độtnghẹt thở trong mối quan hệ cha mẹ &ndash; con c&aacute;i tuổi vị th&agrave;nh ni&ecirc;n, l&agrave; t&igrave;nh th&acirc;n dịu d&agrave;ng s&acirc;u lắng của đứa ch&aacute;u g&aacute;i mồ c&ocirc;i với người b&aacute;c bất đồng ng&ocirc;n ngữ m&agrave; mỗi lần đối thoại c&ugrave;ng nhau phải cầu viện Google Dịch&hellip; Cuốn s&aacute;ch l&agrave; cuộc đời của ri&ecirc;ng Michelle v&agrave; mẹ c&ocirc; nhưng c&oacute; thể n&oacute;i kh&ocirc;ng ngoa l&agrave; tất cả những c&ocirc; con g&aacute;i v&agrave; những b&agrave; mẹ đều c&oacute; thể nhận ra m&igrave;nh v&agrave; nhận ra nhau trong c&acirc;u chuyện cảm động n&agrave;y.<br>Trong những cuốn s&aacute;ch viết về văn h&oacute;a H&agrave;n, &ldquo;Bật kh&oacute;c ở H Mart&rdquo; nổi bật l&ecirc;n với c&aacute;ch viết gần gũi, chuyển tải những n&eacute;t đặc trưng của nền văn h&oacute;a đầy sắc m&agrave;u đến bạn đọc. Michelle Zauner kh&ocirc;ng đi v&agrave;o những điều lớn lao, c&ocirc; cũng kh&ocirc;ng diễn giải qu&aacute; nhiều về những m&oacute;n ăn H&agrave;n, c&ocirc; chỉ đơn thuần viết ra những c&acirc;u chuyện ch&acirc;n thực m&agrave; tr&agrave;n đầy cảm x&uacute;c trong cuộc đời m&igrave;nh. C&ocirc; viết về mối quan hệ mẹ con phức tạp nhưng kh&ocirc;ng qu&aacute; đ&agrave; m&agrave; chỉ như kể lại những mảnh gh&eacute;p k&yacute; ức chất chứa ho&agrave;i niệm. Với cuốn s&aacute;ch n&agrave;y, Michelle kh&ocirc;ng chỉ kể với ch&uacute;ng ta c&acirc;u chuyện của ri&ecirc;ng c&ocirc;, n&oacute; c&ograve;n khiến ta nh&igrave;n lại bản th&acirc;n, nh&igrave;n lại mối quan hệ của ch&uacute;ng ta với người mẹ th&acirc;n thương đang đợi ch&uacute;ng ta về nh&agrave;.</p>
<p><strong>T&aacute;c giả</strong></p>
<p>Michelle Zauner sinh năm 1989, l&agrave; nhạc sĩ, ca sĩ, nghệ sĩ guitar v&agrave; nh&agrave; văn c&oacute; cha l&agrave; người Mỹ v&agrave; mẹ l&agrave; người H&agrave;n. C&ocirc; s&aacute;ng lập v&agrave; l&agrave; giọng ca ch&iacute;nh của ban nhạc indie pop Japanese Breakfast. C&aacute;c album Psychopomp (2016) v&agrave; Soft Sounds from Another Planet (2017) của c&ocirc; đ&atilde; thu h&uacute;t được sự ch&uacute; &yacute; của c&aacute;c h&atilde;ng thu &acirc;m lớn tr&ecirc;n thế giới.<br>Khi Zauner 25 tuổi, mẹ c&ocirc; bị chẩn đo&aacute;n mắc ung thư v&agrave; cuốn hồi k&yacute; Bật kh&oacute;c ở H Mart ghi lại ch&acirc;n thực qu&aacute; tr&igrave;nh suy giảm sức khỏe của người mẹ c&ugrave;ng h&agrave;nh tr&igrave;nh t&igrave;m kiếm bản lai diện mục của ch&iacute;nh c&ocirc;. Th&ocirc;ng qua ẩm thực, Zauner kết nối được nhiều hơn với người mẹ vốn độc lập v&agrave; dữ dội của m&igrave;nh, v&agrave; v&igrave; vậy, nơi khiến c&ocirc; nhớ mẹ nhất l&agrave; cửa h&agrave;ng tạp h&oacute;a H&agrave;n Quốc mang t&ecirc;n H Mart&hellip;<br>Dịch giả L&ecirc; Hồng Phương Hạ tốt nghiệp thủ khoa chuy&ecirc;n ng&agrave;nh Ng&ocirc;n ngữ học Đại học Khoa học x&atilde; hội v&agrave; Nh&acirc;n văn &ndash; ĐHQG TP.HCM.<br>Đ&atilde; dịch gần hai mươi đầu s&aacute;ch văn học, thiếu nhi, t&acirc;m l&yacute; &ndash; kỹ năng, kinh tế, khoa học</p>', 2022, NULL, 400, 21, 9, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (240, N'Putin - Logic Của Quyền Lực - Putin: Innenansichten Der Macht', N'8935086853672', N'Bìa Mềm', CAST(87100.00 AS Decimal(12, 2)), CAST(168000.00 AS Decimal(12, 2)), CAST(134000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_216008.jpg', N'Hubert Seipel', N'<p>T&ecirc;n gốc của t&aacute;c phẩm l&agrave; Putin: Innenansichten der Macht. S&aacute;ch gồm 21 chương, do Hubert Seipel thực hiện trong 5 năm (từ năm 2010 đến 2015). T&aacute;c giả đ&atilde; c&oacute; hơn 20 buổi phỏng vấn chuy&ecirc;n s&acirc;u với Putin, đồng thời th&aacute;p t&ugrave;ng &ocirc;ng tr&ecirc;n h&agrave;ng chục chuyến đi trong, ngo&agrave;i nước.</p>
<p>S&aacute;ch mở ra g&oacute;c nh&igrave;n mới về nh&agrave; l&atilde;nh đạo Nga. Putin: Logic của quyền lực ph&aacute;t h&agrave;nh ở Việt Nam cuối th&aacute;ng 11, do dịch giả Phan Xu&acirc;n Loan chuyển ngữ, Nh&agrave; xuất bản Tổng hợp ph&aacute;t h&agrave;nh. Hubert Seipel t&aacute;i hiện những dấu mốc ch&iacute;nh trong cuộc đời Putin. Năm 1975, Putin tốt nghiệp khoa Luật Đại học Tổng hợp Quốc gia Saint Petersburg. Năm 1985, &ocirc;ng trở th&agrave;nh nh&acirc;n vi&ecirc;n t&igrave;nh b&aacute;o đối ngoại của Li&ecirc;n X&ocirc; ở Đức. Năm 1994, &ocirc;ng trở th&agrave;nh ph&oacute; chủ tịch thứ nhất của th&agrave;nh phố qu&ecirc; nh&agrave; Saint Petersburg. Năm 1996, &ocirc;ng chuyển đến Moskva v&agrave; được bổ nhiệm nhiều chức vụ quan trọng trong văn ph&ograve;ng Tổng thống Nga. Cuối năm 1999, &ocirc;ng trở th&agrave;nh Tổng thống Nga.</p>
<p>Khi mới l&ecirc;n nắm quyền, &ocirc;ng phải đối mặt với nhiều kh&oacute; khăn trong giai đoạn "tư nh&acirc;n h&oacute;a" c&aacute;c t&agrave;i sản quốc gia. Putin c&ugrave;ng l&uacute;c phải vực dậy nền kinh tế sa s&uacute;t, giải quyết nạn tham nhũng, chia rẽ d&acirc;n tộc v&agrave; c&aacute;c &acirc;m mưu lật đổ ch&iacute;nh quyền. Cuốn s&aacute;ch đề cập đến cuộc chiến của Putin v&agrave; hai đối thủ lớn - ch&iacute;nh kh&aacute;ch Boris Berezovsky v&agrave; tỷ ph&uacute; v&agrave; Mikhai Khodorkovsky - chủ tập đo&agrave;n dầu kh&iacute; Yukos. Để đảo ngược t&igrave;nh thế kh&oacute; khăn, Putin đ&atilde; t&igrave;m c&aacute;ch tăng trưởng kinh tế, ph&aacute;t triển c&aacute;c dịch vụ y tế, gi&aacute;o dục. Tr&ecirc;n ch&iacute;nh trường quốc tế, &ocirc;ng đưa ra nhiều quyết định cứng rắn, đặc biệt l&agrave; việc phản đối sự mở rộng của Tổ chức Hiệp ước Bắc Đại T&acirc;y Dương (NATO) về ph&iacute;a Đ&ocirc;ng. S&aacute;ch kh&ocirc;ng chứa nhiều th&ocirc;ng tin về đời sống c&aacute; nh&acirc;n của tổng thống.</p>
<p>Trước khi l&agrave;m việc c&ugrave;ng Hubert Seipel, Putin y&ecirc;u cầu đặt ra một ranh giới r&otilde; r&agrave;ng giữa c&ocirc;ng việc v&agrave; đời tư để bảo vệ bản th&acirc;n v&agrave; gia đ&igrave;nh. &Ocirc;ng n&oacute;i: &ldquo;T&ocirc;i hứng th&uacute; với c&aacute;c phương tiện truyền th&ocirc;ng bởi v&igrave; t&ocirc;i l&agrave; ch&iacute;nh kh&aacute;ch v&agrave; l&agrave; Tổng thống Nga, c&ograve;n c&aacute;c con g&aacute;i t&ocirc;i kh&ocirc;ng giữ chức vụ ch&iacute;nh trị, những quan hệ c&aacute; nh&acirc;n của t&ocirc;i kh&ocirc;ng thuộc về c&aacute;c vấn đề ch&iacute;nh trị - đ&oacute; l&agrave; việc ri&ecirc;ng của t&ocirc;i". V&igrave; thế, vợ con &ocirc;ng chỉ được nhắc đến v&agrave;i lần.</p>
<p>Vladimir Vladimirovich Putin sinh năm 1952. &Ocirc;ng l&agrave; tổng thống Nga trong hai nhiệm kỳ từ năm 2000 tới năm 2008, trước khi phải rời điện Kremlin theo Hiến ph&aacute;p l&uacute;c bấy giờ. Putin đảm nhận vai tr&ograve; thủ tướng Nga sau khi &ocirc;ng Dmitry Medvedev tiếp quản vị tr&iacute; tổng thống. Với việc chiến thắng trong cuộc bầu cử năm 2012, Putin c&oacute; nhiệm kỳ tổng thống thứ ba. Năm 2007, Putin được tạp ch&iacute; Times b&igrave;nh chọn l&agrave; Nh&acirc;n vật của năm. Năm 2015, Putin đứng đầu trong danh s&aacute;ch 100 người c&oacute; sức ảnh hưởng nhất thế giới của tạo ch&iacute; n&agrave;y. Tạp ch&iacute; Forbes xếp Putin l&agrave; người quyền lực nhất thế giới trong bốn năm li&ecirc;n tiếp, từ năm 2013 tới năm 2016.</p>
<p>T&aacute;c giả Hubert Seipel sinh năm 1950 ở Wasserlos, Đức. &Ocirc;ng l&agrave; nh&agrave; b&aacute;o, nh&agrave; l&agrave;m phim t&agrave;i liệu. &Ocirc;ng từng nghi&ecirc;n cứu ch&iacute;nh trị, lịch sử, khoa học ch&iacute;nh trị tại tại Đại học Marburg, Đức v&agrave; Trường Kinh tế v&agrave; Khoa học Ch&iacute;nh trị London, Anh. &Ocirc;ng c&oacute; cơ hội tiếp x&uacute;c với Putin từ năm 2010, khi l&agrave;m bộ phim t&agrave;i liệu I, Putin: A Portrait. Sau bộ phim đ&oacute;, &ocirc;ng trở th&agrave;nh nh&agrave; b&aacute;o phương T&acirc;y được tiếp cận gần Putin. &nbsp;</p>', 2020, NULL, 384, 18, 7, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (241, N'Napoleon Đại Đế - Bìa Cứng (Tái Bản 2023)', N'8935270704100', N'Bìa Cứng', CAST(292175.00 AS Decimal(12, 2)), CAST(529000.00 AS Decimal(12, 2)), CAST(449500.00 AS Decimal(12, 2)), N'https://res.cloudinary.com/dabxzdaf8/image/upload/v1748966983/Book_cover/macwrehonq65wv3syjjc.webp', N'Andrew Roberts', N'<p><strong>Napoleon Đại Đế - B&igrave;a Cứng</strong></p>
<p>Napoleon l&agrave; một nh&acirc;n vật đặc biệt vĩ đại v&agrave; hấp dẫn trong lịch sử Ph&aacute;p cũng như lịch sử thế giới. Cuộc đời, sự nghiệp, quan điểm, t&agrave;i năng của &ocirc;ng đ&atilde; l&agrave; chủ đề của h&agrave;ng ngh&igrave;n cuốn s&aacute;ch trong suốt hai thế kỉ qua, v&agrave; c&oacute; lẽ sẽ c&ograve;n được nghi&ecirc;n cứu tiếp trong nhiều thế kỉ sau nữa.</p>
<p>Trong bối cảnh những cuốn s&aacute;ch dịch ra tiếng Việt về &ocirc;ng cũng như về thời hậu C&aacute;ch mạng Ph&aacute;p ở Việt Nam vẫn chỉ đếm tr&ecirc;n đầu ng&oacute;n tay, &iacute;t cả về số lượng lẫn tầm v&oacute;c, th&igrave; cuốn s&aacute;ch Napoleon Đại đế c&oacute; thể xem l&agrave; một hiện tượng bởi tầm v&oacute;c, quy m&ocirc;, t&iacute;nh chất gi&agrave;u sử liệu đ&atilde; l&agrave;m n&ecirc;n gi&aacute; trị đặc biệt của t&aacute;c phẩm.</p>
<p><strong>+VỀ T&Aacute;C GIẢ:</strong></p>
<p>T&aacute;c giả Andrew Roberts, trong cuốn tiểu sử rất đồ sộ n&agrave;y đ&atilde; đi s&acirc;u m&ocirc; tả một c&aacute;ch chi tiết c&aacute;c ho&agrave;n cảnh của thời C&aacute;ch mạng Ph&aacute;p đ&atilde; đưa Napoleon l&ecirc;n đỉnh quyền lực, c&aacute;ch m&agrave; &ocirc;ng đ&atilde; gi&agrave;nh lấy n&oacute; bằng đại b&aacute;c v&agrave; lưỡi l&ecirc;, v&agrave; củng cố quyền lực bằng chiến tranh, đầu ti&ecirc;n với những người Jacobin, sau đ&oacute; l&agrave; dẹp loạn Vand&eacute;e, v&agrave; cuối c&ugrave;ng đem chiến tranh ra ngo&agrave;i bi&ecirc;n giới nước Ph&aacute;p để trở th&agrave;nh ch&uacute;a tể của Ch&acirc;u &Acirc;u lục địa trong một cuộc chiến m&ugrave; qu&aacute;ng chống lại nước Anh nhằm thiết lập một trật tự thế giới do Paris điều khiển.</p>
<p>Nội dung cuộc tọa đ&agrave;m, th&ocirc;ng qua c&aacute;c tư liệu qu&yacute; được n&ecirc;u ra trong cuốn s&aacute;ch, sẽ thảo luận về nh&acirc;n vật vĩ đại v&agrave; hấp dẫn n&agrave;y: Về t&iacute;nh c&aacute;ch, về c&aacute;ch tư duy v&agrave; h&agrave;nh xử của một nh&agrave; l&atilde;nh đạo, một thi&ecirc;n t&agrave;i qu&acirc;n sự, về cuộc chiến đấu của &ocirc;ng v&igrave; l&yacute; tưởng của ch&iacute;nh &ocirc;ng, v&agrave; về những c&aacute;ch nh&igrave;n nhận, đ&aacute;nh gi&aacute; con người n&agrave;y.</p>', 2023, NULL, 1220, 7, 5, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (242, N'Gia Tộc Morgan', N'8935251400236', N'Bìa Mềm', CAST(275600.00 AS Decimal(12, 2)), CAST(499000.00 AS Decimal(12, 2)), CAST(424000.00 AS Decimal(12, 2)), N'https://res.cloudinary.com/dabxzdaf8/image/upload/v1748967028/Book_cover/ogmcfqyg6n5avsprygib.webp', N'Ron Chernow', N'<p>H&igrave;nh th&agrave;nh, ph&aacute;t triển, sụp đổ rồi lại hồi sinh, c&oacute; lẽ kh&ocirc;ng một tổ chức n&agrave;o ẩn chứa nhiều giai thoại, b&iacute; mật hay chủ đề g&acirc;y tranh c&atilde;i gay gắt như đế chế ng&acirc;n h&agrave;ng Mỹ &ndash; Gia tộc Morgan. Đạt Giải thưởng S&aacute;ch quốc gia v&agrave; hiện được coi l&agrave; một t&aacute;c phẩm kinh điển, Gia tộc Morgan l&agrave; cuốn tiểu sử tham vọng nhất từng được viết về một triều đại ng&acirc;n h&agrave;ng Mỹ. Cuốn s&aacute;ch vẽ n&ecirc;n bức tranh to&agrave;n diện về bốn thế hệ nh&agrave; Morgan v&agrave; c&aacute;c c&ocirc;ng ty b&iacute; mật, mạnh mẽ m&agrave; họ sở hữu. Với thế lực của m&igrave;nh, đế chế Morgan đ&atilde; biến nền kinh tế non trẻ của Mỹ th&agrave;nh một cường quốc c&ocirc;ng nghiệp mạnh nhất thế giới v&agrave; khiến trung t&acirc;m t&agrave;i ch&iacute;nh thế giới dịch chuyển từ London sang New York. Vượt xa cả lịch sử đơn thuần của ng&agrave;nh ng&acirc;n h&agrave;ng Mỹ, cuốn s&aacute;ch ch&iacute;nh l&agrave; c&acirc;u chuyện về sự tiến h&oacute;a của nền t&agrave;i ch&iacute;nh hiện đại. Dựa tr&ecirc;n c&aacute;c cuộc phỏng vấn rộng r&atilde;i c&ugrave;ng quyền truy cập đặc biệt v&agrave;o kho lưu trữ của gia tộc n&agrave;y, t&aacute;c đ&atilde; khắc họa n&ecirc;n bức ch&acirc;n dung hấp dẫn về c&acirc;u chuyện ri&ecirc;ng của nh&agrave; Morgan v&agrave; thế giới hiếm hoi của giới tinh hoa Mỹ v&agrave; Anh.</p>
<p><strong>Tr&iacute;ch đoạn:</strong></p>
<p><em>N&oacute;i về gia tộc Morgan thời kỳ đầu:</em></p>
<p>&ldquo;Gia tộc Morgan trước những năm 1935 được coi l&agrave; sự kết hợp t&agrave;i ch&iacute;nh quyền lực nhất trong lịch sử. Được một chủ ng&acirc;n h&agrave;ng người Mỹ t&ecirc;n l&agrave; George Peabody s&aacute;ng lập tại London năm 1838, c&ocirc;ng ty được gia đ&igrave;nh Morgan kế thừa v&agrave; bắt nh&aacute;nh sang New York. Hai nh&agrave; điều h&agrave;nh được biết đến nhiều nhất của Morgan l&agrave; J. P. Morgan, Sr. (1837-1913) v&agrave; J. P. Morgan, Jr. (1867-1943), đ&atilde; kết hợp ho&agrave;n hảo</p>
<p>th&agrave;nh &ldquo;qu&aacute;i th&uacute;&rdquo; J. P. Morgan tồn tại suốt hơn một thế kỷ. Vẻ bề ngo&agrave;i của họ giống nhau một c&aacute;ch kh&aacute;c thường: từ c&aacute;i đầu h&oacute;i, chiếc mũi to đến th&acirc;n h&igrave;nh quả l&ecirc; đều khiến người kh&aacute;c nhầm lẫn. Đối với những người ủng hộ, hai th&agrave;nh vi&ecirc;n nh&agrave; Morgan l&agrave; khu&ocirc;n mẫu của những &ocirc;ng chủ ng&acirc;n h&agrave;ng cổ điển lu&ocirc;n giữ chữ t&iacute;n trong từng lời n&oacute;i v&agrave; chốt giao dịch chỉ bằng một c&aacute;i bắt tay. Phe chỉ tr&iacute;ch th&igrave; cho rằng họ l&agrave; những t&ecirc;n bạo ch&uacute;a đạo đức giả chuy&ecirc;n đ&agrave;n &aacute;p c&aacute;c c&ocirc;ng ty, b&agrave;y mưu t&iacute;nh kế c&ugrave;ng với quyền lực ngoại bang v&agrave; khiến nước Mỹ rơi v&agrave;o cuộc chiến d&agrave;nh lợi nhuận. Kh&ocirc;ng một ai giữ được quan điểm trung lập khi n&oacute;i về nh&agrave; Morgan.&rdquo;</p>
<p><em>N&oacute;i về con người thật sự của Peabody sau vẻ ngo&agrave;i vui t&iacute;nh:</em></p>
<p>&ldquo;Đằng sau vẻ ngo&agrave;i vui t&iacute;nh của Peabody l&agrave; một g&atilde; h&agrave; tiện c&ocirc; độc. &Ocirc;ng sống trong những căn ph&ograve;ng tiện nghi ở một kh&aacute;ch sạn tr&ecirc;n phố Regent v&agrave; l&agrave;m việc kh&ocirc;ng ngừng nghỉ, ngoại trừ những l&uacute;c thỉnh thoảng đi c&acirc;u c&aacute;. Trong thời gian 12 năm, &ocirc;ng chưa bao giờ nghỉ l&agrave;m hai ng&agrave;y li&ecirc;n tiếp v&agrave; d&agrave;nh trung b&igrave;nh 10 giờ mỗi ng&agrave;y tại nơi l&agrave;m việc. Mặc d&ugrave; c&oacute; những b&agrave;i ph&aacute;t biểu g&acirc;y x&uacute;c động về vận mệnh nước Mỹ, &ocirc;ng kh&ocirc;ng trở về qu&ecirc; nh&agrave; trong 20 năm v&agrave; trong thời gian đ&oacute;, con người &ocirc;ng cũng &ldquo;sạm m&agrave;u&rdquo; c&ugrave;ng với giao dịch ảm đạm của tr&aacute;i phiếu c&aacute;c bang nước Mỹ. Trong đợt khủng hoảng trầm trọng v&agrave;o đầu những năm 1840&ndash;thập kỷ được g&aacute;n cho c&aacute;i t&ecirc;n Những năm 40 thiếu đ&oacute;i&ndash;nợ c&aacute;c bang ngập s&acirc;u tới mức cứ một đồng đ&ocirc;-la th&igrave; 50 xu phải d&agrave;nh để trả nợ. Điều tồi tệ nhất xảy ra khi năm bang của Mỹ&ndash;Pennsylvania, Mississippi, Indiana, Arkansas v&agrave; Michigan v&agrave; l&atilde;nh thổ Florida kh&ocirc;ng trả được nợ l&atilde;i suất tr&aacute;i phiếu của họ. Trong một li&ecirc;n minh con nợ sơ khai, một số thống đốc bang của Mỹ li&ecirc;n kết với nhau nhằm đ&aacute;nh quỵt. Cho đến nay, vụ Mississippi v&ocirc; lại vẫn l&agrave; vụ vỡ nợ đ&aacute;ng hổ thẹn.&rdquo;</p>
<p><em>N&oacute;i về tầm ảnh hưởng của Pierpont đối với sự kịch t&iacute;nh của thị trường t&agrave;i ch&iacute;nh Mỹ:</em></p>
<p>&ldquo;Trong cuộc hoảng loạn năm 1907, Pierpont đ&atilde; chứng minh rằng ng&agrave;nh t&agrave;i ch&iacute;nh Mỹ c&oacute; thể cực kỳ kịch t&iacute;nh. Trong một trận chung kết tối thứ Bảy, ng&agrave;y 2 th&aacute;ng 11, &ocirc;ng đ&atilde; nghĩ ra c&aacute;ch giải cứu cho C&ocirc;ng ty t&iacute;n th&aacute;c Mỹ vẫn đang lung lay, cho Quỹ t&iacute;n th&aacute;c Lincoln v&agrave; cho Moore &amp; Schley, một c&ocirc;ng ty m&ocirc;i giới đầu cơ c&oacute; khoảng 25 triệu đ&ocirc;-la. C&ocirc;ng ty cuối c&ugrave;ng n&agrave;y nắm trong tay phần lớn cổ phần khổng lồ của C&ocirc;ng ty than v&agrave; sắt Tennessee với tư c&aacute;ch t&agrave;i sản thế chấp cho c&aacute;c khoản vay. Nếu c&ocirc;ng ty n&agrave;y phải thanh l&yacute; chỗ cổ phần đ&oacute; th&igrave; thị trường chứng kho&aacute;n c&oacute; thể sẽ sụp đổ. Nếu đến lượt Moore &amp; Schley sụp đổ th&igrave; c&aacute;c ng&acirc;n h&agrave;ng kh&aacute;c c&oacute; thể cũng bị k&eacute;o theo.</p>
<p>Giống như một &ocirc;ng bầu tạo n&ecirc;n kiệt t&aacute;c s&acirc;n khấu của m&igrave;nh, Pierpont tập hợp c&aacute;c chủ ng&acirc;n h&agrave;ng của th&agrave;nh phố tại thư viện ri&ecirc;ng. &Ocirc;ng xếp c&aacute;c chủ ng&acirc;n h&agrave;ng thương mại tại Ph&ograve;ng Đ&ocirc;ng, b&ecirc;n dưới c&aacute;c biểu tượng cung ho&agrave;ng đạo v&agrave; một tấm thảm c&oacute; h&igrave;nh thất đại tội, c&ograve;n ở Ph&ograve;ng T&acirc;y l&agrave; chủ tịch c&aacute;c c&ocirc;ng ty t&iacute;n th&aacute;c ngồi lọt thỏm trong những chiếc ghế salon m&agrave;u đỏ đậm v&agrave; ghế b&agrave;nh dưới c&aacute;i nh&igrave;n của Đức mẹ Madonna v&agrave; c&aacute;c vị th&aacute;nh. Trong văn ph&ograve;ng của Belle Greene ở giữa, Pierpont ngồi chơi b&agrave;i như thần Jupiter v&ocirc; can trước vụ việc nghi&ecirc;m trọng đang diễn ra.&rdquo;</p>', 2020, NULL, 1092, 1, 13, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (243, N'Nguồn Gốc Trật Tự Chính Trị - Từ Thời Tiền Sử Đến Cách Mạng Pháp', N'8935270704391', N'Bìa Mềm', CAST(165100.00 AS Decimal(12, 2)), CAST(299000.00 AS Decimal(12, 2)), CAST(254000.00 AS Decimal(12, 2)), N'https://res.cloudinary.com/dabxzdaf8/image/upload/v1748967076/Book_cover/gs0koohuty0kkwyj24qj.webp', N'Francis Fukuyama', N'<p><strong>Nguồn Gốc Trật Tự Ch&iacute;nh Trị - Từ Thời Tiền Sử Đến C&aacute;ch Mạng Ph&aacute;p</strong></p>
<p>Một nội dung lớn trong cuốn s&aacute;ch ch&iacute;nh l&agrave;&nbsp;<em><strong>&ldquo;trở th&agrave;nh Đan Mạch&rdquo;</strong></em>, nghĩa l&agrave;, tạo ra những x&atilde; hội&nbsp;<em>ổn định, h&ograve;a b&igrave;nh, thịnh vượng, đầy đủ v&agrave; trung thực.</em>&nbsp;Fukuyama chỉ ra rằng tại thời điểm &ocirc;ng đặt b&uacute;t viết t&aacute;c phẩm n&agrave;y, 90 x&atilde; hội &ldquo;nguy&ecirc;n thủy&rdquo; đương thời/đang tồn tại đ&atilde; v&agrave; đang d&iacute;nh l&iacute;u v&agrave;o chiến tranh, h&agrave;m &yacute; trật tự ch&iacute;nh trị phải được ưu ti&ecirc;n hơn so với c&aacute;c cấu tr&uacute;c x&atilde; hội nguy&ecirc;n thủy nếu muốn đạt được sự ổn định.</p>
<p>Việc định h&igrave;nh c&aacute;c quốc gia (nằm ngo&agrave;i thế giới phương T&acirc;y) theo h&igrave;nh mẫu d&acirc;n chủ kiểu phương T&acirc;y đ&atilde; thất bại &ndash; l&yacute; do l&agrave; g&igrave;? Người đọc h&atilde;y theo ch&acirc;n Fukuyama t&igrave;m hiểu căn nguy&ecirc;n cho điều đ&oacute; qua hai chặng: t&igrave;m kiếm nguồn gốc thật sự của trật tự ch&iacute;nh trị, v&agrave; lần theo lịch sử của Trung Hoa, Ấn Độ, ch&acirc;u &Acirc;u v&agrave; một v&agrave;i quốc gia Hồi gi&aacute;o từ g&oacute;c nh&igrave;n ba hợp phần.</p>
<p><strong>| NỘI DUNG CH&Iacute;NH |</strong></p>
<p>Nguồn gốc trật tự ch&iacute;nh trị: từ thời Tiền sử đến C&aacute;ch mạng Ph&aacute;p ra đời năm 2011 dưới ng&ograve;i b&uacute;t của nh&agrave; kinh tế&ndash;ch&iacute;nh trị Francis Fukuyama, n&oacute;i về t&iacute;nh ổn định của nh&agrave; nước. T&aacute;c giả vận dụng lịch sử ch&iacute;nh trị so s&aacute;nh để triển khai một l&yacute; thuyết về t&iacute;nh ổn định của một hệ thống ch&iacute;nh trị. Theo Fukuyama, một nh&agrave; nước ổn định cần mang t&iacute;nh hiện đại v&agrave; mạnh mẽ, cần tu&acirc;n thủ ph&aacute;p luật &aacute;p dụng hiện h&agrave;nh v&agrave; c&oacute; tr&aacute;ch nhiệm giải tr&igrave;nh.</p>
<p>Cuốn s&aacute;ch c&ograve;n nhằm mục đ&iacute;ch l&yacute; giải tại sao việc x&acirc;y dựng nh&agrave; nước hiện đại v&agrave; x&acirc;y dựng c&aacute;c thiết chế ở những quốc gia như Afghanistan, Iraq, Somalia, Haiti, Timor-Leste, Sierra Leone v&agrave; Liberia lại kh&ocirc;ng được như kỳ vọng. Từ hệ quả của cuộc tấn c&ocirc;ng v&agrave;o Iraq năm 2003 của Mỹ, ch&iacute;nh quyền nước n&agrave;y dường như thật sự bất ngờ trước sự sụp đổ của nh&agrave; nước Iraq sau những cuộc cướp b&oacute;c v&agrave; xung đột d&acirc;n sự.</p>
<p>Bởi mục ti&ecirc;u của cuốn s&aacute;ch l&agrave; t&igrave;m hiểu c&aacute;ch thức c&aacute;c thiết chế v&agrave; nh&agrave; nước ph&aacute;t triển ở c&aacute;c quốc gia kh&aacute;c nhau n&ecirc;n n&oacute; c&ograve;n đ&oacute;ng vai tr&ograve; l&agrave; một nghi&ecirc;n cứu lịch sử so s&aacute;nh. C&oacute; thể n&oacute;i, Nguồn gốc trật tự ch&iacute;nh trị: từ thời Tiền sử đến C&aacute;ch mạng Ph&aacute;p l&agrave; sự mở rộng, nối tiếp t&aacute;c phẩm Political Order in Changing Societies (Trật tự ch&iacute;nh trị trong c&aacute;c x&atilde; hội biến đổi) của Samuel P. Huntington, s&aacute;nh ngang về quy m&ocirc; với S&uacute;ng, Vi tr&ugrave;ng v&agrave; Th&eacute;p của Jared Diamond. Fukuyama lập luận dựa v&agrave;o lịch sử c&aacute;c nước như Trung Hoa, Ấn Độ v&agrave; khu vực Trung Đ&ocirc;ng trước khi tập trung v&agrave;o những đường hướng đa dạng m&agrave; c&aacute;c nước ch&acirc;u &Acirc;u đ&atilde; đi.</p>
<p><strong>| TH&Ocirc;NG TIN T&Aacute;C GIẢ |</strong></p>
<p>FRANCIS FUKUYAMA (1952): Nh&agrave; triết học, nh&agrave; kinh tế ch&iacute;nh trị v&agrave; t&aacute;c giả người Mỹ. &Ocirc;ng nhận bằng tiến sĩ tại Đại học Harvard v&agrave; từng l&agrave;m việc trong bộ phận hoạch định ch&iacute;nh s&aacute;ch của Bộ Ngoại giao Mỹ. Fukuyama hiện l&agrave; gi&aacute;o sư Kinh tế Ch&iacute;nh trị Quốc tế v&agrave; Gi&aacute;m đốc Chương tr&igrave;nh Ph&aacute;t triển Quốc tế tại Trường Paul H. Nitze về Nghi&ecirc;n cứu Quốc tế Cấp cao, thuộc Đại học Johns Hopkins, Washington, DC.</p>', 2024, NULL, 740, 6, 15, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (244, N'Huyền Thoại Che - Bản Lĩnh Tính Cách Tình Yêu Và Sự Bất Tử (Tái Bản 2014)', N'8935086835029', N'Bìa Mềm', CAST(32760.00 AS Decimal(12, 2)), CAST(72000.00 AS Decimal(12, 2)), CAST(50400.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935086835029.jpg', N'Nhiều Tác Giả', N'<p>Huyền Thoại Che - Bản Lĩnh T&iacute;nh C&aacute;ch T&igrave;nh Y&ecirc;u v&agrave; Sự Bất Tử</p>
<p>Kh&ocirc;ng ai c&oacute; thể phủ nhận Ernesto Che Guevara lu&ocirc;n l&agrave; một huyền thoại đầy sức cuốn h&uacute;t, một biểu tượng anh h&ugrave;ng c&aacute;ch mạng của tất cả mọi d&acirc;n tộc tr&ecirc;n thế giới kh&ocirc;ng ri&ecirc;ng g&igrave; ở Cuba v&agrave; c&aacute;c quốc gia v&ugrave;ng Ch&acirc;u Mỹ Latin, một trong những con người ch&acirc;n ch&iacute;nh nhất của thế kỷ 20, v&agrave; của mai sau n&agrave;y, để c&aacute;c thế hệ h&ocirc;m nay v&agrave; tương lai noi theo.</p>
<p>Anh l&agrave; biểu tượng của hy vọng v&agrave; niềm tin tuyệt đối. Một tấm gương s&aacute;ng ngời tinh thần quốc tế v&ocirc; sản. Một con người th&ocirc;ng minh, cương trực kh&ocirc;ng bao giờ chịu khuất phục. Che đ&atilde; l&agrave; một b&aacute;c sĩ, một thầy gi&aacute;o, nh&agrave; b&aacute;o, ph&oacute;ng vi&ecirc;n ảnh, chủ ng&acirc;n h&agrave;ng, Bộ trưởng C&ocirc;ng nghiệp, một nh&agrave; thương thuyết bậc thầy đại diện Cuba tại hầu hết c&aacute;c hội nghị thượng đỉnh tr&ecirc;n thế giới, v&agrave; l&agrave; một nh&agrave; chỉ huy qu&acirc;n sự xuất ch&uacute;ng v&agrave; l&agrave; một chiến sĩ can trường. Che c&ograve;n l&agrave; một người đ&agrave;n &ocirc;ng ch&acirc;n ch&iacute;nh với một t&igrave;nh y&ecirc;u tuyệt đẹp.</p>', 2014, NULL, 236, 19, 13, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (245, N'Tự Truyện Benjamin Franklin (Tái Bản 2018)', N'8935270700621', N'Bìa Mềm', CAST(56680.00 AS Decimal(12, 2)), CAST(109000.00 AS Decimal(12, 2)), CAST(87200.00 AS Decimal(12, 2)), N'https://res.cloudinary.com/dabxzdaf8/image/upload/v1748967163/Book_cover/nrnlrsn8ockq3gzvdqma.webp', N'Benjamin Franklin', N'<p>Franklin (1706-1790) l&agrave; một ch&iacute;nh kh&aacute;ch, nh&agrave; ngoại giao, nh&agrave; văn, nh&agrave; khoa học v&agrave; s&aacute;ng chế, một trong những người uy&ecirc;n b&aacute;c v&agrave; t&agrave;i năng nhất nước Mỹ thuộc địa, v&agrave; l&agrave; một nh&acirc;n vật quan trọng trong cuộc chiến đấu gi&agrave;nh độc lập của người Mỹ.</p>
<p>Benjamin Franklin được coi l&agrave; một trong những nh&agrave; lập quốc vĩ đại của nước Mỹ. &Ocirc;ng l&agrave; người duy nhất đ&atilde; k&yacute; t&ecirc;n v&agrave;o cả bốn văn kiện quan trọng trong lịch sử nước Mỹ : Bản Tuy&ecirc;n ng&ocirc;n Độc lập, Hiệp ước đồng minh với Ph&aacute;p, Hiệp ước Paris v&agrave; Bản Hiến ph&aacute;p Hoa Kỳ.</p>
<p>&Ocirc;ng từng l&agrave;m thợ nấu x&agrave; ph&ograve;ng, thợ in, nh&agrave; văn, khoa học gia ki&ecirc;m nh&agrave; ph&aacute;t minh, l&atilde;nh đạo c&aacute;c tổ chức phục vụ cộng đồng. B&ecirc;n cạnh đ&oacute; &ocirc;ng cũng l&agrave; một nh&agrave; ngoại giao c&oacute; t&agrave;i. Nhiều sử gia Hoa Kỳ c&ocirc;ng nhận &ocirc;ng l&agrave; một nh&agrave; ngoại giao c&oacute; năng lực v&agrave; th&agrave;nh c&ocirc;ng nhất từ xưa tới nay.</p>
<p>Một năm sau ng&agrave;y Benjamin &ocirc;ng qua đời, cuốn tự truyện của &ocirc;ng được giới thiệu tới c&ocirc;ng ch&uacute;ng lần đầu tại Paris, th&aacute;ng Ba năm 1791. Được biết tới với t&ecirc;n gọi&nbsp;<strong>The autobiography of Benjamin Franklin -</strong>&nbsp;<strong>Hồi k&yacute; Benjamin Franklin</strong>, t&aacute;c phẩm được viết lại v&agrave; ho&agrave;n th&agrave;nh bởi con trai của Franklin, người sau n&agrave;y l&agrave; Thống đốc bang New Jersey.</p>
<p>T&aacute;c phẩm đ&atilde; nhận được nhiều lời khen ngợi của c&aacute;c nh&agrave; ph&ecirc; b&igrave;nh cũng như được c&ocirc;ng nhận l&agrave; một trong những t&aacute;c phẩm kinh điển nhất trong lịch sử nước Mỹ. Cuốn s&aacute;ch đ&atilde; khắc họa một c&aacute;ch r&otilde; n&eacute;t ch&acirc;n dung con người Benjamin Franklin cũng như cuộc đời đầy biến động của &ocirc;ng khi c&ograve;n sống ở Philadenphia. B&ecirc;n cạnh đ&oacute;, độc giả cũng c&oacute; cơ hội được t&igrave;m hiểu kỹ hơn những quan điểm của &ocirc;ng về Triết học, văn học cũng như t&ocirc;n gi&aacute;o v&agrave; những yếu tố gi&uacute;p Franklin trở th&agrave;nh một nh&acirc;n vật vĩ đại c&oacute; c&ocirc;ng kiến tạo n&ecirc;n nước Mỹ ng&agrave;y nay.</p>
<p>&laquo; Một trong những t&aacute;c phẩm kinh điển nhất của nền văn học Mỹ, cuốn s&aacute;ch ghi lại gần như đầy đủ cuộc đời của Benjamin Franklin từ thời thiếu ni&ecirc;n cho đến khi trở th&agrave;nh Chủ tịch Hội đồng H&agrave;nh ph&aacute;p Tối cao Pennsylvania. &raquo;</p>
<p><strong>- Amazon.com</strong></p>
<p>&laquo; Một t&aacute;c phẩm bất hủ. Th&ocirc;ng qua cuốn tự truyện đầy x&uacute;c động n&agrave;y&hellip; ch&uacute;ng ta như được gặp lại Franklin, được nghe &ocirc;ng kể lại l&yacute; do v&igrave; sao t&igrave;nh y&ecirc;u v&agrave; ảo m&ocirc;ng của &ocirc;ng với đế chế Anh quốc lại đến hồi tan vỡ như vậy&hellip; &raquo;</p>
<p><strong>- Salt lake City Tribune</strong></p>
<p>&laquo; Cuốn tự truyện được Benjamin viết n&ecirc;n với sự kỷ luật của một người chỉ huy chứ kh&ocirc;ng chỉ đơn thuần l&agrave; một lời tự sự th&ocirc;ng thường &raquo;.</p>
<p><strong>- George Fetherling, Vancouver Sun</strong></p>', 2018, NULL, 238, 21, 12, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (246, N'Bắc Hành Lược Ký', N'8935235225558', N'Bìa Mềm', CAST(48750.00 AS Decimal(12, 2)), CAST(125000.00 AS Decimal(12, 2)), CAST(75000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_195509_1_27543.jpg', N'Lê Quýnh', N'<p><em>Bắc h&agrave;nh lược k&yacute;</em>&nbsp;l&agrave; một &ldquo;hồi k&yacute; ch&iacute;nh trị&rdquo; của Trường Ph&aacute;i hầu L&ecirc; Qu&yacute;nh m&agrave; trọng điểm l&agrave; mười năm &ocirc;ng bị cầm t&ugrave; trong nhiều nh&agrave; ngục tại Trung Hoa sau khi theo vua L&ecirc; Chi&ecirc;u Thống chạy sang phương Bắc lưu vong. C&oacute; thể xem n&oacute; như một phong vũ biểu đo lường gi&oacute; mưa, thăng trầm của thời cuộc, phản &aacute;nh những l&ecirc;n xuống trong bang giao Thanh-Việt từ đời Quang Trung&nbsp;sang đời Cảnh Thịnh v&agrave; sau c&ugrave;ng l&agrave; đời Gia Long.</p>
<p>Bản dịch mới lần n&agrave;y dựa theo bản H&aacute;n văn của tạp ch&iacute;&nbsp;<em>Nam Phong</em>, c&oacute; đối chiếu, bổ t&uacute;c, tham khảo c&aacute;c bản in trong&nbsp;<em>Việt Nam H&aacute;n văn tiểu thuy</em><em>ế</em><em>t t&ugrave;ng san</em>&nbsp;v&agrave; lưu trữ tại&nbsp;<em>Viện H&aacute;n N&ocirc;m</em>&nbsp;<em>H&agrave; Nội</em>, c&ugrave;ng những t&agrave;i liệu, văn thư của triều Thanh trong c&ugrave;ng thời điểm, nhằm gi&uacute;p bạn đọc c&oacute; c&aacute;i nh&igrave;n đa chiều, s&aacute;ng tỏ hơn khi nghi&ecirc;n cứu về giai đoạn lịch sử từ cuối triều L&ecirc; đến đầu triều Nguyễn.</p>', 2020, NULL, 376, 21, 12, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (247, N'Nước Mỹ Trong Mắt Trump - The United States Of Trump : How The President Really Sees America', N'8934974169697', N'Bìa Mềm', CAST(107900.00 AS Decimal(12, 2)), CAST(198000.00 AS Decimal(12, 2)), CAST(166000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_195509_1_56100.jpg', N'NXB Trẻ', N'<p>Nước Mỹ trong mắt Trump l&agrave; cuốn s&aacute;ch mới nhất của B.O&rsquo;Reilly, xuất bản cuối 2019, được viết dưới dạng kể chuyện từ những cuộc phỏng vấn trực tiếp của O&rsquo;Reilly với Tổng thống Mỹ D.Trump v&agrave; gia đ&igrave;nh theo mạch thời gian k&egrave;m theo một số b&igrave;nh luận của t&aacute;c giả; cũng như nghi&ecirc;n cứu của t&aacute;c giả về c&aacute;c chủ đề li&ecirc;n quan. O&rsquo;Reilly đ&atilde; t&igrave;m c&aacute;ch l&yacute; giải những động lực th&uacute;c đẩy Donald Trump trong cuộc sống v&agrave; cụ thể hơn l&agrave; trong quyết định tạm g&aacute;c lại những xa hoa ph&uacute; qu&yacute; của một &ocirc;ng tr&ugrave;m bất động sản để tuy&ecirc;n bố tranh cử Tổng thống; chỉ ra sức h&uacute;t của &ocirc;ng Trump đối với cử tri Mỹ trong năm 2016. Những lập luận v&agrave; khung ph&acirc;n t&iacute;ch của t&aacute;c giả chắc chắn rất c&oacute; &iacute;ch trong ph&acirc;n t&iacute;ch cuộc tổng tuyển cử Mỹ năm 2020. Ng&ocirc;n ngữ sắc sảo v&agrave; ngắn gọn, c&ugrave;ng sự cẩn trọng chi tiết trong nghi&ecirc;n cứu về chủ thể của t&aacute;c giả mang lại sự hấp dẫn đặc biệt kh&oacute; cưỡng đối với ai muốn biết về tổng thống Mỹ D. Trump- trong đời thường v&agrave; trong ch&iacute;nh trường.<br>- Về t&aacute;c giả: B. O&rsquo;Reilly c&oacute; hơn 20 năm l&agrave; người dẫn chương tr&igrave;nh v&agrave; b&igrave;nh luận vi&ecirc;n thời sự của Fox News, đ&atilde; trở n&ecirc;n quen thuộc với nhiều độc giả Việt Nam th&ocirc;ng qua loạt s&aacute;ch Killing, kể về những t&igrave;nh tiết đặc biệt xung quanh cuộc đời của những nh&acirc;n vật lịch sử nổi tiếng từng bị &aacute;m s&aacute;t. O&rsquo;Reilly đ&atilde; c&oacute; 4 cuốn s&aacute;ch nằm trong danh s&aacute;ch b&aacute;n chạy nhất của Thời b&aacute;o New York.</p>', 2020, NULL, 392, 7, 9, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (248, N'Bách Khoa Thư Hình Ảnh: Các Đời Tổng Thống Hoa Kỳ', N'8936071678096', N'Bìa Cứng', CAST(156000.00 AS Decimal(12, 2)), CAST(320000.00 AS Decimal(12, 2)), CAST(240000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/b/i/bia-1---cac-doi-tong-thong-hoa-ky.jpg', N'DK', N'<p>B&aacute;ch Khoa Thư H&igrave;nh Ảnh: C&aacute;c Đời Tổng Thống Hoa Kỳ</p>
<p>&ldquo;Kể từ khi George Washington tuy&ecirc;n thệ lần đầu v&agrave;o năm 1789, c&oacute; 44 người đ&atilde; tiếp bước &ocirc;ng giữ chức tổng thống Hoa Kỳ. Tr&ecirc;n cương vị đứng đầu cơ quan h&agrave;nh ph&aacute;p quốc gia, trải bao năm th&aacute;ng, c&aacute;c đời tổng thống Hoa Kỳ đ&atilde; phải đối mặt với nhiều thử th&aacute;ch, cả quốc nội lẫn quốc tế, trong việc đảm bảo nền thịnh vượng v&agrave; an ninh cho đất nước.&rdquo;</p>
<p>(Tr&iacute;ch&nbsp;<em>B&aacute;ch khoa thư h&igrave;nh ảnh: C&aacute;c đời tổng thống Hoa Kỳ</em>)</p>
<p><em>B&aacute;ch khoa thư h&igrave;nh ảnh: C&aacute;c đời tổng thống Hoa Kỳ</em> l&agrave; thước phim đầy m&agrave;u sắc, sống động về th&acirc;n thế, sự nghiệp v&agrave; th&agrave;nh tựu của 45 con người vĩ đại đ&atilde; kiến tạo v&agrave; x&acirc;y dựng n&ecirc;n Hợp ch&uacute;ng quốc Hoa Kỳ h&ugrave;ng mạnh như ng&agrave;y nay. Ngo&agrave;i ra, một số Đệ nhất Phu nh&acirc;n nổi bật, nơi ở, phương tiện đi lại c&ugrave;ng một số điều l&yacute; th&uacute; &iacute;t ai biết của c&aacute;c tổng thống cũng c&oacute; vinh dự được g&oacute;p mặt trong cuốn s&aacute;ch n&agrave;y, như một n&eacute;t chấm ph&aacute; để người đọc c&oacute; cơ hội hiểu r&otilde; hơn về những khoảnh khắc rất &ldquo;đời&rdquo; của c&aacute;c vị tổng tư lệnh Qu&acirc;n đội Hoa Kỳ.</p>', 2020, NULL, 208, 12, 3, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (249, N'45 Đời Tổng Thống Hoa Kỳ', N'8935270702830', N'Bìa Cứng', CAST(330850.00 AS Decimal(12, 2)), CAST(599000.00 AS Decimal(12, 2)), CAST(509000.00 AS Decimal(12, 2)), N'https://res.cloudinary.com/dabxzdaf8/image/upload/v1748967315/Book_cover/hfjxei2vw94zfqbn6hif.webp', N'William A Degregorio', N'<p><strong>45 Đời Tổng Thống Hoa Kỳ</strong></p>
<p><em>45 đời tổng thống Hoa Kỳ</em>&nbsp;l&agrave; một bộ cẩm nang đồ sộ d&agrave;y hơn 1500 trang, t&aacute;i hiện to&agrave;n bộ lịch sử nước Mỹ. Mỗi tổng thống, một t&iacute;nh c&aacute;ch, một bối cảnh lịch sử, rất nhiều những c&acirc;u chuyện v&agrave; b&iacute; ẩn xoay quanh, m&agrave; kh&ocirc;ng c&oacute; bất cứ một k&ecirc;nh truyền th&ocirc;ng n&agrave;o tổng hợp chi tiết v&agrave; đặc sắc bằng t&aacute;c giả William A. Degregorio - nh&agrave; nghi&ecirc;n cứu ch&iacute;nh trị Hoa Kỳ, người say m&ecirc; t&igrave;m hiểu về cuộc đời c&aacute;c Tổng thống Mỹ từ khi c&ograve;n nhỏ.</p>
<p>Cuốn s&aacute;ch l&agrave; một hiện tượng xuất bản tại Mỹ từ những năm 1980s, m&agrave; Tổng thống đương nhiệm khi đ&oacute; l&agrave; Ronald Reagan. Kể từ đ&oacute; trở đi, r&ograve;ng r&atilde; gần 40 năm, rất nhiều tổng thống đ&atilde; qua đời, nhưng cứ 4 hoặc 8 năm, 1 hoặc 2 nhiệm kỳ Tổng thống, s&aacute;ch lại được bổ sung th&ocirc;ng tin v&agrave; t&aacute;i bản một lần. Sưu tầm c&aacute;c bản in cuốn n&agrave;y đ&atilde; v&agrave; vẫn đang l&agrave; niềm đam m&ecirc; của c&aacute;c nh&agrave; nghi&ecirc;n cứu lịch sử.</p>
<p><em>45 đời tổng thống Hoa Kỳ</em>&nbsp;kh&ocirc;ng chỉ dừng lại ở việc m&ocirc; tả s&acirc;u s&aacute;t, kh&aacute;ch quan, kh&ocirc;ng thi&ecirc;n kiến về cuộc đời, hoạt động ch&iacute;nh trường, bạn b&egrave;, kẻ th&ugrave; cũng như th&agrave;nh c&ocirc;ng lẫn thất bại của 45 vị tổng thống, m&agrave; đằng sau đ&oacute; l&agrave; cả một ph&ocirc;ng nền lớn của lịch sử nước Mỹ. Đ&oacute; l&agrave; bi&ecirc;n ni&ecirc;n sự kiện hoạt động của bộ m&aacute;y Nh&agrave; nước Li&ecirc;n bang Hoa Kỳ trong suốt 240 năm qua.</p>
<p>- Nước Mỹ ngh&egrave;o n&agrave;n v&agrave; lạc hậu, phải đi vay từng đồng đ&ocirc;-la ở nước ngo&agrave;i trong thời kỳ đầu mới lập quốc ra sao? Nh&acirc;n d&acirc;n Mỹ đ&atilde; chung lưng đấu cật để đưa nước đi l&ecirc;n từ ngh&egrave;o n&agrave;n, lạc hậu như thế n&agrave;o? V&agrave; họ x&acirc;y dựng một Li&ecirc;n bang Hợp ch&uacute;ng quốc Hoa Kỳ ra sao?</p>
<p>- Li&ecirc;n bang Hoa Kỳ trong những năm đầu mới th&agrave;nh lập đ&atilde; bị đế quốc Anh phong tỏa v&agrave; kiềm chế thế n&agrave;o?</p>
<p>- Nước Mỹ đ&atilde; đưa ra những ch&iacute;nh s&aacute;ch đối nội, đối ngoại như thế n&agrave;o?</p>
<p>- Hệ thống luật ph&aacute;p, hoạt động của c&aacute;c tổ chức đảng (hai đảng lớn D&acirc;n chủ v&agrave; Cộng h&ograve;a).</p>
<p>- Vấn đề mang tầm v&oacute;c to&agrave;n cầu: chống tham nhũng, chống &ocirc; nhiễm m&ocirc;i trường, trồng rừng, bảo vệ m&ocirc;i sinh, coi trọng n&ocirc;ng l&acirc;m nghiệp v&agrave; thủy lợi.</p>
<p>- Kinh nghiệm bổ &iacute;ch trong quản l&yacute;, điều h&agrave;nh đất nước, nhất l&agrave; lựa chọn v&agrave; tuyển dụng nh&acirc;n sự trong cơ quan h&agrave;nh ph&aacute;p để bộ m&aacute;y nh&agrave; nước hoạt động năng động, hữu hiệu nhất.</p>
<p>- Sự thật lịch sử của từng thời kỳ, bản lĩnh, khả năng l&atilde;nh đạo, ch&iacute;nh s&aacute;ch đ&uacute;ng sai của từng tổng thống.</p>
<p>- Cuộc đời, sự nghiệp của những vị tổng thống v&agrave; c&aacute;c nh&acirc;n vật bộ trưởng nổi tiếng đ&atilde; c&oacute; c&ocirc;ng lao mở rộng l&atilde;nh thổ cho nước Mỹ như ng&agrave;y nay.</p>
<p>- V&igrave; sao cuộc Nội chiến Nam &ndash; Bắc Mỹ nổ ra?</p>
<p>- Nước Mỹ c&oacute; bao nhi&ecirc;u vị tổng thống trở th&agrave;nh vĩ đại v&agrave; được xếp v&agrave; bậc danh nh&acirc;n văn h&oacute;a thế giới?</p>
<p>So với phi&ecirc;n bản&nbsp;<em>&ldquo;44 đời tổng thống Hoa Kỳ&rdquo;</em>, phi&ecirc;n bản&nbsp;<em>&ldquo;45 đời tổng thống Hoa Kỳ</em>&rdquo; được dịch bổ sung th&ecirc;m chương 45 về Tổng thống Donald Trump v&agrave; c&oacute; cập nhật lại c&aacute;c số liệu phần mục lục.</p>
<p><strong>Về t&aacute;c giả:</strong></p>
<p>William A. Degregorio t&aacute;c giả, bi&ecirc;n tập vi&ecirc;n về mảng lịch sử, ch&iacute;nh trị v&agrave; s&aacute;ch tham khảo. &Ocirc;ng đ&atilde; đ&oacute;ng g&oacute;p h&agrave;ng trăm b&agrave;i viết cho c&aacute;c nguồn tư liệu c&oacute; độ x&aacute;c t&iacute;n cao như B&aacute;ch khoa to&agrave;n thư Britannica v&agrave; B&aacute;ch khoa to&agrave;n thư Americana</p>', 2020, NULL, 1536, 21, 15, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (250, N'Keynes - Tư Tưởng Kinh Tế Hữu Ích Cho Nền Kinh Tế Hiện Nay', N'9786048481872', N'Bìa Mềm', CAST(90025.00 AS Decimal(12, 2)), CAST(180000.00 AS Decimal(12, 2)), CAST(138500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786048481872.jpg', N'Peter Temin, David Vines', N'<p><strong>Keynes - Tư Tưởng Kinh Tế Hữu &Iacute;ch Cho Nền Kinh Tế Hiện Nay</strong></p>
<p>Cuốn s&aacute;ch &ldquo;Keynes &ndash; Tư tưởng kinh tế hữu &iacute;ch cho nền kinh tế thế giới ng&agrave;y nay&rdquo; của Peter Temin v&agrave; David Vines l&agrave; một h&agrave;nh tr&igrave;nh kh&aacute;m ph&aacute; tư tưởng kinh tế của John Maynard Keynes, một trong những nh&agrave; kinh tế học vĩ đại nhất thế kỷ 20. Với c&aacute;ch viết gi&agrave;u t&iacute;nh thực tiễn v&agrave; dẫn dắt chặt chẽ, t&aacute;c phẩm kh&ocirc;ng chỉ giới thiệu về cuộc đời v&agrave; sự nghiệp của Keynes m&agrave; c&ograve;n giải th&iacute;ch r&otilde; r&agrave;ng c&aacute;c kh&aacute;i niệm kinh tế học Keynesian qua bối cảnh lịch sử cụ thể.</p>
<p>S&aacute;ch khởi đầu bằng c&aacute;ch tr&igrave;nh b&agrave;y nền kinh tế trước thời Keynes, từ c&aacute;c l&yacute; thuyết của Hume đến Marshall, để minh họa những trở ngại m&agrave; Keynes phải đối mặt khi x&acirc;y dựng hệ thống tư tưởng của m&igrave;nh. Qua c&aacute;c chương, độc giả sẽ được l&agrave;m quen với những kh&aacute;i niệm kinh tế quan trọng như bẫy thanh khoản, biểu đồ IS-LM, v&agrave; c&aacute;c ch&iacute;nh s&aacute;ch t&agrave;i ch&iacute;nh Keynesian, được minh họa bằng c&aacute;c m&ocirc; h&igrave;nh v&agrave; biểu đồ dễ hiểu.</p>
<p>Điểm đặc biệt của cuốn s&aacute;ch l&agrave; c&aacute;ch n&oacute; li&ecirc;n kết tư tưởng của Keynes với c&aacute;c vấn đề kinh tế hiện đại, bao gồm cả cuộc khủng hoảng t&agrave;i ch&iacute;nh to&agrave;n cầu 2008 v&agrave; những b&agrave;i học c&oacute; thể &aacute;p dụng v&agrave;o c&aacute;c nền kinh tế đang ph&aacute;t triển như Việt Nam. C&aacute;c t&aacute;c giả cũng tập trung v&agrave;o việc t&aacute;i kh&aacute;m ph&aacute; vai tr&ograve; của nh&agrave; nước trong điều tiết kinh tế, mở ra những hướng đi mới mẻ v&agrave; thiết thực.</p>', 2024, NULL, 236, 14, 2, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (251, N'Hoảng Loạn, Hỗn Loạn Và Cuồng Loạn', N'8935251415612', N'Bìa Mềm', CAST(98800.00 AS Decimal(12, 2)), CAST(179000.00 AS Decimal(12, 2)), CAST(152000.00 AS Decimal(12, 2)), N'https://res.cloudinary.com/dabxzdaf8/image/upload/v1748968563/Book_cover/p5yonczea5pucnmftvi6.webp', N'Charles P Kindleberger, Robert Z Aliber', N'<p>Hoảng Loạn, Hỗn Loạn V&agrave; Cuồng Loạn</p>
<p>Charlie Kindleberger (hay c&ograve;n gọi l&agrave; CPK) l&agrave; một người rất say m&ecirc; c&ocirc;ng việc: am hiểu, tr&aacute;ch nhiệm, mong muốn t&igrave;m hiểu mọi thứ, đầy c&aacute; t&iacute;nh v&agrave; tr&ecirc;n hết đ&oacute; l&agrave; sự năng nổ nhiệt t&igrave;nh. Những phẩm chất n&agrave;y được thể hiện xuy&ecirc;n suốt trong cuốn <strong>Hoảng Loạn, Hỗn Loạn V&agrave; Cuồng Loạn</strong>.</p>
<p>T&ocirc;i cho rằng CPK bắt đầu viết&nbsp;<strong>Hoảng Loạn, Hỗn Loạn V&agrave; Cuồng Loạn&nbsp;</strong>bằng &acirc;m hưởng của văn phong lịch sử tự nhi&ecirc;n, phần n&agrave;o giống với Darwin trong giai đoạn l&ecirc;nh đ&ecirc;nh tr&ecirc;n con t&agrave;u th&aacute;m hiểm Beagle &ndash; thu thập, ph&acirc;n t&iacute;ch v&agrave; ph&acirc;n loại c&aacute;c mẫu vật kỳ lạ.&nbsp;<strong>Hoảng Loạn, Hỗn Loạn V&agrave; Cuồng Loạn</strong>&nbsp;c&oacute; lợi thế hơn so với những lo&agrave;i gặm nhấm, chim v&agrave; bọ c&aacute;nh cứng vốn được nh&agrave; nghi&ecirc;n cứu đương thời mi&ecirc;u tả theo lối hoa mỹ, đ&ocirc;i l&uacute;c rất s&acirc;u sắc, đ&ocirc;i l&uacute;c lại v&ocirc; nghĩa. Đ&oacute; l&agrave; phong c&aacute;ch viết của CPK nhưng chỉ kh&aacute;c l&agrave; &ocirc;ng viết bằng giọng văn của một nh&agrave; sử học kinh tế đang tr&ecirc;n con đường t&igrave;m kiếm v&agrave; nghi&ecirc;n cứu những sự kiện lạ thường, chứ kh&ocirc;ng phải l&agrave; theo đuổi những lịch tr&igrave;nh được hệ thống h&oacute;a từ trước.</p>
<p>Tất nhi&ecirc;n, CPK l&agrave; một nh&agrave; kinh tế học đ&atilde; qua đ&agrave;o tạo v&agrave; trải nghiệm thực tế, &ocirc;ng đ&atilde; sớm t&igrave;m ra c&aacute;c m&ocirc; h&igrave;nh v&agrave; quy luật kinh tế, mối quan hệ giữa nguy&ecirc;n nh&acirc;n v&agrave; kết quả. Đặc biệt &ocirc;ng đ&atilde; nhận ra những điều bất hợp l&yacute; diễn ra thường xuy&ecirc;n g&acirc;y ảnh hưởng trực tiếp v&agrave; gi&aacute;n tiếp tới c&aacute;c sự kiện v&agrave; khiến mọi người c&oacute; c&aacute;i nh&igrave;n lệch lạc về bản chất sự kiện. Bản chất những điều n&agrave;y c&oacute; lẽ chỉ đơn thuần l&agrave; một th&ocirc;ng tin giải tr&iacute;. Nhưng CPK đ&atilde; tạo n&ecirc;n những điều kh&aacute;c lạ khi nghi&ecirc;n cứu sự tương t&aacute;c giữa h&agrave;nh vi v&agrave; c&aacute;c thể chế. Bản chất của c&aacute;c sự kiện được đề cập trong cuốn s&aacute;ch n&agrave;y, v&agrave; quy m&ocirc; hoạt động của n&oacute; phụ thuộc phần lớn v&agrave;o c&aacute;c thể chế li&ecirc;n quan đến tiền tệ v&agrave; thị trường vốn trong từng thời điểm.</p>
<p>C&oacute; thể ngay từ đầu CPK kh&ocirc;ng thể hiểu r&otilde; c&aacute;c cuộc khủng hoảng t&agrave;i ch&iacute;nh diễn ra khắc nghiệt đến mức n&agrave;o. Hai mươi lăm năm sau ng&agrave;y ấn phẩm đầu ti&ecirc;n được xuất bản khắc họa một bức tranh tổng thể về sự hỗn loạn trong hệ thống c&aacute;c ng&acirc;n h&agrave;ng quốc gia, sự biến động về tỷ gi&aacute; v&agrave; bong b&oacute;ng gi&aacute; t&agrave;i sản.</p>
<p>Những th&ocirc;ng tin mới lu&ocirc;n được cập nhật trong những ấn phẩm tiếp theo. Hiện trạng lịch sử n&agrave;y kh&ocirc;ng đơn thuần bắt nguồn từ sự v&ocirc; l&yacute; của con người, mặc d&ugrave; the Law of the Deterioration of Everything (Quy luật về sự t&agrave;n ph&aacute; mọi thứ) từ một người bạn Đức của ch&uacute;ng ta đ&atilde; l&ocirc;i cuốn CPK. Của cải tăng l&ecirc;n, hệ thống truyền th&ocirc;ng nhanh hơn v&agrave; rẻ hơn, v&agrave; sự thay đổi hệ thống t&agrave;i ch&iacute;nh quốc tế v&agrave; của từng quốc gia cũng đ&oacute;ng một vai tr&ograve; lớn kh&ocirc;ng thể phủ nhận được, được tr&igrave;nh b&agrave;y trong Chương 13, đ&atilde; được Robert Aliber bổ sung th&ecirc;m v&agrave;o ấn phẩm n&agrave;y. Nỗ lực của CPK trong lịch sử kinh tế đ&atilde; gi&uacute;p &ocirc;ng nhận ra chủ đề m&agrave; &ocirc;ng sẽ viết dường như sẽ kh&ocirc;ng vượt ra ngo&agrave;i &acirc;m hưởng n&agrave;y.</p>
<p><strong>+T&Aacute;C GIẢ:</strong></p>
<p><strong>Charles P. Kindleberger</strong>&nbsp;l&agrave; Gi&aacute;o sư Kinh tế thuộc Học viện C&ocirc;ng nghệ Massachusetts (MIT), chuy&ecirc;n nghi&ecirc;n cứu về lịch sử t&agrave;i ch&iacute;nh v&agrave; l&agrave; t&aacute;c giả của hơn 30 cuốn s&aacute;ch viết về thương mại quốc tế, hợp t&aacute;c đa quốc gia v&agrave; lịch sử kinh tế &ndash; t&agrave;i ch&iacute;nh.</p>
<p><strong>Robert Z. Aliber&nbsp;</strong>l&agrave; Gi&aacute;o sư nghi&ecirc;n cứu về T&agrave;i ch&iacute;nh v&agrave; Kinh tế quốc tế thuộc Trường Kinh doanh &ndash; Đại học Chicago, cố vấn kinh tế cấp cao cho Vụ Ph&aacute;t triển Kinh tế, Bộ Ngoại giao Hoa Kỳ.</p>', 2020, NULL, 408, 13, 2, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (252, N'Barbarians At The Gate - Bọn Rợ Rình Trước Cổng', N'8935251410341', N'Bìa Mềm', CAST(129675.00 AS Decimal(12, 2)), CAST(399000.00 AS Decimal(12, 2)), CAST(199500.00 AS Decimal(12, 2)), N'https://res.cloudinary.com/dabxzdaf8/image/upload/v1748968682/Book_cover/syyxtz4oairdubglwrkp.webp', N'Bryan Burrough, John Helyar', N'<p><strong>Barbarians At The Gate - Bọn Rợ R&igrave;nh Trước Cổng</strong></p>
<p>Cuốn s&aacute;ch&nbsp;<em>Bọn rợ r&igrave;nh ở cổng</em>&nbsp;l&agrave; c&acirc;u chuyện c&oacute; thật về cuộc chiến gi&agrave;nh quyền kiểm so&aacute;t c&ocirc;ng ty b&aacute;nh quy v&agrave; thuốc l&aacute; Mỹ &ndash; RJR Nabisco &ndash; nh&agrave; sản xuất b&aacute;nh quy Oreo v&agrave; thuốc l&aacute; RJ Reynolds. Nội dung ch&iacute;nh n&oacute;i về việc mua lại c&oacute; đ&ograve;n bẩy (LBO) của tập đo&agrave;n RJR Nabisco với nhịp độ nhanh ch&oacute;ng v&agrave; chi tiết, bao gồm cả những cuộc hội thoại ri&ecirc;ng cũng như trong ph&ograve;ng họp giữa c&aacute;c CEO của c&aacute;c c&ocirc;ng ty. Cuốn s&aacute;ch thể hiện l&ograve;ng tham đ&aacute;ng kinh ngạc của c&aacute;c chủ ng&acirc;n h&agrave;ng đầu tư, nh&agrave; quản l&yacute; c&ocirc;ng ty, nh&agrave; đầu tư cổ phần tư nh&acirc;n, c&aacute;c cổ đ&ocirc;ng&hellip; Việc mua lại diễn ra được mở đầu bằng một cuộc chiến đấu thầu giữa ban l&atilde;nh đạo (do CEO Ross Johnson dẫn đầu), KKR, c&ocirc;ng ty cổ phần tư nh&acirc;n l&acirc;u đời, v&agrave; một số người chơi &ldquo;nhỏ hơn&rdquo;. Việc mua lại c&oacute; đ&ograve;n bẩy thường khiến c&ocirc;ng ty bị mua lại phải g&aacute;nh rất nhiều nợ, đ&ograve;i hỏi c&aacute;c nh&agrave; quản l&yacute; phải cắt giảm chi ph&iacute; (thường bao gồm cả nh&acirc;n sự) &ndash; đ&oacute; l&agrave; l&yacute; do tại sao những điều n&agrave;y kh&ocirc;ng được nh&acirc;n vi&ecirc;n, c&ocirc;ng ch&uacute;ng v&agrave; giới b&aacute;o ch&iacute; ưa chuộng. Khoản mua lại trị gi&aacute; 25 tỷ đ&ocirc; la n&agrave;y, m&agrave; cuối c&ugrave;ng KKR đ&atilde; gi&agrave;nh được bởi cũng kh&ocirc;ng kh&aacute;c g&igrave;, đặc biệt v&igrave; đ&acirc;y l&agrave; LBO lớn nhất tại thời điểm đ&oacute;.</p>
<p>Những người phản đối nỗ lực mua lại c&ocirc;ng ty của Johnson, Henry Kravis v&agrave; anh họ của &ocirc;ng ta l&agrave; George R. Roberts, l&agrave; những người ti&ecirc;n phong trong việc mua lại c&oacute; đ&ograve;n bẩy (LBO). Kravis l&agrave; người đầu ti&ecirc;n m&agrave; Johnson n&oacute;i chuyện về việc thực hiện LBO v&agrave; cảm thấy bị phản bội sau khi biết rằng Johnson muốn thực hiện thỏa thuận với một c&ocirc;ng ty kh&aacute;c, bộ phận Shearson Lehman Hutton trước đ&acirc;y của American Express. Ted Forstmann v&agrave; c&ocirc;ng ty mua lại Forstmann Little của &ocirc;ng cũng đ&oacute;ng một vai tr&ograve; quan trọng.</p>
<p>Khi l&ecirc;n nắm quyền điều h&agrave;nh RJR Nabisco v&agrave; thấy gi&aacute; cổ phiếu của c&ocirc;ng ty đang tr&igrave; trệ, Ross Johnson đ&atilde; t&igrave;m c&aacute;ch để c&oacute; được gi&aacute; trị lớn hơn cho c&aacute;c cổ đ&ocirc;ng của m&igrave;nh v&agrave; cuối c&ugrave;ng đ&atilde; được c&aacute;c cố vấn ng&acirc;n h&agrave;ng đầu tư (của Lehman Brothers) thuyết phục rằng &ocirc;ng n&ecirc;n thực hiện một vụ mua lại c&oacute; đ&ograve;n bẩy. V&agrave; ngay sau khi gi&aacute; thầu được c&ocirc;ng bố, c&aacute;c nh&agrave; thầu cho c&ocirc;ng ty đ&atilde; xuất hiện. KKR đ&atilde; trở th&agrave;nh con mồi đầu ti&ecirc;n của LBO. Hầu như tất cả c&aacute;c ng&acirc;n h&agrave;ng đầu tư lớn đều tham gia với tư c&aacute;ch l&agrave; cố vấn cho thương vụ n&agrave;y. Một số nh&acirc;n vật quan trọng trong giới t&agrave;i ch&iacute;nh xuất hiện. Bruce Wasserstein, CEO của Lazard đ&atilde; tham gia, c&ugrave;ng với Joe Perella, Eric Gleacher, Tom Hill.&nbsp;</p>
<p>Sau khi Kravis v&agrave; Johnson kh&ocirc;ng thể dung h&ograve;a được sự kh&aacute;c biệt của họ, một cuộc chiến đấu thầu đ&atilde; diễn ra m&agrave; cuối c&ugrave;ng Johnson sẽ thua. T&aacute;c dụng phụ đ&aacute;ng tiếc của việc tăng gi&aacute; mua đối với c&aacute;c cổ đ&ocirc;ng l&agrave; tạo ra mức nợ đ&aacute;ng lo ngại cho c&ocirc;ng ty.</p>
<p>Cuốn s&aacute;ch bắt đầu chậm r&atilde;i với hơn 300 trang x&acirc;y dựng bối cảnh cho c&aacute;c nh&acirc;n vật ch&iacute;nh v&agrave; m&ocirc; tả lịch sử của RJR Nabisco. Sau đ&oacute;, n&oacute; đẩy nhanh tốc độ v&agrave; sự kịch t&iacute;nh qua c&aacute;c cuộc hội thoại, thời gian v&agrave; giọng điệu của nh&acirc;n vật.</p>
<p>&nbsp;</p>', 2021, NULL, 816, 5, 1, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (253, N'Kinh Tế Nhật Bản: Giai Đoạn Phát Triển Thần Kỳ 1955-1973', N'8936144201510', N'Bìa Mềm', CAST(118300.00 AS Decimal(12, 2)), CAST(228000.00 AS Decimal(12, 2)), CAST(182000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8936144201510.jpg', N'Trần Văn Thọ', N'<p><strong>Gi&aacute;o sư Trần Văn Thọ l&agrave; chuy&ecirc;n gia tầm ch&iacute;nh phủ về kinh tế. G&oacute;c nh&igrave;n của &ocirc;ng về kinh tế thế giới &ndash; Nhật Bản &ndash; v&agrave; Việt Nam lu&ocirc;n được c&aacute;c nh&agrave; hoạch định ch&iacute;nh s&aacute;ch quan t&acirc;m lắng nghe để đưa ra quyết s&aacute;ch ở tầm vĩ m&ocirc;.</strong></p>
<p><strong>***</strong></p>
<p><strong>Đ&acirc;y l&agrave; một cuốn s&aacute;ch cực kỳ quan trọng, được bi&ecirc;n soạn rất c&ocirc;ng phu, phản ảnh kiến thức s&acirc;u v&agrave; rộng của t&aacute;c giả về cả l&yacute; thuyết lẫn thực h&agrave;nh của ng&agrave;nh kinh tế ph&aacute;t triển. S&aacute;ch được đ&uacute;c kết dựa tr&ecirc;n c&aacute;c ph&acirc;n t&iacute;ch số lượng chặt chẽ v&agrave; đem lại những kiến thức mới để hiểu qu&aacute; tr&igrave;nh Nhật Bản trở th&agrave;nh một cường quốc k&iacute;nh tế. Những b&agrave;i học được t&aacute;c giả r&uacute;t ra từ Nhật Bản sẽ gi&uacute;p Việt Nam tr&ecirc;n đường c&ocirc;ng nghiệp ho&aacute; v&agrave; ph&aacute;t triển. Đặc biệt ấn tượng l&agrave; kinh nghiệm Nhật Bản được tổng kết qua hai kh&aacute;i niệm nh&agrave; nước kiến tạo ph&aacute;t triển v&agrave; năng lực x&atilde; hội.</strong></p>
<p><strong>***</strong></p>
<p><strong>KINH TẾ NHẬT BẢN</strong></p>
<p><strong>Giai đoạn ph&aacute;t triển thần kỳ 1955-1973</strong></p>
<p>T&aacute;c giả: GI&Aacute;O SƯ TRẦN VĂN THỌ</p>
<p>PHANBOOK v&agrave; NXB Đ&Agrave; NẴNG tr&acirc;n trọng giới thiệu!</p>
<p>Trong lịch sử Nhật Bản, giai đoạn 1955-1973 rất đặc biệt. Giai đoạn đ&oacute; l&agrave;m n&ecirc;n một thời đại, thời đại ph&aacute;t triển thần kỳ. Trung b&igrave;nh mỗi năm tăng trưởng 10%, k&eacute;o d&agrave;i gần 20 năm, rất hiệu suất v&agrave; đạt to&agrave;n dụng lao động. Giai đoạn n&agrave;y đ&atilde; đưa Nhật Bản vươn l&ecirc;n th&agrave;nh một cường quốc c&ocirc;ng nghiệp, theo kịp c&aacute;c nước ti&ecirc;n tiến phương T&acirc;y, thực hiện giấc mơ v&agrave; mục ti&ecirc;u của l&atilde;nh đạo thời Minh Trị Duy t&acirc;n.</p>
<p>&nbsp;Xoay quanh hai từ kh&oacute;a&nbsp;<em>nh&agrave; nước kiến tạo ph&aacute;t triển&nbsp;</em>v&agrave;&nbsp;<em>năng lực x&atilde; hội,&nbsp;</em>cuốn s&aacute;ch n&agrave;y ph&acirc;n t&iacute;ch những yếu tố l&agrave;m n&ecirc;n giai đoạn ph&aacute;t triển thần kỳ ấy. Ngo&agrave;i khung ph&acirc;n t&iacute;ch kinh tế học ph&aacute;t triển để khảo s&aacute;t chiến lược, ch&iacute;nh s&aacute;ch về đầu tư, hội nhập, gi&aacute;o dục đ&agrave;o tạo, du nhập v&agrave; sử dụng c&ocirc;ng nghệ, , cuốn s&aacute;ch c&ograve;n đặt vấn đề từ một c&aacute;i nh&igrave;n rộng hơn, khảo s&aacute;t tư tưởng v&agrave; h&agrave;nh động của c&aacute;c chủ thể như l&atilde;nh đạo ch&iacute;nh trị, quan chức, l&atilde;nh đạo doanh nghiệp, S&aacute;ch kể nhiều mẩu chuyện k&egrave;m theo h&igrave;nh ảnh của những ch&iacute;nh trị gia, quan chức, học giả, nh&agrave; doanh nghiệp ti&ecirc;u biểu thời hậu chiến Nhật Bản, những người đ&atilde; l&agrave;m n&ecirc;n giai đoạn thần kỳ n&agrave;y. Cuốn s&aacute;ch c&oacute; th&ecirc;m hai phụ chương để gi&uacute;p c&aacute;c độc giả muốn biết về kinh tế Nhật sau giai đoạn ph&aacute;t triển thần kỳ (1974-2020).</p>
<p>Kinh nghiệm Nhật Bản với hai từ kh&oacute;a&nbsp;<em>nh&agrave; nước kiến tạo ph&aacute;t triển&nbsp;</em>v&agrave;&nbsp;<em>năng lực x&atilde; hội&nbsp;</em>cho thấy nhiều h&agrave;m &yacute; đối với Việt Nam trong giai đoạn ph&aacute;t triển sắp tới.</p>', 2022, NULL, 292, 16, 1, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (254, N'Ký Ức Theo Dòng Đời', N'8936144201558', N'Bìa Mềm', CAST(99190.00 AS Decimal(12, 2)), CAST(218000.00 AS Decimal(12, 2)), CAST(152600.00 AS Decimal(12, 2)), N'https://res.cloudinary.com/dabxzdaf8/image/upload/v1748968775/Book_cover/xnvo8adt79zdhrlq3rxm.webp', N'Phan Chánh Dưỡng', N'<p><strong>K&yacute; Ức Theo D&ograve;ng Đời</strong></p>
<p><em>Anh đ&atilde; l&agrave;m một c&ocirc;ng việc chi&ecirc;u hiền đ&atilde;i sĩ cực kỳ nhạy cảm trong một thời buổi rất, rất kh&oacute; khăn, khi kiến thức bị xem nhẹ v&agrave; kẻ sĩ bị đẩy ra lề x&atilde; hội. Anh kh&ocirc;ng chỉ gi&uacute;p họ được ngồi lại, m&agrave; c&ograve;n c&oacute; thể ngồi chung với nhau, kh&ocirc;ng ph&acirc;n biệt nguồn đ&agrave;o tạo, trong một tinh thần h&ograve;a hợp hiếm c&oacute;. Từ đ&oacute;, người tr&iacute; thức được đ&aacute;nh gi&aacute; lại v&agrave; c&oacute; thể đ&oacute;ng g&oacute;p năng lực, phần n&agrave;o, cho x&atilde; hội, một nền kinh tế đang chuyển m&igrave;nh. Nhưng với t&iacute;nh c&aacute;ch khi&ecirc;m cung v&agrave; h&ograve;a đồng, anh kh&ocirc;ng thấy m&igrave;nh l&agrave; Mạnh Thường Qu&acirc;n. Anh h&ograve;a m&igrave;nh v&agrave;o c&aacute;c m&ocirc;n kh&aacute;ch, trở th&agrave;nh một trong số đ&oacute;, một c&aacute;ch hồn nhi&ecirc;n, ch&acirc;n t&igrave;nh, tự nhi&ecirc;n như một con c&aacute; trong đ&agrave;n c&aacute;.</em></p>
<p><em>- Chuy&ecirc;n gia Kinh tế Huỳnh Bửu Sơn</em></p>
<p>PHANBOOK v&agrave; NXB Đ&agrave; Nẵng tr&acirc;n trọng giới thiệu!</p>
<p>--------------------------</p>
<p><em>K&yacute; ức theo d&ograve;ng đời</em>&nbsp;l&agrave; tập hồi k&yacute; của Phan Ch&aacute;nh Dưỡng &ndash; một con người hăm hở g&oacute;p phần v&agrave;o c&ocirc;ng cuộc đưa nền kinh tế của TP.HCM &ldquo;vượt s&oacute;ng ra Biển Đ&ocirc;ng&rdquo;.</p>
<p>Cuốn s&aacute;ch l&agrave; nguồn t&agrave;i liệu qu&yacute; gi&aacute;, cẩm nang thuyết phục về tư duy s&aacute;ng tạo, c&aacute;ch l&agrave;m đột ph&aacute; v&agrave; tinh thần cống hiến cho x&atilde; hội của Phan Ch&aacute;nh Dưỡng c&ugrave;ng những tr&iacute; thức thế hệ &ocirc;ng trong Nh&oacute;m Thứ S&aacute;u &ndash; nghi&ecirc;n cứu v&agrave; cố vấn ch&iacute;nh s&aacute;ch kinh tế.</p>
<p><em>K&yacute; ức theo d&ograve;ng đời</em>&nbsp;l&agrave; cuốn hồi k&yacute; m&agrave; th&ocirc;ng qua chuyện d&ograve;ng đời v&agrave; chọn lựa lẽ sống, ta thấy được sự cống hiến v&agrave; t&acirc;m t&igrave;nh của một tr&iacute; thức trong bức tranh thời cuộc đất nước từ Bao Cấp sang Đổi Mới v&agrave; Hội nhập &ndash; To&agrave;n cầu h&oacute;a, từ thời chiến dịch chuyển sang thời b&igrave;nh.</p>
<p>-----------------------</p>
<p><strong>TH&Ocirc;NG TIN T&Aacute;C GIẢ</strong></p>
<p><em>Phan Ch&aacute;nh Dưỡng</em>&nbsp;sinh năm 1948, tại C&agrave; Mau. &Ocirc;ng đ&atilde; kinh qua những chức vụ ch&iacute;nh như: Gi&aacute;m đốc C&ocirc;ng ty Cholimex, Tổng Gi&aacute;m đốc C&ocirc;ng ty Ph&aacute;t triển C&ocirc;ng nghiệp T&acirc;n Thuận (IPC), ki&ecirc;m Ph&oacute; Tổng Gi&aacute;m đốc C&ocirc;ng ty Li&ecirc;n doanh Khu Chế xuất T&acirc;n Thuận (TTC) v&agrave; Ph&oacute; Chủ tịch Hội đồng Quản trị C&ocirc;ng ty Li&ecirc;n doanh Ph&uacute; Mỹ Hưng.</p>
<p>Hiện &ocirc;ng l&agrave; giảng vi&ecirc;n Trường Ch&iacute;nh s&aacute;ch C&ocirc;ng v&agrave; Quản l&yacute; Fulbright; Gi&aacute;m đốc Quỹ Hỗ trợ Cộng đồng Đinh Thiện L&yacute; (Lawrence S. Ting).</p>', 2022, NULL, 389, 16, 5, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (255, N'Chiêu Bài Quản Lý Vàng Của Bill Gates (2016)', N'8935077033540', N'Bìa Mềm', CAST(30940.00 AS Decimal(12, 2)), CAST(68000.00 AS Decimal(12, 2)), CAST(47600.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935077033540.jpg', N'Thương Mỗ , Lê Duyên Hải', N'<p>Chi&ecirc;u B&agrave;i Quản L&yacute; V&agrave;ng Của Bill Gates (2016)</p>
<p>Bill Gates l&agrave; người s&aacute;ng lập ra Tập đo&agrave;n Microsoft, c&ocirc;ng ty h&agrave;ng đầu chuy&ecirc;n cung cấp phần mềm cho m&aacute;y t&iacute;nh. &Ocirc;ng nguy&ecirc;n l&agrave; Tổng Gi&aacute;m đốc v&agrave; Chủ tịch Hội đồng quản trị của Microsoft. Bill Gates được cả thế giới biết đến như một huyền thoại trong lĩnh vực phần mềm, &ocirc;ng đ&atilde; tạo ra một vương quốc phần mềm kỳ diệu bằng ch&iacute;nh nỗ lực của m&igrave;nh. Bill Gate cũng l&agrave; người nhiều năm liền nắm vị tr&iacute; &ldquo;người gi&agrave;u nhất thế giới&rdquo; do tạp ch&iacute; danh tiếng Forbes b&igrave;nh chọn.</p>
<p>Tại sao Bill Gates lại th&agrave;nh c&ocirc;ng đến vậy? Tại sao lịch sử lại chọn &ocirc;ng? L&agrave; một nh&agrave; l&atilde;nh đạo, Bill Gates đ&atilde; c&oacute; những phương ph&aacute;p quản l&yacute; như thế n&agrave;o để Microsoft kh&ocirc;ng ngừng ph&aacute;t triển, li&ecirc;n tục đi từ th&agrave;nh c&ocirc;ng n&agrave;y đến th&agrave;nh c&ocirc;ng kh&aacute;c trong nhiều năm? Cu&ocirc;n s&aacute;ch&nbsp;<strong>CHI&Ecirc;U B&Agrave;I QUẢN L&Yacute; V&Agrave;NG CỦA BILLGATES</strong> sẽ giải m&atilde; b&iacute; mật th&agrave;nh c&ocirc;ng của nh&agrave; tỉ ph&uacute; n&agrave;y.</p>', 2016, NULL, 302, 16, 6, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (256, N'Lý Gia Thành - “Ông Chủ Của Những Ông Chủ” Trong Giới Kinh Doanh Hồng Kông (Tái Bản 2017)', N'8935251407488', N'Bìa Mềm', CAST(76700.00 AS Decimal(12, 2)), CAST(139000.00 AS Decimal(12, 2)), CAST(118000.00 AS Decimal(12, 2)), N'https://res.cloudinary.com/dabxzdaf8/image/upload/v1748968848/Book_cover/duuq7no2e2figeodvquw.webp', N'Anthony B. Chan', N'<p>L&yacute; Gia Th&agrave;nh - &ldquo;&Ocirc;ng Chủ Của Những &Ocirc;ng Chủ&rdquo; Trong Giới Kinh Doanh Hồng K&ocirc;ng (T&aacute;i Bản 2017)</p>
<p>Trong văn h&oacute;a kinh doanh của người Hoa c&oacute; một vị tr&iacute; được cộng đồng doanh nh&acirc;n x&acirc;y dựng v&agrave; t&ocirc;n vinh, đ&oacute; ch&iacute;nh l&agrave; &ldquo;&Ocirc;ng chủ của những &Ocirc;ng chủ&rdquo;. Kh&aacute;i niệm &ocirc;ng chủ một nh&agrave; h&agrave;ng, &ocirc;ng chủ một nh&agrave; m&aacute;y lớn, &ocirc;ng chủ của một tập đo&agrave;n kinh tế trong con mắt của người d&acirc;n, người lao động b&igrave;nh thường họ đều l&agrave; những nh&acirc;n vật quan trọng. H&agrave;nh động của họ, c&ocirc;ng việc kinh doanh của c&aacute;c tổ chức kinh tế m&agrave; họ điều h&agrave;nh c&oacute; ảnh hưởng đến cuộc sống của một nh&oacute;m người nhất định c&oacute; c&ugrave;ng lợi &iacute;ch kinh tế trong tổ chức đ&oacute;.</p>
<p>&ldquo;&Ocirc;ng chủ của những &Ocirc;ng chủ&rdquo; l&agrave; nh&acirc;n vật m&agrave; h&agrave;nh động của họ ảnh hưởng đến vận mệnh của c&aacute;c tổ chức kinh tế m&agrave; c&aacute;c &ocirc;ng chủ đang điều h&agrave;nh. Đ&oacute; phải l&agrave; những nh&acirc;n vật nắm trong tay những lĩnh vực kinh tế huyết mạch của cả v&ugrave;ng, thậm ch&iacute; mang tầm quốc gia.L&yacute; Gia Th&agrave;nh ch&iacute;nh l&agrave; &ldquo;&Ocirc;ng chủ của những &Ocirc;ng chủ&rdquo; trong giới kinh doanh Hồng K&ocirc;ng cũng như giới doanh nh&acirc;n người Hoa tr&ecirc;n to&agrave;n thế giới. &Ocirc;ng nắm trong tay 5% nền kinh tế Hong Kong, những ng&agrave;nh kinh tế huyết mạch như: bất động sản, ng&acirc;n h&agrave;ng, hải cảng, đội t&agrave;u biển ở Hong Kong v&agrave; Trung Quốc. Những t&agrave;i sản quan trọng trong cộng đồng Hoa Kiều tại Canada, Mỹ, Singapo, Thai Land, Malaysia&hellip;</p>
<p>Tư tưởng, triết l&yacute; kinh doanh v&agrave; h&agrave;nh đồng của L&yacute; Gia Th&agrave;nh ảnh hưởng đến định hướng v&agrave; quyết định kinh tế của c&aacute;c &ocirc;ng chủ nhỏ trong cộng đồng doanh nh&acirc;n Hoa Kiều. Tập s&aacute;ch của Anthony B. Chan sẽ giới thiệu r&otilde; hơn, chi tiết hơn con đường dẫn đến th&agrave;nh c&ocirc;ng của nh&acirc;n vật ch&acirc;u &Aacute; v&ocirc; c&ugrave;ng nổi tiếng n&agrave;y.</p>', 2017, NULL, 320, 15, 14, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (257, N'Chấn Hưng Nhật Bản', N'8935279109180', N'Bìa Mềm', CAST(68575.00 AS Decimal(12, 2)), CAST(132000.00 AS Decimal(12, 2)), CAST(105500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/b/i/bia_chan-hung-nhat-ban.jpg', N'Clyde Prestowitz', N'<p>Chấn&nbsp;Hưng&nbsp;Nhật&nbsp;Bản</p>
<p>Nhật Bản l&agrave; một trong ba nền kinh tế lớn nhất thế giới với nguồn vốn dồi d&agrave;o, c&ocirc;ng nghệ ti&ecirc;n tiến, c&oacute; kinh nghiệm quản l&yacute; hiện đại v&agrave; hiệu quả. L&agrave; nước xuất khẩu vốn khổng lồ, với hơn 1 ngh&igrave;n tỉ USD đầu tư trực tiếp ở nước ngo&agrave;i n&ecirc;n Nhật Bản l&agrave; đối t&aacute;c kinh tế quan trọng với nhiều nước tr&ecirc;n thế giới, trong đ&oacute; c&oacute; Việt Nam.</p>
<p>Tr&ecirc;n con đường đi l&ecirc;n trở th&agrave;nh một trong ba nền kinh tế lớn nhất thế giới, Nhật Bản đ&atilde; phải trải qua hai cuộc t&aacute;i thiết đất nước v&ocirc; c&ugrave;ng quan trọng, diễn ra v&agrave;o thời kỳ Phục hưng Minh Trị năm 1868 v&agrave; diễn ra sau Chiến tranh thế giới thứ hai. Trong cả hai lần tự t&aacute;i thiết n&agrave;y, Nhật Bản đ&atilde; tạo ra một nỗ lực to lớn để du nhập, l&agrave;m chủ, cải tiến, thay đổi c&ocirc;ng nghệ v&agrave; b&iacute; quyết ng&agrave;nh c&ocirc;ng nghiệp của phương T&acirc;y. V&agrave; nhờ đ&oacute;, Nhật Bản dường như trở n&ecirc;n bất bại trong lĩnh vực c&ocirc;ng nghiệp v&agrave; c&ocirc;ng nghệ.</p>
<p>Tuy nhi&ecirc;n, từ năm 1990 trở về đ&acirc;y, nền kinh tế Nhật Bản c&oacute; dấu hiệu ph&aacute;t triển chậm lại, đặc biệt l&agrave; vị tr&iacute; đứng đầu của Nhật Bản trong lĩnh vực c&ocirc;ng nghiệp v&agrave; c&ocirc;ng nghệ đang bị đe dọa thay thế bởi c&aacute;c đối thủ cạnh tranh như H&agrave;n Quốc, Trung Quốc v&agrave; Đ&agrave;i Loan. Hoạt động đổi mới s&aacute;ng tạo của Nhật Bản cũng c&oacute; dấu hiệu đi xuống v&agrave;o đầu những năm 1990 mặc d&ugrave; Ch&iacute;nh phủ Nhật Bản đ&atilde; hết sức nỗ lực tăng gấp đ&ocirc;i chi ti&ecirc;u d&agrave;nh cho hoạt động nghi&ecirc;n cứu v&agrave; ph&aacute;t triển. Một phần nguy&ecirc;n nh&acirc;n l&agrave; Nhật Bản chỉ tập trung đầu tư nghi&ecirc;n cứu v&agrave; ph&aacute;t triển trong lĩnh vực &ocirc;t&ocirc; v&agrave; điện tử m&agrave; bỏ qua những lĩnh vực kh&aacute;c c&oacute; quy m&ocirc; to&agrave;n cầu v&agrave; lại những lĩnh vực đ&ograve;i hỏi đầu tư cao cho nghi&ecirc;n cứu v&agrave; ph&aacute;t triển như dược phẩm, c&ocirc;ng nghệ sinh học, phần mềm v&agrave; dịch vụ m&aacute;y t&iacute;nh. Đứng trước nguy cơ n&agrave;y, c&acirc;u hỏi đặt ra l&agrave; liệu Nhật Bản c&oacute; cần một cuộc t&aacute;i thiết nữa hay kh&ocirc;ng? V&agrave; nếu cần th&igrave; phải t&aacute;i thiết như thế n&agrave;o</p>
<p>Nhằm gi&uacute;p bạn đọc c&oacute; th&ecirc;m t&agrave;i liệu nghi&ecirc;n cứu, tham khảo về ph&aacute;t triển nước Nhật Bản, Th&aacute;i H&agrave; Books v&agrave; NXB Ch&iacute;nh trị quốc gia Sự thật xuất bản cuốn s&aacute;ch&nbsp;<strong><em>Chấn hưng Nhật Bản: L&agrave;m c&aacute;ch n&agrave;o Nhật Bản c&oacute; thể tự t&aacute;i thiết v&agrave; tại sao điều n&agrave;y lại quan trọng với Hoa Kỳ v&agrave; thế giới&nbsp;</em></strong>của t&aacute;c giả Clyde Prestowitz.</p>
<p>Cuốn s&aacute;ch được chia th&agrave;nh 10 chương v&agrave; được viết theo phong c&aacute;ch hết sức độc đ&aacute;o. Thay v&igrave; m&ocirc; tả đất nước Nhật Bản của hiện tại sau đ&oacute; đưa ra những khuyến nghị về mặt ch&iacute;nh s&aacute;ch,... th&igrave; ở đ&acirc;y, t&aacute;c giả đ&atilde; ph&aacute;c họa một bức tranh về đất nước Nhật Bản trong tương lai của năm 2050, một đất nước đ&atilde; được t&aacute;i thiết lần thứ ba với rất nhiều sự thay đổi cả về kinh tế - x&atilde; hội v&agrave; ch&iacute;nh trị, chẳng hạn như GDP tăng 4,5%/năm, vượt xa so với bất kỳ nước lớn n&agrave;o v&agrave; gần gấp đ&ocirc;i GDP của Trung Quốc; d&acirc;n số c&oacute; chiều hướng tăng l&ecirc;n v&agrave; vượt mức 150 triệu người; phụ nữ tham gia nhiều hơn v&agrave;o lực lượng lao động, sinh nhiều con hơn;... v&agrave; đ&aacute;ng ngạc nhi&ecirc;n hơn l&agrave; Nhật Bản trở th&agrave;nh quốc gia n&oacute;i tiếng Anh! C&oacute; thể thấy đ&acirc;y l&agrave; một đất nước trong tương lai ho&agrave;n to&agrave;n thay đổi so với Nhật Bản của hiện tại. Tưởng như cuốn s&aacute;ch mang đến một c&acirc;u chuyện giả tưởng song đ&oacute; lại ch&iacute;nh l&agrave; những th&ocirc;ng điệp, những lời khuy&ecirc;n v&agrave; những kỳ vọng của t&aacute;c giả, một người Mỹ đ&atilde; từng c&oacute; thời gian d&agrave;i sinh sống v&agrave; học tập tại Nhật Bản, d&agrave;nh cho đất nước n&agrave;y.</p>
<p><strong>Mục lục:</strong></p>
<p><em>Những lời khen tặng d&agrave;nh cho Chấn Hưng Nhật Bản</em></p>
<p><em>Lời Nh&agrave; xuất bản</em></p>
<p><em>Giới thiệu: Nền tảng của cuốn s&aacute;ch</em></p>
<p>Chương 1: Tokyo, năm 2050</p>
<p>Chương 2: 2016 - Năm của những cuộc khủng hoảng</p>
<p>Chương 3: H&ograve;a b&igrave;nh kiểu Th&aacute;i B&igrave;nh Dương</p>
<p>Chương 4: Phụ nữ giải cứu đất nước</p>
<p>Chương 5: Nhật Bản trở th&agrave;nh nước n&oacute;i tiếng Anh</p>
<p>Chương 6: Quốc gia đổi mới s&aacute;ng tạo</p>
<p>Chương 7: Tự chủ về năng lượng</p>
<p>Chương 8: Tập đo&agrave;n Nhật Bản đến tập đo&agrave;n Đức - với những đặc trưng Nhật Bản</p>
<p>Chương 9: Đ&aacute;nh bại kẻ trong cuộc</p>
<p>Chương 10: Đi l&ecirc;n với d&acirc;n, đi xuống với quan</p>
<p><em>Kết luận: Tại sao Nhật Bản lại l&agrave; vấn đề đ&aacute;ng quan t&acirc;m với Hoa Kỳ v&agrave; thế giới?</em></p>
<p><em>Lời cảm ơn</em></p>
<p><strong>Th&ocirc;ng tin về t&aacute;c giả:</strong></p>
<p><strong>Clyde Prestowitz</strong> l&agrave; t&aacute;c giả của những cuốn s&aacute;ch b&aacute;n chạy nhất v&agrave; được đ&aacute;nh gi&aacute; cao như Trading Places, Rogue Nation v&agrave; Three Billion New Capitalists. &Ocirc;ng giữ chức vụ cố vấn cho Bộ trưởng Bộ Thương mại Hoa Kỳ v&agrave; l&agrave; nh&agrave; đ&agrave;m ph&aacute;n thương mại đứng đầu tại ch&acirc;u &Aacute;. &Ocirc;ng cũng l&agrave; Ph&oacute; Chủ tịch của Ủy ban Thương mại v&agrave; Đầu tư khu vực ch&acirc;u &Aacute; - Th&aacute;i B&igrave;nh Dương của Tổng thống Clinton. L&agrave; người th&agrave;nh lập Viện Chiến lược kinh tế ở Washington D.C, &ocirc;ng cũng đưa ra lời khuy&ecirc;n cho ch&iacute;nh phủ, c&aacute;c tập đo&agrave;n quốc tế,c&aacute;c li&ecirc;n đo&agrave;n lao động về vấn đề cạnh tranh v&agrave; chiến lược to&agrave;n cầu ho&aacute;.</p>', 2018, NULL, 327, 14, 14, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (258, N'Donald Trump Dưới Góc Nhìn Của Tâm Lý Học', N'8935235222311', N'Bìa Mềm', CAST(81900.00 AS Decimal(12, 2)), CAST(180000.00 AS Decimal(12, 2)), CAST(126000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_188849.jpg', N'Bandy X Lee', N'<p>C&oacute; thể coi cuốn s&aacute;ch n&agrave;y l&agrave; một tập t&agrave;i liệu chuy&ecirc;n m&ocirc;n về sức khỏe t&acirc;m thần, t&acirc;m l&yacute; học, nhưng kh&ocirc;ng l&agrave;m cho người đọc thấy hoảng sợ, v&igrave; l&yacute; thuyết được gắn với một t&igrave;nh huống nghi&ecirc;n cứu thực tiễn, điển h&igrave;nh.</p>
<p>Đồng thời đ&acirc;y cũng l&agrave; tiếng n&oacute;i của những c&ocirc;ng d&acirc;n c&oacute; chuy&ecirc;n m&ocirc;n, &yacute; thức rất r&otilde; về &ldquo;tr&aacute;ch nhiệm cảnh b&aacute;o&rdquo; của m&igrave;nh; nhưng lại bị kẹt giữa hai nghĩa vụ nghề nghiệp ho&agrave;n to&agrave;n đối lập nhau, v&agrave; việc vi phạm bất cứ nghĩa vụ n&agrave;o cũng khiến họ bị coi l&agrave; h&agrave;nh xử thiếu đạo đức.</p>
<p>Thứ nhất, họ c&oacute; nghĩa vụ im lặng về đ&aacute;nh gi&aacute; của họ với bất kỳ ai nếu người đ&oacute; chưa cho ph&eacute;p họ l&ecirc;n tiếng c&ocirc;ng khai. Thứ hai, họ c&oacute; nghĩa vụ l&ecirc;n tiếng v&agrave; th&ocirc;ng b&aacute;o cho những người kh&aacute;c nếu họ c&oacute; cơ sở để tin rằng một người n&agrave;o đ&oacute; c&oacute; thể g&acirc;y nguy hiểm cho những người kh&aacute;c.</p>
<p>Nh&acirc;n vật được đưa ra l&agrave;m điển h&igrave;nh trong cuốn s&aacute;ch l&agrave; Donald Trump, tổng thống đương nhiệm của Hoa Kỳ, v&igrave; những h&agrave;nh xử c&oacute; vẻ bất thường của &ocirc;ng.</p>
<p>Tuy nhi&ecirc;n, t&aacute;c giả Bandy X. Lee đ&atilde; chỉ ra rằng, &ldquo;điểm ch&iacute;nh của cuốn s&aacute;ch n&agrave;y kh&ocirc;ng phải l&agrave; về &ocirc;ng Trump, m&agrave; về bối cảnh lớn hơn dẫn tới việc &ocirc;ng l&ecirc;n l&agrave;m tổng thống, v&agrave; về phần đ&ocirc;ng d&acirc;n số m&agrave; &ocirc;ng g&acirc;y được ảnh hưởng bởi vị thế của &ocirc;ng&rdquo;.</p>
<p>B&agrave; đ&atilde; đặt ngược lại c&acirc;u hỏi, rằng việc Donald Trump đắc cử tổng thống Mỹ kh&ocirc;ng phải vấn đề, m&agrave; vấn đề nằm ở ch&iacute;nh đ&aacute;m đ&ocirc;ng d&acirc;n số đ&atilde; bầu cho &ocirc;ng. V&agrave;, &ldquo;Sự nổi l&ecirc;n của một c&aacute; nh&acirc;n với những khiếm khuyết như thế tự n&oacute; n&oacute;i l&ecirc;n t&igrave;nh trạng sức khỏe v&agrave; sự thịnh vượng của quốc gia, v&agrave; ch&uacute;ng ta c&oacute; thể phản ứng thế n&agrave;o: cải thiện n&oacute; hay l&agrave;m n&oacute; suy yếu th&ecirc;m nữa?&rdquo;</p>
<p>&ldquo;Kh&ocirc;ng cuốn s&aacute;ch n&agrave;o được xuất bản trong m&ugrave;a thu n&agrave;y nguy hiểm hơn, quan trọng hơn v&agrave; g&acirc;y tranh c&atilde;i hơn cuốn s&aacute;ch n&agrave;y&hellip; s&acirc;u sắc, s&aacute;ng tỏ v&agrave; đầy lo lắng.&rdquo;</p>
<p>- Bill Moyers</p>
<p>&ldquo;Lập trường của c&aacute;c chuy&ecirc;n gia t&acirc;m thần học n&agrave;y cần đến l&ograve;ng can đảm, v&agrave; những kết luận của họ thật thuyết phục.&rdquo;</p>
<p>-&nbsp;<em>The Washington Post</em></p>', 2019, NULL, 440, 20, 2, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (259, N'The Big Four - 4 Đại Gia Kiểm Toán: Deloitte - PwC - EY - KPMG', N'8936184340156', N'Bìa Mềm', CAST(83850.00 AS Decimal(12, 2)), CAST(168000.00 AS Decimal(12, 2)), CAST(129000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/4/-/4-dai-gia-kiem-toan---bia-1.jpg', N'Ian D Gow, Stuart Kells', N'<p>The Big Four - 4 Đại Gia Kiểm To&aacute;n: Deloitte - PwC - EY - KPMG: Qu&aacute; Khứ Kỳ Lạ V&agrave; Tương Lai Hiểm Trở Của Sự Độc Quyền Kiểm To&aacute;n To&agrave;n Cầu</p>
<p>&ldquo;Big Four&rdquo; h&igrave;nh th&agrave;nh thế n&agrave;o?</p>
<p>Trước năm 1989, thế giới kiểm to&aacute;n vẫn được thống trị bởi nh&oacute;m &ldquo;Big 8&rdquo;: (1) Arthur Andersen, (2) Arthur Young &amp; Co., (3) Coopers &amp; Lybrand, (4) Ernst &amp; Whinney, (5) Deloitte, Haskins &amp; Sells, (6) KPMG, (7) Touche Ross, (8) Price Waterhouse.</p>
<p>Năm 1989, hai vụ s&aacute;t nhập v&ocirc; c&ugrave;ng lớn đ&atilde; giảm nh&oacute;m &ldquo;Big 8&rdquo; xuống c&ograve;n &ldquo;Big 6&rdquo;: Ernst &amp; Whinney v&agrave; Arthur Young &amp; Co s&aacute;t nhập để tạo ra Ernst and Young (EY); Deloitte, Haskins &amp; Sells hợp nhất với Touche Ross tạo th&agrave;nh Deloitte Touche.</p>
<p>Năm 1998, Price Waterhouse s&aacute;t nhập với Coopers &amp; Lybrand tạo n&ecirc;n PriceWaterhouseCoopers (PwC). &ldquo;Big 6&rdquo; trở th&agrave;nh &ldquo;Big 5&rdquo;.</p>
<p>Năm 2002, Arthur Anderson ph&aacute; sản. &ldquo;Big Four&rdquo; h&igrave;nh th&agrave;nh v&agrave; tồn tại đến ng&agrave;y nay.</p>
<p>Với đội ngũ nh&acirc;n vi&ecirc;n đ&ocirc;ng hơn cả qu&acirc;n đội Nga v&agrave; tổng doanh thu hơn 130 tỷ USD mỗi năm, c&aacute;c c&ocirc;ng ty kế to&aacute;n thuộc nh&oacute;m Big Four - Deloitte, PricewaterhouseCoopers (PwC), Ernst &amp; Young (EY) v&agrave; KPMG - trở th&agrave;nh nền tảng của thương mại to&agrave;n cầu!</p>
<p>&ldquo;The Big Four &ndash; 4 đại gia kiểm to&aacute;n&rdquo; đ&atilde; khắc họa lịch sử h&igrave;nh th&agrave;nh, những biến cố, thăng trầm v&agrave; h&agrave;nh tr&igrave;nh ph&aacute;t triển như vũ b&atilde;o của bốn tập đo&agrave;n kể tr&ecirc;n bằng lối kể chuyện hấp dẫn. Cuốn s&aacute;ch c&ograve;n đưa ra những nhận định về &ldquo;tương lai hiểm trở&rdquo; m&agrave; bốn đại gia n&agrave;y sẽ phải đối mặt. Trong những năm gần đ&acirc;y, cả bốn c&ocirc;ng ty đ&atilde; phải chịu đựng những thảm họa lớn với h&agrave;ng trăm trường hợp t&ograve;a &aacute;n v&agrave; truy tố ph&aacute;p l&yacute; v&igrave; c&aacute;c cuộc kiểm to&aacute;n thất bại, b&ecirc; bối thuế v&agrave; vi phạm t&iacute;nh độc lập. C&aacute;c c&ocirc;ng ty đ&atilde; tiến gần đến "sự kiện cấp độ diệt vong" đến mức c&aacute;c nh&agrave; quản l&yacute; buộc họ phải chuẩn bị "&yacute; ch&iacute; sống c&ograve;n". L&agrave;m thế n&agrave;o để họ vượt qua được v&agrave; vẫn tiếp tục đứng vững, đ&oacute;ng g&oacute;p vai tr&ograve; quan trọng cho nền tảng thương mại to&agrave;n cầu?</p>
<p>Đ&acirc;y l&agrave; cuốn s&aacute;ch d&agrave;nh cho bất kỳ ai bối rối hoặc bị cuốn h&uacute;t bởi c&aacute;c dịch vụ t&agrave;i ch&iacute;nh chuy&ecirc;n nghiệp, đang l&agrave;m việc hoặc c&acirc;n nhắc l&agrave;m việc trong lĩnh vực n&agrave;y hoặc đơn giản l&agrave; t&ograve; m&ograve; về số phận của nền kinh tế to&agrave;n cầu. C&ograve;n với tất cả nh&acirc;n vi&ecirc;n kế to&aacute;n, kiểm to&aacute;n, t&agrave;i ch&iacute;nh &ndash; ng&acirc;n h&agrave;ng, đ&acirc;y nhất thiết l&agrave; cuốn s&aacute;ch PHẢI ĐỌC.</p>', 2020, NULL, 272, 20, 13, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (260, N'Làm Sạch Tâm Hồn - Các Bài Tập Thiền (Tái Bản 2024)', N'8935280916289', N'Bìa Mềm', CAST(45045.00 AS Decimal(12, 2)), CAST(99000.00 AS Decimal(12, 2)), CAST(69300.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/l/a/lam-sach-tam-hon---bia-1.jpg', N'Nishi Katsuzo', N'<p><strong>L&agrave;m Sạch T&acirc;m Hồn - C&aacute;c B&agrave;i Tập Thiền</strong></p>
<p><strong><em>&ldquo;L&agrave;m sạch t&acirc;m hồn - c&aacute;c b&agrave;i thiền tập&rdquo;</em></strong>&nbsp;của t&aacute;c giả Nishi Katsuzo do Tiến sĩ Trương Thị Thảo dịch, đ&acirc;y l&agrave; những nội dung v&agrave; c&aacute;c phương ph&aacute;p giảng dạy đ&atilde; được thử th&aacute;ch qua thời gian. Đ&acirc;y l&agrave; những nghi&ecirc;n cứu kiệt xuất trong nền y học tự nhi&ecirc;n của tất cả c&aacute;c d&acirc;n tộc từ xưa cho tới nay. Đ&acirc;y l&agrave; những b&iacute; quyết đ&atilde; được kh&ocirc;i phục lại với những giải th&iacute;ch của c&aacute;c chuy&ecirc;n gia thời nay c&ugrave;ng những lời khuy&ecirc;n hết sức cấp thiết của những nh&agrave; chuy&ecirc;n m&ocirc;n vĩ đại.</p>
<p>Thiền tĩnh t&acirc;m l&agrave; phương ph&aacute;p c&oacute; thể cứu gi&uacute;p ch&uacute;ng ta khi th&acirc;n thể đang suy sụp v&agrave; tinh thần mỏi mệt. Thiền cho t&acirc;m hồn l&agrave; điều đem lại hy vọng v&agrave; chỉ ra con đường dẫn đến phục hồi sức khỏe khi ch&uacute;ng ta cảm thấy dường như mọi con đường đều đ&atilde; bị cắt đứt.</p>
<p>Ở trong trạng th&aacute;i Thiền tĩnh t&acirc;m tức l&agrave; ta biết lắng nghe v&agrave; thấu hiểu được ch&iacute;nh m&igrave;nh, tức l&agrave; ta t&igrave;m ra được lời giải cho mọi vấn đề của bản th&acirc;n &ndash; qua c&aacute;c c&acirc;u trả lời vốn nằm trong ch&iacute;nh m&igrave;nh. Chỉ l&agrave; b&igrave;nh thường ta kh&ocirc;ng lắng nghe ch&uacute;ng do những bận rộn trong đời sống, do những suy nghĩ v&ocirc; nghĩa đang chen ch&uacute;c x&ocirc; đẩy nhau trong đầu. Cơ thể ch&uacute;ng ta rất th&ocirc;ng minh. N&oacute; biết tất cả về sự sống v&agrave; về bản th&acirc;n m&igrave;nh. N&oacute; biết cả những con đường dẫn đến chữa l&agrave;nh bệnh tật. Chỉ l&agrave; ch&uacute;ng ta kh&ocirc;ng tạo cho n&oacute; cơ hội thể hiện sự th&ocirc;ng tuệ n&agrave;y v&agrave;o đời sống m&agrave; th&ocirc;i. Ch&uacute;ng ta kh&ocirc;ng muốn lắng nghe cơ thể m&igrave;nh, ch&uacute;ng ta ưa n&oacute;i nhiều về bản th&acirc;n v&agrave; cứ hay bận rộn tất tả về rất nhiều điều. N&agrave;o, bạn h&atilde;y d&agrave;nh sự ch&uacute; &yacute; n&agrave;y cho ch&iacute;nh cơ thể m&igrave;nh. N&oacute; sẽ n&oacute;i cho bạn biết điều g&igrave; đ&oacute;.</p>
<p>Gi&aacute; như thế giới phương T&acirc;y hiểu được bản chất của y học! Chừng n&agrave;o &iacute;t người bị bệnh hơn, chừng ấy sẽ nhiều người hạnh ph&uacute;c v&agrave; khỏe mạnh hơn! Đ&acirc;y mới đ&uacute;ng l&agrave; dược phẩm huyền diệu &ndash; l&agrave; cơ sở của sức khỏe.</p>
<p>Hồi nhỏ, Nishi Katsuzo đ&atilde; c&oacute; rất nhiều cơ hội học tập nghệ thuật Thiền &ndash; định t&acirc;m, v&igrave; t&aacute;c giả l&agrave; một bệnh nh&acirc;n v&ocirc; phương cứu chữa. C&aacute;c b&aacute;c sĩ đ&atilde; nhận định như thế, cha mẹ &ocirc;ng cũng nhận định như vậy. Nhưng Thiền đ&atilde; gi&uacute;p &ocirc;ng vượt qua c&aacute;i chết. T&aacute;c giả đ&atilde; chi&ecirc;m ngưỡng c&acirc;y hoa anh đ&agrave;o trước khi nở hoa, khi hoa đang nở, v&agrave; khi hoa t&agrave;n, &ocirc;ng nh&igrave;n thấy r&otilde; gi&oacute; đ&atilde; cuốn những c&aacute;nh hoa m&agrave;u hồng rụng xuống như thế n&agrave;o. Rồi v&agrave;o m&ugrave;a xu&acirc;n năm sau, c&acirc;y lại hồi sinh, v&agrave; tất cả lại bắt đầu. T&aacute;c giả đ&atilde; hiểu ra rằng, trong tự nhi&ecirc;n kh&ocirc;ng c&oacute; c&aacute;i chết &ndash; m&agrave; chỉ l&agrave; sự tồn tại đời sống vĩnh hằng li&ecirc;n tục theo v&ograve;ng tr&ograve;n &ldquo;lu&acirc;n hồi sinh tử&rdquo;. Ch&iacute;nh bởi thế n&ecirc;n kh&ocirc;ng việc g&igrave; phải sợ chết. Bản th&acirc;n con người l&agrave; một phần của tự nhi&ecirc;n v&agrave; n&oacute; cũng sẽ sống thuận theo quy luật như thế. T&aacute;c giả kh&ocirc;ng c&ograve;n sợ nữa, v&agrave; từ đấy, qu&aacute; tr&igrave;nh hồi phục sức khỏe của &ocirc;ng bắt đầu.</p>
<p>C&oacute; thể n&oacute;i rằng, sự phục hồi sức khỏe của t&ocirc;i bắt đầu từ khả năng thấu hiểu sự thật về c&aacute;c quy luật đ&iacute;ch thực của thế giới, của vũ trụ v&agrave; của tự nhi&ecirc;n. T&aacute;c giả đ&atilde; thấu hiểu điều ấy th&ocirc;ng qua Thiền, chỉ trong Thiền. Qua Thiền, Nishi Katsuzo nắm được c&aacute;c b&iacute; mật của cơ thể m&igrave;nh, lắng nghe những lời giải đ&aacute;p của n&oacute; đối với c&aacute;c vấn đề của ch&iacute;nh m&igrave;nh &ndash; v&agrave; &ocirc;ng đ&atilde; t&igrave;m được những phương ph&aacute;p đ&uacute;ng đắn đ&iacute;ch thực để chữa bệnh, điều m&agrave; bản th&acirc;n &ocirc;ng rất cần. T&aacute;c giả đ&atilde; t&igrave;m ra con đường n&agrave;y v&agrave; những phương thuốc chữa l&agrave;nh bệnh kh&ocirc;ng phải từ trong s&aacute;ch, cũng kh&ocirc;ng phải từ c&aacute;c cuộc hội thảo của c&aacute;c nh&agrave; b&aacute;c học vĩ đại m&agrave; đ&atilde; t&igrave;m ra ch&uacute;ng từ b&ecirc;n trong bản th&acirc;n m&igrave;nh nhờ nghệ thuật Thiền tập trung tư tưởng.</p>
<p>Sự phục hồi sức khỏe được bắt đầu từ việc kh&aacute;m ph&aacute; trạng th&aacute;i chữa l&agrave;nh bệnh b&ecirc;n trong bản th&acirc;n m&igrave;nh. Ch&uacute;ng ta kh&ocirc;ng thể đi v&agrave;o trong m&igrave;nh với trạng th&aacute;i bận rộn, l&uacute;ng t&uacute;ng của cuộc sống thường nhật, khi đầu &oacute;c ta cứ loay hoay, bận rộn với những quyết định tức thời, với nhiều vấn đề nảy sinh c&ugrave;ng một l&uacute;c, v&agrave; do vậy, n&oacute; kh&ocirc;ng kịp hiểu thấu tất cả những &yacute; nghĩ đang đồng thời chuyển động hỗn loạn theo những l&agrave;n s&oacute;ng cuồn cuộn b&ecirc;n trong. Trạng th&aacute;i chữa l&agrave;nh bệnh l&agrave; một trạng th&aacute;i tĩnh lặng b&ecirc;n trong. Chỉ c&oacute; Thiền mới đem lại cho ch&uacute;ng ta trạng th&aacute;i tĩnh lặng b&ecirc;n trong ấy.</p>
<p>Thiền l&agrave; điều kh&ocirc;ng hề đơn giản đối với con người hiện đại, nhất l&agrave; khi họ phải đối diện với biết bao mối quan t&acirc;m v&agrave; c&aacute;c vấn đề thường nhật. T&aacute;c giả kh&ocirc;ng n&oacute;i rằng cần phải t&igrave;m ra một lối đi kh&aacute;c, một c&aacute;ch tiếp cận kh&aacute;c với sức khỏe của m&igrave;nh để giải quyết h&agrave;ng n&uacute;i vấn đề. Trong trạng th&aacute;i hỗn loạn, l&uacute;ng t&uacute;ng của t&acirc;m tr&iacute;, ch&uacute;ng ta kh&ocirc;ng thể đưa ra được quyết định s&aacute;ng suốt cho c&aacute;c vấn đề, cũng như kh&ocirc;ng thể t&igrave;m thấy con đường dẫn đến sự khỏe mạnh. Sự tĩnh lặng b&ecirc;n trong, trạng th&aacute;i Thiền tập trung tư tưởng, ch&iacute;nh l&agrave; trạng th&aacute;i để sức khỏe tồn tại. Kh&ocirc;ng c&oacute; trạng th&aacute;i n&agrave;y th&igrave; kh&ocirc;ng c&oacute; sức khỏe. Bạn h&atilde;y l&agrave;m cho t&acirc;m tr&iacute; đang hỗn loạn lắng dịu xuống, b&igrave;nh y&ecirc;n lại, h&atilde;y t&igrave;m bằng được cho m&igrave;nh trạng th&aacute;i tĩnh lặng b&ecirc;n trong, trạng th&aacute;i m&agrave; ở đ&oacute; lời giải đ&aacute;p cho mọi vấn đề xuất hiện, trạng th&aacute;i m&agrave; trong đ&oacute;, cơ thể bắt đầu tự chữa l&agrave;nh bệnh. H&atilde;y t&igrave;m bằng được cho m&igrave;nh kho b&aacute;u n&agrave;y &ndash; v&agrave; bạn sẽ khỏe mạnh.</p>', 2024, NULL, 213, 15, 11, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (261, N'Tự Truyện Steven Gerrard - Người Đội Trưởng Vĩ Đại', N'9786043931617', N'Bìa Mềm', CAST(119600.00 AS Decimal(12, 2)), CAST(239000.00 AS Decimal(12, 2)), CAST(184000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786043931617.jpg', N'Donald McRae', N'<p><strong>Tự Truyện Steven Gerrard - Người Đội Trưởng Vĩ Đại</strong></p>
<p>Gia đ&igrave;nh t&ocirc;i sống qua từng trang của cuốn s&aacute;ch n&agrave;y, từ nốt thăng tới nốt trầm, từ kỉ niệm buồn đến kỉ niệm đẹp. Vậy n&ecirc;n, cuốn s&aacute;ch thuộc về họ v&igrave; nếu kh&ocirc;ng c&oacute; t&igrave;nh y&ecirc;u thương v&agrave; sự cổ vũ kh&ocirc;ng ngừng nghỉ của họ, t&ocirc;i sẽ chẳng thể đạt được th&agrave;nh t&iacute;ch n&agrave;o, cả ở trong lẫn ngo&agrave;i s&acirc;n cỏ. T&ocirc;i nợ vợ t&ocirc;i, Alex. C&ocirc; ấy c&oacute; thể kh&ocirc;ng biết nhiều về b&oacute;ng đ&aacute; nhưng l&agrave; người hiểu t&ocirc;i hơn ai hết, vậy n&ecirc;n sự biết ơn lớn nhất phải l&agrave; d&agrave;nh cho vợ t&ocirc;i v&igrave; c&ocirc; ấy đ&atilde; lu&ocirc;n ủng hộ t&ocirc;i, lu&ocirc;n l&agrave; một người vợ tuyệt vời v&agrave; một người mẹ phi thường với ba c&ocirc; con g&aacute;i của t&ocirc;i.</p>
<p>D&ugrave; thấy buồn khi kh&ocirc;ng c&ograve;n được chơi cho Liverpool nữa, nhưng t&ocirc;i rất hạnh ph&uacute;c khi c&oacute; th&ecirc;m thời gian ở b&ecirc;n Alex v&agrave; ba c&ocirc; con g&aacute;i đ&aacute;ng y&ecirc;u Lilly-Ella, Lexie v&agrave; Lourdes. Tại Mỹ, gia đ&igrave;nh t&ocirc;i c&oacute; thể l&agrave;m được nhiều thứ m&agrave; trước kia ch&uacute;ng t&ocirc;i kh&ocirc;ng thể l&agrave;m khi t&ocirc;i c&ograve;n l&agrave; đội trưởng của Liverpool. Gia đ&igrave;nh sẽ l&agrave;m t&ocirc;i cười v&agrave; khiến t&ocirc;i hạnh ph&uacute;c. Từ giờ trở đi, Lilly, Lexie v&agrave; Lourdes sẽ vui vẻ hơn khi c&oacute; một người bố b&igrave;nh thường ở b&ecirc;n cạnh.</p>
<p>Bố v&agrave; mẹ cũng đ&atilde; ủng hộ t&ocirc;i hết m&igrave;nh từ những ng&agrave;y đầu. Họ đ&atilde; tạo dựng trong t&ocirc;i những phẩm chất c&oacute; gi&aacute; trị m&agrave; t&ocirc;i mong m&igrave;nh sẽ truyền lại cho c&aacute;c con. Cảm ơn bố mẹ v&igrave; lu&ocirc;n ở b&ecirc;n con - v&agrave; v&igrave; tất cả sự gi&uacute;p đỡ cũng như lời khuy&ecirc;n của bố mẹ trong suốt 35 năm qua.</p>
<p>Anh trai t&ocirc;i - Paul, th&igrave; giống như một người bạn hơn. Mối quan hệ giữa ch&uacute;ng t&ocirc;i v&ocirc; c&ugrave;ng th&acirc;n thiết v&agrave; t&ocirc;i c&oacute; thể tin cậy v&agrave;o anh mỗi khi gặp kh&oacute; khăn. T&ocirc;i cũng mừng rằng m&igrave;nh đ&atilde; l&agrave;m cho cả bố v&agrave; Paul vui khi ở lại Liverpool trong trọn vẹn sự nghiệp thi đấu tại Anh.</p>
<p>T&ocirc;i cũng rất may mắn khi c&oacute; được một nh&oacute;m bạn th&acirc;n đ&aacute;ng tin cậy. T&ocirc;i c&oacute; thể l&agrave; ch&iacute;nh m&igrave;nh, v&agrave; tất cả ch&uacute;ng t&ocirc;i cười đ&ugrave;a vui vẻ mỗi khi t&ocirc;i ở cạnh họ. Vẫn như thường lệ, cảm ơn anh em rất nhiều.</p>
<p>Cuốn s&aacute;ch n&agrave;y cũng l&agrave; d&agrave;nh cho cổ động vi&ecirc;n số một thế giới - những người h&acirc;m mộ Liverpool FC, v&igrave; nếu kh&ocirc;ng c&oacute; họ, t&ocirc;i sẽ chẳng bao giờ c&oacute; thể trung th&agrave;nh với một đội b&oacute;ng. Sự ủng hộ của họ c&ugrave;ng m&agrave;n ch&agrave;o tạm biệt đ&aacute;ng nhớ khiến t&ocirc;i biết m&igrave;nh sẽ kh&ocirc;ng bao giờ hối hận v&igrave; lu&ocirc;n chọn Liverpool. Người h&acirc;m mộ Liverpool khiến t&ocirc;i cảm thấy m&igrave;nh may mắn v&agrave; cả c&aacute;c cổ động vi&ecirc;n trung th&agrave;nh của đội tuyển Anh theo t&ocirc;i v&agrave; đội đi khắp thế giới cũng vậy. Kh&ocirc;ng c&oacute; những fan ch&acirc;n ch&iacute;nh đ&oacute;, b&oacute;ng đ&aacute; sẽ chẳng c&ograve;n &yacute; nghĩa nữa.</p>
<p>T&ocirc;i muốn cảm ơn tất cả mọi người tại Liverpool FC - c&aacute;c huấn luyện vi&ecirc;n cũ, đồng đội cũ, nh&acirc;n vi&ecirc;n bảo vệ, đội ngũ y tế, nh&acirc;n vi&ecirc;n văn ph&ograve;ng v&agrave; tất cả những ai c&oacute; li&ecirc;n quan tới c&acirc;u lạc bộ ở Anfield, tại s&acirc;n tập Melwood v&agrave; c&aacute;c học viện nơi t&ocirc;i từng được huấn luyện tại Merseyside. Việc t&ocirc;i c&ograve;n gần gũi với nhiều người tại Liverpool đến vậy đ&atilde; n&oacute;i l&ecirc;n rất nhiều thứ về c&acirc;u lạc bộ. T&ocirc;i rất muốn một ng&agrave;y n&agrave;o đ&oacute; sẽ được trở lại &ndash; bất kể l&agrave; với vai tr&ograve; g&igrave; m&agrave; Liverpool FC tin t&ocirc;i c&oacute; thể đ&oacute;ng g&oacute;p.</p>
<p>K&iacute;nh mời c&aacute;c bạn đến với những c&acirc;u chuyện trong trang s&aacute;ch!</p>', 2025, NULL, 438, 16, 11, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (262, N'Andrés Iniesta The Artist - Khi Bóng Đá Là Nghệ Thuật', N'9786045533963', N'Bìa Mềm', CAST(67177.50 AS Decimal(12, 2)), CAST(159000.00 AS Decimal(12, 2)), CAST(103350.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_180272.jpg', N'Peter Jenson, Sid Love', N'<p>C&oacute; một điều kh&aacute; hoang đường trong thời đại truyền th&ocirc;ng như b&acirc;y giờ, đ&oacute; l&agrave; sự tồn tại của những cầu thủ kh&ocirc;ng c&oacute; antifan. Vậy m&agrave; Andr&eacute;s Iniesta lại l&agrave; một người nằm trong c&otilde;i hoang đường đ&oacute;. Ch&agrave;ng trai ấy sở hữu t&agrave;i năng xuất ch&uacute;ng, nh&acirc;n c&aacute;ch hiền hậu, những ph&aacute;t ng&ocirc;n chuẩn mực, v&agrave; đặc biệt l&agrave; những b&agrave;n thắng tuy kh&ocirc;ng nhiều nhưng b&ugrave;ng nổ đất trời. Thế rồi, ta rời khỏi những d&ograve;ng t&igrave;m kiếm tr&ecirc;n Google, rời khỏi thảm cỏ xanh mướt, v&agrave; thời khắc ta lật cuốn s&aacute;ch &ldquo;Andr&eacute;s Iniesta - Khi b&oacute;ng đ&aacute; l&agrave; nghệ thuật&rdquo;, th&igrave; điều đập v&agrave;o mắt ta l&agrave; một thế giới kh&aacute;c: thế giới nội t&acirc;m đầy những hỷ nộ &aacute;i ố, cắn rứt, đau khổ của con người ngỡ rằng c&oacute; tất cả ấy. Đ&oacute; l&agrave; một thế giới nghệ thuật mang t&ecirc;n Andr&eacute;s Iniesta m&agrave; như anh bảo &ldquo;T&ocirc;i d&agrave;nh cho bạn những g&igrave; bạn chưa biết&hellip;&rdquo;</p>
<p><strong>(Dũng Phan)</strong></p>', 2018, NULL, 388, 11, 10, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (263, N'Hồi Ký Alex Ferguson (Tái Bản 2019)', N'8934974160137', N'Bìa Mềm', CAST(95550.00 AS Decimal(12, 2)), CAST(175000.00 AS Decimal(12, 2)), CAST(147000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/c/c/cccccc_2.jpg', N'Alex Ferguson', N'<p><strong>Hồi K&yacute; Alex Ferguson (T&aacute;i Bản 2019)</strong></p>
<p>Hồi k&yacute; Ferguson l&agrave; c&acirc;u chuyện đấy ấn tượng về con người được thừa nhận rộng r&atilde;i l&agrave; huấn luyện vi&ecirc;n xuất sắc nhất trong lịch sử b&oacute;ng đ&aacute; Li&ecirc;n hiệp Anh.</p>
<p>&nbsp;Cuốn s&aacute;ch đầy ắp c&aacute;c c&acirc;u chuyện th&uacute; vị v&agrave; những quan điểm thẳng thắn, kh&ocirc;ng khoan nhượng, theo đ&oacute; c&acirc;u chuyện của vị HLV t&agrave;i ba n&agrave;y bắt đầu từ Govan, một thị trấn đ&oacute;ng t&agrave;u tại Glasgow, trải d&agrave;i qua một sự nghiệp huấn luyện v&ocirc; c&ugrave;ng lừng lẫy, với c&uacute;p ch&acirc;u &Acirc;u lần đầu ti&ecirc;n cho CLB Aberdeen v&agrave; 27 năm th&agrave;nh c&ocirc;ng với Manchester United.</p>
<p>&nbsp;Trong một phần tư thế kỷ tại Manchester United đ&atilde; c&oacute; v&ocirc; số thay đổi khi CLB b&oacute;ng đ&aacute; n&agrave;y ph&aacute;t triển th&agrave;nh một thế lực thể thao mang tầm thế giới. Tuy nhi&ecirc;n, vẫn c&oacute; những thứ kh&ocirc;ng hề thay đổi, đ&oacute; l&agrave; vị HLV trưởng Alex Ferguson, chất lượng h&agrave;ng đầu của đội b&oacute;ng, c&ugrave;ng h&agrave;ng loạt th&agrave;nh c&ocirc;ng trong thi đấu, nổi bật l&agrave; việc đoạt chức v&ocirc; địch Champions League lần thứ hai năm 2008 v&agrave; chức v&ocirc; địch Premier League năm 2013.</p>
<p>&nbsp;Ch&iacute;nh bởi tầm nh&igrave;n xa tr&ocirc;ng rộng, năng lượng dồi d&agrave;o v&agrave; những kỹ năng huấn luyện tuyệt vời m&agrave; Sir Alex đ&atilde; c&oacute; thể x&acirc;y dựng được c&aacute;c đội h&igrave;nh th&agrave;nh c&ocirc;ng của &ocirc;ng tại MU, cả khi thi đấu lẫn khi tập luyện. Trong t&aacute;c phẩm n&agrave;y, bằng phong c&aacute;ch hấp dẫn v&agrave; s&acirc;u sắc, Sir Alex Ferguson kể lại cho ch&uacute;ng ta c&acirc;u chuyện về việc &ocirc;ng đ&atilde; đ&agrave;o tạo được một đội ngũ t&agrave;i năng, gồm những ch&agrave;ng trai như Ryan Giggs, David Beckham, Nicky Butt, Paul Scholes v&agrave; anh em nh&agrave; Neville như thế n&agrave;o.</p>
<p>&nbsp;L&agrave; một HLV với kỹ năng huấn luyện xuất ch&uacute;ng, Sir Alex Ferguson lu&ocirc;n thể hiện sự chăm s&oacute;c, động vi&ecirc;n nhưng vẫn rất nghi&ecirc;m khắc, cứng rắn khi l&agrave;m việc với những danh thủ h&agrave;ng đầu tại MU như Ryan Giggs, Roy Keane, Eric Cantona v&agrave; Ruud van Nistelrooy, hay khi đối xử với những ng&ocirc;i sao tầm thế giới như Cristiano Ronaldo v&agrave; David Beckham, những người xem &ocirc;ng như một người cha tinh thần.</p>
<p>&nbsp;Ngo&agrave;i ra, cuốn hồi k&yacute; c&ograve;n d&agrave;nh nhiều trang n&oacute;i về mối &ldquo;th&acirc;m th&ugrave;&rdquo; trong b&oacute;ng đ&aacute; giữa Manchester United v&agrave; những đại k&igrave;nh địch như Liverpool, Arsenal, Chelsea hay gần đ&acirc;y l&agrave; Manchester City. Với n&eacute;t h&oacute;m hỉnh, đ&ocirc;i khi cay độc, t&aacute;c giả cũng kể về mối quan hệ đầy cạnh tranh v&agrave; s&oacute;ng gi&oacute; với những đồng nghiệp nổi danh như Ars&egrave;ne Wenger v&agrave; Jos&eacute; Mourinho.</p>
<p>&nbsp;Tuy cả t&acirc;m l&yacute; huấn luyện v&agrave; chiến lược b&oacute;ng đ&aacute; đỉnh cao đều l&agrave; những vấn đề chuy&ecirc;n m&ocirc;n kh&ocirc;ng dễ giải th&iacute;ch, nhưng kh&oacute; ai c&oacute; thể tr&igrave;nh b&agrave;y ch&uacute;ng với ng&ocirc;n ngữ trong s&aacute;ng, th&uacute; vị v&agrave; giản dị đối với độc giả th&ocirc;ng thường như t&aacute;c giả cuốn hồi k&yacute; n&agrave;y.</p>
<p>&nbsp;Ngo&agrave;i b&oacute;ng đ&aacute;, Sir Alex Ferguson c&oacute; cuộc sống gia đ&igrave;nh rất đầm ấm v&agrave; hạnh ph&uacute;c, &ocirc;ng cũng duy tr&igrave; nhiều sở th&iacute;ch kh&aacute;c như xem đua ngựa, đọc s&aacute;ch v.v&hellip; Cuộc sống của vị HLV t&agrave;i ba n&agrave;y quả thật v&ocirc; c&ugrave;ng hấp dẫn v&agrave; phong ph&uacute;.</p>
<p>&nbsp;Hồi k&yacute; Alex Ferguson l&agrave; cuốn s&aacute;ch chứa đựng nhiều bất ngờ được h&eacute; lộ, được viết v&ocirc; c&ugrave;ng hấp dẫn, v&agrave; tr&ecirc;n hết, cực kỳ truyền cảm hứng cho người đọc.</p>', 2019, NULL, 344, 21, 7, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (264, N'Thỏa Giấc Mơ Vàng', N'9786045549247', N'Bìa Mềm', CAST(46052.50 AS Decimal(12, 2)), CAST(109000.00 AS Decimal(12, 2)), CAST(70850.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_195509_1_24761.jpg', N'Nhiều Tác Giả', N'<p>Khi đặt b&uacute;t viết 2 chữ &ldquo;hiện thực&rdquo;, trong t&ocirc;i bỗng tr&agrave;o d&acirc;ng nhiều nỗi niềm, bởi chưa bao giờ thấy 2 chữ &ldquo;hiện thực&rdquo; lại c&oacute; độ d&agrave;i khủng khiếp, v&agrave; lại khiến ch&uacute;ng ta vất vả đến như thế. Chung kết b&oacute;ng đ&aacute; nam SEA Games năm 1995 tại Th&aacute;i Lan với đội chủ nh&agrave;, ch&uacute;ng ta đ&atilde; kh&ocirc;ng d&aacute;m nghĩ đến 2 chữ &ldquo;hiện thực&rdquo;, v&igrave; hồi đ&oacute; v&agrave;o được chung kết đ&atilde; l&agrave; qu&aacute; vẻ vang, v&agrave; một đội tuyển Việt Nam mới hội nhập trở lại với l&agrave;ng cầu quốc tế th&igrave; kh&ocirc;ng c&oacute; &ldquo;cửa&rdquo; khi đặt b&ecirc;n cạnh &ldquo;&ocirc;ng kẹ&rdquo; Th&aacute;i. Chung kết b&oacute;ng đ&aacute; nam SEA Games năm 2005, ch&uacute;ng ta cũng kh&ocirc;ng d&aacute;m nghĩ đến 2 chữ &ldquo;hiện thực&rdquo; v&igrave; đấy l&agrave; trận chung kết m&agrave; &ldquo;nghi &aacute;n b&aacute;n độ&rdquo; ở v&ograve;ng bảng đ&atilde; phủ một c&aacute;i b&oacute;ng đen nặng nề l&ecirc;n t&acirc;m l&yacute; nhiều cầu thủ.&rdquo;</p>', 2019, NULL, 227, 16, 1, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (265, N'Pele Cuộc Đời Và Thời Đại', N'8934974166528', N'Bìa Mềm', CAST(95550.00 AS Decimal(12, 2)), CAST(175000.00 AS Decimal(12, 2)), CAST(147000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_195509_1_31594.jpg', N'Harry Harris', N'<p>L&agrave; t&aacute;c phẩm b&aacute;n chạy tại Anh v&agrave; Mỹ ngay từ lần xuất bản đầu ti&ecirc;n, cuốn s&aacute;ch n&agrave;y l&agrave; tiểu sử được cho ph&eacute;p đầu ti&ecirc;n, v&agrave; đầy đủ nhất, của cầu thủ b&oacute;ng đ&aacute; vĩ đại nhất thế giới. C&oacute; cơ hội tiếp cận đặc biệt với ch&iacute;nh Pel&eacute;, t&aacute;c giả chuy&ecirc;n viết về đề t&agrave;i thể thao Harry Harris kể lại cho ch&uacute;ng ta nghe qu&aacute; tr&igrave;nh thăng tiến phi thường của Pel&eacute;, từ một gia đ&igrave;nh ngh&egrave;o kh&oacute; ở Brazil đến lần ra mắt đội tuyển quốc gia ở tuổi 16. Kỹ năng chơi b&oacute;ng si&ecirc;u hạng, khả năng tư duy nhạy b&eacute;n tr&ecirc;n s&acirc;n cỏ v&agrave; khả năng kiểm so&aacute;t b&oacute;ng tuyệt diệu đ&atilde; gi&uacute;p Pel&eacute; trở th&agrave;nh cầu thủ duy nhất ba lần đoạt chức v&ocirc; địch b&oacute;ng đ&aacute; thế giới, ghi được hơn 1.200 b&agrave;n thắng trong sự nghiệp &ndash; một kỷ lục m&agrave; c&oacute; lẽ kh&oacute; ai c&oacute; thể bắt kịp, chứ chưa n&oacute;i tới chuyện vượt qua.<br>Pel&eacute; vẫn l&agrave; cầu thủ b&oacute;ng đ&aacute; vĩ đại nhất mọi thời đại, bất chấp những th&agrave;nh t&iacute;ch xuất sắc của c&aacute;c danh thủ kh&aacute;c như Cristiano Ronaldo, Lionel Messi, Neymar hiện nay, hay những huyền thoại trước kia như Diego Maradona v&agrave; Johan Cruyff. Ấn bản n&agrave;y của cuốn s&aacute;ch được sửa đổi v&agrave; cập nhật đến năm 2018, như một sự t&ocirc;n vinh d&agrave;nh cho một ng&ocirc;i sao thể thao tầm thế giới, nguồn cảm hứng cho rất nhiều người tr&ecirc;n tr&aacute;i đất n&agrave;y.</p>', 2020, NULL, 312, 21, 8, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (266, N'Chạy Bộ Cùng Người Kenya', N'8935251414646', N'Bìa Mềm', CAST(68250.00 AS Decimal(12, 2)), CAST(150000.00 AS Decimal(12, 2)), CAST(105000.00 AS Decimal(12, 2)), N'https://res.cloudinary.com/dabxzdaf8/image/upload/v1748969226/Book_cover/graprxs3kcc24d6gr8gt.webp', N'Adharanad Finn', N'<p>Chạy bộ c&ugrave;ng người Kenya l&agrave; c&acirc;u chuyện về s&aacute;u th&aacute;ng trải nghiệm thực tế của c&acirc;y b&uacute;t thể thao Adharanand Finn. Quyết định đưa cả gia đ&igrave;nh (gồm vợ v&agrave; ba con nhỏ) khỏi cuộc sống tiện nghi tại Anh Quốc, Finn đến với một thị trấn nhỏ tại Thung lũng Rift của Kenya &ndash; nơi được coi l&agrave; &ldquo;th&aacute;nh địa&rdquo; của những người chạy bộ cự ly d&agrave;i. Tại đ&acirc;y, t&aacute;c giả được tập luyện c&ugrave;ng những nh&agrave; v&ocirc; địch Olympic, những người trẻ tuổi đầy nhiệt huyết v&agrave; hy vọng, hay những đứa trẻ chạy bộ h&agrave;ng c&acirc;y số đến trường mỗi ng&agrave;y; được trao đổi v&agrave; chia sẻ c&ugrave;ng một số chuy&ecirc;n gia hay t&ecirc;n tuổi h&agrave;ng đầu trong giới huấn luyện vi&ecirc;n. Đ&acirc;y cũng l&agrave; nơi anh gặp những c&aacute; nh&acirc;n vừa ti&ecirc;u biểu vừa rất ri&ecirc;ng của l&agrave;ng chạy bộ Kenya, c&ugrave;ng họ lập n&ecirc;n một nh&oacute;m để tập luyện cho giải chạy Lewa. Liệu nhờ đ&oacute; Finn c&oacute; đạt được mục đ&iacute;ch kh&aacute;m ph&aacute; ra c&aacute;c b&iacute; mật đằng sau th&agrave;nh c&ocirc;ng của &ldquo;những người nhanh nhất thế giới&rdquo; n&agrave;y? &Iacute;t nhất anh cũng t&igrave;m ra được kh&ocirc;ng &iacute;t yếu tố độc đ&aacute;o m&agrave; hiếm nơi kh&aacute;c tr&ecirc;n thế giới c&oacute; được: độ cao lớn so với mực nước biển, những năm th&aacute;ng ấu thơ chạy bộ đến trường, th&oacute;i quen chạy ch&acirc;n đất, việc ch&uacute; t&acirc;m d&agrave;nh to&agrave;n bộ cuộc sống cho sự nghiệp chạy bộ, hay đơn giản l&agrave; ước mơ đổi đời nhờ chạy bộ, hay thậm ch&iacute; l&agrave; yếu tố &ldquo;gen di truyền&rdquo;&hellip; Nhưng d&ugrave; b&iacute; quyết thực sự của họ l&agrave; g&igrave;, điều m&agrave; Finn hay bất cứ độc giả n&agrave;o cũng c&oacute; thể thấy được qua t&aacute;c phẩm n&agrave;y, chắc chắn l&agrave; t&igrave;nh y&ecirc;u nguy&ecirc;n sơ d&agrave;nh cho chạy bộ, d&ugrave; cuộc sống nơi đ&acirc;y c&oacute; kh&oacute; khăn đến nhường n&agrave;o.</p>
<p><strong>+T&Aacute;C GIẢ :&nbsp;</strong></p>
<p>Adharanad Finn l&agrave; một bi&ecirc;n tập vi&ecirc;n, một nh&agrave; b&aacute;o tự do với c&aacute;c b&agrave;i viết đ&oacute;ng g&oacute;p cho tạp ch&iacute; The Guardian, The Independent v&agrave; Runner&rsquo;s World. Anh cũng l&agrave; cựu vận động vi&ecirc;n chạy đường trường, từng chiến thắng giải cự ly 10K ở Devon, Anh Quốc, nơi anh v&agrave; gia đ&igrave;nh sinh sống. &nbsp;</p>', 2020, NULL, 292, 8, 3, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (267, N'Barça Lionel Messi Và Sự Thăng Trầm Của Câu Lạc Bộ Bóng Đá Vĩ Đại Nhất Thế Giới', N'8934974183105', N'Bìa Mềm', CAST(112125.00 AS Decimal(12, 2)), CAST(230000.00 AS Decimal(12, 2)), CAST(172500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8934974183105.jpg', N'Simon Kuper', N'<p>Với nguồn th&ocirc;ng tin nội bộ v&agrave; khả năng tiếp cận kh&oacute; ai c&oacute; được, Simon Kuper, ph&oacute;ng vi&ecirc;n l&acirc;u năm của Financial Times, kể lại những c&acirc;u chuyện về FC Barcelona, tập trung v&agrave;o c&aacute;i c&aacute;ch m&agrave; họ đ&atilde; trở th&agrave;nh c&acirc;u lạc bộ th&agrave;nh c&ocirc;ng nhất thế giới, v&agrave; l&yacute; do tại sao giờ đ&acirc;y kỷ nguy&ecirc;n vang dội đ&oacute; đang đi v&agrave;o giai đoạn kết th&uacute;c. FC Barcelona kh&ocirc;ng chỉ l&agrave; c&acirc;u lạc bộ thể thao c&oacute; doanh thu cao nhất thế giới, m&agrave; c&ograve;n l&agrave; một trong những tổ chức c&oacute; tầm ảnh hưởng lớn nhất. Họ c&oacute; khoảng 214 triệu người đăng k&yacute; theo d&otilde;i tr&ecirc;n mạng x&atilde; hội, cao hơn mọi c&acirc;u lạc bộ thể thao kh&aacute;c, trừ Real Madrid. Con số n&agrave;y thậm ch&iacute; cao hơn tổng số người theo d&otilde;i của 32 đội b&oacute;ng ở giải B&oacute;ng bầu dục Quốc gia Mỹ (NFL). Barcelona giống c&aacute;c tập đo&agrave;n đa quốc gia, thậm ch&iacute; l&agrave; c&aacute;c quốc gia nhỏ, hơn l&agrave; giống với một c&acirc;u lạc bộ b&oacute;ng đ&aacute; b&igrave;nh thường. Kh&ocirc;ng c&oacute; g&igrave; ngạc nhi&ecirc;n khi phương ch&acirc;m của họ l&agrave; &ldquo;Hơn cả một c&acirc;u lạc bộ&rdquo;. Nhưng điều đ&oacute; kh&ocirc;ng phải l&uacute;c n&agrave;o cũng đ&uacute;ng. Trong ba thập kỷ vừa qua, Barcelona từ một đội b&oacute;ng địa phương đ&atilde; vươn l&ecirc;n tầm một c&acirc;u lạc bộ h&agrave;ng đầu thế giới, l&agrave; h&igrave;nh mẫu về phong độ xuất sắc v&agrave; lối chơi b&oacute;ng đ&aacute; đẹp, v&agrave; li&ecirc;n tiếp gi&agrave;nh nhiều chức v&ocirc; địch c&aacute;c giải đấu kh&aacute;c nhau. Simon Kuper ph&acirc;n t&iacute;ch chi tiết qu&aacute; tr&igrave;nh chuyển đổi đ&oacute;, tập trung v&agrave;o hai ng&ocirc;i sao s&aacute;ng nhất l&agrave; Johan Cruyff v&agrave; Lionel Messi, người c&oacute; thể được xem l&agrave; cầu thủ vĩ đại nhất mọi thời đại. Gia nhập Bar&ccedil;a từ khi mới 13 tuổi, hơn bất kỳ ai kh&aacute;c, Messi ch&iacute;nh l&agrave; động cơ v&agrave; người dẫn đầu trong mọi vinh quang của đội b&oacute;ng n&agrave;y. Tuy nhi&ecirc;n, thời của Messi cũng đang đi dần tới hồi kết, v&agrave; c&ugrave;ng với điều đ&oacute; l&agrave; sự đi xuống của một giai đoạn v&agrave;ng son tại Barcelona. Cuốn s&aacute;ch dẫn dắt độc giả đi qua những bước thăng trầm của c&acirc;u lạc bộ vĩ đại n&agrave;y.&nbsp;<br>Như nhiều tổ chức h&agrave;ng đầu tr&ecirc;n thế giới, FC Barcelona bảo vệ rất kỹ c&aacute;c b&iacute; mật của họ, hầu như kh&ocirc;ng cho người ngo&agrave;i tiếp cận s&acirc;u v&agrave;o nội t&igrave;nh Camp Nou. Sau nhiều thập kỷ viết b&agrave;i về b&oacute;ng đ&aacute; v&agrave; Barcelona, Simon Kuper mới được ph&eacute;p tiếp cận v&agrave; t&igrave;m hiểu những con người ở hậu trường đang h&agrave;ng ng&agrave;y nỗ lực để duy tr&igrave; th&agrave;nh t&iacute;ch cao nhất cho đội b&oacute;ng. V&igrave; thế, những c&acirc;u chuyện trong cuốn s&aacute;ch n&agrave;y nhiều khi đ&atilde; vượt qua ranh giới của b&oacute;ng đ&aacute;, hướng tới việc t&igrave;m hiểu FC Barcelona như l&agrave; một hiện tượng x&atilde; hội, văn h&oacute;a v&agrave; ch&iacute;nh trị c&oacute; một kh&ocirc;ng hai.</p>', 2022, NULL, 440, 15, 11, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (268, N'Quái Kiệt Marathon - Hồi Ký Người Chạy Xuyên Đêm', N'8935077039702', N'Bìa Mềm', CAST(100100.00 AS Decimal(12, 2)), CAST(220000.00 AS Decimal(12, 2)), CAST(154000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935077039702.jpg', N'Dean Karnazes', N'<p><strong>Qu&aacute;i Kiệt Marathon - Hồi K&yacute; Người Chạy Xuy&ecirc;n Đ&ecirc;m</strong></p>
<p><em>&ldquo;Một huyền thoại chạy việt d&atilde;&rdquo;.</em></p>
<p>~ Tạp ch&iacute; Men&rsquo;s Journal ~</p>
<p>Một trong những nỗ lực thể chất đầy tham vọng cho đến nay của Dean Karnazes, người đ&atilde; tham gia 50 cuộc chạy marathon tại 50 tiểu bang kh&aacute;c nhau trong v&ograve;ng 50 ng&agrave;y, nhằm n&acirc;ng cao nhận thức về t&igrave;nh trạng b&eacute;o ph&igrave; ở thanh thiếu ni&ecirc;n v&agrave; khuyến kh&iacute;ch người Mỹ &ldquo;nối tiếp bước ch&acirc;n của m&igrave;nh&rdquo;.</p>
<p>&ldquo;Qu&aacute;i kiệt marathon: 50 cuộc chạy marathon tại 50 tiểu bang trong 50 ng&agrave;y&rdquo; l&agrave; một bộ phim t&agrave;i liệu d&otilde;i theo từng bước ch&acirc;n đầy nhiệm m&agrave;u của Dean trong thử th&aacute;ch chạy marathon dọc nước Mỹ. Dị nh&acirc;n trứ danh trong l&agrave;ng chạy đường d&agrave;i Dean Karnazes đ&atilde; chạy 262 dặm (422 km) &ndash; tương đương với 10 cuộc chạy marathon &ndash; m&agrave; kh&ocirc;ng hề nghỉ ngơi. Anh ấy đ&atilde; băng rừng, vượt Thung Lũng Chết, chạy marathon tại Cao Nguy&ecirc;n Nam Cực v&agrave; c&oacute; lẽ Dean l&agrave; người đầu ti&ecirc;n ăn hết một chiếc pizza trong khi vẫn đang chạy. Dưới c&aacute;i nh&igrave;n s&acirc;u sắc, sự ch&acirc;n th&agrave;nh v&agrave; h&agrave;i hước hiếm gặp trong số c&aacute;c hồi k&yacute; thể thao (được viết bởi Dean Karnazes v&agrave; kh&ocirc;ng hề c&oacute; sự gi&uacute;p đỡ của đồng t&aacute;c giả), cuốn s&aacute;ch &ldquo;Qu&aacute;i kiệt marathon: Hồi k&yacute; người chạy xuy&ecirc;n đ&ecirc;m&rdquo; đ&atilde; truyền cảm hứng cho h&agrave;ng chục ngh&igrave;n người, từ những người kh&ocirc;ng c&oacute; th&oacute;i quen chạy bộ đến những người chạy đam m&ecirc; chạy bộ, tự th&uacute;c đẩy bản th&acirc;n bước ra khỏi v&ugrave;ng an to&agrave;n v&agrave; gợi lại cho họ &ldquo;cuộc sống thực sự l&agrave; như thế n&agrave;o&rdquo; (theo lời của Sam Fussel, t&aacute;c giả của cuốn &ldquo;Muscle&rdquo;).</p>
<p>Cuốn s&aacute;ch &ldquo;Qu&aacute;i kiệt Marathon&rdquo; sẽ trả lời c&aacute;c c&acirc;u hỏi m&agrave; Karnazes li&ecirc;n tục được hỏi:</p>
<p>- Sao anh lại thực hiện thử th&aacute;ch n&agrave;y?</p>
<p>- Anh đ&atilde; l&agrave;m như thế n&agrave;o?</p>
<p>- Liệu anh c&oacute; bị đi&ecirc;n hay kh&ocirc;ng?</p>
<p>V&agrave; trong ấn phẩm mới nhất, Karnazes đ&atilde; trả lời th&ecirc;m hai c&acirc;u hỏi m&agrave; anh nhận được nhiều nhất trong c&aacute;c buổi gặp gỡ độc giả của m&igrave;nh:</p>
<p>- Chế độ ăn của anh như thế n&agrave;o?</p>
<p>- Anh đ&atilde; luyện tập những g&igrave; để cơ thể lu&ocirc;n c&acirc;n đối?</p>
<p>H&atilde;y c&ugrave;ng đ&oacute;n đọc cuốn s&aacute;ch n&agrave;y, cuốn s&aacute;ch nằm top National Bestseller, cuốn s&aacute;ch l&agrave; những kinh nghiệm được đ&uacute;c kết từ Dean&rsquo;s về chế độ ăn uống v&agrave; tập luyện.</p>', 2023, NULL, 408, 17, 3, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (269, N'Giải Thích Ngữ Pháp Tiếng Anh (Tái Bản 2024)', N'8794069303524', N'Bìa Mềm', CAST(100100.00 AS Decimal(12, 2)), CAST(220000.00 AS Decimal(12, 2)), CAST(154000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/g/i/giaithichnguphapta-tb2024_bia1.jpg', N'Mai Lan Hương, Hà Thanh Uyên', N'<p><strong>Giải Th&iacute;ch Ngữ Ph&aacute;p Tiếng Anh</strong></p>
<p>Ngữ ph&aacute;p Tiếng Anh tổng hợp c&aacute;c chủ điểm ngữ ph&aacute;p trọng yếu m&agrave; học sinh cần nắm vững. C&aacute;c chủ điểm ngữ ph&aacute;p được tr&igrave;nh b&agrave;y r&otilde; r&agrave;ng, chi tiết. Sau mỗi chủ điểm ngữ ph&aacute;p l&agrave; phần b&agrave;i tập &amp; đ&aacute;p &aacute;n nhằm gi&uacute;p c&aacute;c em củng cố kiến thức đ&atilde; học, đồng thời tự kiểm tra kết quả.</p>
<p>S&aacute;ch Giải Th&iacute;ch Ngữ Ph&aacute;p Tiếng Anh, t&aacute;c Mai Lan Hương &ndash; H&agrave; Thanh Uy&ecirc;n, l&agrave; cuốn s&aacute;ch ngữ ph&aacute;p đ&atilde; được ph&aacute;t h&agrave;nh v&agrave; t&aacute;i bản rất nhiều lần trong những năm qua.</p>
<p>Giải Th&iacute;ch Ngữ Ph&aacute;p Tiếng Anh được bi&ecirc;n soạn th&agrave;nh 9 chương, đề cập đến những vấn đề ngữ ph&aacute;p từ cơ bản đến n&acirc;ng cao, ph&ugrave; hợp với mọi tr&igrave;nh độ. C&aacute;c chủ điểm ngữ ph&aacute;p trong từng chương được bi&ecirc;n soạn chi tiết, giải th&iacute;ch cặn kẽ c&aacute;c c&aacute;ch d&ugrave;ng v&agrave; quy luật m&agrave; người học cần nắm vững. Sau mỗi chủ điểm ngữ ph&aacute;p l&agrave; phần b&agrave;i tập đa dạng nhằm gi&uacute;p người học củng cố l&yacute; thuyết.</p>
<p>Hy vọng Giải Th&iacute;ch Ngữ Ph&aacute;p Tiếng Anh sẽ l&agrave; một quyển s&aacute;ch thiết thực, đ&aacute;p ứng y&ecirc;u cầu học, &ocirc;n tập v&agrave; n&acirc;ng cao tr&igrave;nh độ ngữ ph&aacute;p cho người học v&agrave; l&agrave; quyển s&aacute;ch tham khảo bổ &iacute;ch d&agrave;nh cho gi&aacute;o vi&ecirc;n.</p>', 2021, NULL, 560, 10, 15, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (270, N'Giúp Trí Nhớ Ngữ Pháp Tiếng Anh Và Động Từ Bất Quy Tắc', N'8931805024026', N'Bìa Mềm', CAST(3575.00 AS Decimal(12, 2)), CAST(7000.00 AS Decimal(12, 2)), CAST(5500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_195509_1_32135.jpg', N'Chính Bình', N'<p>Gi&uacute;p Tr&iacute; Nhớ Ngữ Ph&aacute;p Tiếng Anh V&agrave; Động Từ Bất Quy Tắc</p>', 2020, NULL, 1, 10, 4, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (273, N'"Chém" Tiếng Anh Không Cần Động Não - Tặng Kèm Bộ Video Luyện Nghe-Nói + Sổ Học Từ Vựng', N'8794069305344', N'Bìa Mềm', CAST(82387.50 AS Decimal(12, 2)), CAST(169000.00 AS Decimal(12, 2)), CAST(126750.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/c/h/chemta-bino_bia1.jpg', N'Bino Chém Tiếng Anh', N'<p><strong>&ldquo;Ch&eacute;m<em>&rdquo;&nbsp;</em>Tiếng Anh Kh&ocirc;ng Cần Động N&atilde;o</strong></p>
<p><em>&ldquo;Phần lớn người Việt đều biết tiếng Anh NHIỀU HƠN HỌ NGHĨ, chỉ l&agrave; họ chưa biết l&agrave;m thế n&agrave;o để đưa &yacute; tưởng th&agrave;nh lời n&oacute;i m&agrave; th&ocirc;i!&rdquo;&nbsp;</em>- Bino ch&eacute;m tiếng Anh</p>
<p>Biết nhiều tiếng Anh nhưng kh&ocirc;ng&hellip; n&oacute;i được - điều n&agrave;y c&oacute; đ&uacute;ng với bạn kh&ocirc;ng? Sao 12 năm học tiếng Anh kh&ocirc;ng gi&uacute;p ch&uacute;ng ta xử l&yacute; được những cuộc tr&ograve; chuyện th&ocirc;ng thường?</p>
<p>Sao điểm tiếng Anh tr&ecirc;n lớp to&agrave;n 9, 10 nhưng gặp T&acirc;y lại ấp a ấp &uacute;ng? Sao sở hữu điểm IELTS 7.0+ nhưng vẫn &ldquo;sốc ng&ocirc;n ngữ&rdquo; khi ra nước ngo&agrave;i?</p>
<p>Nguy&ecirc;n nh&acirc;n c&oacute; lẽ nằm nhiều ở c&aacute;ch gi&aacute;o dục truyền thống tại Việt Nam - vốn nặng t&iacute;nh học thuật, thiếu &ldquo;hơi thở đời thường&rdquo;, &iacute;t luyện tập v&agrave; &iacute;t nhấn mạnh v&agrave;o thứ ng&ocirc;n ngữ tự nhi&ecirc;n m&agrave; người bản xứ thường n&oacute;i với nhau.</p>
<p><em>&ldquo;Ch&eacute;m tiếng Anh kh&ocirc;ng cần động n&atilde;o&rdquo;&nbsp;</em>của t&aacute;c giả Bino - chủ k&ecirc;nh TikTok @<em>binochemtienganh</em>&nbsp;với hơn 750 ngh&igrave;n người theo d&otilde;i - được thiết kế để giải quyết điểm kh&oacute; cố hữu tr&ecirc;n. Với c&aacute;ch tiếp cận nặng t&iacute;nh thực tiễn, thực chiến v&agrave; luyện tập - đ&acirc;y ch&iacute;nh l&agrave; cuốn s&aacute;ch luyện n&oacute;i tiếng Anh d&agrave;nh cho những ai đang muốn thực sự n&oacute;i được tiếng Anh trong đời sống.</p>
<p>Để đạt được mục ti&ecirc;u đ&oacute;,&nbsp;<em>&ldquo;Ch&eacute;m tiếng Anh kh&ocirc;ng cần động n&atilde;o&rdquo;</em>&nbsp;c&oacute;&nbsp;<strong>những đặc điểm nổi bật&nbsp;</strong>sau:</p>
<p>★&nbsp;<strong>500+ mẫu c&acirc;u th&ocirc;ng dụng thuộc 12 chủ đề thiết thực&nbsp;</strong>(tương ứng 12 chương): Từ ch&agrave;o hỏi, giới thiệu bản th&acirc;n; hội thoại ở c&ocirc;ng sở, khi mua sắm; diễn tả sở th&iacute;ch, thời tiết, lịch tr&igrave;nh, di chuyển&hellip;</p>
<p>Đ&acirc;y l&agrave; những chủ đề đơn giản nhất, c&oacute; vẻ qu&aacute; cơ bản, nhưng sẽ đảm bảo bạn TỒN TẠI ĐƯỢC nếu lỡ c&oacute; một ng&agrave;y lạc ch&acirc;n ra ngoại quốc.</p>
<p>★Tất cả c&aacute;c đoạn hội thoại đều c&oacute;&nbsp;<strong>văn phong v&agrave; từ vựng</strong>&nbsp;đ&uacute;ng c&aacute;ch n&oacute;i chuyện&nbsp;<strong>của người bản xứ.</strong></p>
<p>★ Với&nbsp;<strong>mỗi hội thoại,</strong>&nbsp;t&aacute;c giả cung cấp<strong>&nbsp;1 video ngắn để bạn c&oacute; thể luyện nghe - n&oacute;i 1:1 với Bino - ngay tại nh&agrave;</strong>&nbsp;m&igrave;nh, hết sức&nbsp;<strong>tiết kiệm, thuận tiện, tự tin</strong>. Theo Bino, sự<strong>&nbsp;lặp đi lặp lại như-một-đứa-trẻ</strong>,&nbsp;<strong><em>&ldquo;mở miệng ra v&agrave; n&oacute;i, n&oacute;i, n&oacute;i kh&ocirc;ng ngừng nghỉ&rdquo;</em></strong>&nbsp;ch&iacute;nh yếu tố quan trọng để bạn<strong>&nbsp;h&igrave;nh th&agrave;nh vốn từ vựng chủ động</strong>&nbsp;v&agrave;&nbsp;<strong>th&oacute;i quen phản xạ</strong>, qua đ&oacute;&nbsp;<strong>n&oacute;i tiếng Anh tr&ocirc;i chảy, lưu lo&aacute;t</strong>&nbsp;hơn.</p>
<p>Do đ&oacute;, c&aacute;c video luyện nghe - n&oacute;i 1:1 trong cuốn s&aacute;ch n&agrave;y đ&oacute;ng vai tr&ograve; như một &ldquo;vũ kh&iacute; tối thượng&rdquo; gi&uacute;p bạn n&acirc;ng tr&igrave;nh kỹ năng giao tiếp.</p>
<p>★<strong>&nbsp;1000+ từ vựng, tiếng l&oacute;ng, idiom,&nbsp;</strong>c&aacute;ch n&oacute;i tắt v&agrave; c&aacute;c c&aacute;ch diễn đạt tự nhi&ecirc;n, b&igrave;nh d&acirc;n.</p>
<p>★ Những<strong>&nbsp;tips, tricks n&oacute;i v&agrave; ph&aacute;t &acirc;m</strong>&nbsp;tiếng Anh sao cho&nbsp;<strong>gọn g&agrave;ng, đơn giản, kh&ocirc;ng rườm r&agrave;.</strong>&nbsp;Đ&oacute; đều l&agrave; những đ&uacute;c kết xương m&aacute;u của t&aacute;c giả sau nhiều năm quan s&aacute;t người bản xứ lẫn bản th&acirc;n tự nghiệm ra khi anh l&agrave;m việc, giao tiếp tiếng Anh trong những m&ocirc;i trường đ&ograve;i hỏi phản xạ nhanh.</p>
<p>★ Những&nbsp;<strong>mẹo học ng&ocirc;n ngữ</strong>&nbsp;chất như nước cất<strong>&nbsp;của Bino sau nhiều năm học 5 thứ tiếng kh&aacute;c nhau</strong>. Chẳng hạn:&nbsp;<em>&ldquo;Tại sao nhiều người học tiếng Anh qua phim lại kh&ocirc;ng hiệu quả?&rdquo;; &ldquo;H&atilde;y để tiếng Việt gi&uacute;p bạn học tiếng Anh&rdquo;; &ldquo;H&atilde;y đặt nhiều c&acirc;u hỏi HOW hơn thay v&igrave; WHY!&rdquo;...</em></p>
<p>★ C&aacute;c hướng dẫn gần gũi, ho&agrave;n to&agrave;n bằng tiếng Việt v&agrave;&nbsp;<strong>đậm chất gen Z!.</strong></p>
<p>★ Hệ thống<strong>&nbsp;từ vựng si&ecirc;u đơn giản, ph&ugrave; hợp</strong>&nbsp;với cả c&aacute;c bạn&nbsp;<strong>mất gốc</strong>&nbsp;tiếng Anh, c&aacute;c bạn ở<strong>&nbsp;tr&igrave;nh độ beginner (sơ cấp)</strong>, lẫn những ai đang ở&nbsp;<strong>tr&igrave;nh độ cao hơn nhưng đang muốn &ldquo;b&igrave;nh d&acirc;n ho&aacute;&rdquo; văn n&oacute;i của m&igrave;nh</strong>.</p>
<p>Với cuốn s&aacute;ch n&agrave;y, t&aacute;c giả muốn g&oacute;p phần thay đổi c&aacute;ch học v&agrave; tiếp cận tiếng Anh của người Việt Nam n&oacute;i chung - thực dụng hơn, hiệu quả hơn v&agrave; tự tin hơn.</p>
<p><em>&ldquo;Muốn n&oacute;i tốt hơn, bạn phải luyện tập n&oacute;i nhiều hơn. Tất cả những g&igrave; bạn đọc được trong cuốn s&aacute;ch đều cần được<strong>&nbsp;ĐỌC TO BẰNG MIỆNG, N&Oacute;I TO TH&Agrave;NH TIẾNG c&ugrave;ng Bino - kh&ocirc;ng chỉ một m&agrave; rất rất nhiều lần</strong>&rdquo;,</em>&nbsp;Bino chia sẻ.</p>
<p>N&agrave;o, bạn đ&atilde; sẵn s&agrave;ng c&ugrave;ng Bino bước v&agrave;o h&agrave;nh tr&igrave;nh &ldquo;ch&eacute;m tiếng Anh kh&ocirc;ng cần động n&atilde;o&rdquo; chưa?</p>
<p><strong><em>Lời khen tặng d&agrave;nh cho &ldquo;Ch&eacute;m tiếng Anh kh&ocirc;ng cần động n&atilde;o&rdquo;</em></strong></p>
<p>★&nbsp;<em>&ldquo;C&oacute; kh&aacute; &iacute;t t&agrave;i liệu tiếng Anh giao tiếp chất lượng, c&oacute; lẽ bởi v&igrave; giao tiếp l&agrave; một kỹ năng thực sự kh&oacute; để dạy th&ocirc;ng qua một t&agrave;i liệu đọc. &lsquo;Ch&eacute;m tiếng Anh kh&ocirc;ng cần động n&atilde;o&rsquo; đ&atilde; l&agrave;m được việc kh&oacute; đ&oacute;, với những c&ocirc;ng cụ thiết thực cho người học ở bất cứ tr&igrave;nh độ n&agrave;o, như: hệ thống từ vựng đa dạng, video mang t&iacute;nh tương t&aacute;c.</em></p>
<p><em>Th&ecirc;m v&agrave;o đ&oacute;, &lsquo;Ch&eacute;m tiếng Anh kh&ocirc;ng cần động n&atilde;o&rsquo; c&ograve;n chứa những chia sẻ &lsquo;t&acirc;m t&igrave;nh&rsquo; của anh Bino, người đ&atilde; chinh phục những kh&oacute; khăn, bỡ ngỡ của việc giao tiếp tiếng Anh tại những m&ocirc;i trường th&aacute;ch thức nhất, v&agrave; giờ được đ&ocirc;ng đảo c&aacute;c bạn trẻ hướng tới như l&agrave; một tiếng n&oacute;i uy t&iacute;n nhất về tiếng Anh thực tiễn sử dụng trong cuộc sống&rdquo;</em>&nbsp;&ndash;<strong><em>&nbsp;Đặng Trần T&ugrave;ng - TIW&rsquo;s CEO/Head teacher, 6 time IELTS 9.0 holder</em></strong></p>
<p>★&nbsp;<em>&ldquo;Một phong c&aacute;ch học rất GenZ v&agrave; thực tế, kết hợp c&ugrave;ng với c&aacute;c video duet mang lại trải nghiệm thực h&agrave;nh tương t&aacute;c cho người học. Ấn tượng về việc mang văn ho&aacute; v&agrave; ng&ocirc;n ngữ v&agrave;o trong những cuộc hội thoại tự nhi&ecirc;n, một phong c&aacute;ch rất Bino!&rdquo; &ndash;&nbsp;<strong>AlexD - &Ocirc;ng bố hot dad với hai con song ngữ từ nhỏ</strong></em></p>
<p><strong><em>Về t&aacute;c giả</em></strong></p>
<p><em>Bino ch&eacute;m ti&eacute;ng Anh, t&ecirc;n thật l&agrave; Vũ Vi B&igrave;nh, l&agrave; một gymer c&oacute; khả năng n&acirc;ng tạ 140kg, hiện l&agrave; chủ sở hữu k&ecirc;nh @binochemtienganh với hơn 750k người theo d&otilde;i tr&ecirc;n TikTok v&agrave; hơn 1 triệu người theo d&otilde;i tr&ecirc;n to&agrave;n bộ c&aacute;c nền tảng. Anh nổi tiếng với hững video chia sẻ kiến thức tiếng Anh thực tế, dễ hiểu v&agrave; h&agrave;i hước.</em></p>
<p><em>Trước khi l&agrave;m TikTok v&agrave; chuyển về Việt Nam sinh sống, Bino từng &ldquo;lăn lộn&rdquo; nhiều năm ở Nga, &Uacute;c v&agrave; c&oacute; thời gian l&agrave;m việc cho một trong &ldquo;tứ đại ng&acirc;n h&agrave;ng&rdquo; tại &Uacute;c. Bino từng học 4 thứ tiếng (Anh, Ph&aacute;p, Ả Rập, Nga) v&agrave; c&oacute; nhiều năm dạy giảng tiếng Anh cho người Việt.</em></p>
<p><em>Hiện Bino c&ograve;n đảm nhiệm vai tr&ograve; host cho chương tr&igrave;nh IELTS Face Off tr&ecirc;n VTV7 (c&ugrave;ng nhiều KOls nổi tiếng kh&aacute;c trong lĩnh vực tiếng Anh như Kh&aacute;nh Vy, Uy L&ecirc;&hellip;)</em></p>', 2024, NULL, 200, 5, 8, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (274, N'4000 Từ Vựng Và Mẫu Câu Tiếng Anh Thiết Yếu Cho Trẻ Em', N'8935212353540', N'Bìa Mềm', CAST(105625.00 AS Decimal(12, 2)), CAST(250000.00 AS Decimal(12, 2)), CAST(162500.00 AS Decimal(12, 2)), N'https://res.cloudinary.com/dabxzdaf8/image/upload/v1748969438/Book_cover/oorfvddiybns8yrxshwq.webp', N'Ban Biên tập MIS', N'<p>Mở ra thế giới tri thức v&agrave; ph&aacute;t triển kỹ năng của trẻ với 4000 từ vựng v&agrave; mẫu c&acirc;u thiết yếu</p>
<p>Hỗ trợ trẻ học tiếng Anh ngay từ nhỏ l&agrave; một việc v&ocirc; c&ugrave;ng quan trọng, bởi điều n&agrave;y c&oacute; thể gi&uacute;p trẻ em l&agrave;m quen với tiếng Anh v&agrave;o tạo ra hứng th&uacute; học tập cho trẻ. Cuốn từ điển tiếng Anh với h&agrave;ng trăm chủ đề phong ph&uacute;, phi&ecirc;n &acirc;m r&otilde; r&agrave;ng v&agrave; tranh minh họa sống động n&agrave;y sẽ gi&uacute;p c&aacute;c bạn nhỏ học từ vựng tiếng Anh v&agrave; những mẫu c&acirc;u đơn giản một c&aacute;ch dễ d&agrave;ng hơn. Sau mỗi b&agrave;i học, c&aacute;c em sẽ c&oacute; thể gọi t&ecirc;n c&aacute;c đồ vật xung quanh m&igrave;nh bằng tiếng Anh, thậm ch&iacute; l&agrave; tự đặt c&acirc;u bằng c&aacute;ch tổ hợp c&aacute;c từ vựng đ&atilde; học. Th&ocirc;ng qua cuốn s&aacute;ch n&agrave;y, kh&ocirc;ng chỉ IQ m&agrave; cả EQ của trẻ cũng sẽ được bồi dưỡng từng ng&agrave;y, tạo tiền đề thuận lợi để trẻ gặt h&aacute;i th&agrave;nh c&ocirc;ng trong tương lai.</p>', 2021, NULL, 356, 12, 7, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (275, N'Tự Học 2000 Từ Vựng Tiếng Anh Theo Chủ Đề (Tái Bản)', N'8935246915486', N'Bìa Mềm', CAST(29575.00 AS Decimal(12, 2)), CAST(65000.00 AS Decimal(12, 2)), CAST(45500.00 AS Decimal(12, 2)), N'https://res.cloudinary.com/dabxzdaf8/image/upload/v1748969503/Book_cover/zuzgvt7d9vgnvutehupl.webp', N'The Windy', N'<p>Nh&agrave; ng&ocirc;n ngữ học nổi tiếng D.A.Wilkins đ&atilde; n&oacute;i rằng &ldquo;Without grammar, very little can be conveyed; without vocabulary, nothing can be conveyed.&rdquo; (Kh&ocirc;ng c&oacute; ngữ ph&aacute;p, rất &iacute;t th&ocirc;ng tin c&oacute; thể được truyền đạt; Kh&ocirc;ng c&oacute; từ vựng, kh&ocirc;ng một th&ocirc;ng tin n&agrave;o c&oacute; thể được truyền đạt cả). V&igrave; thế, trong việc học một ngoại ngữ, th&igrave; từ vựng c&oacute; thể xem như c&aacute;c tế b&agrave;o nhỏ h&igrave;nh th&agrave;nh n&ecirc;n khả năng sử dụng ngoại ngữ của người học.</p>
<p>C&aacute;c bạn đang băn khoăn chưa biết n&ecirc;n học từ vựng như thế n&agrave;o để c&oacute; thể ghi nhớ được nhiều từ v&agrave; l&acirc;u nhất. Dưới đ&acirc;y l&agrave; những phương ph&aacute;p học m&agrave; c&aacute;c bạn c&oacute; thể &aacute;p dụng để học từ vựng hiệu quả nhất.</p>
<p>1. Học từ vựng theo chủ đề<br>Thay v&igrave; học ri&ecirc;ng lẻ từng từ rời rạc, nếu c&aacute;c bạn biết nh&oacute;m ch&uacute;ng v&agrave;o c&ugrave;ng một chủ đề th&igrave; đảm bảo việc học thuộc sẽ trở n&ecirc;n đơn giản hơn rất nhiều lu&ocirc;n. C&oacute; vốn từ vựng theo chủ đề, khi l&agrave;m b&agrave;i thi n&oacute;i hoặc viết theo một chủ đề n&agrave;o đ&oacute; bạn sẽ ph&aacute;t huy được tối đa vốn từ vựng. Khiến b&agrave;i n&oacute;i v&agrave; b&agrave;i viết của bạn tr&ocirc;i chảy v&agrave; nhiều &yacute; tưởng. V&igrave; vậy, việc học từ theo chủ đề cũng giống như một mũi t&ecirc;n tr&uacute;ng hai đ&iacute;ch vậy, vừa gi&uacute;p ch&uacute;ng ta biết th&ecirc;m nhiều từ mới, vừa c&oacute; nhiều từ vựng v&agrave; &yacute; hay để triển khai cho b&agrave;i thi được tốt hơn.</p>
<p>2. Sử dụng h&igrave;nh ảnh, &acirc;m thanh hay c&acirc;u chuyện để ghi nhớ từ vựng nhanh<br>Thực tế cho thấy, c&aacute;ch m&agrave; nhiều người thường hay học từ vựng đ&oacute; l&agrave; viết từ vựng đ&oacute; k&egrave;m nghĩa ra giấy thật nhiều lần để ghi nhớ. Tuy nhi&ecirc;n, c&aacute;ch n&agrave;y c&oacute; thể hiệu quả tức thời nhưng về l&acirc;u về d&agrave;i, nếu kh&ocirc;ng sử dụng lại th&igrave; chắc chắn ta sẽ qu&ecirc;n từ. Ngược lại, nếu sử dụng những h&igrave;nh ảnh, &acirc;m thanh hay c&acirc;u chuyện ấn tượng th&igrave; c&oacute; thể khiến n&atilde;o bộ ch&uacute;ng ta nhớ rất m&atilde;i. C&aacute;ch thức học n&agrave;y cũng v&ocirc; c&ugrave;ng đơn giản, khi ch&uacute;ng ta học một từ mới, h&atilde;y cố gắng tự nghĩ &yacute; tưởng v&agrave; minh họa cho n&oacute; bằng h&igrave;nh ảnh ngộ nghĩnh, khi học một nh&oacute;m từ vựng theo chủ đề, h&atilde;y cố gắng sắp xếp ch&uacute;ng v&agrave;o th&agrave;nh một đoạn văn, kể về một c&acirc;u chuyện th&uacute; vị.</p>
<p>3. Học từ vựng qua b&agrave;i h&aacute;t, phim ảnh</p>
<p>Nhiều l&uacute;c do t&acirc;m l&yacute; nghĩ học tập l&agrave; một g&aacute;nh nặng, bắt buộc phải học m&agrave; khiến ch&uacute;ng ta mất đi niềm vui trong việc tiếp nhận tri thức. Nếu c&aacute;c bạn c&oacute; thể giải tỏa t&acirc;m l&yacute; đ&oacute; bằng việc nghe nhạc hay xem phim th&igrave; sẽ khiến từ mới &ldquo;v&agrave;o đầu&rdquo; dễ d&agrave;ng hơn m&agrave; kh&ocirc;ng khiến ta ch&aacute;n nản khi học. C&aacute;c bạn n&ecirc;n học từ vựng bằng những phim từ mức độ thấp đến cao. Rất nhiều bộ phim hay để học tiếng Anh như: Extra English, Friends, How I met your mother?...</p>
<p>4. Lu&ocirc;n c&oacute; một cuốn sổ tay ghi từ mới<br>Cuốn sổ n&agrave;y sẽ cực k&igrave; hữu &iacute;ch cho bạn trong việc học mọi l&uacute;c mọi nơi. Mỗi ng&agrave;y bạn hay ghi v&agrave;o quyển sổ đ&oacute; những từ mới học được bao gồm nghĩa, họ từ v&agrave; ng&agrave;y n&agrave;o cũng mở ra đọc v&agrave; học lại như vậy từ vựng đ&oacute; sẽ kh&ocirc;ng bao giờ c&oacute; thể qu&ecirc;n được.</p>
<p>5. Tập sử dụng c&aacute;c từ mới v&agrave; &ocirc;n tập thường xuy&ecirc;n<br>Sau khi học c&aacute;c từ mới, bạn n&ecirc;n tập sử dụng ch&uacute;ng h&agrave;ng</p>', 2019, NULL, 260, 19, 9, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (276, N'Ngữ Pháp Tiếng Anh (Tái Bản 2021)', N'8794069303302', N'Bìa Mềm', CAST(37602.50 AS Decimal(12, 2)), CAST(89000.00 AS Decimal(12, 2)), CAST(57850.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_240310.jpg', N'Mai Lan Hương, Hà Thanh Uyên', N'<p>Ngữ ph&aacute;p Tiếng Anh với lần t&aacute;i bản 2021 được t&aacute;c giả Mai Lan Hương &amp; Nguyễn Thanh Loan tổng hợp c&aacute;c chủ điểm ngữ ph&aacute;p trọng yếu. C&aacute;c chủ điểm ngữ ph&aacute;p được tr&igrave;nh b&agrave;y r&otilde; r&agrave;ng, chi tiết.</p>
<p>Sau mỗi chủ điểm ngữ ph&aacute;p l&agrave; phần b&agrave;i tập nhằm gi&uacute;p c&aacute;c bạn củng cố kiến thức đ&atilde; học v&agrave; c&oacute; phần đ&aacute;p &aacute;n để gi&uacute;p người học tự kiểm tra kết quả. Cuốn s&aacute;ch n&agrave;y kh&ocirc;ng chia theo chương v&agrave; giải th&iacute;ch cặn kẽ từ l&yacute; thuyết cho đến từng v&iacute; dụ b&agrave;i tập từ cơ bản đến n&acirc;ng cao như cuốn Giải th&iacute;ch ngữ ph&aacute;p Tiếng Anh.</p>
<p>Ngữ ph&aacute;p Tiếng Anh được chia theo từng ph&acirc;n mục ngữ ph&aacute;p: Tense, Sequence of tenses, Clauses and phrases, Expression of quantity, Styles (văn phong), Emphasis (dạng nhấn mạnh), The parts of speech (từ loại), Reported speech, The passive and active sentences, Sentences, Practice test v&agrave; Đ&aacute;p &aacute;n b&agrave;i tập.</p>', 2022, NULL, 280, 9, 14, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (281, N'BộBộ Giáo Trình Chuẩn YCT 1, YCT 2, YCT 3', N'9786045877289', N'Bìa Mềm', CAST(73450.00 AS Decimal(12, 2)), CAST(138000.00 AS Decimal(12, 2)), CAST(113000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_195509_1_11579.jpg', N'Tô Anh Hà, Kim Phi Phi, Vương Lôi', N'<p>中小学生汉语考试（YCT）是一项国际汉语能力标准化考试，考查汉语非第一语言的中小学生在日常生活和学习中运用汉语的能力。在真题分析的基础上，本着&ldquo;考教结合&rdquo;的理念，《YCT标准教程》应运而生。</p>
<p>B&agrave;i thi tiếng Trung Quốc d&agrave;nh cho học sinh (Youth Chinese Test &ndash; YCT) l&agrave; b&agrave;i kiểm tra chuẩn ở cấp độ quốc tế về tr&igrave;nh độ tiếng Trung Quốc. B&agrave;i thi n&agrave;y đ&aacute;nh gi&aacute; khả năng sử dụng tiếng Trung Quốc trong cuộc sống hằng ng&agrave;y cũng như trong học tập của học sinh tiểu học v&agrave; trung học cơ sở c&oacute; ng&ocirc;n ngữ mẹ đẻ kh&ocirc;ng phải l&agrave; tiếng Trung Quốc. Bộ s&aacute;ch Gi&aacute;o tr&igrave;nh chuẩn YCT được bi&ecirc;n soạn theo hướng b&aacute;m s&aacute;t c&aacute;c b&agrave;i thi YCT đồng thời dựa tr&ecirc;n nguy&ecirc;n tắc kết hợp giảng dạy v&agrave; kiểm tra.</p>', 2018, NULL, 68, 4, 7, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (283, N'BộBộ Giáo Trình Chuẩn YCT 1, YCT 2, YCT 3', N'9786043772067', N'Bìa Mềm', CAST(36075.00 AS Decimal(12, 2)), CAST(68000.00 AS Decimal(12, 2)), CAST(55500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/2/0/2023_02_20_11_54_17_1-390x510.jpg', N'Tô Anh Hà, Kim Phi Phi, Vương Lôi', N'<p>B&agrave;i thi tiếng Trung Quốc d&agrave;nh cho học sinh (Youth Chinese Test - YCT) l&agrave; b&agrave;i kiểm tra chuẩn ở cấp độ quốc tế về tr&igrave;nh độ tiếng Trung Quốc. B&agrave;i thi n&agrave;y đ&aacute;nh gi&aacute; khả năng sử dụng tiếng Trung Quốc trong cuộc sống hằng ng&agrave;y cũng như trong học tập của học sinh tiểu học v&agrave; trung học cơ sở c&oacute; ng&ocirc;n ngữ mẹ để kh&ocirc;ng phải l&agrave; tiếng Trung Quốc. Bộ s&aacute;ch Gi&aacute;o tr&igrave;nh chuẩn YCT được bi&ecirc;n soạn theo hướng b&aacute;m s&aacute;t c&aacute;c b&agrave;i thi YCT đồng thời dựa tr&ecirc;n nguy&ecirc;n tắc kết hợp giảng dạy v&agrave; kiểm tra.</p>', 2022, NULL, 52, 6, 2, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (287, N'Nói Tiếng Nhật Như Người Nhật (Tập 1)', N'9786047763603', N'Bìa Mềm', CAST(40137.50 AS Decimal(12, 2)), CAST(95000.00 AS Decimal(12, 2)), CAST(61750.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786047763603.jpg', N'Miki Jun, Ooi Kensuke', N'<p><strong>N&oacute;i Tiếng Nhật Như Người Nhật (Tập 1)</strong></p>
<p>&ldquo;N&oacute;i tiếng Nhật như người Nhật&rdquo; l&agrave; cuốn s&aacute;ch dạy giao tiếp d&agrave;nh cho gi&aacute;o vi&ecirc;n dạy tiếng Nhật cho người Việt, người Việt học tiếng Nhật v&agrave; người Nhật học tiếng Việt.</p>
<p>Cuốn s&aacute;ch được viết để giải quyết những kh&oacute; khăn thực tế của người Việt trong qu&aacute; tr&igrave;nh học v&agrave; giao tiếp tiếng Nhật.</p>
<p>Với số lượng từ vựng lớn v&agrave; v&iacute; dụ minh họa dễ hiểu, &ldquo;N&oacute;i tiếng Nhật như người Nhật&rdquo; gi&uacute;p người đọc dễ d&agrave;ng mở rộng vốn từ v&agrave; ứng dụng những g&igrave; đ&atilde; học v&agrave;o t&igrave;nh huống giao tiếp cụ thể.</p>
<p><em>T&oacute;m tắt:</em></p>
<p>Cuốn s&aacute;ch &ldquo;N&oacute;i tiếng Nhật như người Nhật&rdquo; gồm 5 chương lớn:</p>
<p>- Chương 1: Luyện tập Hiragana v&agrave; Katakana</p>
<p>- Chương 2: C&aacute;c từ ngữ sử dụng trong lớp học</p>
<p>- Chương 3: Với từng n&agrave;y kiến thức, bạn đ&atilde; c&oacute; thể n&oacute;i được tiếng Nhật!</p>
<p>- Chương 4: Luyện tập đặt c&acirc;u hỏi</p>
<p>- Chương 5: Luyện tập từ H&aacute;n Việt</p>', 2023, NULL, 124, 10, 6, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (288, N'Kizuki Kids - Tiếng Nhật Cho Trẻ Em Việt Nam - Quyển 2', N'9786043416619', N'Bìa Mềm', CAST(50700.00 AS Decimal(12, 2)), CAST(120000.00 AS Decimal(12, 2)), CAST(78000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786043416619-_1_.jpg', N'Hoàng Hồng Nhung', N'<p><strong>S&aacute;ch KIZUKI KIDS - Tiếng Nhật d&agrave;nh cho trẻ em Việt Nam (quyển 2)</strong></p>
<p>- Nối tiếp sự th&agrave;nh c&ocirc;ng của Quyển 1, KIZUKI KIDS 2 ch&iacute;nh thức được ho&agrave;n thiện v&agrave; xuất bản.</p>
<p>- KIZUKI KIDS (quyển 2) được mở rộng hơn về c&aacute;c chủ đề như ng&ocirc;i nh&agrave;, sở th&iacute;ch, c&acirc;y v&agrave; hoa&hellip; gi&uacute;p c&aacute;c em nhỏ tiếp cận học tiếng Nhật được n&acirc;ng cao hơn nhưng vẫn rất gần gũi v&agrave; dễ hiểu với c&aacute;c em.</p>
<p>- Chắc chắn rằng, KIZUKI KIDS - Tiếng Nhật d&agrave;nh cho trẻ em VN (quyển 2) sẽ mang lại nhiều điều th&iacute;ch th&uacute; khi c&aacute;c em học tiếng Nhật c&ugrave;ng với cuốn s&aacute;ch.</p>
<p>S&aacute;ch do trung t&acirc;m KIZUKI thuộc c&ocirc;ng ty KHANG EDUTAINMENT bi&ecirc;n soạn v&agrave; NXB Thanh Ni&ecirc;n ph&aacute;t h&agrave;nh.</p>
<p>T&aacute;c giả: Ho&agrave;ng Hồng Nhung</p>
<p>Bi&ecirc;n tập: Nguyễn Nhật H&agrave; Anh</p>
<p>Thiết kế: Kanayama Etsuko</p>
<p>Minh họa: Vũ Yến Linh</p>', 2022, NULL, 83, 20, 6, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (289, N'Tự Học Viết Tiếng Nhật Căn Bản - KATAKANA (Tái Bản 2022)', N'8935086855843', N'Bìa Mềm', CAST(24700.00 AS Decimal(12, 2)), CAST(48000.00 AS Decimal(12, 2)), CAST(38000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935086855843_1.jpg', N'Jim Glesson', N'<p><strong>Tự Học Viết Tiếng Nhật Căn Bản - KATAKANA (T&aacute;i Bản 2022)</strong></p>
<p>Cuốn s&aacute;ch Katakana - Tự Học Viết Tiếng Nhật Căn Bản được bi&ecirc;n soạn nhằm gi&uacute;p cho những học vi&ecirc;n mới c&oacute; thể l&agrave;m quen với tiếng Nhật một c&aacute;ch nhanh nhất. Do đ&oacute; mọi ưu ti&ecirc;n đều được tập trung k&iacute;ch th&iacute;ch v&agrave;o sự tham gia của gi&aacute;o vi&ecirc;n, với khối lượng đa dạng c&aacute;c c&acirc;u v&agrave; th&agrave;nh ngữ thực h&agrave;nh để củng cố cho học vi&ecirc;n những k&yacute; tự đ&atilde; học trong mỗi giai đoạ. S&aacute;ch cũng tạo cho học vi&ecirc;n học một c&aacute;ch dễ d&agrave;ng bằng những k&yacute; tự m&agrave;u x&aacute;m nhạt theo n&eacute;t chữ, cho ph&eacute;p học vi&ecirc;n nắm vững được c&aacute;ch viết, đường n&eacute;t v&agrave; sự c&acirc;n bằng của c&aacute;c k&yacute; tự.</p>
<p>S&aacute;ch c&oacute; một số đặc điểm nổi bật:</p>
<p>- Mẫu tự được tr&igrave;nh b&agrave;y theo 3 dạng: Viết bằng b&uacute;t l&ocirc;ng truyền thống, viết tay v&agrave; chữ in.</p>
<p>- Chữ được in mờ để học vi&ecirc;n tập đồ theo n&eacute;t chữ.</p>
<p>- B&agrave;i tập đa dạng.</p>
<p>- Giải th&iacute;ch bổ sung, gồm cả giới thiệu ngắn gọn về nguồn gốc của từng mẫu tự để n&acirc;ng cao khả năng nhận diện mặt chữ.</p>
<p>- Nhiều h&igrave;nh ảnh v&agrave; v&iacute; dụ minh họa.</p>', 2022, NULL, 87, 17, 2, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (290, N'Kizuki Kids - Tiếng Nhật Cho Trẻ Em Việt Nam - Quyển 1', N'9786044124698', N'Bìa Mềm', CAST(59800.00 AS Decimal(12, 2)), CAST(120000.00 AS Decimal(12, 2)), CAST(92000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786044124698-_1_.jpg', N'Hoàng Hồng Nhung', N'<p>Kizuki Kids - Tiếng Nhật Cho Trẻ Em Việt Nam - Quyển 1</p>
<p><strong>S&aacute;ch KIZUKI KIDS - Tiếng Nhật d&agrave;nh cho trẻ em Việt Nam (quyển 1) (T&aacute;i bản lần thứ nhất)</strong></p>
<p>Cuốn s&aacute;ch xoay quanh những c&acirc;u chuyện th&uacute; vị về cuộc sống h&agrave;ng ng&agrave;y của hai nh&acirc;n vật ch&iacute;nh KI&amp;ZU.</p>
<p>Bạn KI - nickname của bạn trai người Nhật Bản, 5 tuổi theo bố mẹ sang Việt Nam l&agrave;m việc v&agrave; sinh sống gần nh&agrave; bạn ZU. Bạn ZU - nickname của bạn g&aacute;i người Việt Nam, 6 tuổi biết n&oacute;i tiếng Nhật v&igrave; đang được học ở trung t&acirc;m tiếng Nhật.</p>
<p><strong>Th&ocirc;ng qua 4 chủ đề - 10 b&agrave;i học gần gũi, quen thuộc với c&aacute;c em nhỏ như gia đ&igrave;nh, sinh nhật, m&oacute;n ăn..</strong></p>
<p>- T&igrave;m hiểu tiếng Nhật một c&aacute;ch thực tế v&agrave; dễ hiểu</p>
<p>- Tiếp cận tiếng Nhật theo c&aacute;ch nh&igrave;n v&agrave; cuộc sống của bạn ZU - c&ugrave;ng độ tuổi với c&aacute;c con, đều l&agrave; người Việt, ở Việt Nam v&agrave; đang l&agrave;m quen với tiếng Nhật</p>
<p>- Kh&aacute;m ph&aacute; những n&eacute;t đặc trưng về văn h&oacute;a - đất nước - con người Nhật Bản</p>
<p>- Nhận ra điểm giống v&agrave; kh&aacute;c giữa 2 quốc gia Nhật Bản v&agrave; Việt Nam</p>
<p>S&aacute;ch do trung t&acirc;m KIZUKI thuộc c&ocirc;ng ty KHANG EDUTAINMENT bi&ecirc;n soạn v&agrave; NXB Thanh Ni&ecirc;n t&aacute;i bản, ph&aacute;t h&agrave;nh.</p>
<p>T&aacute;c giả: Ho&agrave;ng Hồng Nhung</p>
<p>Bi&ecirc;n tập: Trần Thị Hương</p>
<p>Trợ gi&uacute;p bi&ecirc;n tập: Nguyễn Nhật H&agrave; Anh - Kobayashi Natsumi &ndash; Nguyễn Thị Mai Anh</p>
<p>B&igrave;a, tr&igrave;nh b&agrave;y: Kanayama Etsuko, Vũ Yến Linh</p>', 2024, NULL, 77, 20, 9, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (291, N'Keep It Up - Tập Viết Tiếng Nhật Theo Bảng Chữ Cái Hiragana', N'8936110986847', N'Bìa Mềm', CAST(24927.50 AS Decimal(12, 2)), CAST(59000.00 AS Decimal(12, 2)), CAST(38350.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/k/e/keep-it-up-t_p-vi_t-ti_ng-nh_t.jpg', N'Jeong Eui Sang', N'<p>Kh&aacute;c với tiếng Việt hay tiếng Anh l&agrave; ng&ocirc;n ngữ sử dụng chữ c&aacute;i Latinh, tiếng Nhật l&agrave; ng&ocirc;n ngữ sử dụng chữ tượng h&igrave;nh phức tạp v&agrave; kh&oacute; hơn rất nhiều. Bởi vậy, r&agrave;o cản đầu ti&ecirc;n m&agrave; nhiều người gặp phải khi bắt đầu học tiếng Nhật ch&iacute;nh l&agrave; c&aacute;c k&yacute; tự tiếng Nhật.</p>
<p>Ch&iacute;nh v&igrave; thế, c&ugrave;ng với cuốn s&aacute;ch&nbsp;<strong>Keep it up &ndash; Tiếng&nbsp;</strong><strong>Nhật</strong><strong>&nbsp;cấp tốc cho người mới bắt đầu</strong>, cuốn&nbsp;<strong>Keep it up</strong><strong>&nbsp;&ndash; Tập&nbsp;</strong><strong>viết chữ&nbsp;</strong><strong>Nhật</strong><strong>theo bảng chữ c&aacute;i Hiragana</strong>được bi&ecirc;n soạn gi&uacute;p c&aacute;c bạn tự luyện viết tại nh&agrave;, ghi nhớ từ vựng hiệu quả.</p>
<p><strong>ƯU ĐIỂM NỔI BẬT CỦA CUỐN TẬP VIẾT</strong></p>
<p>1. Hệ thống văn tự k&yacute; hiệu 50 &acirc;m tiết Kana trong tiếng Nhật</p>
<p>2. Luyện tập v&agrave; ghi nhớ bảng chữ Hiragana với c&aacute;c &acirc;m trong, &acirc;m đục, &acirc;m b&aacute;n đục, &acirc;m đ&ocirc;i</p>
<p>3. Thiết kế vở c&oacute; &ocirc; ly gi&uacute;p người học dễ d&agrave;ng luyện viết v&agrave; viết chữ đẹp hơn</p>
<p>4. Qu&eacute;t m&atilde; QR truy cập file nghe, tặng k&egrave;m ứng dụng học từ vựng qua h&igrave;nh ảnh động</p>
<p>Với những ưu điểm tr&ecirc;n, cuốn&nbsp;<strong>Keep it up &ndash; Tập viết tiếng Nhật theo bảng chữ c&aacute;i Hiragana,&nbsp;</strong>cũng như trọn bộ s&aacute;ch&nbsp;<strong>Keep it up &ndash; Tiếng Nhật cấp tốc cho người mới bắt đầu</strong> chắc chắn sẽ l&agrave; một người bạn đồng h&agrave;nh tuyệt vời v&agrave; dẫn dắt c&aacute;c bạn đến đ&iacute;ch cuối c&ugrave;ng tr&ecirc;n con đường chinh phục tiếng Nhật!</p>', 2021, NULL, 68, 21, 13, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (292, N'Tự Học Viết Tiếng Nhật Căn Bản Hiragana (Tái Bản)', N'8935086856482', N'Bìa Mềm', CAST(24700.00 AS Decimal(12, 2)), CAST(48000.00 AS Decimal(12, 2)), CAST(38000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935086856482.jpg', N'Jim Gleeson', N'<p>Đ&acirc;y l&agrave; bộ t&agrave;i liệu được bi&ecirc;n soạn kỹ lưỡng nhằm gi&uacute;p người học c&oacute; thể nhanh ch&oacute;ng nắm vững bộ vần 46 k&yacute; tự Hiragana v&agrave; Katakana, hai bộ vần căn bản của tiếng Nhật.</p>
<p>Bộ s&aacute;ch Tự học viết tiếng Nhật căn bản (Hiragana &amp; Katakana) được bi&ecirc;n soạn khoa học, h&igrave;nh thức tr&igrave;nh b&agrave;y hấp dẫn, dễ tiếp cận v&agrave; nhấn mạnh v&agrave;o vai tr&ograve; chủ động của học vi&ecirc;n nhắm gi&uacute;p học vi&ecirc;n dễ d&agrave;ng học c&aacute;ch viết đẹp v&agrave; nhanh 46 mẫu tự trong hai bộ vần Hiragana v&agrave; Katakana.</p>
<p>S&aacute;ch c&oacute; một số ưu điểm như: mẫu tự được tr&igrave;nh b&agrave;y theo ba dạng - viết bằng b&uacute;t l&ocirc;ng truyền thống, viết tay, v&agrave; chữ in; những chữ mẫu được in mờ để học vi&ecirc;n tập viết theo n&eacute;t; b&agrave;i tập đa dạng, nhiều giải th&iacute;ch bổ sung, c&ugrave;ng nhiều h&igrave;nh ảnh, v&iacute; dụ minh họa.</p>
<p>Luyện viết l&agrave; phương ph&aacute;p hiệu quả nhất để nắm vững tiếng Nhật dạng viết. Đ&acirc;y l&agrave; c&ocirc;ng cụ rất hữu hiệu để bắt đầu qu&aacute; tr&igrave;nh nắm vững chữ viết tiếng Nhật.</p>
<p>Với những ưu điểm tr&ecirc;n, Hiragana v&agrave; Katakana l&agrave; hai bộ s&aacute;ch luyện viết tiếng Nhật kh&ocirc;ng thể thiếu đối với người bắt đầu học tiếng Nhật ở mọi lứa tuổi.</p>', 2022, NULL, 87, 20, 12, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (293, N'BộMarugoto - Ngôn Ngữ Và Văn Hóa Nhật Bản - Trung Cấp 2 - B1', N'8935086855294', N'Bìa Mềm', CAST(100100.00 AS Decimal(12, 2)), CAST(220000.00 AS Decimal(12, 2)), CAST(154000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/m/a/marugoto-trungcap2-b1_bia01-1.jpg', N'Japan Foundation', N'<p><strong>Marugoto - Ng&ocirc;n Ngữ V&agrave; Văn H&oacute;a Nhật Bản - Trung Cấp 2 B1</strong></p>
<p>Ng&agrave;y nay, khi qu&aacute; tr&igrave;nh to&agrave;n cầu h&oacute;a diễn ra ng&agrave;y c&agrave;ng mạnh mẽ th&igrave; việc người ta c&oacute; nhu cầu học một ng&ocirc;n ngữ mới ng&agrave;y c&agrave;ng cao. Theo thống k&ecirc; của Trung t&acirc;m giao lưu văn h&oacute;a Nhật Bản tại Việt Nam - Quỹ giao lưu quốc tế Nhật Bản, số cơ sở đ&agrave;o tạo tiếng Nhật tại Việt Nam tăng 26 lần sau 20 năm, v&agrave; Việt Nam l&agrave; nước c&oacute; số người học tiếng Nhật nhiều thứ 3 ở nh&oacute;m c&aacute;c nước Đ&ocirc;ng Nam &Aacute;. Kh&ocirc;ng chỉ bởi nhu cầu về học tập, việc l&agrave;m, m&agrave; đ&oacute; c&ograve;n l&agrave; cơ hội để người học tiếng Nhật kh&aacute;m ph&aacute; v&agrave; am hiểu về nền văn h&oacute;a l&acirc;u đời của xứ sở Ph&ugrave; Tang.</p>
<p>Được d&agrave;y c&ocirc;ng bi&ecirc;n soạn bởi Quỹ Giao lưu Quốc tế Nhật Bản (Japan Foundation), v&agrave; triển hai theo Chuẩn gi&aacute;o dục tiếng Nhật JF gồm 6 cấp độ: A1, A2 (sử dụng ng&ocirc;n ngữ ở mức độ cơ bản); B1, B2 (sử dụng ng&ocirc;n ngữ ở mức độ độc lập); C1, C2 (sử dụng ng&ocirc;n ngữ ở mức độ th&agrave;nh thạo), từ l&acirc;u, &ldquo;Marugoto - Ng&ocirc;n ngữ v&agrave; Văn h&oacute;a Nhật Bản&rdquo; đ&atilde; được biết đến l&agrave; bộ gi&aacute;o tr&igrave;nh ho&agrave;n hảo d&agrave;nh cho những ai c&oacute; nhu cầu học tập v&agrave; sử dụng th&agrave;nh thạo tiếng Nhật trong c&aacute;c t&igrave;nh huống ứng xử ngo&agrave;i đời sống. Tựa đề &ldquo;Marugoto&rdquo; trong tiếng Nhật c&oacute; nghĩa l&agrave; &ldquo;trọn vẹn&rdquo;, chứa đựng th&ocirc;ng điệp m&agrave; những người thực hiện bộ gi&aacute;o tr&igrave;nh muốn gửi gắm: trọn vẹn trong giao tiếp, trọn vẹn trong trải nghiệm ng&ocirc;n ngữ c&ugrave;ng đời sống v&agrave; văn h&oacute;a.</p>
<p>&ldquo;Marugoto - Trung cấp 2 B1&rdquo; l&agrave; cuốn s&aacute;ch cuối c&ugrave;ng trong bộ gi&aacute;o tr&igrave;nh Marugoto xuất bản tại Việt Nam. Mục ti&ecirc;u của cuốn s&aacute;ch n&agrave;y l&agrave; gi&uacute;p người học c&oacute; thể giao tiếp bằng tiếng Nhật ở cấp độ B1, nghĩa l&agrave; c&oacute; thể diễn đạt một c&acirc;u chuyện ho&agrave;n chỉnh, hiểu được những điểm ch&iacute;nh của đoạn hội thoại với chủ đề gần gũi, đặc biệt l&agrave; c&oacute; thể tự m&igrave;nh xử l&yacute; c&aacute;c vấn đề khi đặt ch&acirc;n đến Nhật Bản.</p>
<p>Cuốn s&aacute;ch n&agrave;y d&agrave;nh cho những ai đ&atilde; ho&agrave;n th&agrave;nh cấp độ Trung cấp 1 B1 trước đ&oacute;, v&agrave; c&oacute; mong muốn n&acirc;ng cao hơn nữa tr&igrave;nh độ tiếng Nhật của m&igrave;nh. Do đ&oacute;, &ldquo;Marugoto - Trung Cấp 2 B1&rdquo; được thiết kế để hướng tới c&aacute;c mục ti&ecirc;u sau:</p>
<p>- Người học c&oacute; thể tham gia v&agrave;o c&aacute;c hoạt động giao tiếp phức tạp hơn, chẳng hạn như cung cấp th&ocirc;ng tin về tin tức gần đ&acirc;y, đưa ra lời khuy&ecirc;n về sức khỏe v&agrave; n&oacute;i về nghệ thuật, lịch sử truyền thống của đất nước;</p>
<p>- Người học c&oacute; thể đọc v&agrave; hiểu nhiều loại văn bản, chẳng hạn như bảng th&ocirc;ng b&aacute;o tr&ecirc;n Internet v&agrave; nội dung trong tạp ch&iacute;.</p>', 2022, NULL, 288, 7, 13, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (294, N'Tiếng Nhật Cho Mọi Người - Sơ Cấp 2 - 25 Bài Đọc Hiểu Trình Độ Sơ Cấp (Bản Mới)', N'8934974187806', N'Bìa Mềm', CAST(41437.50 AS Decimal(12, 2)), CAST(85000.00 AS Decimal(12, 2)), CAST(63750.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8934974187806.jpg', N'Minna no Nihongo', N'<p><strong>Tiếng Nhật Cho Mọi Người - Sơ Cấp 2 - 25 B&agrave;i Đọc Hiểu Tr&igrave;nh Độ Sơ Cấp (Bản Mới)</strong></p>
<p>S&aacute;ch nằm trong bộ Minna no Nihongo - Tiếng Nhật d&agrave;nh cho mọi người - Bản mới, tiếp nối cuốn "25 b&agrave;i đọc hiểu tr&igrave;nh độ Sơ cấp 1.&nbsp;</p>
<p>L&agrave; s&aacute;ch bổ trợ gi&uacute;p người học n&acirc;ng cao kỹ năng đọc &nbsp;th&ocirc;ng qua nhiều chủ đề kh&aacute;c nhau, được bi&ecirc;n soạn b&aacute;m s&aacute;t gi&aacute;o tr&igrave;nh "Minna no Nihongo - Tiếng Nhật cho mọi người", d&agrave;nh cho đối tượng c&oacute; tr&igrave;nh độ Sơ cấp.</p>', 2023, NULL, 150, 20, 14, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (295, N'Tiếng Nhật Cho Mọi Người Sơ Cấp Bản Mới: Tập Viết Theo Chủ Đề Với Các Bài Văn Mẫu', N'8934974170105', N'Bìa Mềm', CAST(41437.50 AS Decimal(12, 2)), CAST(85000.00 AS Decimal(12, 2)), CAST(63750.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_196899.jpg', N'Kadowaki Kaoru, Nishiuma Kaoru', N'<p>S&aacute;ch nằm trong bộ Minna no Nihongo - Tiếng Nhật d&agrave;nh cho mọi người - Bản mới. L&agrave; s&aacute;ch bổ trợ gi&uacute;p người học n&acirc;ng cao kỹ năng viết, tr&igrave;nh b&agrave;y suy nghĩ của bản th&acirc;n về nhiều chủ đề kh&aacute;c nhau.</p>
<p>Người học bắt đầu với việc luyện tập nắm bắt cấu tr&uacute;c tổng thể v&agrave; l&ecirc;n sơ đồ mạch văn. Với việc viết đi viết lại nhiều đề t&agrave;i kh&aacute;c nhau, người học sẽ tự nhi&ecirc;n &yacute; thức được về cấu tr&uacute;c tổng thể, từ đ&oacute; c&oacute; thể &aacute;p dụng được cho cả kỹ năng n&oacute;i v&agrave; đọc hiểu.</p>', 2020, NULL, 172, 2, 3, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (296, N'BộTiếng Hàn Tổng Hợp Dành Cho Người Việt Nam - Sơ Cấp 1 - Sách Bài Tập (Tái Bản 2023)', N'8935246937938', N'Bìa Mềm', CAST(47125.00 AS Decimal(12, 2)), CAST(89000.00 AS Decimal(12, 2)), CAST(72500.00 AS Decimal(12, 2)), N'https://res.cloudinary.com/dabxzdaf8/image/upload/v1748969729/Book_cover/eqxd2pd9sbczwrlvhqko.webp', N'Nhiều Tác Giả', N'<p><strong>Tiếng H&agrave;n Tổng Hợp D&agrave;nh Cho Người Việt Nam - Sơ Cấp 1 - S&aacute;ch B&agrave;i Tập</strong></p>
<p>Nếu bạn đ&atilde; c&oacute; trong tay cuốn Gi&aacute;o tr&igrave;nh tiếng H&agrave;n tổng hợp d&agrave;nh cho người Việt Nam &ndash; sơ cấp 1 th&igrave; ngay lập tức phải sở hữu th&ecirc;m cuốn s&aacute;ch b&agrave;i tập n&agrave;y.</p>
<p>S&aacute;ch b&agrave;i tập tiếng H&agrave;n tổng hợp sơ cấp 1 được bi&ecirc;n tập với mục đ&iacute;ch nhằm hỗ trợ cho việc &ocirc;n tập v&agrave; luyện tập n&acirc;ng cao của những người học quyển Gi&aacute;o tr&igrave;nh tiếng H&agrave;n tổng hợp sơ cấp 1.</p>
<p><strong>S&aacute;ch b&agrave;i tập sơ cấp 1 &ndash; bổ trợ cho Gi&aacute;o tr&igrave;nh tiếng H&agrave;n tổng hợp được chia th&agrave;nh 3 phần ch&iacute;nh sau đ&acirc;y:</strong></p>
<p>Phần 1: Luyện tập từ vựng. Phần n&agrave;y gi&uacute;p cho người học &ocirc;n tập v&agrave; luyện tập n&acirc;ng cao tr&ecirc;n cơ sở c&aacute;c từ vựng ph&ugrave; hợp với nội dung v&agrave; chủ đề được học trong gi&aacute;o tr&igrave;nh ch&iacute;nh.</p>
<p>Phần 2: Phần luyện tập ngữ ph&aacute;p gi&uacute;p luyện tập c&aacute;c cấu tr&uacute;c ngữ ph&aacute;p cơ bản đ&atilde; học trong gi&aacute;o tr&igrave;nh ch&iacute;nh. Ngo&agrave;i ra, bằng việc so s&aacute;nh những cấu tr&uacute;c ngữ ph&aacute;p đ&atilde; học trong gi&aacute;o tr&igrave;nh ch&iacute;nh gi&uacute;p người học c&oacute; thể học ngữ ph&aacute;p một c&aacute;ch c&oacute; hệ thống.</p>
<p>Phần 3: Phần &ocirc;n luyện tổng hợp c&aacute;c kỹ năng giao tiếp như: Nghe &ndash; N&oacute;i &ndash; Đọc &ndash; Viết. Đặc biệt trong phần n&agrave;y c&ograve;n c&oacute; những b&agrave;i luyện đa dạng nhằm n&acirc;ng cao năng lực hoạt động thực tế cho người học.</p>
<p>Th&ocirc;ng qua từng phần trong cuốn s&aacute;ch b&agrave;i tập, người học sẽ được mở rộng phạm vi học tập từ vựng, ngữ ph&aacute;p; c&oacute; thể hiểu v&agrave; thực hiện được những hội thoại th&iacute;ch hợp.</p>
<p>Gi&aacute;o tr&igrave;nh tiếng H&agrave;n tổng hợp d&agrave;nh cho người Việt Nam &ndash; S&aacute;ch b&agrave;i tập sơ cấp 1</p>
<p>Gi&aacute;o tr&igrave;nh tiếng H&agrave;n tổng hợp d&agrave;nh cho người Việt Nam &ndash; Sơ cấp 1 được bi&ecirc;n soạn d&agrave;nh cho người Việt Nam muốn học tiếng H&agrave;n ở tr&igrave;nh độ sơ cấp. S&aacute;ch được bi&ecirc;n soạn nhằm hướng tới việc sử dụng được trong c&aacute;c tiết học tiếng H&agrave;n tại giảng đường đại học n&ecirc;n mỗi b&agrave;i học được chia th&agrave;nh nhiều phần như: L&yacute; thuyết cơ bản gồm từ vựng v&agrave; cấu tr&uacute;c ngữ ph&aacute;p; phần luyện tập theo 4 kỹ năng giao tiếp như: Nghe &ndash; N&oacute;i &ndash; Đọc &ndash; Viết, phần luyện ph&aacute;t &acirc;m, phần t&igrave;m hiểu văn h&oacute;a&hellip;</p>', 2023, NULL, 250, 15, 12, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (297, N'BộTiếng Hàn Tổng Hợp Dành Cho Người Việt Nam - Sơ Cấp 1 - Bản Màu (Tái Bản 2023)', N'8935246937907', N'Bìa Mềm', CAST(109746.00 AS Decimal(12, 2)), CAST(268000.00 AS Decimal(12, 2)), CAST(168840.00 AS Decimal(12, 2)), N'https://res.cloudinary.com/dabxzdaf8/image/upload/v1748969766/Book_cover/gwu52eca4e620icd03br.webp', N'Nhiều Tác Giả', N'<p><strong>Tiếng H&agrave;n Tổng Hợp D&agrave;nh Cho Người Việt Nam - Sơ Cấp 1</strong></p>
<p>Trong những năm gần đ&acirc;y, nhu cầu học tiếng H&agrave;n v&agrave; t&igrave;m hiểu về văn h&oacute;a H&agrave;n Quốc đang c&oacute; xu hướng tăng l&ecirc;n. Người học tiếng H&agrave;n rất mong muốn c&oacute; được một bộ gi&aacute;o tr&igrave;nh chuẩn, được bi&ecirc;n soạn một c&aacute;ch tỉ mỉ v&agrave; hữu &iacute;ch nhất.</p>
<p><strong>Gi&aacute;o tr&igrave;nh tiếng H&agrave;n tổng hợp lần đầu ti&ecirc;n được trao bản quyền ch&iacute;nh thức tại Việt Nam</strong></p>
<p>Hiểu được điều đ&oacute;, ng&agrave;y 4-7, Đại diện ch&iacute;nh phủ H&agrave;n Quốc,&nbsp;ng&agrave;i Woo Hyeong Min &ndash; Trưởng đại diện Văn ph&ograve;ng Quỹ giao lưu Quốc tế HQ tại Việt Nam c&ugrave;ng GS.TS.NGƯT Mai Ngọc Chừ &ndash; Chủ tịch Hội Nghi&ecirc;n cứu khoa học về H&agrave;n Quốc của Việt Nam (KRAV) đ&atilde; trao quyết định cho ph&eacute;p C&ocirc;ng ty Cổ phần s&aacute;ch MCBooks của Việt Nam được xuất bản cuốn s&aacute;ch n&agrave;y tại thị trường Việt Nam. V&agrave; đ&acirc;y ch&iacute;nh l&agrave; bộ gi&aacute;o tr&igrave;nh tiếng H&agrave;n tổng hợp đầu ti&ecirc;n c&oacute; bản quyền ch&iacute;nh thức c&oacute; mặt tại Việt Nam.</p>
<p>Cũng theo &ocirc;ng Woo Hyeong Min, Thực tế đ&acirc;y l&agrave; bộ gi&aacute;o tr&igrave;nh ch&iacute;nh thống m&agrave; tất cả người học tiếng H&agrave;n tại Việt Nam cần sử dụng. Tuy nhi&ecirc;n nhiều năm qua bộ s&aacute;ch đến tay người d&ugrave;ng đều l&agrave; s&aacute;ch lậu n&ecirc;n chưa đạt được kết quả m&agrave; ch&iacute;nh phủ H&agrave;n muốn mang tới Việt Nam. Do đ&oacute; Ch&iacute;nh phủ H&agrave;n Quốc đ&atilde; quyết&nbsp; định t&igrave;m 1 đơn vị xuất bản uy t&iacute;n của Việt Nam để gi&uacute;p họ mang đến cho người học những cuốn s&aacute;ch tiếng H&agrave;n chất lượng tốt với gi&aacute; cả hợp l&yacute;.</p>
<p>Bộ gi&aacute;o tr&igrave;nh được Hội nghi&ecirc;n cứu khoa học H&agrave;n Quốc của Việt Nam bi&ecirc;n soạn v&agrave; hiệu đ&iacute;nh.</p>
<p>Bộ gi&aacute;o tr&igrave;nh sẽ gi&uacute;p n&acirc;ng cao hiệu quả trong việc sử dụng ng&ocirc;n ngữ H&agrave;n sau tiếng mẹ đẻ v&agrave; tiếng Anh, l&agrave; nền tảng gi&uacute;p người lao động Việt Nam nhận được những vị tr&iacute; l&agrave;m việc cao trong doanh nghiệp H&agrave;n Quốc. Đ&acirc;y cũng l&agrave; c&aacute;ch để th&uacute;c đẩy quan hệ hợp t&aacute;c về văn ho&aacute; v&agrave; gi&aacute;o dục giữa hai nước trong thời gian tới.</p>
<p><strong>Giới thiệu cuốn Gi&aacute;o tr&igrave;nh tiếng H&agrave;n tổng hợp d&agrave;nh cho người Việt Nam &ndash; Sơ cấp 1</strong></p>
<p>Gi&aacute;o tr&igrave;nh tiếng H&agrave;n tổng hợp d&agrave;nh cho người Việt Nam &ndash; Sơ cấp 1 được bi&ecirc;n soạn d&agrave;nh cho người&nbsp; Việt Nam muốn học tiếng H&agrave;n ở tr&igrave;nh độ sơ cấp. S&aacute;ch được bi&ecirc;n soạn nhằm hướng tới việc sử dụng được trong c&aacute;c tiết học tiếng H&agrave;n tại giảng đường đại học n&ecirc;n mỗi b&agrave;i học được chia th&agrave;nh nhiều phần như: L&yacute; thuyết cơ bản gồm từ vựng v&agrave; cấu tr&uacute;c ngữ ph&aacute;p; phần luyện tập theo 4 kỹ năng giao tiếp như: Nghe &ndash; N&oacute;i &ndash; Đọc &ndash; Viết, phần luyện ph&aacute;t &acirc;m, phần t&igrave;m hiểu văn h&oacute;a&hellip;</p>
<p>C&aacute;c chủ đề trong s&aacute;ch được sắp xếp một c&aacute;ch c&oacute; hệ thống v&agrave; li&ecirc;n quan chặt chẽ với nhau. Gi&aacute;o tr&igrave;nh tiếng H&agrave;n tổng hợp được bi&ecirc;n soạn k&egrave;m theo một cuốn s&aacute;ch b&agrave;i tập hỗ trợ gi&uacute;p người học &ocirc;n tập kỹ hơn v&agrave; c&oacute; thể luyện tập n&acirc;ng cao trong những trường hợp cần thiết.</p>
<p><strong>Nội dung trong Gi&aacute;o tr&igrave;nh tiếng H&agrave;n tổng hợp &ndash; Sơ cấp 1</strong></p>
<p>2 cuốn s&aacute;ch trong bộ Sơ cấp được x&acirc;y dựng với 30 b&agrave;i kh&oacute;a v&agrave; bảng chữ c&aacute;i. Trong đ&oacute; quyển 1 gồm phần bảng chữ c&aacute;i v&agrave; 15 b&agrave;i đầu. Học hết quyển 1, bạn sẽ học đến quyển sơ cấp 2 với 15 b&agrave;i c&ograve;n lại.</p>
<p>Cấu tr&uacute;c tổng thể của gi&aacute;o tr&igrave;nh được x&acirc;y dựng theo c&aacute;c chủ đề; mỗi chủ đề được li&ecirc;n kết thống nhất với một hệ thống c&aacute;c từ vựng v&agrave; cấu tr&uacute;c ngữ ph&aacute;p cơ bản, b&agrave;i tập ứng dụng, kỹ năng v&agrave; t&igrave;m hiểu văn h&oacute;a.</p>
<p>Trong mỗi b&agrave;i học, nội dung học được chia th&agrave;nh c&aacute;c phần như: luyện từ vựng, luyện ngữ ph&aacute;p cơ bản, luyện tập kỹ năng nghe &ndash; n&oacute;i &ndash; đọc &ndash; viết, luyện ph&aacute;t &acirc;m, t&igrave;m hiểu văn h&oacute;a của đất nước H&agrave;n Quốc xinh đẹp. V&agrave; kết th&uacute;c mỗi b&agrave;i đều c&oacute; th&ecirc;m bảng từ mới xuất hiện trong b&agrave;i học.</p>
<p>Phần cuối của s&aacute;ch, c&aacute;c t&aacute;c giả đưa ra hệ thống từ mới được sắp xếp theo thứ tự của bảng chữ c&aacute;i. Đ&acirc;y l&agrave; những từ kh&ocirc;ng xuất hiện trong phần ngữ ph&aacute;p, từ vựng cơ bản; nhưng lại xuất hiện nhiều ở phần luyện tập của từng b&agrave;i.</p>', 2023, NULL, 378, 1, 15, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (298, N'BộTiếng Hàn Tổng Hợp Dành Cho Người Việt Nam - Sơ Cấp 1 (Tái Bản 2023)', N'8935246937945', N'Bìa Mềm', CAST(75075.00 AS Decimal(12, 2)), CAST(165000.00 AS Decimal(12, 2)), CAST(115500.00 AS Decimal(12, 2)), N'https://res.cloudinary.com/dabxzdaf8/image/upload/v1748969824/Book_cover/pofkyerl02aqjcfepd0x.webp', N'Nhiều Tác Giả', N'<p><strong>Tiếng H&agrave;n Tổng Hợp D&agrave;nh Cho Người Việt Nam - Sơ Cấp 1</strong></p>
