INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (306, N'450 Nouveaux Exercices - Grammaire (Niveau Débutant)', N'1105020009459', N'Bìa Mềm', CAST(29575.00 AS Decimal(12, 2)), CAST(56000.00 AS Decimal(12, 2)), CAST(45500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/4/7/47-450-grammaire.u5465.d20170808.t161803.456664.jpg', N'Laurent Hermeline', N'<p>450 Grammaire Niveau D&eacute;butant&nbsp;gồm c&aacute;c từ vựng được đề cập trong c&aacute;c b&agrave;i tập từ vựng m&agrave; c&ograve;n được bao gồm trong c&aacute;c b&agrave;i tập li&ecirc;n quan đến ngữ ph&aacute;p, ch&iacute;nh tả, chia động từ v&agrave; c&aacute;ch ph&aacute;t &acirc;m. Tổ chức n&agrave;y cho ph&eacute;p ch&uacute;ng t&ocirc;i cung cấp cho sinh vi&ecirc;n một sự phản &aacute;nh tr&ecirc;n cả hai cấp độ c&uacute; ph&aacute;p v&agrave; ngữ nghĩa.</p>
<p>C&aacute;c hoạt động rất đa dạng v&agrave; vận h&agrave;nh c&aacute;c b&agrave;i tập loại nổi tiếng của người học: b&agrave;i tập viết lại, mai mối, sắp xếp lại, trắc nghiệỗi b&agrave;i tập được giới thiệu bởi một hướng dẫn r&otilde; r&agrave;ng k&egrave;m theo một v&iacute; dụ.</p>
<p>Cuốn s&aacute;ch n&agrave;y c&oacute; thể l&agrave;m việc trong lớp học về tăng cường sự kiện ng&ocirc;n ngữ cụ thể. do đ&oacute; n&oacute; c&oacute; thể đ&oacute;ng vai tr&ograve; như một c&ocirc;ng cụ bổ sung cho một phương ph&aacute;p v&agrave; gi&uacute;p đỡ c&aacute;c đồng h&oacute;a c&aacute;c kh&aacute;i niệm nghi&ecirc;n cứu trong lớp.</p>', 2007, NULL, 174, 9, 1, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (307, N'Tự Học 5000 Câu Giao Tiếp Tiếng Pháp', N'9786044121802', N'Bìa Mềm', CAST(63700.00 AS Decimal(12, 2)), CAST(120000.00 AS Decimal(12, 2)), CAST(98000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786044121802.jpg', N'Thiên Ân', N'<p><strong>Tự Học 5000 C&acirc;u Giao Tiếp Tiếng Ph&aacute;p</strong></p>
<p>S&aacute;ch gồm c&oacute; hai phần ch&iacute;nh:</p>
<p>- Phần 1: 112 t&igrave;nh huống giao tiếp</p>
<p>D&ugrave;ng cho c&aacute;c mục đ&iacute;ch đ&agrave;m thoại, phần n&agrave;y c&oacute; nhiều mẫu c&acirc;u chuy&ecirc;n d&ugrave;ng, được sắp xếp theo tần suất xuất hiện trong giao tiếp hằng ng&agrave;y.</p>
<p>- Phần 2: 57 b&agrave;i hội thoại</p>
<p>Đ&acirc;y l&agrave; những ngữ cảnh sống động, qua đ&oacute; c&aacute;c mẫu c&acirc;u đ&atilde; được giới thiệu trong phần 1 sẽ xuất hiện trở lại, gi&uacute;p người học củng cố, ghi nhớ, đồng thời vận dụng c&aacute;c kiến thức từ vựng v&agrave; mẫu c&acirc;u v&agrave;o những t&igrave;nh huống giao tiếp thực tiễn.</p>', 2024, NULL, 250, 1, 1, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (308, N'450 Nouveaux Exercices - Vocabulaire Niveau Intermediare', N'1105020009213', N'Bìa Mềm', CAST(31850.00 AS Decimal(12, 2)), CAST(60000.00 AS Decimal(12, 2)), CAST(49000.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/1/1/1105020009213_2.jpg', N'Thierry Gallier', N'<p><strong>450 Nouveaux Exercices - Vocabulaire Niveau Intermediare</strong></p>
<p>Cet ouvrage propose &agrave; un public de niveau interm&eacute;diaire 450 activit&eacute;s d&rsquo;apprentissage et de r&eacute;emploi pour apprendre, s&rsquo;exercer, tester ses connaissances et ainsi progresser dans la ma&icirc;trise du vocabulaire fran&ccedil;ais.</p>
<p>Les th&egrave;mes des quinze chapitres correspondent aux contenus de m&eacute;thodes d&rsquo;apprentissage du fran&ccedil;ais de 2&egrave;me ann&eacute;e. Ils sont choisis pour couvrir de larges aspects de la vie courante.</p>
<p>Dans chaque chapitre, les contenus lexicaux sont pr&eacute;sent&eacute;s en suivant une difficult&eacute; progressive: le lexique indispensable &agrave; la communication est &eacute;tudi&eacute; en priorit&eacute;, puis viennent des termes apportant une nuance et enfin sont propos&eacute;es des expressions correspondant &agrave; une langue plus famili&egrave;re. L&rsquo;ensemble des besoins langagiers est ainsi couvert.</p>
<p>Les exercices sont aussi organis&eacute;s selon un parcours d&rsquo;apprentisage construit : &agrave; une phase de d&eacute;couverte, dans laquelle l&rsquo;apprenant observe les mots et d&eacute;duit leur sens, succ&egrave;dent une phase d&rsquo;identification (l&rsquo;apprenant retrouve les m&ecirc;mes mots dans diverses phrases) puis de v&eacute;rification des connaissances. Chaque chapitre s&rsquo;ach&egrave;ve sur deux bilans.</p>', 2011, NULL, 189, 4, 7, 100)
INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (309, N'450 Nouveaux Exercices - Grammaire Niveau Intermediare', N'1105020009237', N'Bìa Mềm', CAST(36075.00 AS Decimal(12, 2)), CAST(68000.00 AS Decimal(12, 2)), CAST(55500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_195509_1_21141.jpg', N'E1Velyne Siréjols, Dominique Renaud', N'<p>Cet ouvrage pr&eacute;sente 450 exercices regroup&eacute;s en cat&eacute;gories grammaticales.</p>
<p>Cet ouvrage s&rsquo;adresse &agrave; un pubic de niveau interm&eacute;diire en fran&ccedil;ais; il a pour objectif le r&eacute;emploi et l&rsquo;ancrage des structures grammaticales pr&eacute;alablement &eacute;tuid&eacute;es: les exercices propos&eacute;s doivent permettre &agrave; l&rsquo;apprenant de fixer ses acquisitions par le maniement des formes syntaxiques. Compl&eacute;ment des m&eacute;thodes, il offre un v&eacute;ritable entra&icirc;nement grammatical.</p>
<p>La conception p&eacute;dagogique de chaque activit&eacute; veut amener l&rsquo;apprenant &agrave; r&eacute;fl&eacute;chir sur chaque &eacute;nonc&eacute;, tant du point de vue syntaxique que du point de vue s&eacute;mantique. Les exercices dont les r&eacute;ponses sont n&eacute;cessairement dirig&eacute;es n&rsquo;impliquent pas pour autant un travail automtique sans r&eacute;flexion sur les faits de langue &eacute;tudi&eacute;s.</p>', 2006, NULL, 211, 15, 5, 100)
