INSERT [dbo].[Book] ([id], [book_name], [isbn], [cover], [import_price], [first_price], [second_price], [image_url], [author], [description], [year_published], [rating], [pages], [category_id], [publisher_id], [quantity]) VALUES (311, N'Tiếng Pháp Toàn Tập - Ôn Tập Và Thực Hành (Tái Bản 2024)', N'8935072957759', N'Bìa Mềm', CAST(52325.00 AS Decimal(12, 2)), CAST(115000.00 AS Decimal(12, 2)), CAST(80500.00 AS Decimal(12, 2)), N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935072957759.jpg', N'David M Stillman, Ronni L Gordon', N'<p><strong>Tiếng Ph&aacute;p To&agrave;n Tập - &Ocirc;n Tập V&agrave; Thực H&agrave;nh</strong></p>
<p>"Tiếng Ph&aacute;p To&agrave;n Tập" l&agrave; một tập s&aacute;ch d&agrave;nh cho c&aacute;c học vi&ecirc;n tiếng Ph&aacute;p ở tr&igrave;nh độ trung cấp v&agrave; cao cấp như một c&ocirc;ng cụ hữu dụng trong việc &ocirc;n tập v&agrave; ph&aacute;t triển ng&ocirc;n ngữ.</p>
